output:
// Функция заполняет табличную часть документа "Заказ" остатками товаров
// из регистра накопления "ТоварныеЗапасы" для указанного склада и даты
//
// Параметры:
//   ДокументОбъект - ДокументОбъект.Заказ - документ, который необходимо заполнить
//
// Возвращаемое значение:
//   Булево - Истина, если заполнение выполнено успешно
//
Функция ЗаполнитьТабличнуюЧастьОстатками(ДокументОбъект) Экспорт

    // Проверяем заполненность обязательных реквизитов
    Если НЕ ЗначениеЗаполнено(ДокументОбъект.Склад) Тогда
        Возврат Ложь;
    КонецЕсли;

    // Определяем параметр периода
    // Если дата документа не указана, используем текущую дату
    ПараметрПериода = ?(ЗначениеЗаполнено(ДокументОбъект.Дата), 
                        ДокументОбъект.Дата, 
                        ТекущаяДата());

    // Создаем запрос для получения остатков
    Запрос = Новый Запрос;

    Запрос.Текст = 
    "ВЫБРАТЬ
    |	ТоварныеЗапасыОстатки.Товар КАК Товар,
    |	ТоварныеЗапасыОстатки.КоличествоОстаток КАК Количество
    |ИЗ
    |	РегистрНакопления.ТоварныеЗапасы.Остатки(
    |	        &Период,
    |	        Склад = &Склад
    |	        И Товар.ВидТовара = ЗНАЧЕНИЕ(Перечисление.ВидыТоваров.Товар)
    |	    ) КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |	ТоварныеЗапасыОстатки.КоличествоОстаток > 0
    |УПОРЯДОЧИТЬ ПО
    |	ТоварныеЗапасыОстатки.Товар.Наименование";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("Период", ПараметрПериода);
    Запрос.УстановитьПараметр("Склад", ДокументОбъект.Склад);

    // Выполняем запрос
    РезультатЗапроса = Запрос.Выполнить();

    // Если остатков нет - выходим
    Если РезультатЗапроса.Пустой() Тогда
        Возврат Истина;
    КонецЕсли;

    // Очищаем табличную часть перед заполнением
    ДокументОбъект.Товары.Очистить();

    // Получаем выборку из результата запроса
    Выборка = РезультатЗапроса.Выбрать();

    // Обходим выборку и добавляем строки в табличную часть
    Пока Выборка.Следующий() Цикл

        // Добавляем новую строку табличной части
        НоваяСтрока = ДокументОбъект.Товары.Добавить();

        // Заполняем реквизиты строки
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.Количество = Выборка.Количество;

    КонецЦикла;

    Возврат Истина;

КонецФункции // ЗаполнитьТабличнуюЧастьОстатками()

Функция ЗаполнитьТабличныйДокумент(ТабДокумент, Макет, Дата) Экспорт

    // Получаем область "Шапка" из макета
    ОбластьШапка = Макет.ПолучитьОбласть("Шапка");

    // Выводим область шапки в табличный документ
    ТабДокумент.Вывести(ОбластьШапка);

    // Формируем запрос для получения остатков взаиморасчетов
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Контрагент,
    |    ВзаиморасчетыОстатки.СуммаОстаток КАК Задолженность
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&Дата, ) КАК ВзаиморасчетыОстатки
    |ГДЕ
    |    ВзаиморасчетыОстатки.СуммаОстаток <> 0
    |УПОРЯДОЧИТЬ ПО
    |    ВзаиморасчетыОстатки.Контрагент.Наименование";

    // Устанавливаем параметр запроса - дата среза остатков
    Запрос.УстановитьПараметр("Дата", Дата);

    // Выполняем запрос и получаем выборку
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // Получаем область "Строка" из макета
    ОбластьСтрока = Макет.ПолучитьОбласть("Строка");

    // Обходим выборку и выводим строки в табличный документ
    Пока Выборка.Следующий() Цикл

        // Заполняем параметры области строки данными из выборки
        ОбластьСтрока.Параметры.Контрагент = Выборка.Контрагент;
        ОбластьСтрока.Параметры.Задолженность = Выборка.Задолженность;

        // Выводим область строки в табличный документ
        ТабДокумент.Вывести(ОбластьСтрока);

    КонецЦикла;

КонецФункции

// Устанавливает во всех строках ТЧ «Товары» значение поля «СкладСтроки» 
// равным реквизиту документа «Склад»
//
// Параметры:
//   ДокументОбъект - ДокументОбъект - Объект документа, содержащий ТЧ «Товары»
//
Функция УстановитьСклад(ДокументОбъект) Экспорт

    // Проверка на пустую ссылку
    Если ДокументОбъект = Неопределено Тогда
        Возврат;
    КонецЕсли;

    // Проверка заполнения склада в документе
    Если НЕ ЗначениеЗаполнено(ДокументОбъект.Склад) Тогда
        Возврат;
    КонецЕсли;

    // Проверка наличия строк в ТЧ
    Если ДокументОбъект.Товары.Количество() = 0 Тогда
        Возврат;
    КонецЕсли;

    // Кэшируем значение склада для оптимизации
    ТекущийСклад = ДокументОбъект.Склад;

    // Обходим все строки ТЧ «Товары» и устанавливаем склад
    Для Каждого СтрокаТЧ Из ДокументОбъект.Товары Цикл
        СтрокаТЧ.СкладСтроки = ТекущийСклад;
    КонецЦикла;

КонецФункции

Функция УдалитьПоследнююЗапись(Валюта) Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ ПЕРВЫЕ 1
    |    КурсыВалют.Период
    |ИЗ
    |    РегистрСведений.КурсыВалют КАК КурсыВалют
    |ГДЕ
    |    КурсыВалют.Валюта = &Валюта
    |УПОРЯДОЧИТЬ ПО
    |    КурсыВалют.Период УБЫВ";

    Запрос.УстановитьПараметр("Валюта", Валюта);

    Результат = Запрос.Выполнить();

    Если Результат.Пустой() Тогда
        Возврат;
    КонецЕсли;

    Выборка = Результат.Выбрать();
    Выборка.Следующий();

    Период = Выборка.Период;

    МенеджерЗаписи = РегистрыСведений.КурсыВалют.СоздатьМенеджерЗаписи();
    МенеджерЗаписи.Валюта = Валюта;
    МенеджерЗаписи.Период = Период;
    МенеджерЗаписи.Удалить();

КонецФункции

// Функция возвращает список товаров указанного поставщика,
// для которых не установлены цены
//
// Параметры:
//  Поставщик - СправочникСсылка.Поставщики - Поставщик для фильтрации
//
// Возвращаемое значение:
//  СписокЗначений - список товаров без установленных цен
//
Функция НеУстановленыЦены(Поставщик) Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    Товары.Ссылка КАК Товар
    |ИЗ
    |    Справочник.Товары КАК Товары
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров КАК ЦеныТоваров
    |        ПО Товары.Ссылка = ЦеныТоваров.Товар
    |ГДЕ
    |    Товары.Поставщик = &Поставщик
    |    И ЦеныТоваров.Товар ЕСТЬ NULL";

    Запрос.УстановитьПараметр("Поставщик", Поставщик);

    РезультатЗапроса = Запрос.Выполнить();

    СписокТоваров = Новый СписокЗначений;

    Если НЕ РезультатЗапроса.Пустой() Тогда
        Выборка = РезультатЗапроса.Выбрать();
        Пока Выборка.Следующий() Цикл
            СписокТоваров.Добавить(Выборка.Товар);
        КонецЦикла;
    КонецЕсли;

    Возврат СписокТоваров;

КонецФункции

Функция ВыгрузитьОстаткиСклада(Склад, МинимальныйОстаток, ФайлJson) Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар.Код КАК Товар_Код,
    |    ТоварныеЗапасыОстатки.Товар.Наименование КАК Товар_Наименование,
    |    ОКР(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК Остаток
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Период, Склад = &Склад) КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |    ТоварныеЗапасыОстатки.КоличествоОстаток >= &МинимальныйОстаток
    |УПОРЯДОЧИТЬ ПО
    |    Товар_Код ВОЗР
    |";

    Запрос.УстановитьПараметр("Период", ТекущаяДатаСеанса());
    Запрос.УстановитьПараметр("Склад", Склад);
    Запрос.УстановитьПараметр("МинимальныйОстаток", МинимальныйОстаток);

    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаОстатков = РезультатЗапроса.Выгрузить();

    МассивДанных = Новый Массив;

    Для Каждого СтрокаТаблицы Из ТаблицаОстатков Цикл

        СтруктураСтроки = Новый Структура;
        СтруктураСтроки.Вставить("Товар_Код", СтрокаТаблицы.Товар_Код);
        СтруктураСтроки.Вставить("Товар_Наименование", СтрокаТаблицы.Товар_Наименование);
        СтруктураСтроки.Вставить("Остаток", СтрокаТаблицы.Остаток);

        МассивДанных.Добавить(СтруктураСтроки);

    КонецЦикла;

    ЗаписьJSON = Новый ЗаписьJSON;
    ЗаписьJSON.ОткрытьФайл(ФайлJson, "UTF-8");

    СериализаторXDTO = Новый СериализаторXDTO(ФабрикаXDTO);
    СериализаторXDTO.ЗаписатьJSON(ЗаписьJSON, МассивДанных, НазначениеТипаXML.Неявное);

    ЗаписьJSON.Закрыть();

КонецФункции

// Функция выбирает строки из таблицы значений по заданным условиям
//
// Параметры:
//   Таблица      - ТаблицаЗначений - исходная таблица с колонками:
//                  Склад, Товар, Количество
//   Склад        - СправочникСсылка.Склады - фильтр по складу
//   Наименование - Строка - подстрока для поиска в наименовании товара
//
// Возвращаемое значение:
//   ТаблицаЗначений - отфильтрованная таблица
//
Функция ВыбратьСтрокиТаблицы(Таблица, Склад, Наименование) Экспорт

    // Создаём запрос
    Запрос = Новый Запрос;

    // Устанавливаем параметр - таблицу значений
    Запрос.УстановитьПараметр("Таблица", Таблица);
    Запрос.УстановитьПараметр("Склад", Склад);
    Запрос.УстановитьПараметр("Наименование", Наименование);

    // Формируем текст запроса
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Таблица.Склад,
    |    Таблица.Товар,
    |    Таблица.Количество
    |ПОМЕСТИТЬ ВТ_Данные
    |ИЗ
    |    &Таблица КАК Таблица
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ВТ_Данные.Склад,
    |    ВТ_Данные.Товар,
    |    ВТ_Данные.Количество
    |ИЗ
    |    ВТ_Данные КАК ВТ_Данные
    |ГДЕ
    |    ВТ_Данные.Склад = &Склад
    |    И ВТ_Данные.Товар.Наименование ПОДОБНО ""%"" + &Наименование + ""%""";

    // Выполняем запрос и получаем результат
    РезультатЗапроса = Запрос.Выполнить();

    // Создаём результирующую таблицу значений
    Результат = Новый ТаблицаЗначений;

    // Загружаем результат запроса в таблицу значений
    Результат = РезультатЗапроса.Выгрузить();

    Возврат Результат;

КонецФункции

// Функция возвращает таблицу значений с товарами, 
// которые были на складе на Дата1, но отсутствуют на складе на Дата2
//
// Параметры:
//   Дата1 - Дата - Дата, на которую анализируются остатки (товар должен быть)
//   Дата2 - Дата - Дата, на которую анализируются остатки (товар должен отсутствовать)
//
// Возвращаемое значение:
//   ТаблицаЗначений - колонки: "Товар", "Количество"
//
Функция УшедшийТовар(Дата1, Дата2) Экспорт

    Запрос = Новый Запрос;

    Запрос.Текст = 
    "ВЫБРАТЬ
|    ТоварныеЗапасыОстатки.Товар,
|    СУММА(ТоварныеЗапасыОстатки.Количество) КАК Количество
||ПОМЕСТИТЬ ОстаткиНаДату1
||ИЗ
|    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата1, ) КАК ТоварныеЗапасыОстатки
||СГРУППИРОВАТЬ ПО
|    ТоварныеЗапасыОстатки.Товар
||;
||/////////////////////////////////////////////////////////////
||ВЫБРАТЬ
|    ТоварныеЗапасыОстатки.Товар
||ПОМЕСТИТЬ ОстаткиНаДату2
||ИЗ
|    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата2, ) КАК ТоварныеЗапасыОстатки
||СГРУППИРОВАТЬ ПО
|    ТоварныеЗапасыОстатки.Товар
||;
||/////////////////////////////////////////////////////////////
||ВЫБРАТЬ
|    ОстаткиНаДату1.Товар КАК Товар,
|    ОстаткиНаДату1.Количество
||ИЗ
|    ОстаткиНаДату1 КАК ОстаткиНаДату1
|        ВНУТРЕННЕЕ СОЕДИНЕНИЕ ОстаткиНаДату2 КАК ОстаткиНаДату2
|        ПО (ЛОЖЬ)
||ГДЕ
|    НЕ ОстаткиНаДату1.Товар В
|            (ВЫБРАТЬ
|                ОстаткиНаДату2.Товар
|             ИЗ
|                ОстаткиНаДату2 КАК ОстаткиНаДату2)
||
||УПОРЯДОЧИТЬ ПО
|    ОстаткиНаДату1.Товар.Наименование
||АВТОУПОРЯДОЧИВАНИЕ
||";

    Запрос.УстановитьПараметр("Дата1", Дата1);
    Запрос.УстановитьПараметр("Дата2", Дата2);

    РезультатЗапроса = Запрос.Выполнить();

    Возврат РезультатЗапроса.Выгрузить();

КонецФункции

// Функция возвращает таблицу значений с контрагентами,
// у которых на заданную дату есть просроченный долг.
//
// Параметры:
//  Дата        - Дата - Дата, на которую определяются остатки задолженности
//  МинДолг     - Число - Минимальная сумма общего долга для включения в результат
//  СрокДолга   - Число - Количество дней, после которого долг считается просроченным
//
// Возвращаемое значение:
//  ТаблицаЗначений с колонками:
//   Контрагент            - СправочникСсылка.Контрагенты
//   ДолгВсего            - Число - Общая сумма задолженности
//   ДолгПросроченный     - Число - Сумма просроченной задолженности
//   ДатаОбразованияДолга - Дата - Дата возникновения самой ранней задолженности
//
Функция ПросроченныеДолги(Дата, МинДолг, СрокДолга) Экспорт

    Запрос = Новый Запрос;
    Запрос.МенеджерВременныхТаблиц = Новый МенеджерВременныхТаблиц;
    Запрос.УстановитьПараметр("Дата", Дата);
    Запрос.УстановитьПараметр("МинДолг", МинДолг);
    Запрос.УстановитьПараметр("СрокДолга", СрокДолга);

    // Этап 1: Получаем все движения по контрагентам с ненулевыми суммами
    |ВЫБРАТЬ
    |    Взаиморасчеты.Период,
    |    Взаиморасчеты.Контрагент,
    |    Взаиморасчеты.Сумма
    |ПОМЕСТИТЬ ДвиженияКонтрагентов
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты КАК Взаиморасчеты
    |ГДЕ
    |    Взаиморасчеты.Период <= &Дата
    |    И Взаиморасчеты.Сумма <> 0
    |;

    // Этап 2: Вычисляем нарастающий остаток для каждого контрагента
    // и находим первую дату, когда остаток стал положительным
    |ВЫБРАТЬ
    |    МИНИМУМ(НарастающиеОстатки.Период) КАК ДатаОбразования,
    |    НарастающиеОстатки.Контрагент
    |ПОМЕСТИТЬ ДатыОбразования
    |ИЗ
    |    (ВЫБРАТЬ
    |        Движения.Период,
    |        Движения.Контрагент,
    |        СУММА(ДвиженияДо.Сумма) КАК НарастающийОстаток
    |    ИЗ
    |        ДвиженияКонтрагентов КАК Движения
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ ДвиженияКонтрагентов КАК ДвиженияДо
    |            ПО Движения.Контрагент = ДвиженияДо.Контрагент
    |            И ДвиженияДо.Период <= Движения.Период
    |    СГРУППИРОВАТЬ ПО
    |        Движения.Период,
    |        Движения.Контрагент
    |    ) КАК НарастающиеОстатки
    |ГДЕ
    |    НарастающиеОстатки.НарастающийОстаток > 0
    |СГРУППИРОВАТЬ ПО
    |    НарастающиеОстатки.Контрагент
    |;

    // Этап 3: Формируем итоговую таблицу с расчётом просроченного долга
    |ВЫБРАТЬ
    |    Остатки.Контрагент,
    |    Остатки.СуммаОстаток КАК ДолгВсего,
    |    ВЫБОР
    |        КОГДА ЕСТЬNULL(ДатыОбразования.ДатаОбразования, ДАТАВРЕМЯ(1, 1, 1)) <> ДАТАВРЕМЯ(1, 1, 1)
    |             И РАЗНОСТЬДАТ(ДатыОбразования.ДатаОбразования, &Дата, ДЕНЬ) > &СрокДолга
    |        ТОГДА Остатки.СуммаОстаток
    |        ИНАЧЕ 0
    |    КАК ДолгПросроченный,
    |    ДатыОбразования.ДатаОбразования КАК ДатаОбразованияДолга
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&Дата, ) КАК Остатки
    |    ЛЕВОЕ СОЕДИНЕНИЕ ДатыОбразования КАК ДатыОбразования
    |        ПО Остатки.Контрагент = ДатыОбразования.Контрагент
    |ГДЕ
    |    Остатки.СуммаОстаток > &МинДолг
    |УПОРЯДОЧИТЬ ПО
    |    Остатки.Контрагент
    |";

    РезультатЗапроса = Запрос.Выполнить();

    Возврат РезультатЗапроса.Выгрузить();

КонецФункции

// Функция создает объект ИнтернетПочтовоеСообщение на основании данных справочника ИсходящиеПисьма
//
// Параметры:
//  Письмо - СправочникСсылка.ИсходящиеПисьма - элемент справочника для формирования почтового сообщения
//  Отправитель - Строка - email адрес отправителя
// 
// Возвращаемое значение:
//  ИнтернетПочтовоеСообщение - готовое к отправке почтовое сообщение
//
Функция СоздатьИнтернетПочтовоеСообщение(Письмо, Отправитель) Экспорт

    // Создаем объект почтового сообщения
    ИнтернетПочтовоеСообщение = Новый ИнтернетПочтовоеСообщение;

    // Устанавливаем отправителя
    ИнтернетПочтовоеСообщение.Отправитель = Отправитель;

    // Получаем данные письма из базы данных
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ИсходящиеПисьма.Текст,
    |    ИсходящиеПисьма.Содержимое
    |ИЗ
    |    Справочник.ИсходящиеПисьма КАК ИсходящиеПисьма
    |ГДЕ
    |    ИсходящиеПисьма.Ссылка = &Письмо";

    Запрос.УстановитьПараметр("Письмо", Письмо);

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    Если Выборка.Следующий() Тогда

        // Получаем текст письма
        ТекстПисьма = Выборка.Текст;

        // Если текст содержит HTML-разметку, используем HTML, иначе - простой текст
        ТипТекста = ?(СтрНайти(ТекстПисьма, "<html") > 0 
            ИЛИ СтрНайти(ТекстПисьма, "<body") > 0,
            ТипТекстаПочтовогоСообщения.HTML,
            ТипТекстаПочтовогоСообщения.ПростойТекст);

        // Добавляем текст в коллекцию Тексты
        ИнтернетПочтовоеСообщение.Тексты.Добавить(ТекстПисьма, ТипТекста);

        // Получаем вложенную таблицу получателей
        Получатели = Выборка.Получатели;

        // Добавляем получателей из табличной части
        Для Каждого СтрокаПолучателя Из Получатели Цикл

            Если НЕ ПустаяСтрока(СтрокаПолучателя.ЭлектроннаяПочта) Тогда
                ИнтернетПочтовоеСообщение.Получатели.Добавить(
                    СтрокаПолучателя.ЭлектроннаяПочта);
            КонецЕсли;

        КонецЦикла;

    КонецЕсли;

    Возврат ИнтернетПочтовоеСообщение;

КонецФункции

// Функция создает движения регистра накопления "Продажи" по документу "РасходТовара"
//
// Параметры:
//   ДокументСсылка - ДокументСсылка.РасходТовара - ссылка на документ
//
Процедура СоздатьДвиженияРегистраПродажи(ДокументСсылка) Экспорт

    // Проверка на пустую ссылку
    Если НЕ ЗначениеЗаполнено(ДокументСсылка) Тогда
        Возврат;
    КонецЕсли;

    // Создаем набор записей регистра накопления "Продажи"
    НаборЗаписей = РегистрыНакопления.Продажи.СоздатьНаборЗаписей();

    // Устанавливаем отбор по документу (это удалит существующие движения)
    НаборЗаписей.Отбор.Регистратор.Установить(ДокументСсылка);

    // Записываем пустой набор (тем самым удаляем старые движения)
    НаборЗаписей.Записать();

    // Получаем данные документа
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   РасходТовараТовары.Номенклатура,
    |   РасходТовараТовары.Количество,
    |   РасходТовараТовары.Цена,
    |   РасходТовараТовары.Сумма,
    |   РасходТовара.Контрагент,
    |   РасходТовара.Дата КАК Период
    |ИЗ
    |   Документ.РасходТовара.Товары КАК РасходТовараТовары
    |   ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасходТовара КАК РасходТовара
    |   ПО РасходТовараТовары.Ссылка = РасходТовара.Ссылка
    |ГДЕ
    |   РасходТовараТовары.Ссылка = &Ссылка";

    Запрос.УстановитьПараметр("Ссылка", ДокументСсылка);

    РезультатЗапроса = Запрос.Выполнить();

    // Если нет данных - выходим
    Если РезультатЗапроса.Пустой() Тогда
        Возврат;
    КонецЕсли;

    // Заполняем набор записей новыми данными
    НаборЗаписей.Отбор.Регистратор.Установить(ДокументСсылка);

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл

        НоваяЗапись = НаборЗаписей.Добавить();

        // Измерения
        НоваяЗапись.Регистратор   = ДокументСсылка;
        НоваяЗапись.Период        = Выборка.Период;
        НоваяЗапись.Номенклатура  = Выборка.Номенклатура;
        НоваяЗапись.Контрагент    = Выборка.Контрагент;

        // Ресурсы
        НоваяЗапись.Количество    = Выборка.Количество;
        НоваяЗапись.Сумма         = Выборка.Сумма;

    КонецЦикла;

    // Записываем новые движения
    НаборЗаписей.Записать(Истина);

КонецПроцедуры

Функция ЗаменитьНоменклатуру(НоменклатураИсточник, НоменклатураЗамены, ДатаС, ДатаПо) Экспорт

    // Проверка корректности входных параметров
    Если НоменклатураИсточник = НоменклатураЗамены Тогда
        Возврат 0;
    КонецЕсли;

    Если НоменклатураИсточник.Пустая() Тогда
        Возврат 0;
    КонецЕсли;

    // Запрос для поиска документов с искомой номенклатурой
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ РАЗЛИЧНЫЕ
    |    ЗаказТовары.Ссылка КАК Ссылка,
    |    ЗаказТовары.Ссылка.Проведен КАК Проведен
    |ИЗ
    |    Документ.Заказ.Товары КАК ЗаказТовары
    |ГДЕ
    |    ЗаказТовары.Товар = &НоменклатураИсточник
    |    И ЗаказТовары.Ссылка.Дата >= &ДатаС
    |    И ЗаказТовары.Ссылка.Дата <= &ДатаПо
    |    И НЕ ЗаказТовары.Ссылка.ПометкаУдаления
    |
    |УПОРЯДОЧИТЬ ПО
    |    ЗаказТовары.Ссылка.Дата ВОЗР,
    |    ЗаказТовары.Ссылка.МоментВремени";

    Запрос.УстановитьПараметр("НоменклатураИсточник", НоменклатураИсточник);
    Запрос.УстановитьПараметр("ДатаС", ДатаС);
    Запрос.УстановитьПараметр("ДатаПо", ДатаПо);

    РезультатЗапроса = Запрос.Выполнить();

    Если РезультатЗапроса.Пустой() Тогда
        Возврат 0;
    КонецЕсли;

    Выборка = РезультатЗапроса.Выбрать();
    КоличествоОбработанных = 0;

    Пока Выборка.Следующий() Цикл

        ДокументСсылка = Выборка.Ссылка;

        // Блокировка объекта для безопасной записи
        Блокировка = Новый БлокировкаДанных;
        ЭлементБлокировки = Блокировка.Добавить("Документ.Заказ");
        ЭлементБлокировки.УстановитьЗначение("Ссылка", ДокументСсылка);
        Блокировка.Заблокировать();

        ДокументОбъект = ДокументСсылка.ПолучитьОбъект();

        // Повторная проверка пометки удаления (могла измениться)
        Если ДокументОбъект = Неопределено Или ДокументОбъект.ПометкаУдаления Тогда
            Продолжить;
        КонецЕсли;

        БылаЗамена = Ложь;

        // Обработка табличной части
        Для Каждого СтрокаТЧ Из ДокументОбъект.Товары Цикл
            Если СтрокаТЧ.Товар = НоменклатураИсточник Тогда
                СтрокаТЧ.Товар = НоменклатураЗамены;
                БылаЗамена = Истина;
            КонецЕсли;
        КонецЦикла;

        // Запись документа
        Если БылаЗамена Тогда
            Если ДокументОбъект.Проведен Тогда
                ДокументОбъект.Записать(РежимЗаписиДокумента.Проведение);
            Иначе
                ДокументОбъект.Записать(РежимЗаписиДокумента.Запись);
            КонецЕсли;
            КоличествоОбработанных = КоличествоОбработанных + 1;
        КонецЕсли;

    КонецЦикла;

    Возврат КоличествоОбработанных;

КонецФункции

// Функция расчета комиссии менеджеров за период
//
// Параметры:
//   ТаблицаКомиссий - ТаблицаЗначений - таблица для заполнения результатами
//   Процент         - Число - процент комиссии (например, 0.05 для 5%)
//   ДатаС           - Дата - начало периода
//   ДатаПо          - Дата - конец периода
//
Функция РасчетКомиссииМенеджера(ТаблицаКомиссий, Процент, ДатаС, ДатаПо) Экспорт

    // Создаем таблицу результатов с нужными колонками
    ТаблицаКомиссий.Очистить();
    ТаблицаКомиссий.Колонки.Добавить("Менеджер",      Новый ОписаниеТипов("СправочникСсылка.Пользователи"));
    ТаблицаКомиссий.Колонки.Добавить("СуммаЗаказов",  Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    ТаблицаКомиссий.Колонки.Добавить("Комиссия",      Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Формируем запрос для получения сумм заказов по менеджерам
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Заказ.Автор КАК Менеджер,
    |    СУММА(ЗаказТовары.Сумма) КАК СуммаЗаказов
    |ИЗ
    |    Документ.Заказ.Товары КАК ЗаказТовары
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.Заказ КАК Заказ
    |        ПО ЗаказТовары.Ссылка = Заказ.Ссылка
    |ГДЕ
    |    Заказ.Дата >= &ДатаС
    |    И Заказ.Дата <= &ДатаПо
    |    И Заказ.Проведен = ИСТИНА
    |СГРУППИРОВАТЬ ПО
    |    Заказ.Автор
    |УПОРЯДОЧИТЬ ПО
    |    Заказ.Автор.Наименование";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("ДатаС", ДатаС);
    Запрос.УстановитьПараметр("ДатаПо", ДатаПо);

    // Выполняем запрос и обходим результат
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    Пока Выборка.Следующий() Цикл

        // Получаем сумму заказов менеджера
        СуммаЗаказов = Выборка.СуммаЗаказов;

        // Рассчитываем комиссию
        Комиссия = СуммаЗаказов * Процент;

        // Добавляем строку в таблицу результатов
        НоваяСтрока = ТаблицаКомиссий.Добавить();
        НоваяСтрока.Менеджер      = Выборка.Менеджер;
        НоваяСтрока.СуммаЗаказов  = СуммаЗаказов;
        НоваяСтрока.Комиссия      = Комиссия;

    КонецЦикла;

КонецФункции

// Функция получает ширину и высоту изображения из JPEG файла
//
// Параметры:
//   ИмяФайла - Строка - Полный путь к файлу JPEG
//
// Возвращаемое значение:
//   Структура с ключами "Ширина" и "Высота" (в пикселах),
//   либо Неопределено в случае ошибки
//
Функция ПолучитьШиринуВысотуКартинкиИзФайлаJPEG(ИмяФайла) Экспорт

    // Проверяем существование файла
    Файл = Новый Файл(ИмяФайла);
    Если Не Файл.Существует() Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Проверяем расширение (опционально)
    НРегРасширения = НРег(Файл.Расширение);
    Если НРегРасширения <> ".jpg" И НРегРасширения <> ".jpeg" Тогда
        Возврат Неопределено;
    КонецЕсли;

    Попытка
        // Читаем файл в двоичные данные
        ДвоичныеДанные = Новый ДвоичныеДанные(ИмяФайла);
        Поток = Новый ПотокВПамяти();
        Поток.Записать(ДвоичныеДанные);
        Поток.Перейти(0, ПозицияПотока.Начало);

        // Читаем первые 2 байта - сигнатура JPEG (FF D8)
        Сигнатура = Новый Массив(2);
        Для и = 0 По 1 Цикл
            Сигнатура[и] = Поток.ПрочитатьБайт();
        КонецЦикла;

        // Проверяем сигнатуру JPEG: FF D8
        Если Сигнатура[0] <> 16*15 + 8 ИЛИ Сигнатура[1] <> 16*15 + 10 Тогда
            // Не JPEG или сигнатура не найдена
            Возврат Неопределено;
        КонецЕсли;

        Ширина = 0;
        Высота = 0;
        НайденРазмер = Ложь;

        // Проходим по маркерам файла в поисках SOF (Start Of Frame)
        // JPEG маркеры начинаются с FF, за которым следует код маркера
        Пока Поток.Доступно > 0 И НЕ НайденРазмер Цикл

            // Читаем первый байт - должен быть FF
            ПервыйБайт = Поток.ПрочитатьБайт();
            Если ПервыйБайт <> 255 Тогда
                // Неожиданный байт, ищем следующий FF
                Продолжить;
            КонецЕсли;

            // Читаем код маркера
            КодМаркера = Поток.ПрочитатьБайт();

            // Пропускаем RST маркеры (FF 00 - FF 07)
            Если КодМаркера >= 0 И КодМаркера <= 7 Тогда
                Продолжить;
            КонецЕсли;

            // Пропускаем заполнители (FF FF ...)
            Если КодМаркера = 255 Тогда
                Продолжить;
            КонецЕсли;

            // SOF маркеры: FF C0 - SOF0 (Baseline), FF C1 - SOF1, 
            // FF C2 - SOF2 (Progressive), FF C3 - SOF3, и т.д.
            // Нас интересуют SOF0, SOF1, SOF2 (наиболее распространенные)
            Если (КодМаркера >= 192 И КодМаркера <= 207) 
                И КодМаркера <> 216  // DHT (Define Huffman Table)
                И КодМаркера <> 217  // EOI (End Of Image)
                И КодМаркера <> 218  // DAC (Define Arithmetic Coding)
                Тогда

                // Читаем длину сегмента (2 байта, big-endian)
                ДлинаМладшая = Поток.ПрочитатьБайт();
                ДлинаСтаршая = Поток.ПрочитатьБайт();
                ДлинаСегмента = ДлинаСтаршая * 256 + ДлинаМладшая;

                // Пропускаем байт precision (1 байт)
                Поток.Пропустить(1);

                // Читаем высоту (2 байта, big-endian)
                ВысотаМладшая = Поток.ПрочитатьБайт();
                ВысотаСтаршая = Поток.ПрочитатьБайт();
                Высота = ВысотаСтаршая * 256 + ВысотаМладшая;

                // Читаем ширину (2 байта, big-endian)
                ШиринаМладшая = Поток.ПрочитатьБайт();
                ШиринаСтаршая = Поток.ПрочитатьБайт();
                Ширина = ШиринаСтаршая * 256 + ШиринаМладшая;

                НайденРазмер = Истина;

            ИначеЕсли КодМаркера <> 216 И КодМаркера <> 217 Тогда
                // Для других маркеров читаем длину и пропускаем данные
                // (исключая Standalone маркеры без длины)
                Если КодМаркера <> 216  // RST markers don't have length
                    И КодМаркера <> 217 
                    И КодМаркера <> 218 
                    И КодМаркера <> 219 
                    И КодМаркера <> 220 
                    И КодМаркера <> 221 
                    И КодМаркера <> 222 
                    И КодМаркера <> 223 
                    И КодМаркера <> 224 
                    И КодМаркера <> 225 
                    И КодМаркера <> 226 
                    И КодМаркера <> 227 
                    И КодМаркера <> 228 
                    И КодМаркера <> 229 
                    И КодМаркера <> 230 
                    И КодМаркера <> 231 
                    И КодМаркера <> 232 
                    И КодМаркера <> 233 
                    И КодМаркера <> 234 
                    И КодМаркера <> 235 
                    И КодМаркера <> 236 
                    И КодМаркера <> 237 
                    И КодМаркера <> 238 
                    И КодМаркера <> 239 
                    Тогда

                    // Читаем длину сегмента
                    ДлинаМладшая = Поток.ПрочитатьБайт();
                    ДлинаСтаршая = Поток.ПрочитатьБайт();
                    ДлинаДанных = ДлинаСтаршая * 256 + ДлинаМладшая - 2;

                    // Пропускаем данные сегмента
                    Если ДлинаДанных > 0 И ДлинаДанных <= Поток.Доступно Тогда
                        Поток.Пропустить(ДлинаДанных);
                    КонецЕсли;
                КонецЕсли;
            КонецЕсли;

        КонецЦикла;

        // Проверяем, что размеры найдены и валидны
        Если НайденРазмер И Ширина > 0 И Высота > 0 Тогда
            Результат = Новый Структура("Ширина, Высота", Ширина, Высота);
            Возврат Результат;
        Иначе
            Возврат Неопределено;
        КонецЕсли;

    Исключение
        Возврат Неопределено;
    КонецПопытки;

КонецФункции

// Функция извлекает партии по методу ФИФО на заданную сумму
//
// Параметры:
//   ТаблицаПартий - ТаблицаЗначений - таблица с колонками:
//       Партия - Произвольный - идентификатор партии
//       Дата - Дата - дата и время партии
//       Сумма - Число - сумма партии
//   Сумма - Число - требуемая сумма для извлечения
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками Партия, Дата, Сумма
//
Функция ИзвлечьПартииФИФО(ТаблицаПартий, Сумма) Экспорт

    // Создаём таблицу результата с аналогичной структурой
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Партия");
    Результат.Колонки.Добавить("Дата");
    Результат.Колонки.Добавить("Сумма");

    // Проверка на пустые данные
    Если ТаблицаПартий.Количество() = 0 Тогда
        Возврат Результат;
    КонецЕсли;

    Если Сумма <= 0 Тогда
        Возврат Результат;
    КонецЕсли;

    // Создаём копию таблицы для сортировки
    ТаблицаКопия = ТаблицаПартий.Скопировать();

    // Сортируем по дате (метод ФИФО - первыми идут партии с наименьшей датой)
    ТаблицаКопия.Сортировать("Дата Возр");

    // Накапливаем сумму для определения необходимой корректировки последней партии
    НакопленнаяСумма = 0;

    // Обрабатываем каждую партию
    Для Каждого СтрокаПартии Из ТаблицаКопия Цикл

        // Определяем сумму для добавления из текущей партии
        Если НакопленнаяСумма + СтрокаПартии.Сумма <= Сумма Тогда
            // Партия помещается полностью
            СуммаКСписанию = СтрокаПартии.Сумма;
        Иначе
            // Берём только необходимую часть (подгонка последней партии)
            СуммаКСписанию = Сумма - НакопленнаяСумма;
        КонецЕсли;

        // Добавляем строку в результат
        НоваяСтрока = Результат.Добавить();
        НоваяСтрока.Партия = СтрокаПартии.Партия;
        НоваяСтрока.Дата = СтрокаПартии.Дата;
        НоваяСтрока.Сумма = СуммаКСписанию;

        // Обновляем накопленную сумму
        НакопленнаяСумма = НакопленнаяСумма + СуммаКСписанию;

        // Если достигли требуемой суммы - выходим из цикла
        Если НакопленнаяСумма >= Сумма Тогда
            Прервать;
        КонецЕсли;

    КонецЦикла;

    Возврат Результат;

КонецФункции

// Функция добавляет в начало первой ТЗ строки из второй ТЗ 
// с обеспечением уникальности по указанной колонке
//
// Параметры:
//  Таблица1 - ТаблицаЗначений - основная таблица (не изменяется)
//  Таблица2 - ТаблицаЗначений - таблица-источник новых строк
//  КолонкаУникальности - Строка - имя колонки для проверки уникальности
//
// Возвращаемое значение:
//  ТаблицаЗначений - объединенная таблица (строки Таблица2 в начале)
//
Функция ДополнитьТаблицуЗначениямиИзВторой(Таблица1, Таблица2, КолонкаУникальности) Экспорт

    // Создаем копию первой таблицы - результат будет включать все её строки
    Результат = Таблица1.Скопировать();

    // Создаем Соответствие для быстрой проверки существования значений
    // Ключ = значение колонки уникальности, Значение = Истина
    СуществующиеЗначения = Новый Соответствие;
    Для Каждого СтрокаТаблицы Из Таблица1 Цикл
        СуществующиеЗначения.Вставить(СтрокаТаблицы[КолонкаУникальности], Истина);
    КонецЦикла;

    // Добавляем строки из второй таблицы в начало (только уникальные)
    Для Каждого СтрокаТаблицы Из Таблица2 Цикл

        ЗначениеУникальности = СтрокаТаблицы[КолонкаУникальности];

        // Пропускаем если значение уже существует
        Если СуществующиеЗначения.Получить(ЗначениеУникальности) <> Неопределено Тогда
            Продолжить;
        КонецЕсли;

        // Вставляем строку в начало таблицы
        НоваяСтрока = Результат.Вставить(0);

        // Заполняем значениями из строки второй таблицы
        ЗаполнитьЗначенияСвойств(НоваяСтрока, СтрокаТаблицы);

        // Регистрируем значение как обработанное
        СуществующиеЗначения.Вставить(ЗначениеУникальности, Истина);

    КонецЦикла;

    Возврат Результат;

КонецФункции

