// Функция преобразует объект данных (документ, справочник и т.д.) в структуру
//
// Параметры:
//  ОбъектДанных - Объект данных (ДокументОбъект, СправочникОбъект и т.д.)
//
// Возвращаемое значение:
//  Структура - Структура с данными объекта
//
Функция ОбъектВСтруктуру(ОбъектДанных) Экспорт

    Результат = Новый Структура;

    // Получаем метаданные объекта
    МетаданныеОбъекта = ОбъектДанных.Метаданные();

    // 1. Обрабатываем стандартные реквизиты
    СтандартныеРеквизиты = МетаданныеОбъекта.СтандартныеРеквизиты;

    Для Каждого СтандартныйРеквизит Из СтандартныеРеквизиты Цикл

        ИмяРеквизита = СтандартныйРеквизит.Имя;

        // Пропускаем служебные реквизиты, которые не имеют смысла в структуре
        Если ИмяРеквизита = "Ref" 
            ИЛИ ИмяРеквизита = "IsFolder" 
            ИЛИ ИмяРеквизита = "Parent" 
            ИЛИ ИмяРеквизита = "PredefinedDataName"
            ИЛИ ИмяРеквизита = "DataVersion" Тогда
            Продолжить;
        КонецЕсли;

        Попытка
            Значение = ОбъектДанных[ИмяРеквизита];
            Результат.Вставить(ИмяРеквизита, ПолучитьСериализуемоеЗначение(Значение));
        Исключение
            // Игнорируем ошибки при получении реквизита
        КонецПопытки;

    КонецЦикла;

    // 2. Обрабатываем реквизиты шапки (для документов)
    Если ОбщегоНазначения.ЕстьРеквизитОбъекта("Склад", МетаданныеОбъекта) Тогда

        РеквизитыШапки = ПолучитьРеквизитыШапки(МетаданныеОбъекта);

        Для Каждого Реквизит Из РеквизитыШапки Цикл

            ИмяРеквизита = Реквизит.Имя;

            Попытка
                Значение = ОбъектДанных[ИмяРеквизита];
                Результат.Вставить(ИмяРеквизита, ПолучитьСериализуемоеЗначение(Значение));
            Исключение
                // Игнорируем ошибки при получении реквизита
            КонецПопытки;

        КонецЦикла;

    Иначе

        // Для справочников и других объектов - обычные реквизиты
        Реквизиты = МетаданныеОбъекта.Реквизиты;

        Для Каждого Реквизит Из Реквизиты Цикл

            ИмяРеквизита = Реквизит.Имя;

            Попытка
                Значение = ОбъектДанных[ИмяРеквизита];
                Результат.Вставить(ИмяРеквизита, ПолучитьСериализуемоеЗначение(Значение));
            Исключение
                // Игнорируем ошибки при получении реквизита
            КонецПопытки;

        КонецЦикла;

    КонецЕсли;

    // 3. Обрабатываем табличные части
    ТабличныеЧасти = МетаданныеОбъекта.ТабличныеЧасти;

    Если ТабличныеЧасти.Количество() > 0 Тогда

        МассивТабличныхЧастей = Новый Массив;

        Для Каждого ТабличнаяЧасть Из ТабличныеЧасти Цикл

            ИмяТЧ = ТабличнаяЧасть.Имя;

            СтруктураТЧ = Новый Структура;
            СтруктураТЧ.Вставить(ИмяТЧ, Новый Массив);

            Попытка

                КоличествоСтрок = ОбъектДанных[ИмяТЧ].Количество();

                Если КоличествоСтрок > 0 Тогда

                    // Получаем реквизиты табличной части
                    РеквизитыТЧ = ТабличнаяЧасть.Реквизиты;

                    Для Каждого СтрокаТЧ Из ОбъектДанных[ИмяТЧ] Цикл

                        СтрокаСтруктура = Новый Структура;

                        // Добавляем реквизиты строки
                        Для Каждого РеквизитТЧ Из РеквизитыТЧ Цикл

                            ИмяРеквизита = РеквизитТЧ.Имя;

                            Попытка
                                Значение = СтрокаТЧ[ИмяРеквизита];
                                СтрокаСтруктура.Вставить(ИмяРеквизита, ПолучитьСериализуемоеЗначение(Значение));
                            Исключение
                                // Игнорируем ошибки
                            КонецПопытки;

                        КонецЦикла;

                        МассивТабличныхЧастей[МассивТабличныхЧастей.ВГраница()][ИмяТЧ].Добавить(СтрокаСтруктура);

                    КонецЦикла;

                КонецЕсли;

            Исключение
                // Игнорируем ошибки при обработке табличной части
            КонецПопытки;

            МассивТабличныхЧастей.Добавить(СтруктураТЧ);

        КонецЦикла;

        // Добавляем табличные части в результат
        Результат.Вставить("ТабличныеЧасти", МассивТабличныхЧастей);

    КонецЕсли;

    Возврат Результат;

КонецФункции

// Функция получает реквизиты шапки для документа
//
// Параметры:
//  МетаданныеОбъекта - Объект метаданных
//
// Возвращаемое значение:
//  Коллекция - Реквизиты шапки
//
Функция ПолучитьРеквизитыШапки(МетаданныеОбъекта)

    // Для документов используем реквизиты шапки
    Если Метаданные.Документы.Содержит(МетаданныеОбъекта) Тогда
        Возврат МетаданныеОбъекта.Реквизиты;
    КонецЕсли;

    // Для других объектов также возвращаем реквизиты
    Возврат МетаданныеОбъекта.Реквизиты;

КонецФункции

// Функция преобразует значение в сериализуемое для структуры/JSON
//
// Параметры:
//  Значение - Произвольное значение
//
// Возвращаемое значение:
//  Произвольный - Сериализуемое значение
//
Функция ПолучитьСериализуемоеЗначение(Значение)

    Если Значение = Неопределено Тогда
        Возврат Null;
    КонецЕсли;

    ТипЗначения = ТипЗнч(Значение);

    // Обработка различных типов значений

    Если ТипЗначения = Тип("Дата") Тогда
        Возврат Формат(Значение, "ДФ=yyyy-MM-ddTHH:mm:ss");
    КонецЕсли;

    Если ТипЗначения = Тип("СправочникСсылка.*") 
        ИЛИ ТипЗначения = Тип("ДокументСсылка.*")
        ИЛИ ТипЗначения = Тип("ПланВидовХарактеристикСсылка.*")
        ИЛИ ТипЗначения = Тип("ПеречислениеСсылка.*")
        ИЛИ ТипЗначения = Тип("БизнесПроцессСсылка.*")
        ИЛИ ТипЗначения = Тип("ЗадачаСсылка.*") Тогда

        Если Значение.Пустая() Тогда
            Возврат Неопределено;
        КонецЕсли;

        Возврат Новый Структура("Ссылка, Наименование", 
            Значение.УникальныйИдентификатор(), 
            Строка(Значение));
    КонецЕсли;

    Если ТипЗначения = Тип("УникальныйИдентификатор") Тогда
        Возврат Строка(Значение);
    КонецЕсли;

    Если ТипЗначения = Тип("ХранилищеЗначения") Тогда
        Возврат Неопределено; // Хранилище значений не сериализуется просто
    КонецЕсли;

    // Для примитивных типов и объектов возвращаем значение как есть
    Возврат Значение;

КонецФункции

// Функция формирует отчет "ОстаткиТоваровНаСкладах" с отбором по складу и товару
// и возвращает значение из указанной ячейки табличного документа
//
// Параметры:
//   Склад  - СправочникСсылка.Склады - ссылка на склад для отбора
//   Товар  - СправочникСсылка.Товары  - ссылка на товар для отбора
//   Строка - Число - номер строки ячейки
//   Колонка - Число - номер колонки ячейки
//
// Возвращаемое значение:
//   Число - значение из указанной ячейки
//
Функция СформироватьОтчетПолучитьОстаток(Склад, Товар, Строка, Колонка) Экспорт

    // Проверка обязательных параметров
    Если Склад = Неопределено ИЛИ Склад = NULL Тогда
        ВызватьИсключение "Не указан склад для формирования отчета";
    КонецЕсли;

    Если Товар = Неопределено ИЛИ Товар = NULL Тогда
        ВызватьИсключение "Не указан товар для формирования отчета";
    КонецЕсли;

    // Проверка корректности координат ячейки
    Если НЕ ТипЗнч(Строка) = Тип("Число") ИЛИ НЕ ТипЗнч(Колонка) = Тип("Число") Тогда
        ВызватьИсключение "Параметры Строка и Колонка должны быть числовыми";
    КонецЕсли;

    Если Строка <= 0 ИЛИ Колонка <= 0 Тогда
        ВызватьИсключение "Параметры Строка и Колонка должны быть положительными";
    КонецЕсли;

    // Создаем объект отчета и получаем схему компоновки данных
    ОтчетОбъект = Отчеты.ОстаткиТоваровНаСкладах.Создать();
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создаем и инициализируем компоновщик настроек
    ИсточникДоступныхНастроек = Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных);
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных(СхемаКомпоновкиДанных);
    КомпоновщикНастроек.Инициализировать(ИсточникДоступныхНастроек);
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.НастройкиПоУмолчанию);

    // Устанавливаем параметры отбора
    КомпоновщикНастроек.Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("Склад", Склад);
    КомпоновщикНастроек.Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("Товар", Товар);

    // Подготавливаем расшифровку для хранения данных компоновки
    ДанныеРасшифровки = Новый ДанныеРасшифровкиКомпоновкиДанных;

    // Компилируем макет компоновки
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        КомпоновщикНастроек.Настройки,
        ДанныеРасшифровки
    );

    // Создаем процессор компоновки данных
    ПроцессорКомпоновкиДанных = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновкиДанных.Инициализировать(
        МакетКомпоновки,
        ,
        ДанныеРасшифровки
    );

    // Создаем табличный документ для результата
    Результат = Новый ТабличныйДокумент;

    // Создаем процессор вывода и формируем отчет
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Результат);
    ПроцессорВывода.Вывести(ПроцессорКомпоновкиДанных);

    // Получаем значение из указанной ячейки
    Если Строка <= Результат.ВысотаТаблицы И Колонка <= Результат.ШиринаТаблицы Тогда
        Область = Результат.ПолучитьОбласть(Строка, Колонка);
        ТекстЗначения = Область.ТекущаяОбласть.Текст;

        Попытка
            Возврат Цел(Число(ТекстЗначения));
        Исключение
            Возврат 0;
        КонецПопытки;
    Иначе
        Возврат 0;
    КонецЕсли;

КонецФункции

// Функция заполняет цены в табличной части "Товары" документа "Заказ"
// по виду цен из регистра сведений "Цены товаров" с пересчетом сумм.
//
// Параметры:
//  Заказ - ДокументСсылка.Заказ - ссылка на документ заказа
//  ВидЦен - СправочникСсылка.ВидыЦен - вид цен для заполнения
//
// Возвращаемое значение:
//  ДокументСсылка.Заказ - ссылка на обработанный заказ
//
Функция ЗаполнитьТабличнуюЧастьЗаказаЦенами(Заказ, ВидЦен) Экспорт

    ДокументОбъект = Заказ.ПолучитьОбъект();

    Запрос = Новый Запрос;

    // Формируем запрос в едином цикле обработки
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ТЧТовары.НомерСтроки,
    |    ТЧТовары.Товар,
    |    ТЧТовары.Количество,
    |    ТЧТовары.Цена,
    |    ТЧТовары.Сумма КАК СуммаИсходная
    |ПОМЕСТИТЬ ВТ_Товары
    |ИЗ
    |    Документ.Заказ.Товары КАК ТЧТовары
    |ГДЕ
    |    ТЧТовары.Ссылка = &Заказ
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ТЧ.НомерСтроки,
    |    ТЧ.Товар,
    |    ТЧ.Количество,
    |    ВЫБОР
    |        КОГДА ТЧ.Товар = ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка) ТОГДА
    |            0
    |        КОГДА Цены.Цена ЕСТЬ NULL ТОГДА
    |            NULL
    |        ИНАЧЕ
    |            Цены.Цена
    |    КОНЕЦ КАК Цена,
    |    ВЫБОР
    |        КОГДА ТЧ.Товар = ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка) ТОГДА
    |            0
    |        ИНАЧЕ
    |            ТЧ.Количество * ВЫБОР
    |                КОГДА Цены.Цена ЕСТЬ NULL ТОГДА
    |                    NULL
    |                ИНАЧЕ
    |                    Цены.Цена
    |            КОНЕЦ
    |    КОНЕЦ КАК Сумма
    |ИЗ
    |    ВТ_Товары КАК ТЧ
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних(
    |                &ДатаЦены,
    |                ВидЦен = &ВидЦен) КАК Цены
    |        ПО ТЧ.Товар = Цены.Товар
    |УПОРЯДОЧИТЬ ПО
    |    ТЧ.НомерСтроки";

    Запрос.УстановитьПараметр("Заказ", Заказ);
    Запрос.УстановитьПараметр("ДатаЦены", ДокументОбъект.Дата);
    Запрос.УстановитьПараметр("ВидЦен", ВидЦен);

    РезультатЗапроса = Запрос.Выполнить();

    // Обработка результата одним запросом (без дополнительных циклов)
    ДокументОбъект.Товары.Загрузить(РезультатЗапроса.Выгрузить());

    ДокументОбъект.Записать();

    Возврат Заказ;

КонецФункции

// Функция ПолучитьСреднююЦенуПоНоменклатуре
// Возвращает таблицу значений со средними ценами по каждой номенклатуре
//
// Параметры:
//  ТаблицаПродаж - ТаблицаЗначений - исходная таблица с колонками:
//   * Номенклатура (Строка)
//   * Количество (Число)
//   * СуммаПродажи (Число)
//
// Возвращаемое значение:
//  ТаблицаЗначений - с колонками:
//   * Номенклатура (Строка)
//   * Количество (Число)
//   * СуммаПродажи (Число)
//   * СредняяЦенаПродажи (Число)
//
Функция ПолучитьСреднююЦенуПоНоменклатуре(ТаблицаПродаж) Экспорт

    // Создаём запрос для обработки таблицы значений
    Запрос = Новый Запрос;
    Запрос.МенеджерВременныхТаблиц = Новый МенеджерВременныхТаблиц;

    // Помещаем таблицу значений в параметр запроса
    Запрос.УстановитьПараметр("ТаблицаПродаж", ТаблицаПродаж);

    // Формируем текст запроса
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ТаблицаПродаж.Номенклатура,
    |    ТаблицаПродаж.Количество,
    |    ТаблицаПродаж.СуммаПродажи
    |ПОМЕСТИТЬ ВременнаяТаблицаПродаж
    |ИЗ
    |    &ТаблицаПродаж КАК ТаблицаПродаж
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ВременнаяТаблицаПродаж.Номенклатура,
    |    СУММА(ВременнаяТаблицаПродаж.Количество) КАК Количество,
    |    СУММА(ВременнаяТаблицаПродаж.СуммаПродажи) КАК СуммаПродажи,
    |    ВЫБОР
    |        КОГДА СУММА(ВременнаяТаблицаПродаж.Количество) = 0
    |            ТОГДА 0
    |        ИНАЧЕ ОКРУГЛЕНИЕ(СУММА(ВременнаяТаблицаПродаж.СуммаПродажи) / СУММА(ВременнаяТаблицаПродаж.Количество), 2)
    |    КОНЕЦ КАК СредняяЦенаПродажи
    |ИЗ
    |    ВременнаяТаблицаПродаж КАК ВременнаяТаблицаПродаж
    |
    |СГРУППИРОВАТЬ ПО
    |    ВременнаяТаблицаПродаж.Номенклатура
    |
    |УПОРЯДОЧИТЬ ПО
    |    Номенклатура ВОЗР";

    // Выполняем запрос и возвращаем результат
    РезультатЗапроса = Запрос.Выполнить();

    Возврат РезультатЗапроса.Выгрузить();

КонецФункции

Функция ПолучитьОстатокНоменклатуры(Номенклатура, Склад, Дата) Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК Количество
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Период, ) КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |    ТоварныеЗапасыОстатки.Товар = &Товар
    |    И ТоварныеЗапасыОстатки.Склад = &Склад";

    Запрос.УстановитьПараметр("Период", Дата);
    Запрос.УстановитьПараметр("Товар", Номенклатура);
    Запрос.УстановитьПараметр("Склад", Склад);

    РезультатЗапроса = Запрос.Выполнить();

    Если РезультатЗапроса.Пустой() Тогда
        Возврат 0;
    КонецЕсли;

    Выборка = РезультатЗапроса.Выбрать();
    Выборка.Следующий();

    Возврат Выборка.Количество;

КонецФункции

Функция ЗагрузитьПрайсЛистИзCSV(ПутьКФайлу, ВидЦен) Экспорт

    // Формируем результирующую структуру
    Результат = Новый Структура;
    Результат.Вставить("КоличествоОбработанныхСтрок", 0);
    Результат.Вставить("ТаблицаОшибок", Новый ТаблицаЗначений);

    // Инициализируем таблицу ошибок
    ТаблицаОшибок = Результат.ТаблицаОшибок;
    ТаблицаОшибок.Колонки.Добавить("НомерСтроки", Новый ОписаниеТипов("Число"));
    ТаблицаОшибок.Колонки.Добавить("Причина", Новый ОписаниеТипов("Строка"));

    // Читаем CSV файл
    Текст = Новый ЧтениеТекста(ПутьКФайлу, КодировкаТекста.UTF8);

    // Разделитель колонок
    Разделитель = ";";

    // Пропускаем заголовок
    Текст.ПрочитатьСтроку();

    НомерСтроки = 1;

    // Читаем строки файла
    СтрокаФайла = Текст.ПрочитатьСтроку();
    Пока СтрокаФайла <> Неопределено Цикл
        НомерСтроки = НомерСтроки + 1;

        // Разбиваем строку по разделителю
        МассивСтрок = СтрРазделить(СтрокаФайла, Разделитель, Истина);

        // Проверяем количество колонок
        Если МассивСтрок.Количество() < 3 Тогда
            НоваяСтрокаОшибки = ТаблицаОшибок.Добавить();
            НоваяСтрокаОшибки.НомерСтроки = НомерСтроки;
            НоваяСтрокаОшибки.Причина = "Недостаточно колонок в строке (ожидалось 3)";

            СтрокаФайла = Текст.ПрочитатьСтроку();
            Продолжить;
        КонецЕсли;

        // Получаем данные из колонок
        Артикул = СокрЛП(МассивСтрок[0]);
        Наименование = СокрЛП(МассивСтрок[1]);
        ЦенаСтрока = СокрЛП(МассивСтрок[2]);

        // Проверяем обязательные поля
        Если ПустаяСтрока(Артикул) И ПустаяСтрока(Наименование) Тогда
            НоваяСтрокаОшибки = ТаблицаОшибок.Добавить();
            НоваяСтрокаОшибки.НомерСтроки = НомерСтроки;
            НоваяСтрокаОшибки.Причина = "Не указан артикул и наименование товара";

            СтрокаФайла = Текст.ПрочитатьСтроку();
            Продолжить;
        КонецЕсли;

        // Обрабатываем цену
        Цена = 0;
        Если Не ПустаяСтрока(ЦенаСтрока) Тогда
            Попытка
                Цена = Число(ЦенаСтрока);
            Исключение
                НоваяСтрокаОшибки = ТаблицаОшибок.Добавить();
                НоваяСтрокаОшибки.НомерСтроки = НомерСтроки;
                НоваяСтрокаОшибки.Причина = "Некорректное значение цены: """ + ЦенаСтрока + """";

                СтрокаФайла = Текст.ПрочитатьСтроку();
                Продолжить;
            КонецПопытки;
        КонецЕсли;

        // Ищем товар
        Товар = НайтиТовар(Артикул, Наименование);

        Если Товар = Неопределено Тогда
            ТекстОшибки = "Товар не найден";
            Если Не ПустаяСтрока(Артикул) Тогда
                ТекстОшибки = ТекстОшибки + " (артикул: """ + Артикул + """)";
            КонецЕсли;
            Если Не ПустаяСтрока(Наименование) Тогда
                ТекстОшибки = ТекстОшибки + " (наименование: """ + Наименование + """)";
            КонецЕсли;

            НоваяСтрокаОшибки = ТаблицаОшибок.Добавить();
            НоваяСтрокаОшибки.НомерСтроки = НомерСтроки;
            НоваяСтрокаОшибки.Причина = ТекстОшибки;

            СтрокаФайла = Текст.ПрочитатьСтроку();
            Продолжить;
        КонецЕсли;

        // Записываем цену в регистр сведений
        Попытка
            НаборЗаписей = РегистрыСведений.ЦеныТоваров.СоздатьНаборЗаписей();

            // Устанавливаем отборы
            НаборЗаписей.Отбор.Товар.Установить(Товар);
            НаборЗаписей.Отбор.ВидЦен.Установить(ВидЦен);

            // Читаем существующие записи
            НаборЗаписей.Прочитать();

            // Очищаем набор (удаляем старые записи)
            НаборЗаписей.Очистить();

            // Добавляем новую запись
            Запись = НаборЗаписей.Добавить();
            Запись.Период = НачалоДня(ТекущаяДата());
            Запись.Товар = Товар;
            Запись.ВидЦен = ВидЦен;
            Запись.Цена = Цена;

            // Записываем
            НаборЗаписей.Записать();

            Результат.КоличествоОбработанныхСтрок = Результат.КоличествоОбработанныхСтрок + 1;

        Исключение
            НоваяСтрокаОшибки = ТаблицаОшибок.Добавить();
            НоваяСтрокаОшибки.НомерСтроки = НомерСтроки;
            НоваяСтрокаОшибки.Причина = "Ошибка записи цены: " + ОписаниеОшибки();
        КонецПопытки;

        СтрокаФайла = Текст.ПрочитатьСтроку();
    КонецЦикла;

    Текст.Закрыть();

    Возврат Результат;

КонецФункции

