// Функция получает актуальную цену товара на указанную дату
//
// Параметры:
//   Товар    - СправочникСсылка.Товары - товар, для которого получаем цену
//   ВидЦен   - СправочникСсылка.ВидыЦен - вид цены
//   Дата     - Дата - дата, на которую получаем цену
//
// Возвращаемое значение:
//   Число - цена товара (0 если цена не найдена)
//
Функция ПолучитьАктуальнуюЦену(Товар, ВидЦен, Дата) Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЦеныТоваровСрезПоследних.Цена
    |ИЗ
    |    РегистрСведений.ЦеныТоваров.СрезПоследних(
    |            &Дата,
    |            Товар = &Товар
    |            И ВидЦен = &ВидЦен
    |        ) КАК ЦеныТоваровСрезПоследних";

    Запрос.УстановитьПараметр("Товар", Товар);
    Запрос.УстановитьПараметр("ВидЦен", ВидЦен);
    Запрос.УстановитьПараметр("Дата", Дата);

    Результат = Запрос.Выполнить();

    Если Результат.Пустой() Тогда
        Возврат 0;
    КонецЕсли;

    Выборка = Результат.Выбрать();
    Выборка.Следующий();

    Возврат Выборка.Цена;

КонецФункции

// Функция выгружает таблицу значений в CSV-файл
// Параметры:
//   ТаблицаДанных - ТаблицаЗначений - данные для выгрузки
//   ПутьФайла - Строка - полный путь к файлу (если пусто - создается во временном каталоге)
// Возвращаемое значение:
//   Строка - путь к созданному файлу
//
Функция ВыгрузитьТаблицуВCSV(ТаблицаДанных, ПутьФайла) Экспорт

    // Определяем путь к файлу
    Если ПустаяСтрока(ПутьФайла) Тогда
        ПутьКФайлу = ПолучитьИмяВременногоФайла("csv");
    Иначе
        ПутьКФайлу = ПутьФайла;
    КонецЕсли;

    // Создаем текстовый документ для записи
    ЗаписьТекста = Новый ЗаписьТекста(
        ПутьКФайлу,
        КодировкаТекста.UTF8,
        Символы.ПС,
        Ложь// добавлять перевод строки в конце файла
    );

    Попытка

        // Записываем заголовки колонок
        СтрокаЗаголовков = "";
        Для Каждого Колонка Из ТаблицаДанных.Колонки Цикл
            СтрокаЗаголовков = СтрокаЗаголовков + Колонка.Имя + ";";
        КонецЦикла;

        // Удаляем последний разделитель
        Если СтрДлина(СтрокаЗаголовков) > 0 Тогда
            СтрокаЗаголовков = Лев(СтрокаЗаголовков, СтрДлина(СтрокаЗаголовков) - 1);
        КонецЕсли;

        ЗаписьТекста.ЗаписатьСтроку(СтрокаЗаголовков);

        // Записываем данные строк
        Для Каждого СтрокаТаблицы Из ТаблицаДанных Цикл

            СтрокаДанных = "";

            Для Каждого Колонка Из ТаблицаДанных.Колонки Цикл

                Значение = СтрокаТаблицы[Колонка.Имя];

                // Преобразуем значение в строку с учетом типа
                Если ЗначениеЗаполнено(Значение) Тогда

                    ТипЗначения = ТипЗнч(Значение);

                    Если ТипЗначения = Тип("Строка") Тогда

                        // Экранируем специальные символы в строке
                        ТекстовоеЗначение = Значение;
                        ТекстовоеЗначение = СтрЗаменить(ТекстовоеЗначение, Символы.ПС, " ");
                        ТекстовоеЗначение = СтрЗаменить(ТекстовоеЗначение, Символы.ВК, " ");
                        ТекстовоеЗначение = СтрЗаменить(ТекстовоеЗначение, """", """""");

                        // Если есть разделитель или кавычки - оборачиваем в кавычки
                        Если СтрНайти(ТекстовоеЗначение, ";") > 0 
                            Или СтрНайти(ТекстовоеЗначение, """") > 0 Тогда
                            ТекстовоеЗначение = """" + ТекстовоеЗначение + """";
                        КонецЕсли;

                        СтрокаДанных = СтрокаДанных + ТекстовоеЗначение + ";";

                    ИначеЕсли ТипЗначения = Тип("Число") Тогда
                        СтрокаДанных = СтрокаДанных + Строка(Значение) + ";";

                    ИначеЕсли ТипЗначения = Тип("Дата") Тогда
                        СтрокаДанных = СтрокаДанных 
                            + Формат(Значение, "ДФ=""гггг-ММ-ддЧЧ:мм:сс""") + ";";

                    ИначеЕсли ТипЗначения = Тип("Булево") Тогда
                        СтрокаДанных = СтрокаДанных + ?(Значение, "1", "0") + ";";

                    Иначе
                        // Для ссылочных типов вызываем метод ЗначениеВСтрокуВнутр
                        // чтобы получить представление с типом
                        СтрокаДанных = СтрокаДанных + Строка(Значение) + ";";

                    КонецЕсли;

                Иначе
                    // Для пустых значений записываем пустую строку
                    СтрокаДанных = СтрокаДанных + ";";

                КонецЕсли;

            КонецЦикла;

            // Удаляем последний разделитель
            Если СтрДлина(СтрокаДанных) > 0 Тогда
                СтрокаДанных = Лев(СтрокаДанных, СтрДлина(СтрокаДанных) - 1);
            КонецЕсли;

            ЗаписьТекста.ЗаписатьСтроку(СтрокаДанных);

        КонецЦикла;

        // Закрываем файл
        ЗаписьТекста.Закрыть();

    Исключение

        // В случае ошибки закрываем файл и пробрасываем исключение
        ЗаписьТекста.Закрыть();
        ВызватьИсключение;

    КонецПопытки;

    Возврат ПутьКФайлу;

КонецФункции

// Функция сворачивает дубликаты строк по полю "КлючСтроки"
// и суммирует значения для каждого уникального ключа
//
// Параметры:
//   ТаблицаДанных - ТаблицаЗначений с колонками:
//                   КлючСтроки (Строка), Значение (Число)
//
// Возвращает:
//   ТаблицаЗначений - сгруппированная таблица
//
Функция СвернутьДубли(ТаблицаДанных) Экспорт

    // Создаём объект запроса
    Запрос = Новый Запрос;

    // Формируем текст запроса для группировки данных
    // Используем параметр таблицы для передачи входных данных
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТаблицаДанных.КлючСтроки,
    |    СУММА(ТаблицаДанных.Значение) КАК Значение
    |ИЗ
    |    &ТаблицаДанных КАК ТаблицаДанных
    |СГРУППИРОВАТЬ ПО
    |    ТаблицаДанных.КлючСтроки
    |УПОРЯДОЧИТЬ ПО
    |    КлючСтроки";

    // Устанавливаем параметр с входной таблицей
    // Временная таблица не изменяется
    Запрос.УстановитьПараметр("ТаблицаДанных", ТаблицаДанных);

    // Выполняем запрос и выгружаем результат в таблицу значений
    Результат = Запрос.Выполнить().Выгрузить();

    Возврат Результат;

КонецФункции

// Функция получает средний курс валюты за указанный период
//
// Параметры:
//   Валюта        - СправочникСсылка.Валюты - Валюта, для которой получаем курс
//   ДатаНачала    - Дата - Начало периода
//   ДатаОкончания - Дата - Конец периода
//
// Возвращаемое значение:
//   Число - Средний курс валюты с точностью 4 знака после запятой
//   Неопределено - Если курс валюты отсутствует
//
Функция ПолучитьСреднийКурс(Валюта, ДатаНачала, ДатаОкончания) Экспорт

    // Проверяем наличие валюты на дату окончания периода
    ЗапросСрез = Новый Запрос;
    ЗапросСрез.Текст =
    "ВЫБРАТЬ ПЕРВЫЕ 1
    |    КурсыВалютСрезПоследних.Курс
    |ИЗ
    |    РегистрСведений.КурсыВалют.СрезПоследних(&Период, Валюта = &Валюта) КАК КурсыВалютСрезПоследних";

    ЗапросСрез.УстановитьПараметр("Период", ДатаОкончания);
    ЗапросСрез.УстановитьПараметр("Валюта", Валюта);

    РезультатСреза = ЗапросСрез.Выполнить();

    // Если курс отсутствует - возвращаем Неопределено
    Если РезультатСреза.Пустой() Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Получаем средний курс за период
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ВЫРАЗИТЬ(СРЕДНЕЕ(КурсыВалют.Курс) КАК ЧИСЛО(10, 4)) КАК СреднийКурс
    |ИЗ
    |    РегистрСведений.КурсыВалют.СрезПоследних(
    |            &ДатаОкончания,
    |            Валюта = &Валюта
    |        ) КАК КурсыВалют";

    Запрос.УстановитьПараметр("Валюта", Валюта);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

    Результат = Запрос.Выполнить();

    Выборка = Результат.Выбрать();

    Если Выборка.Следующий() Тогда
        // Если средний курс не определен - возвращаем Неопределено
        Если НЕ ЗначениеЗаполнено(Выборка.СреднийКурс) Тогда
            Возврат Неопределено;
        КонецЕсли;

        Возврат Выборка.СреднийКурс;
    КонецЕсли;

    Возврат Неопределено;

КонецФункции

// Функция добавляет характеристику товара и присваивает заданное значение характеристики.
//
Функция ДобавитьХарактеристикуТовара(Товар, ВидХарактеристики, Значение, Замещать) Экспорт

    // Создаём набор записей регистра сведений
    НаборЗаписей = РегистрыСведений.Характеристики.СоздатьНаборЗаписей();
    НаборЗаписей.Отбор.Объект.Установить(Товар);
    НаборЗаписей.Отбор.ВидХарактеристики.Установить(ВидХарактеристики);

    // Запрос для получения информации о существующих записях
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Характеристики.Номер,
    |    Характеристики.Регистратор
    |ПОМЕСТИТЬ СуществующиеЗаписи
    |ИЗ РегистрСведений.Характеристики КАК Характеристики
    |ГДЕ Характеристики.Объект = &Объект
    |    И Характеристики.ВидХарактеристики = &ВидХарактеристики
    |УПОРЯДОЧИТЬ ПО Характеристики.Номер УБЫВ
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ЕСТЬNULL(КОЛИЧЕСТВО(СуществующиеЗаписи.Номер), 0) КАК Количество,
    |    ЕСТЬNULL(МАКСИМУМ(СуществующиеЗаписи.Номер), 0) КАК МаксимальныйНомер,
    |    ВЫБОР
    |        КОГДА КОЛИЧЕСТВО(СуществующиеЗаписи.Номер) = 0
    |        ТОГДА ЗНАЧЕНИЕ(РегистрСведенийЗапись.Характеристики.ПустаяСсылка)
    |        ИНАЧЕ МАКСИМУМ(СуществующиеЗаписи.Регистратор)
    |    КОНЕЦ КАК СсылкаНаЗапись
    |ИЗ
    |    СуществующиеЗаписи КАК СуществующиеЗаписи";

    Запрос.УстановитьПараметр("Объект", Товар);
    Запрос.УстановитьПараметр("ВидХарактеристики", ВидХарактеристики);

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // Получаем данные из запроса
    Если Выборка.Следующий() Тогда
        СчетчикЗаписей = Выборка.Количество;
        МаксимальныйНомер = Выборка.МаксимальныйНомер;
        СсылкаНаЗапись = Выборка.СсылкаНаЗапись;
    Иначе
        СчетчикЗаписей = 0;
        МаксимальныйНомер = 0;
        СсылкаНаЗапись = Неопределено;
    КонецЕсли;

    // Обработка в зависимости от количества существующих записей
    Если СчетчикЗаписей = 0 Тогда
        // Записей не существует - добавляем новую запись
        Запись = НаборЗаписей.Добавить();
        Запись.Объект = Товар;
        Запись.ВидХарактеристики = ВидХарактеристики;
        Запись.Номер = 1;
        Запись.Значение = Значение;

        НаборЗаписей.Записать();
    Иначе
        // Записи существуют
        Если Замещать Тогда
            // Замещаем существующую запись новой
            // Если найдена одна запись - замещаем её
            Если СчетчикЗаписей = 1 Тогда
                // Загружаем существующую запись для замещения
                НаборЗаписей.Прочитать();

                // Замещаем значение
                Если НаборЗаписей.Количество() > 0 Тогда
                    НаборЗаписей[0].Значение = Значение;
                Иначе
                    // На всякий случай добавляем запись
                    Запись = НаборЗаписей.Добавить();
                    Запись.Объект = Товар;
                    Запись.ВидХарактеристики = ВидХарактеристики;
                    Запись.Номер = 1;
                    Запись.Значение = Значение;
                КонецЕсли;

                НаборЗаписей.Записать(Истина);
            Иначе
                // Если записей больше одной - удаляем все и добавляем одну новую
                НаборЗаписей.Очистить();

                Запись = НаборЗаписей.Добавить();
                Запись.Объект = Товар;
                Запись.ВидХарактеристики = ВидХарактеристики;
                Запись.Номер = МаксимальныйНомер + 1;
                Запись.Значение = Значение;

                НаборЗаписей.Записать(Истина);
            КонецЕсли;
        Иначе
            // Замещать = Ложь
            Если СчетчикЗаписей = 1 Тогда
                // Одна запись - новая запись не добавляется
                Возврат Истина;
            Иначе
                // Добавляем новую запись с увеличенным номером
                Запись = НаборЗаписей.Добавить();
                Запись.Объект = Товар;
                Запись.ВидХарактеристики = ВидХарактеристики;
                Запись.Номер = МаксимальныйНомер + 1;
                Запись.Значение = Значение;

                НаборЗаписей.Записать();
            КонецЕсли;
        КонецЕсли;
    КонецЕсли;

    Возврат Истина;

КонецФункции

// Функция ищет в структуре настроек отчета группировку по имени элемента.
//
// Параметры:
//  Структура - КоллекцияЭлементовСтруктурыНастроекКомпоновкиДанных - набор группировок
//              данного уровня настроек.
//  Имя - Строка - имя искомого элемента структуры отчета.
//
// Возвращаемое значение:
//  ГруппировкаКомпоновкиДанных, ТаблицаКомпоновкиДанных,
//  ГруппировкаТаблицыКомпоновкиДанных, ГруппировкаДиаграммыКомпоновкиДанных,
//  ДиаграммаКомпоновкиДанных - найденный элемент структуры.
//  Неопределено - группировка не найдена.
//
Функция НайтиГруппировкуПоИмени(Структура, Имя) Экспорт

    Если Структура = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    Для Каждого ЭлементСтруктуры Из Структура Цикл

        // Проверяем имя текущего элемента
        Если ЭлементСтруктуры.Имя = Имя Тогда
            Возврат ЭлементСтруктуры;
        КонецЕсли;

        // Для таблицы проверяем строки и колонки отдельно
        Если ТипЗнч(ЭлементСтруктуры) = Тип("ТаблицаКомпоновкиДанных") Тогда

            Результат = НайтиГруппировкуПоИмени(ЭлементСтруктуры.Строки, Имя);
            Если Результат <> Неопределено Тогда
                Возврат Результат;
            КонецЕсли;

            Результат = НайтиГруппировкуПоИмени(ЭлементСтруктуры.Колонки, Имя);
            Если Результат <> Неопределено Тогда
                Возврат Результат;
            КонецЕсли;

        ИначеЕсли ТипЗнч(ЭлементСтруктуры) = Тип("ДиаграммаКомпоновкиДанных") Тогда

            // Для диаграммы проверяем её структуру
            Результат = НайтиГруппировкуПоИмени(ЭлементСтруктуры.Структура, Имя);
            Если Результат <> Неопределено Тогда
                Возврат Результат;
            КонецЕсли;

        Иначе
            // Для группировок и их вложенных элементов
            Результат = НайтиГруппировкуПоИмени(ЭлементСтруктуры.Структура, Имя);
            Если Результат <> Неопределено Тогда
                Возврат Результат;
            КонецЕсли;

        КонецЕсли;

    КонецЦикла;

    Возврат Неопределено;

КонецФункции

// Возвращает структуру значений реквизитов объекта по ссылке.
//
// Параметры:
//  Ссылка - ЛюбаяСсылка - ссылка на объект, реквизиты которого необходимо получить.
//  Реквизиты - Строка, Структура, ФиксированнаяСтруктура, Массив, ФиксированныйМассив - 
//              имена реквизитов в формате требований к свойствам структуры.
//
// Возвращаемое значение:
//  Структура - значения реквизитов.
//  РезультатЗапроса - если запрошены поля табличной части.
//
Функция ЗначенияРеквизитовОбъекта(Ссылка, Реквизиты) Экспорт

    // Проверка на пустую строку
    Если ТипЗнч(Реквизиты) = Тип("Строка") И СокрЛП(Реквизиты) = "" Тогда
        Возврат Новый Структура;
    КонецЕсли;

    // Проверка на пустой массив
    МассивРеквизитов = Неопределено;
    Если ТипЗнч(Реквизиты) = Тип("Массив") ИЛИ ТипЗнч(Реквизиты) = Тип("ФиксированныйМассив") Тогда
        МассивРеквизитов = Реквизиты;
        Если МассивРеквизитов.Количество() = 0 Тогда
            Возврат Новый Структура;
        КонецЕсли;
    КонецЕсли;

    // Проверка на пустую структуру
    Если (ТипЗнч(Реквизиты) = Тип("Структура") Или ТипЗнч(Реквизиты) = Тип("ФиксированнаяСтруктура"))
        И Реквизиты.Количество() = 0 Тогда
        Возврат Новый Структура;
    КонецЕсли;

    // Инициализация коллекций
    fieldNames        = Новый Соответствие; // Alias -> FieldName (для запроса)
    tablePartFields   = Новый Соответствие; // TablePartName -> FieldName (поля табличных частей)
    fieldNameFromKey  = Новый Соответствие; // Alias -> Поле для возврата структуры

    // Разбор параметра Реквизиты
    Если МассивРеквизитов <> Неопределено Тогда

        // Массив строк
        Для Каждого Элемент Из МассивРеквизитов Цикл
            fieldName = Строка(Элемент);
            Если СокрЛП(fieldName) = "" Тогда
                Продолжить;
            КонецЕсли;
            value       = "";
            alias       = fieldName;
            fieldNames.Вставить(alias, fieldName);
            fieldNameFromKey.Вставить(alias, fieldName);
        КонецЕсли;

    ИначеЕсли ТипЗнч(Реквизиты) = Тип("Структура") Или ТипЗнч(Реквизиты) = Тип("ФиксированнаяСтруктура") Тогда

        // Структура: ключ = alias, значение = fieldName (опционально)
        Для Каждого КЗ Из Реквизиты Цикл
            alias     = КЗ.Ключ;
            value     = КЗ.Значение;
            fieldName = ?(value <> Неопределено И ЗначениеЗаполнено(value), value, alias);
            fieldNames.Вставить(alias, fieldName);
            fieldNameFromKey.Вставить(alias, fieldName);
        КонецЕсли;

    Иначе

        // Строка: имена через запятую
        parts = СтрРазделить(Реквизиты, ",", Ложь);
        Для Каждого part Из parts Цикл
            fieldName = СокрЛП(part);
            Если fieldName = "" Тогда
                Продолжить;
            КонецЕсли;
            value       = "";
            alias       = fieldName;
            fieldNames.Вставить(alias, fieldName);
            fieldNameFromKey.Вставить(alias, fieldName);
        КонецЕсли;

    КонецЕсли;

    // Нормализация: разбор dotted notation (например "Товары.Номенклатура")
    normalizedFields       = Новый Соответствие;
    tablePartFieldNamesMap = Новый Соответствие; // Alias -> Структура("TablePartName", "FieldName")

    Для Каждого КЗ Из fieldNames Цикл
        alias     = КЗ.Ключ;
        fieldName = КЗ.Значение;

        Если СтрНайти(fieldName, ".") > 0 Тогда
            parts = СтрРазделить(fieldName, ".", Истина);
            Если parts.Количество() = 2 Тогда
                tablePartName = СокрЛП(parts[0]);
                fieldSimple   = СокрЛП(parts[1]);
                normalizedFields.Вставить(alias, fieldSimple);
                tablePartFieldNamesMap.Вставить(alias, 
                    Новый Структура("TablePartName, FieldName", tablePartName, fieldSimple));
                tablePartFields.Вставить(tablePartName, fieldSimple);
            Иначе
                normalizedFields.Вставить(alias, fieldName);
            КонецЕсли;
        Иначе
            normalizedFields.Вставить(alias, fieldName);
        КонецЕсли;
    КонецЕсли;

    // Проверка на битую ссылку
   Если Ссылка.Пустая() Тогда
        Результат = Новый Структура;
        Для Каждого КЗ Из fieldNameFromKey Цикл
            Результат.Вставить(КЗ.Ключ, Неопределено);
        КонецДо;
        Возврат Результат;
    КонецЕсли;

    // Попытка получения объекта для определения битой ссылки
    ТестОбъект = Ссылка.ПолучитьОбъект();
    Если ТестОбъект = Неопределено Тогда
        Результат = Новый Структура;
        Для Каждого КЗ Из fieldNameFromKey Цикл
            Результат.Вставить(КЗ.Ключ, Неопределено);
        КонецДо;
        Возврат Результат;
    КонецЕсли;

    // Определение типа объекта
    МетаОбъект = Ссылка.Метаданные();
    ИмяТаблицы = МетаОбъект.Имя;
    ЕстьТабличныеЧасти = МетаОбъект.ТабличныеЧасти.Количество() > 0;

    // Определение типа запроса: табличная часть или основная таблица
    tablePartNameRequest = "";
    Если tablePartFields.Количество() = 1 И normalizedFields.Количество() = 1 Тогда
        // Единственное поле — может быть табличной частью целиком
        Для Каждого КЗ Из normalizedFields Цикл
            Если ЕстьТабличныеЧасти И МетаОбъект.ТабличныеЧасти.Найти(КЗ.Значение) <> Неопределено Тогда
                tablePartNameRequest = КЗ.Значение;
                Прервать;
            КонецЕсли;
        КонецДо;
    КонецЕсли;

    // Запрос
    Запрос = Новый Запрос;

    Если tablePartNameRequest <> "" Тогда
        // Запрос одной табличной части целиком
        Запрос.Текст =
        "ВЫБРАТЬ
        |   ТЧ.*
        |ИЗ
        |   &ИмяТаблицы КАК ТЧ
        |ГДЕ
        |   ТЧ.Ссылка = &Ссылка";
        Запрос.Текст = СтрЗаменить(Запрос.Текст, "&ИмяТаблицы", "Документ." + ИмяТаблицы + "." + tablePartNameRequest);
        Запрос.УстановитьПараметр("Ссылка", Ссылка);
        Возврат Запрос.Выполнить();

    ИначеЕсли tablePartFields.Количество() > 0 Тогда

        // Запрос с полями табличной части
        Запрос.Текст =
        "ВЫБРАТЬ
        |   ТЧ.Ссылка КАК Ссылка
        |ИЗ
        |   Документ." + ИмяТаблицы + "." + tablePartFields[0].Ключ + " КАК ТЧ
        |ГДЕ
        |   ТЧ.Ссылка = &Ссылка";
        Запрос.УстановитьПараметр("Ссылка", Ссылка);

    Иначе

        // Запрос основной таблицы
        Запрос.Текст =
        "ВЫБРАТЬ
        |   Ссылка
        |ИЗ
        |   Документ." + ИмяТаблицы + " КАК Т
        |ГДЕ
        |   Т.Ссылка = &Ссылка";
        Запрос.УстановитьПараметр("Ссылка", Ссылка);

    КонецЕсли;

    // Добавление полей запроса
    Для Каждого КЗ Из normalizedFields Цикл
        alias     = КЗ.Ключ;
        fieldName = КЗ.Значение;

        Если tablePartFieldNamesMap.Получить(alias) <> Неопределено Тогда
            // Поле табличной части — добавлено выше
        Иначе
            Если СтрНайти(fieldName, ".") = 0 Тогда
                Запрос.Текст = Запрос.Текст + ",
                |   Т." + fieldName + " КАК " + alias;
            КонецЕсли;
        КонецЕсли;
    КонецЕсли;

    // Добавление полей табличных частей, если есть
    Если tablePartFields.Количество() > 0 Тогда
        Для Каждого КЗ Из tablePartFields Цикл
            Запрос.Текст = Запрос.Текст + ",
            |   ТЧ." + КЗ.Значение + " КАК " + КЗ.Ключ;
        КонецДо;
    КонецЕсли;

    // Выполнение запроса
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();
    Выборка.Следующий();

    // Формирование результата
    Результат = Новый Структура;
    ВыборкаМета = РезультатЗапроса.Выбрать();

    Если ВыборкаМета.Количество() > 0 Тогда
        ВыборкаМета.Следующий();
        МетаВыборки = РезультатЗапроса.Выбрать();

        Для Каждого КЗ Из fieldNameFromKey Цикл
            alias       = КЗ.Ключ;
            fieldSource = КЗ.Значение; // что было передано

            Если tablePartFieldNamesMap.Получить(alias) <> Неопределено Тогда
                // Табличная часть — возврат запроса
                Результат.Вставить(alias, Неопределено);
            Иначе
                Результат.Вставить(alias, Выборка[alias]);
            КонецЕсли;
        КонецДо;
    Иначе
        Для Каждого КЗ Из fieldNameFromKey Цикл
            Результат.Вставить(КЗ.Ключ, Неопределено);
        КонецДо;
    КонецЕсли;

    Возврат Результат;

КонецФункции

// Функция подставляет параметры в строку по шаблону
// Параметры в шаблоне задаются как %<номер> (начиная с 1)
//
// Параметры:
//   ШаблонСтроки - Строка - шаблон с параметрами вида %1, %2 и т.д.
//   Параметр1 - Строка - значение параметра 1
//   Параметр2 - Строка - значение параметра 2
//   Параметр3 - Строка - значение параметра 3
//   Параметр4 - Строка - значение параметра 4
//   Параметр5 - Строка - значение параметра 5
//
// Возвращаемое значение:
//   Строка - строка с подставленными параметрами
//
Функция ПодставитьПараметрыВСтроку(ШаблонСтроки, Параметр1, Параметр2, Параметр3, Параметр4, Параметр5) Экспорт

    Результат = ШаблонСтроки;

    Результат = СтрЗаменить(Результат, "%1", Параметр1);
    Результат = СтрЗаменить(Результат, "%2", Параметр2);
    Результат = СтрЗаменить(Результат, "%3", Параметр3);
    Результат = СтрЗаменить(Результат, "%4", Параметр4);
    Результат = СтрЗаменить(Результат, "%5", Параметр5);

    Возврат Результат;

КонецФункции

// Функция формирует реестр документов реализации товаров
//
// Возвращаемое значение:
//  ТаблицаЗначений - таблица с реестром реализаций
//
Функция СформироватьРеестрРеализаций() Экспорт

    // Создаём результирующую таблицу значений
    РеестрРеализаций = Новый ТаблицаЗначений;

    // Добавляем колонки в таблицу
    РеестрРеализаций.Колонки.Добавить("Дата",       Новый ОписаниеТипов("Дата", , , Новый КвалификаторыДаты(ЧастиДаты.Дата)));
    РеестрРеализаций.Колонки.Добавить("Покупатель", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    РеестрРеализаций.Колонки.Добавить("Склад",       Новый ОписаниеТипов("СправочникСсылка.Склады"));
    РеестрРеализаций.Колонки.Добавить("Валюта",      Новый ОписаниеТипов("СправочникСсылка.Валюты"));
    РеестрРеализаций.Колонки.Добавить("ВидЦен",      Новый ОписаниеТипов("СправочникСсылка.ВидыЦен"));

    // Формируем запрос к документу РасходТовара
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    РасходТовара.Дата КАК Дата,
    |    РасходТовара.Покупатель КАК Покупатель,
    |    РасходТовара.Склад КАК Склад,
    |    РасходТовара.Валюта КАК Валюта,
    |    РасходТовара.ВидЦен КАК ВидЦен
    |ИЗ
    |    Документ.РасходТовара КАК РасходТовара
    |ГДЕ
    |    РасходТовара.Проведен = ИСТИНА
    |УПОРЯДОЧИТЬ ПО
    |    РасходТовара.Дата УБЫВ";

    // Выполняем запрос и выгружаем результат в таблицу значений
    РезультатЗапроса = Запрос.Выполнить();

    Если НЕ РезультатЗапроса.Пустой() Тогда
        РеестрРеализаций = РезультатЗапроса.Выгрузить();
    КонецЕсли;

    // Возвращаем сформированную таблицу
    Возврат РеестрРеализаций;

КонецФункции

// Функция формирует таблицу заказов за период с пересчетом суммы по курсу валют
//
// Параметры:
//   ДатаНачала - Дата - дата начала периода (если пустая, без ограничений)
//   ДатаОкончания - Дата - дата окончания периода (если пустая, без ограничений)
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками: Дата, Заказ, Сумма, Покупатель
//
Функция ПолучитьТаблицуЗаказовПоКурсуВалют(ДатаНачала, ДатаОкончания) Экспорт

    // Создаём таблицу значений с нужными колонками
    ТаблицаЗаказов = Новый ТаблицаЗначений;
    ТаблицаЗаказов.Колонки.Добавить("Дата",       Новый ОписаниеТипов("Число"));
    ТаблицаЗаказов.Колонки.Добавить("Заказ",      Новый ОписаниеТипов("ДокументСсылка.Заказ"));
    ТаблицаЗаказов.Колонки.Добавить("Сумма",      Новый ОписаниеТипов("Число"));
    ТаблицаЗаказов.Колонки.Добавить("Покупатель", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));

    // Формируем текст запроса
    Запрос = Новый Запрос;

    // Формируем условие по датам динамически
    МассивУсловий = Новый Массив;
    МассивУсловий.Добавить("НЕ Заказ.ПометкаУдаления");

    Если ЗначениеЗаполнено(ДатаНачала) Тогда
        МассивУсловий.Добавить("Заказ.Дата >= &ДатаНачала");
        Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    КонецЕсли;

    Если ЗначениеЗаполнено(ДатаОкончания) Тогда
        МассивУсловий.Добавить("Заказ.Дата <= &ДатаОкончания");
        Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    КонецЕсли;

    // Если обе даты пустые - условие по дате не добавляется (выбираем все)

    ТекстУсловия = СтрСоединить(МассивУсловий, Символы.ПС + "    И ");

    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Заказ.Дата КАК Дата,
    |    Заказ.Ссылка КАК Заказ,
    |    Заказ.Сумма / ЕСТЬNULL(КурсыВалют.Курс, 1) КАК Сумма,
    |    Заказ.Покупатель КАК Покупатель
    |ИЗ
    |    Документ.Заказ КАК Заказ
    |    ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.КурсыВалют.СрезПоследних(
    |        ,
    |        Валюта В (
    |            ВЫБРАТЬ РАЗЛИЧНЫЕ
    |                ЗаказВнутр.Валюта
    |            ИЗ Документ.Заказ КАК ЗаказВнутр
    |            ГДЕ &УсловиеПоВалюте
    |        )
    |    ) КАК КурсыВалют
    |    ПО Заказ.Валюта = КурсыВалют.Валюта
    |        И КурсыВалют.Период = (
    |            ВЫБРАТЬ МАКСИМУМ(КурсыВнутр.Период)
    |            ИЗ РегистрСведений.КурсыВалют КАК КурсыВнутр
    |            ГДЕ КурсыВнутр.Валюта = Заказ.Валюта
    |                И КурсыВнутр.Период <= Заказ.Дата
    |        )
    |ГДЕ
    |    " + ТекстУсловия + "
    |УПОРЯДОЧИТЬ ПО
    |    Заказ.Дата УБЫВ
    |";

    // Устанавливаем параметры для условия по валюте (без ограничений = истина)
    Если МассивУсловий.Количество() > 1 Тогда
        // Были добавлены условия по датам, нужен подзапрос для валют
        ТекстПоВалюте = "ЗаказВнутр.Дата МЕЖДУ &ДатаНачала И &ДатаОкончания";
    Иначе
        // Только пометка удаления, условие по валюте не нужно
        ТекстПоВалюте = "ИСТИНА";
    КонецЕсли;

    Запрос.Текст = СтрЗаменить(Запрос.Текст, "&УсловиеПоВалюте", ТекстПоВалюте);

    РезультатЗапроса = Запрос.Выполнить();
    ТаблицаЗаказов = РезультатЗапроса.Выгрузить();

    Возврат ТаблицаЗаказов;

КонецФункции

// Функция формирует отчет "ОтчетПоВзаиморасчетам" с задолженностью контрагентов
//
// Параметры:
//  ДатаНачала - Дата - начало периода отчета
//  ДатаОкончания - Дата - окончание периода отчета
//  Валюта - СправочникСсылка.Валюты - валюта для отбора
//
// Возвращаемое значение:
//  ТабличныйДокумент - сформированный отчет
//
Функция СформироватьОтчетЗадолженностьКонтрагентов(ДатаНачала, ДатаОкончания, Валюта) Экспорт

    // Получаем внешний отчет
    ОтчетСсылка = Справочники.ВнешниеОтчеты.НайтиПоНаименованию("ОтчетПоВзаиморасчетам");

    // Проверяем наличие отчета
    Если ОтчетСсылка = Неопределено Тогда
        ВызватьИсключение "Отчет ""ОтчетПоВзаиморасчетам"" не найден в справочнике внешних отчетов!";
    КонецЕсли;

    // Получаем объект внешнего отчета
    ОтчетОбъект = ОтчетСсылка.ПолучитьОбъект();

    // Получаем схему компоновки данных из макета отчета
    СхемаКомпоновки = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создаем компоновщик настроек на основе схемы
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый Структура("URLСхемы", СхемаКомпоновки));
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновки.НастройкиПоУмолчанию);

    // Загружаем вариант отчета "Основной"
    ВариантОтчета = СхемаКомпоновки.ВариантыНастроек.Основной;
    КомпоновщикНастроек.ЗагрузитьНастройки(ВариантОтчета.Настройки);

    // Устанавливаем параметр "Период" отчета
    ПараметрПериод = КомпоновщикНастроек.Настройки.ПараметрыДанных.Элементы.Найти("Период");
    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Значение = Новый СтандартныйПериод(ДатаНачала, ДатаОкончания);
        ПараметрПериод.Использование = Истина;
    КонецЕсли;

    // Формируем отбор: СуммаКонечныйОстаток < 0
    Отбор = КомпоновщикНастроек.Настройки.Отбор;
    ЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СуммаКонечныйОстаток");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.Меньше;
    ЭлементОтбора.ПравоеЗначение = 0;
    ЭлементОтбора.Использование = Истина;

    // Формируем отбор: Валюта = Валюта
    ЭлементОтбораВалюта = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбораВалюта.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Валюта");
    ЭлементОтбораВалюта.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбораВалюта.ПравоеЗначение = Валюта;
    ЭлементОтбораВалюта.Использование = Истина;

    // Настраиваем структуру отчета: строки - Контрагент, столбцы - Валюта
    // Получаем таблицу из структуры настроек
    Таблица = КомпоновщикНастроек.Настройки.Структура.Добавить(Тип("ТаблицаКомпоновкиДанных"));

    // Строки группировки - Контрагент
    ГруппировкаСтрок = Таблица.Строки.Добавить();
    ГруппировкаСтрок.Поле = Новый ПолеКомпоновкиДанных("Контрагент");
    ПолеГруппировки = ГруппировкаСтрок.ПоляГруппировки.Элементы.Добавить(Тип("ПолеГруппировкиКомпоновкиДанных"));
    ПолеГруппировки.Поле = Новый ПолеКомпоновкиДанных("Контрагент");
    ГруппировкаСтрок.Использование = Истина;

    // Столбцы группировки - Валюта
    ГруппировкаСтолбцов = Таблица.Колонки.Добавить();
    ГруппировкаСтолбцов.Поле = Новый ПолеКомпоновкиДанных("Валюта");
    ПолеГруппировкиКолонка = ГруппировкаСтолбцов.ПоляГруппировки.Элементы.Добавить(Тип("ПолеГруппировкиКомпоновкиДанных"));
    ПолеГруппировкиКолонка.Поле = Новый ПолеКомпоновкиДанных("Валюта");
    ГруппировкаСтолбцов.Использование = Истина;

    // Настраиваем выбранные поля: СуммаКонечныйОстаток, Контрагент
    ВыбранныеПоля = КомпоновщикНастроек.Настройки.Выбор;
    ВыбранныеПоля.Элементы.Очистить();

    ПолеСумма = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеСумма.Поле = Новый ПолеКомпоновкиДанных("СуммаКонечныйОстаток");
    ПолеСумма.Заголовок = "Сумма остатка";

    ПолеКонтрагент = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеКонтрагент.Поле = Новый ПолеКомпоновкиДанных("Контрагент");
    ПолеКонтрагент.Заголовок = "Контрагент";

    // Устанавливаем параметры вывода: не выводить параметры данных и отбор
    ПараметрыВывода = КомпоновщикНастроек.Настройки.ПараметрыВывода;

    ПараметрВыводаПараметры = ПараметрыВывода.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("ВыводитьПараметрыДанных"));
    Если ПараметрВыводаПараметры <> Неопределено Тогда
        ПараметрВыводаПараметры.Значение = РежимВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаПараметры.Использование = Истина;
    КонецЕсли;

    ПараметрВыводаОтбор = ПараметрыВывода.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("ВыводитьОтбор"));
    Если ПараметрВыводаОтбор <> Неопределено Тогда
        ПараметрВыводаОтбор.Значение = РежимВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаОтбор.Использование = Истина;
    КонецЕсли;

    // Устанавливаем условное оформление для поля "СуммаКонечныйОстаток"
    УсловноеОформление = КомпоновщикНастроек.Настройки.УсловноеОформление;
    УсловноеОформление.Очистить();

    // Создаем новое условное оформление
    Оформление = УсловноеОформление.Элементы.Добавить();

    // Оформление: Формат = "ЧЦ=10; ЧДЦ=2; ЧО=1"
    Оформление.Оформление.УстановитьЗначениеПараметра("Формат", "ЧЦ=10; ЧДЦ=2; ЧО=1");

    // Условие: СуммаКонечныйОстаток < 0
    ОтборУсловия = Оформление.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ОтборУсловия.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СуммаКонечныйОстаток");
    ОтборУсловия.ВидСравнения = ВидСравненияКомпоновкиДанных.Меньше;
    ОтборУсловия.ПравоеЗначение = 0;

    // Оформляемые поля: СуммаКонечныйОстаток
    ОформляемоеПоле = Оформление.Поля.Элементы.Добавить();
    ОформляемоеПоле.Поле = Новый ПолеКомпоновкиДанных("СуммаКонечныйОстаток");
    ОформляемоеПоле.Использование = Истина;

    // Формируем отчет
    Результат = Новый ТабличныйДокумент;

    ДанныеРасшифровки = Новый ДанныеРасшифровкиКомпоновкиДанных;

    // Компонуем данные
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;

    Попытка
        МакетКомпоновки = КомпоновщикМакета.Выполнить(
            СхемаКомпоновки,
            КомпоновщикНастроек.Настройки,
            ДанныеРасшифровки
        );
    Исключение
        ВызватьИсключение "Ошибка при формировании макета отчета: " + ОписаниеОшибки();
    КонецПопытки;

    // Создаем процессор компоновки
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(
        МакетКомпоновки,
        ,
        ДанныеРасшифровки
    );

    // Создаем процессор вывода
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Результат);

    // Выводим результат
    Попытка
        ПроцессорВывода.Вывести(ПроцессорКомпоновки);
    Исключение
        ВызватьИсключение "Ошибка при выводе отчета: " + ОписаниеОшибки();
    КонецПопытки;

    Возврат Результат;

КонецФункции

// Функция формирует таблицу непрочитанных писем от контрагентов за предыдущий месяц
//
// Параметры:
//   мКонтрагенты - Массив из СправочникСсылка.Контрагенты - контрагенты для отбора писем
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками:
//     * Письмо - СправочникСсылка.ВходящиеПисьма
//     * Тема - Строка
//     * Контрагента - СправочникСсылка.Контрагенты
//     * Дата - Дата
//
Функция ПолучитьТаблицуНепрочитанныхПисемКонтрагентов(мКонтрагенты) Экспорт

    // Получаем границы предыдущего месяца
    ТекущаяДата = ТекущаяДатаСеанса();
    НачалоПредыдущегоМесяца = НачалоМесяца(ДобавитьМесяц(ТекущаяДата, -1));
    КонецПредыдущегоМесяца = КонецМесяца(ТекущаяДата);

    // Если массив контрагентов пуст - возвращаем пустую таблицу
    Если мКонтрагенты.Количество() = 0 Тогда
        ТаблицаРезультат = Новый ТаблицаЗначений;
        ТаблицаРезультат.Колонки.Добавить("Письмо",      Новый ОписаниеТипов("СправочникСсылка.ВходящиеПисьма"));
        ТаблицаРезультат.Колонки.Добавить("Тема",         Новый ОписаниеТипов("Строка"));
        ТаблицаРезультат.Колонки.Добавить("Контрагента",  Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
        ТаблицаРезультат.Колонки.Добавить("Дата",         Новый ОписаниеТипов("Дата"));
        Возврат ТаблицаРезультат;
    КонецЕсли;

    // Формируем запрос для получения непрочитанных писем
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   ВходящиеПисьма.Ссылка КАК Письмо,
    |   ВходящиеПисьма.Тема КАК Тема,
    |   Контрагенты.Ссылка КАК Контрагента,
    |   ВходящиеПисьма.Дата КАК Дата
    |ИЗ
    |   Справочник.ВходящиеПисьма КАК ВходящиеПисьма
    |       ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.Контрагенты КАК Контрагенты
    |       ПО (ВЫРАЗИТЬ(ВходящиеПисьма.Отправитель КАК Строка(100)) = Контрагенты.ЭлектроннаяПочта)
    |           И (Контрагенты.ЭлектроннаяПочта <> """")
    |       ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрСведений.СостояниеВходящихПисем КАК СостояниеВходящихПисем
    |       ПО ВходящиеПисьма.Ссылка = СостояниеВходящихПисем.Письмо
    |ГДЕ
    |   СостояниеВходящихПисем.Прочитано = &Прочитано
    |   И Контрагенты.Ссылка В (&мКонтрагенты)
    |   И ВходящиеПисьма.Дата >= &НачалоПериода
    |   И ВходящиеПисьма.Дата < &КонецПериода
    |УПОРЯДОЧИТЬ ПО
    |   ВходящиеПисьма.Дата УБЫВ";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("НачалоПериода", НачалоПредыдущегоМесяца);
    Запрос.УстановитьПараметр("КонецПериода",  КонецПредыдущегоМесяца);
    Запрос.УстановитьПараметр("мКонтрагенты",   мКонтрагенты);
    Запрос.УстановитьПараметр("Прочитано",      Ложь);

    // Возвращаем результат выполнения запроса
    Возврат Запрос.Выполнить().Выгрузить();

КонецФункции

// Функция формирует выгрузку заказов в работе в XML-файл
//
// Возвращаемое значение:
//  Строка - путь к созданному XML-файлу во временном каталоге
//
Функция ВыгрузитьЗаказыВXMLФайл() Экспорт

    // Создаём временный файл во временном каталоге
    ИмяВременногоФайла = ПолучитьИмяВременногоФайла("xml");

    // Формируем XML-документ
    ЗаписьXML = Новый ЗаписьXML;
    ЗаписьXML.ОткрытьФайл(ИмяВременногоФайла, "UTF-8");
    ЗаписьXML.ЗаписатьОбъявлениеXML();

    // Записываем корневой элемент с атрибутом Имя = "ЗаказТовары"
    ЗаписьXML.ЗаписатьНачалоЭлемента("Заказ");
    ЗаписьXML.ЗаписатьАтрибут("Имя", "ЗаказТовары");

    // Формируем текст запроса для выборки заказов
    Запрос = Новый Запрос;
    Запрос.Текст = 
    |ВЫБРАТЬ
    |    Заказ.Ссылка,
    |    Заказ.Номер,
    |    Заказ.Дата,
    |    Заказ.Проведен,
    |    Заказ.Сумма,
    |    Заказ.Покупатель,
    |    Заказ.Склад,
    |    Заказ.Валюта,
    |    Заказ.ВидЦен,
    |    Заказ.Организация,
    |    Заказ.СостояниеЗаказа,
    |    Заказ.Покупатель.Представление КАК ПокупательПредставление,
    |    Заказ.Склад.Представление КАК СкладПредставление,
    |    Заказ.Валюта.Представление КАК ВалютаПредставление,
    |    Заказ.ВидЦен.Представление КАК ВидЦенПредставление,
    |    Заказ.Организация.Представление КАК ОрганизацияПредставление,
    |    Заказ.СостояниеЗаказа.Представление КАК СостояниеЗаказаПредставление
    |ИЗ
    |    Документ.Заказ КАК Заказ
    |ГДЕ
    |    Заказ.Проведен = ИСТИНА
    |    И Заказ.СостояниеЗаказа = ЗНАЧЕНИЕ(Перечисление.СостоянияЗаказов.ВРаботе)
    |УПОРЯДОЧИТЬ ПО
    |    Заказ.Дата УБЫВ
    |";

    // Выполняем запрос и получаем выборку
    РезультатЗапроса = Запрос.Выполнить();

    // Если выборка пустая - закрываем XML и возвращаем пустой файл
    Если РезультатЗапроса.Пустой() Тогда
        ЗаписьXML.ЗаписатьКонецЭлемента(); // Корневой элемент
        ЗаписьXML.ЗаписатьКонецДокумента();
        ЗаписьXML.Закрыть();
        Возврат ИмяВременногоФайла;
    КонецЕсли;

    // Обходим выборку заказов
    ВыборкаЗаказов = РезультатЗапроса.Выбрать();
    Пока ВыборкаЗаказов.Следующий() Цикл

        // Формируем элемент "Запись" для каждого заказа
        ЗаписьXML.ЗаписатьНачалоЭлемента("Запись");

        // Записываем атрибуты заказа
        ЗаписьXML.ЗаписатьАтрибут("Номер", XMLСтрока(ВыборкаЗаказов.Номер));
        ЗаписьXML.ЗаписатьАтрибут("Дата", XMLСтрока(ВыборкаЗаказов.Дата));
        ЗаписьXML.ЗаписатьАтрибут("СуммаДокумента", XMLСтрока(ВыборкаЗаказов.Сумма));

        // Записываем детальные сведения о заказе
        ЗаписьXML.ЗаписатьНачалоЭлемента("Покупатель");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.ПокупательПредставление);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Склад");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.СкладПредставление);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Валюта");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.ВалютаПредставление);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("ВидЦен");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.ВидЦенПредставление);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Организация");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.ОрганизацияПредставление);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("СостояниеЗаказа");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.СостояниеЗаказаПредставление);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        // Получаем и записываем товары заказа
        ВыборкаТовары = ПолучитьТоварыЗаказа(ВыборкаЗаказов.Ссылка);

        Если ВыборкаТовары.Количество() > 0 Тогда
            ЗаписьXML.ЗаписатьНачалоЭлемента("Товары");

            Пока ВыборкаТовары.Следующий() Цикл
                ЗаписьXML.ЗаписатьНачалоЭлемента("СтрокаТовары");
                ЗаписьXML.ЗаписатьАтрибут("Товар", ВыборкаТовары.ТоварПредставление);
                ЗаписьXML.ЗаписатьАтрибут("Цена", XMLСтрока(ВыборкаТовары.Цена));
                ЗаписьXML.ЗаписатьАтрибут("Количество", XMLСтрока(ВыборкаТовары.Количество));
                ЗаписьXML.ЗаписатьАтрибут("Сумма", XMLСтрока(ВыборкаТовары.Сумма));
                ЗаписьXML.ЗаписатьКонецЭлемента();
            КонецЦикла;

            ЗаписьXML.ЗаписатьКонецЭлемента(); // Товары
        КонецЕсли;

        ЗаписьXML.ЗаписатьКонецЭлемента(); // Запись

    КонецЦикла;

    // Закрываем корневой элемент и документ
    ЗаписьXML.ЗаписатьКонецЭлемента(); // Корневой элемент Заказ
    ЗаписьXML.ЗаписатьКонецДокумента();
    ЗаписьXML.Закрыть();

    Возврат ИмяВременногоФайла;

КонецФункции

// Функция получает выборку товаров заказа
//
// Параметры:
//  ЗаказСсылка - ДокументСсылка.Заказ - ссылка на документ заказ
//
// Возвращаемое значение:
//  ВыборкаИзРезультатаЗапроса - выборка товаров
//
Функция ПолучитьТоварыЗаказа(ЗаказСсылка)

    ЗапросТовары = Новый Запрос;
    ЗапросТовары.Текст = 
    |ВЫБРАТЬ
    |    ЗаказТовары.Товар,
    |    ЗаказТовары.Товар.Представление КАК ТоварПредставление,
    |    ЗаказТовары.Цена,
    |    ЗаказТовары.Количество,
    |    ЗаказТовары.Сумма
    |ИЗ
    |    Документ.Заказ.Товары КАК ЗаказТовары
    |ГДЕ
    |    ЗаказТовары.Ссылка = &ЗаказСсылка
    |";

    ЗапросТовары.УстановитьПараметр("ЗаказСсылка", ЗаказСсылка);

    Возврат ЗапросТовары.Выполнить().Выбрать();

КонецФункции

// Функция разлагает строку в массив подстрок на основе заданного разделителя.
// Параметры:
//   Стр - Строка - исходная строка для разложения (передается по значению)
//   Разделитель - Строка - разделитель подстрок (по умолчанию запятая)
//
// Возвращает:
//   Массив - массив значений, содержащий подстроки
//
Функция РазложитьСтрокуВМассивПодстрок(Знач Стр, Разделитель = ",") Экспорт

    МассивСтрок = Новый Массив;

    Если ПустаяСтрока(Стр) Тогда
        Возврат МассивСтрок;
    КонецЕсли;

    // Специальная обработка для разделителя-пробела:
    // группируем последовательные пробелы и игнорируем ведущие/хвостовые
    Если Разделитель = " " Тогда

        Стр = СокрЛП(Стр);

        Если ПустаяСтрока(Стр) Тогда
            Возврат МассивСтрок;
        КонецЕсли;

        ДлинаСтроки    = СтрДлина(Стр);
        Позиция        = 1;
        НачалоЭлемента = 1;

        Пока Позиция <= ДлинаСтроки Цикл

            Если Сред(Стр, Позиция, 1) = " " Тогда

                // Нашли пробел - добавляем подстроку до него
                Если Позиция > НачалоЭлемента Тогда
                    МассивСтрок.Добавить(Сред(Стр, НачалоЭлемента, Позиция - НачалоЭлемента));
                КонецЕсли;

                // Пропускаем все последовательные пробелы (группируем их в один разделитель)
                Пока Позиция <= ДлинаСтроки И Сред(Стр, Позиция, 1) = " " Цикл
                    Позиция = Позиция + 1;
                КонецЦикла;

                НачалоЭлемента = Позиция;

            Иначе

                Позиция = Позиция + 1;

            КонецЕсли;

        КонецЦикла;

        // Добавляем последний элемент (после последнего пробела)
        Если НачалоЭлемента <= ДлинаСтроки Тогда
            МассивСтрок.Добавить(Сред(Стр, НачалоЭлемента));
        КонецЕсли;

    Иначе

        // Стандартная обработка для произвольного разделителя
        ДлинаРазделителя = СтрДлина(Разделитель);

        Пока Истина Цикл

            Позиция = Найти(Стр, Разделитель);

            Если Позиция = 0 Тогда
                Прервать;
            КонецЕсли;

            // Добавляем подстроку до разделителя
            МассивСтрок.Добавить(Лев(Стр, Позиция - 1));

            // Удаляем часть строки до разделителя (включая сам разделитель)
            Стр = Сред(Стр, Позиция + ДлинаРазделителя);

        КонецЦикла;

        // Добавляем оставшуюся часть строки (после последнего разделителя)
        МассивСтрок.Добавить(Стр);

    КонецЕсли;

    Возврат МассивСтрок;

КонецФункции

// Функция возвращает таблицу значений с битыми ссылками из зарегистрированных к обмену объектов
//
// Параметры:
//  Узел             - ПланОбменаСсылка - узел плана обмена
//  ТипМетаданных    - ОбъектМетаданных - метаданные из состава плана обмена (необязательно)
//
// Возвращает:
//  ТаблицаЗначений - с колонками:
//   * МетаИмя       - Строка - полное имя метаданных
//   * ТипМетаданных - ОбъектМетаданных - тип метаданных
//   * УИД           - УникальныйИдентификатор - GUID ссылки
//
Функция ЗарегистрированныеКОбменуБитыеСсылки(Узел, ТипМетаданных = Неопределено) Экспорт

    // Создаем результирующую таблицу
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("МетаИмя",       Новый ОписаниеТипов("Строка"));
    Результат.Колонки.Добавить("ТипМетаданных");
    Результат.Колонки.Добавить("УИД",            Новый ОписаниеТипов("УникальныйИдентификатор"));

    // Получаем менеджер плана обмена
    ИмяПланаОбмена = Узел.Метаданные().Имя;
    МенеджерПланаОбмена = ПланыОбмена[ИмяПланаОбмена];

    // Определяем состав плана обмена
    Если ТипМетаданных = Неопределено Тогда
        // Получаем все ссылочные метаданные из состава плана обмена
        ТаблицаМетаданных = Новый ТаблицаЗначений;
        ТаблицаМетаданных.Колонки.Добавить("Метаданные");

        Для Каждого ЭлементСостава Из Метаданные.ПланыОбмена[ИмяПланаОбмена].Состав Цикл
            Если ОбщегоНазначения.ЭтоСсылочныйТипДанных(ЭлементСостава.Метаданные) Тогда
                СтрокаТаблицы = ТаблицаМетаданных.Добавить();
                СтрокаТаблицы.Метаданные = ЭлементСостава.Метаданные;
            КонецЕсли;
        КонецЦикла;
    Иначе
        // Фильтруем только по указанному типу метаданных
        ТаблицаМетаданных = Новый ТаблицаЗначений;
        ТаблицаМетаданных.Колонки.Добавить("Метаданные");

        Если ОбщегоНазначения.ЭтоСсылочныйТипДанных(ТипМетаданных) Тогда
            СтрокаТаблицы = ТаблицаМетаданных.Добавить();
            СтрокаТаблицы.Метаданные = ТипМетаданных;
        КонецЕсли;
    КонецЕсли;

    // Обрабатываем каждый тип метаданных
    Для Каждого СтрокаМетаданных Из ТаблицаМетаданных Цикл

        ТекущиеМетаданные = СтрокаМетаданных.Метаданные;
        ПолноеИмя = ТекущиеМетаданные.ПолноеИмя();

        // Создаем запрос для получения изменений
        Запрос = Новый Запрос;
        Запрос.Текст = 
        "ВЫБРАТЬ
        |   Регистрация.Ссылка КАК Ссылка
        |ИЗ
        |   #ПолноеИмя КАК Регистрация
        |ГДЕ
        |   Регистрация.Ссылка <> ЗНАЧЕНИЕ(#ПолноеИмя.ПустаяСсылка)";

        Запрос.Текст = СтрЗаменить(Запрос.Текст, "#ПолноеИмя", ПолноеИмя);

        Выборка = Запрос.Выполнить().Выбрать();

        // Получаем менеджер записи для проверки ссылок
        МенеджерОбъекта = ОбщегоНазначения.МенеджерОбъектаПоПолномуИмени(ПолноеИмя);

        // Проверяем каждую ссылку
        Пока Выборка.Следующий() Цикл
            ТекущаяСсылка = Выборка.Ссылка;

            // Проверяем, является ли ссылка "битой"
            Если НЕ ОбщегоНазначения.СсылкаСуществует(ТекущаяСсылка) Тогда
                // Получаем уникальный идентификатор битой ссылки
                Попытка
                    УИД = ТекущаяСсылка.УникальныйИдентификатор();
                Исключение
                    УИД = Неопределено;
                КонецПопытки;

                // Добавляем строку в результат
                СтрокаРезультата = Результат.Добавить();
                СтрокаРезультата.МетаИмя       = ПолноеИмя;
                СтрокаРезультата.ТипМетаданных = ТекущиеМетаданные;
                СтрокаРезультата.УИД           = УИД;
            КонецЕсли;
        КонецЦикла;

    КонецЦикла;

    Возврат Результат;

КонецФункции

// Процедура проверки количества элементов в результате
//
// Параметры:
//  Узел             - ПланОбменаСсылка - узел плана обмена
//  ТипМетаданных    - ОбъектМетаданных - метаданные (необязательно)
//
Процедура ПроверитьБитыеСсылкиНаУзле(Узел, ТипМетаданных = Неопределено) Экспорт

    ТаблицаБитыхСсылок = ЗарегистрированныеКОбменуБитыеСсылки(Узел, ТипМетаданных);

    КоличествоБитыхСсылок = ТаблицаБитыхСсылок.Количество();

    Если КоличествоБитыхСсылок > 0 Тогда
        Сообщить(СтрШаблон("Внимание! Обнаружено %1 битых(ая) ссылок(а) среди зарегистрированных к обмену объектов.", 
            КоличествоБитыхСсылок));

        // Выводим детализацию
        Для Каждого СтрокаТаблицы Из ТаблицаБитыхСсылок Цикл
            Сообщить(СтрШаблон("  - %1, УИД: %2", 
                СтрокаТаблицы.МетаИмя, 
                СтрокаТаблицы.УИД));
        КонецЦикла;
    Иначе
        Сообщить("Битых ссылок среди зарегистрированных к обмену объектов не обнаружено.");
    КонецЕсли;

КонецПроцедуры

&НаКлиенте
Функция НайтиАдресПоКоординатам(Широта, Долгота, APIКлюч) Экспорт

    // Формируем URL для запроса к API Яндекс.Геокодера
    Сервер = "geocode-maps.yandex.ru";

    // Формируем строку координат в формате "Долгота,Широта"
    КоординатыСтрока = Формат(Долгота, "ЧГ=.") + "," + Формат(Широта, "ЧГ=.");

    // Формируем параметры запроса
    ПараметрыЗапроса = "apikey=" + APIКлюч 
        + "&geocode=" + КодироватьСтроку(КоординатыСтрока, СпособКодированияСтроки.КодировкаURL)
        + "&format=json"
        + "&results=1";

    URLЗапроса = "/1.x/?" + ПараметрыЗапроса;

    // Создаем защищенное соединение для HTTPS
    ЗащищенноеСоединение = Новый ЗащищенноеСоединениеOpenSSL();

    // Создаем HTTP-соединение
    HTTPСоединение = Новый HTTPСоединение(
        Сервер,
        443,
        ,
        ,
        ,
        ,
        ЗащищенноеСоединение
    );

    // Создаем HTTP-запрос
    HTTPЗапрос = Новый HTTPЗапрос(URLЗапроса);

    // Выполняем GET-запрос
    HTTPОтвет = HTTPСоединение.Получить(HTTPЗапрос);

    // Проверяем код состояния ответа
    Если HTTPОтвет.КодСостояния <> 200 Тогда
        ВызватьИсключение "Ошибка выполнения запроса. Код состояния: " + HTTPОтвет.КодСостояния;
    КонецЕсли;

    // Читаем ответ как строку
    ТелоОтвета = HTTPОтвет.ПолучитьТелоКакСтроку();

    // Проверяем, получен ли корректный ответ
    Если ПустаяСтрока(ТелоОтвета) Тогда
        Возврат "";
    КонецЕсли;

    // Создаем объект для чтения JSON
    ЧтениеJSON = Новый ЧтениеJSON;
    ЧтениеJSON.УстановитьСтроку(ТелоОтвета);

    // Десериализуем JSON в структуру
    СтруктураОтвета = ПрочитатьJSON(ЧтениеJSON, Истина);
    ЧтениеJSON.Закрыть();

    // Извлекаем адрес из ответа
    Адрес = ИзвлечьАдресИзОтвета(СтруктураОтвета);

    Возврат Адрес;

КонецФункции

// Вспомогательная функция для извлечения адреса из структуры ответа
&НаКлиенте
Функция ИзвлечьАдресИзОтвета(СтруктураОтвета)

    // Проверяем наличие данных в ответе
    Если СтруктураОтвета = Неопределено Тогда
        Возврат "";
    КонецЕсли;

    // Переходим к данным ответа
    // Структура: response -> GeoObjectCollection -> featureMember -> GeoObject -> metaDataProperty -> GeocoderMetaData -> text

    Попытка
        response = СтруктураОтвета.response;

        Если response = Неопределено Тогда
            Возврат "";
        КонецЕсли;

        GeoObjectCollection = response.GeoObjectCollection;

        Если GeoObjectCollection = Неопределено Тогда
            Возврат "";
        КонецЕсли;

        featureMember = GeoObjectCollection.featureMember;

        Если featureMember = Неопределено 
            ИЛИ featureMember.Количество() = 0 Тогда
            Возврат "";
        КонецЕсли;

        // Получаем первый найденный объект
        ПерваяЗапись = featureMember[0];
        GeoObject = ПерваяЗапись.GeoObject;

        Если GeoObject = Неопределено Тогда
            Возврат "";
        КонецЕсли;

        metaDataProperty = GeoObject.metaDataProperty;

        Если metaDataProperty = Неопределено Тогда
            Возврат "";
        КонецЕсли;

        GeocoderMetaData = metaDataProperty.GeocoderMetaData;

        Если GeocoderMetaData = Неопределено Тогда
            Возврат "";
        КонецЕсли;

        // Получаем текстовое представление адреса
        Адрес = GeocoderMetaData.text;

        Возврат ?(Адрес = Неопределено, "", Адрес);

    Исключение
        // В случае ошибки парсинга возвращаем пустую строку
        Возврат "";
    КонецПопытки;

КонецФункции

// Функция проверяет превышение лимита дебиторской задолженности контрагента
// Параметры:
//   Заказ - Структура с полями: Контрагент, Валюта, Дата, Сумма
//   ЛимитВРублях - Число, лимит в валюте RUB
// Возвращает структуру с результатами проверки
//
Функция ПроверкаЛимитаЗадолженности(Заказ, ЛимитВРублях) Экспорт

    // Если валюта заказа уже рубли - используем её как есть
    // Иначе получаем курс валюты заказа на дату документа
    Если Заказ.Валюта = Справочники.Валюты.НайтиПоНаименованию("RUB") Тогда
        КурсВалютыЗаказа = 1;
    Иначе
        КурсВалютыЗаказа = РегистрыСведений.КурсыВалют.ПолучитьПоследнее(
            Заказ.Дата, 
            Новый Структура("Валюта", Заказ.Валюта)
        ).Курс;
    КонецЕсли;

    // Рассчитываем сумму заказа в рублях
    СуммаЗаказаВРублях = Окр(Заказ.Сумма * КурсВалютыЗаказа, 2);

    // Формируем текст запроса для получения дебиторской задолженности
    // Используем виртуальную таблицу Остатки регистра накопления Взаиморасчеты
    // и СрезПоследних регистра сведений КурсыВалют для получения курсов валют
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЕСТЬNULL(СУММА(ДебиторскаяЗадолженность.СуммаОстаток * ЕСТЬNULL(КурсыВалют.Курс, 1)), 0) КАК СуммаДебиторскойЗадолженности
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(
    |        &Дата, 
    |        Контрагент = &Контрагент
    |    ) КАК ДебиторскаяЗадолженность
    |    ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.КурсыВалют.СрезПоследних(&Дата, ) КАК КурсыВалют
    |    ПО ДебиторскаяЗадолженность.Валюта = КурсыВалют.Валюта";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("Дата", Заказ.Дата);
    Запрос.УстановитьПараметр("Контрагент", Заказ.Контрагент);

    // Выполняем запрос и получаем выборку
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // Получаем текущую сумму дебиторской задолженности в рублях
    СуммаДебиторскойЗадолженности = 0;
    Если Выборка.Следующий() Тогда
        СуммаДебиторскойЗадолженности = Выборка.СуммаДебиторскойЗадолженности;
    КонецЕсли;

    // Рассчитываем прогнозируемую задолженность с учётом заказа
    СуммаДебиторскойЗадолженностиСЗаказом = 
        СуммаДебиторскойЗадолженности + СуммаЗаказаВРублях;

    // Проверяем превышение лимита
    ЛимитНеПревышен = (СуммаДебиторскойЗадолженностиСЗаказом <= ЛимитВРублях);

    // Формируем сообщение пользователю
    Если ЛимитНеПревышен Тогда
        СообщениеПользователю = СтрШаблон(
            "Лимит дебиторской задолженности не превышен. 
            |Текущая задолженность: %1 руб.
            |С учётом заказа: %2 руб.
            |Лимит: %3 руб.",
            СуммаДебиторскойЗадолженности,
            СуммаДебиторскойЗадолженностиСЗаказом,
            ЛимитВРублях
        );
    Иначе
        СуммаПревышения = СуммаДебиторскойЗадолженностиСЗаказом - ЛимитВРублях;
        СообщениеПользователю = СтрШаблон(
            "Превышен лимит дебиторской задолженности!
            |Сумма превышения: %1 руб.
            |Текущая задолженность: %2 руб.
            |С учётом заказа: %3 руб.
            |Лимит: %4 руб.",
            СуммаПревышения,
            СуммаДебиторскойЗадолженности,
            СуммаДебиторскойЗадолженностиСЗаказом,
            ЛимитВРублях
        );
    КонецЕсли;

    // Возвращаем структуру с результатами проверки
    Возврат Новый Структура(
        "СуммаДебиторскойЗадолженности, 
        |СуммаДебиторскойЗадолженностиСЗаказом, 
        |СуммаЗаказаВРублях, 
        |ЛимитНеПревышен, 
        |СообщениеПользователю",
        СуммаДебиторскойЗадолженности,
        СуммаДебиторскойЗадолженностиСЗаказом,
        СуммаЗаказаВРублях,
        ЛимитНеПревышен,
        СообщениеПользователю
    );

КонецФункции

// Функция формирует таблицу анализа продаж товаров за указанный период
//
// Параметры:
//  НачалоПериода     - Дата - начало анализируемого периода
//  ОкончаниеПериода  - Дата - окончание анализируемого периода
//  НормаПродаж       - Число - норма продаж для сравнения
//
// Возвращаемое значение:
//  ТаблицаЗначений с колонками:
//   - Товар (СправочникСсылка.Товары)
//   - КоличествоДнейМин (Число) - дни с нулевыми продажами
//   - КоличествоДнейМакс (Число) - дни с максимальными продажами
//   - КоличествоДнейНорма (Число) - дни с продажами выше нормы
//   - СуммаВсего (Число) - сумма продаж за период
//   - ОстатокНаКонецПериода (Число) - остаток товара на конец периода
//
Функция ПолучитьТаблицуАнализаПродаж(НачалоПериода, ОкончаниеПериода, НормаПродаж) Экспорт

    // Создаем запрос для получения данных о продажах
    Запрос = Новый Запрос;

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("НачалоПериода", НачалоПериода);
    Запрос.УстановитьПараметр("ОкончаниеПериода", ОкончаниеПериода);
    Запрос.УстановитьПараметр("НормаПродаж", НормаПродаж);

    // Формируем текст запроса для анализа продаж
    // Запрос состоит из двух частей:
    // 1. Получение максимумов продаж по товарам
    // 2. Расчет показателей с использованием максимумов
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.Товар,
    |    МАКСИМУМ(ПродажиОбороты.КоличествоОборот) КАК МаксимумПродаж
    |ПОМЕСТИТЬ Максимумы
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&НачалоПериода, &ОкончаниеПериода, День, ) КАК ПродажиОбороты
    |СГРУППИРОВАТЬ ПО
    |    ПродажиОбороты.Товар
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |
    |ВЫБРАТЬ
    |    ПродажиОбороты.Товар КАК Товар,
    |    СУММА(ВЫБОР КОГДА ПродажиОбороты.КоличествоОборот = 0 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК КоличествоДнейМин,
    |    СУММА(ВЫБОР КОГДА ПродажиОбороты.КоличествоОборот <> 0 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК КоличествоДнейНенулевых,
    |    СУММА(ВЫБОР КОГДА ПродажиОбороты.КоличествоОборот > &НормаПродаж ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК КоличествоДнейНорма,
    |    СУММА(ПродажиОбороты.СуммаОборот) КАК СуммаВсего,
    |    МАКСИМУМ(Максимумы.МаксимумПродаж) КАК МаксимумПродаж
    |ПОМЕСТИТЬ ПродажиПоТоварам
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&НачалоПериода, &ОкончаниеПериода, День, ) КАК ПродажиОбороты
    |    ЛЕВОЕ СОЕДИНЕНИЕ Максимумы КАК Максимумы
    |    ПО ПродажиОбороты.Товар = Максимумы.Товар
    |
    |СГРУППИРОВАТЬ ПО
    |    ПродажиОбороты.Товар
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |
    |ВЫБРАТЬ
    |    ПродажиПоТоварам.Товар КАК Товар,
    |    ПродажиПоТоварам.КоличествоДнейМин,
    |    КОЛИЧЕСТВО(РАЗЛИЧНЫХ ВЫБОР КОГДА ПродажиОборотыДень.КоличествоОборот = ПродажиПоТоварам.МаксимумПродаж
    |                                                        И ПродажиПоТоварам.МаксимумПродаж > 0
    |                                                        ТОГДА ПродажиОборотыДень.Период КОНЕЦ) КАК КоличествоДнейМакс,
    |    ПродажиПоТоварам.КоличествоДнейНорма,
    |    ПродажиПоТоварам.СуммаВсего КАК СуммаВсего,
    |    СУММА(ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0)) КАК ОстатокНаКонецПериода
    |ИЗ
    |    ПродажиПоТоварам
    |    ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.Продажи.Обороты(&НачалоПериода, &ОкончаниеПериода, День, ) КАК ПродажиОборотыДень
    |    ПО ПродажиПоТоварам.Товар = ПродажиОборотыДень.Товар
    |    ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварныеЗапасы.Остатки(&ОкончаниеПериода, ) КАК ТоварныеЗапасыОстатки
    |    ПО ПродажиПоТоварам.Товар = ТоварныеЗапасыОстатки.Товар
    |
    |СГРУППИРОВАТЬ ПО
    |    ПродажиПоТоварам.Товар,
    |    ПродажиПоТоварам.КоличествоДнейМин,
    |    ПродажиПоТоварам.КоличествоДнейНорма,
    |    ПродажиПоТоварам.СуммаВсего
    |
    |УПОРЯДОЧИТЬ ПО
    |    Товар
    |АВТОУПОРЯДОЧИВАНИЕ";

    // Выполняем запрос и возвращаем результат в виде таблицы значений
    Результат = Запрос.Выполнить().Выгрузить();

    Возврат Результат;

КонецФункции

// Функция заполняет табличный документ актуальными ценами товаров на заданную дату
//
// Параметры:
//  ТабДокумент - ТабличныйДокумент - результирующий документ
//  Макет - ТабличныйДокумент - макет с областями Шапка, ШапкаТаблицы, Строка
//  Дата - Дата - дата, на которую получаются цены
//  ВидЦен - СправочникСсылка.ВидыЦен - вид цен (необязательный)
//
// Возвращаемое значение:
//  ТабличныйДокумент - заполненный документ
//
Функция ЗаполнитьТабличныйДокумент(ТабДокумент, Макет, Дата, ВидЦен = Неопределено) Экспорт

    // Получаем области макета
    ОбластьШапка = Макет.ПолучитьОбласть("Шапка");
    ОбластьШапкаТаблицы = Макет.ПолучитьОбласть("ШапкаТаблицы");
    ОбластьСтрока = Макет.ПолучитьОбласть("Строка");

    // Заполняем параметр "НаДату" в области шапки
    ОбластьШапка.Параметры.НаДату = Дата;

    // Выводим области в документ
    ТабДокумент.Вывести(ОбластьШапка);
    ТабДокумент.Вывести(ОбластьШапкаТаблицы);

    // Формируем текст запроса для получения товаров и цен
    Запрос = Новый Запрос;

    Запрос.Текст =
    "ВЫБРАТЬ
    |    Товары.Ссылка КАК Товар,
    |    Товары.Артикул КАК Артикул,
    |    ЦеныТоваровСрез.Цена КАК Цена,
    |    ЦеныТоваровСрез.ВидЦен КАК ВидЦен
    |ИЗ
    |    Справочник.Товары КАК Товары
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних(
    |                &Дата,
    |                &УсловиеПоВидуЦен) КАК ЦеныТоваровСрез
    |        ПО Товары.Ссылка = ЦеныТоваровСрез.Товар
    |УПОРЯДОЧИТЬ ПО
    |    Товары.Наименование
    |ИТОГИ ПО
    |    Товар";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("Дата", Дата);

    // Формируем условие по виду цен
    Если ВидЦен <> Неопределено И НЕ ВидЦен.Пустая() Тогда
        ТекстУсловия = "ВидЦен = &ВидЦен";
        Запрос.УстановитьПараметр("ВидЦен", ВидЦен);
    Иначе
        ТекстУсловия = "";
    КонецЕсли;

    // Заменяем параметр условия в тексте запроса
    Запрос.Текст = СтрЗаменить(Запрос.Текст, "&УсловиеПоВидуЦен", ТекстУсловия);

    // Выполняем запрос
    РезультатЗапроса = Запрос.Выполнить();

    // Обходим результаты запроса
    ВыборкаТовары = РезультатЗапроса.Выбрать(ОбходРезультатаЗапроса.ПоГруппировкам);

    Пока ВыборкаТовары.Следующий() Цикл

        // Если вид цен не задан, выводим все цены для товара
        Если ВидЦен = Неопределено ИЛИ ВидЦен.Пустая() Тогда

            ВыборкаЦены = ВыборкаТовары.Выбрать();

            Пока ВыборкаЦены.Следующий() Цикл

                // Заполняем параметры строки
                ОбластьСтрока.Параметры.Товар = ВыборкаЦены.Товар;
                ОбластьСтрока.Параметры.Артикул = ВыборкаЦены.Артикул;
                ОбластьСтрока.Параметры.Цена = ВыборкаЦены.Цена;
                ОбластьСтрока.Параметры.ВидЦен = ВыборкаЦены.ВидЦен;

                // Выводим строку в документ
                ТабДокумент.Вывести(ОбластьСтрока);

            КонецЦикла;

        Иначе

            // Выводим одну строку с указанным видом цен
            ОбластьСтрока.Параметры.Товар = ВыборкаТовары.Товар;
            ОбластьСтрока.Параметры.Артикул = ВыборкаТовары.Артикул;
            ОбластьСтрока.Параметры.Цена = ВыборкаТовары.Цена;
            ОбластьСтрока.Параметры.ВидЦен = ВидЦен;

            // Выводим строку в документ
            ТабДокумент.Вывести(ОбластьСтрока);

        КонецЕсли;

    КонецЦикла;

    // Задаём параметры отображения документа
    ТабДокумент.АвтоМасштаб = Истина;
    ТабДокумент.ОтображатьСетку = Ложь;
    ТабДокумент.ОтображатьЗаголовки = Ложь;

    Возврат ТабДокумент;

КонецФункции

// Функция поиска контрагентов по контактной информации (телефон, факс, email, веб-сайт)
//
// Параметры:
//  СтрокаКонтактнойИнформации - Строка - номер телефона, адрес e-mail или web-сайт
//
// Возвращаемое значение:
//  Структура - содержит ключи:
//    "КонтактнаяИнформация" - Строка - переданное значение
//    "Количество" - Число - количество найденных соответствий
//    "КоличествоПолныхСоответствий" - Число - количество полных соответствий
//    "Контрагенты" - ТаблицаЗначений - найденные контрагенты
//
Функция НайтиКонтрагентовПоКонтактнойИнформации(СтрокаКонтактнойИнформации) Экспорт

    // Проверка на пустую строку
    Если ПустаяСтрока(СтрокаКонтактнойИнформации) Тогда
        Возврат Новый Структура(
            "КонтактнаяИнформация, Количество, КоличествоПолныхСоответствий, Контрагенты",
            Неопределено, Неопределено, Неопределено, Неопределено
        );
    КонецЕсли;

    // Создание запроса
    Запрос = Новый Запрос;

    // Текст запроса с нормализацией телефонных номеров
    Запрос.Текст =
    "ВЫБРАТЬ
    |    Контрагенты.Ссылка КАК Контрагент,
    |    ""Телефон"" КАК ТипКонтактнойИнформации,
    |    Контрагенты.Телефон КАК Значение,
    |    ВЫБОР
    |        КОГДА СтрЗаменить(СтрЗаменить(СтрЗаменить(СтрЗаменить(СтрЗаменить(
    |            Контрагенты.Телефон, ""-"", """"), "" "", """"), ""("", """"), "")"", """"), ""+"", """") 
    |            = &НормализованнаяСтрока
    |            ТОГДА ИСТИНА
    |        ИНАЧЕ ЛОЖЬ
    |    КОНЕЦ КАК ПолноеСоответствие
    |ИЗ
    |    Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |    НЕ ПустаяСтрока(Контрагенты.Телефон)
    |    И СтрНайти(
    |        СтрЗаменить(СтрЗаменить(СтрЗаменить(СтрЗаменить(СтрЗаменить(
    |            Контрагенты.Телефон, ""-"", """"), "" "", """"), ""("", """"), "")"", """"), ""+"", """"),
    |        &НормализованнаяСтрока) > 0
    |
    |ОБЪЕДИНИТЬ ВСЕ
    |
    |ВЫБРАТЬ
    |    Контрагенты.Ссылка,
    |    ""Факс"",
    |    Контрагенты.Факс,
    |    ВЫБОР
    |        КОГДА СтрЗаменить(СтрЗаменить(СтрЗаменить(СтрЗаменить(СтрЗаменить(
    |            Контрагенты.Факс, ""-"", """"), "" "", """"), ""("", """"), "")"", """"), ""+"", """") 
    |            = &НормализованнаяСтрока
    |            ТОГДА ИСТИНА
    |        ИНАЧЕ ЛОЖЬ
    |    КОНЕЦ
    |ИЗ
    |    Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |    НЕ ПустаяСтрока(Контрагенты.Факс)
    |    И СтрНайти(
    |        СтрЗаменить(СтрЗаменить(СтрЗаменить(СтрЗаменить(СтрЗаменить(
    |            Контрагенты.Факс, ""-"", """"), "" "", """"), ""("", """"), "")"", """"), ""+"", """"),
    |        &НормализованнаяСтрока) > 0
    |
    |ОБЪЕДИНИТЬ ВСЕ
    |
    |ВЫБРАТЬ
    |    Контрагенты.Ссылка,
    |    ""ЭлектроннаяПочта"",
    |    Контрагенты.ЭлектроннаяПочта,
    |    ВЫБОР
    |        КОГДА СокрЛП(Контрагенты.ЭлектроннаяПочта) = &СтрокаПоискаБезНормализации
    |            ТОГДА ИСТИНА
    |        ИНАЧЕ ЛОЖЬ
    |    КОНЕЦ
    |ИЗ
    |    Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |    НЕ ПустаяСтрока(Контрагенты.ЭлектроннаяПочта)
    |    И СтрНайти(Контрагенты.ЭлектроннаяПочта, &СтрокаПоискаБезНормализации) > 0
    |
    |ОБЪЕДИНИТЬ ВСЕ
    |
    |ВЫБРАТЬ
    |    Контрагенты.Ссылка,
    |    ""ВебСайт"",
    |    Контрагенты.ВебСайт,
    |    ВЫБОР
    |        КОГДА СокрЛП(Контрагенты.ВебСайт) = &СтрокаПоискаБезНормализации
    |            ТОГДА ИСТИНА
    |        ИНАЧЕ ЛОЖЬ
    |    КОНЕЦ
    |ИЗ
    |    Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |    НЕ ПустаяСтрока(Контрагенты.ВебСайт)
    |    И СтрНайти(Контрагенты.ВебСайт, &СтрокаПоискаБезНормализации) > 0
    |
    |УПОРЯДОЧИТЬ ПО
    |    ПолноеСоответствие УБЫВ,
    |    ТипКонтактнойИнформации";

    // Подготовка нормализованной строки (только цифры)
    НормализованнаяСтрока = "";
    Для Индекс = 1 По СтрДлина(СтрокаКонтактнойИнформации) Цикл
        Символ = Сред(СтрокаКонтактнойИнформации, Индекс, 1);
        Если СтрНайти("0123456789", Символ) > 0 Тогда
            НормализованнаяСтрока = НормализованнаяСтрока + Символ;
        КонецЕсли;
    КонецЦикла;

    // Установка параметров запроса
    Запрос.УстановитьПараметр("НормализованнаяСтрока", НормализованнаяСтрока);
    Запрос.УстановитьПараметр("СтрокаПоискаБезНормализации", СтрокаКонтактнойИнформации);

    // Выполнение запроса и загрузка результата
    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаКонтрагентов = Новый ТаблицаЗначений;
    ТаблицаКонтрагентов.Колонки.Добавить("Контрагент", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    ТаблицаКонтрагентов.Колонки.Добавить("ТипКонтактнойИнформации", Новый ОписаниеТипов("Строка"));
    ТаблицаКонтрагентов.Колонки.Добавить("Значение", Новый ОписаниеТипов("Строка"));
    ТаблицаКонтрагентов.Колонки.Добавить("ПолноеСоответствие", Новый ОписаниеТипов("Булево"));

    Если НЕ РезультатЗапроса.Пустой() Тогда
        ТаблицаКонтрагентов = РезультатЗапроса.Выгрузить();
    КонецЕсли;

    // Сортировка: сначала полные соответствия
    ТаблицаКонтрагентов.Сортировать("ПолноеСоответствие УБЫВ, ТипКонтактнойИнформации ВОЗР");

    // Подсчёт количеств
    Количество = ТаблицаКонтрагентов.Количество();

    КоличествоПолныхСоответствий = 0;
    Для Каждого СтрокаТаблицы Из ТаблицаКонтрагентов Цикл
        Если СтрокаТаблицы.ПолноеСоответствие Тогда
            КоличествоПолныхСоответствий = КоличествоПолныхСоответствий + 1;
        КонецЕсли;
    КонецЦикла;

    // Формирование возвращаемой структуры
    Возврат Новый Структура(
        "КонтактнаяИнформация, Количество, КоличествоПолныхСоответствий, Контрагенты",
        СтрокаКонтактнойИнформации,
        Количество,
        КоличествоПолныхСоответствий,
        ТаблицаКонтрагентов
    );

КонецФункции

Функция ВыполнитьABCАнализПродаж(ДатаНач, ДатаКон) Экспорт

    Запрос = Новый Запрос;

    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.Товар,
    |    ПродажиОбороты.Товар.Наименование КАК НаименованиеТовара,
    |    ПродажиОбороты.СуммаОборот КАК СуммаПродаж
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, Авто, Товар) КАК ПродажиОбороты
    |ГДЕ
    |    ПродажиОбороты.СуммаОборот > 0
    |УПОРЯДОЧИТЬ ПО
    |    ПродажиОбороты.СуммаОборот УБЫВ";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    Если НЕ Выборка.Следующий() Тогда
        Возврат Новый ТаблицаЗначений;
    КонецЕсли;

    // Формируем список товаров с ненулевыми оборотами
    СписокТоваров = Новый Массив;
    СписокТоваров.Добавить(Выборка.Товар);

    Пока Выборка.Следующий() Цикл
        СписокТоваров.Добавить(Выборка.Товар);
    КонецЦикла;

    // Получаем общую сумму продаж
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЕСТЬNULL(ПродажиОбороты.СуммаОборот, 0) КАК ОбщаяСумма
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, Авто, ) КАК ПродажиОбороты";

    РезультатИтога = Запрос.Выполнить().Выбрать();
    РезультатИтога.Следующий();
    ОбщаяСумма = РезультатИтога.ОбщаяСумма;

    // Создаём результирующую таблицу
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Товар");
    ТаблицаРезультат.Колонки.Добавить("НаименованиеТовара");
    ТаблицаРезультат.Колонки.Добавить("СуммаПродаж");
    ТаблицаРезультат.Колонки.Добавить("ДоляПроцентов");
    ТаблицаРезультат.Колонки.Добавить("НакопительныйПроцент");
    ТаблицаРезультат.Колонки.Добавить("КатегорияABC");

    // Формируем итоговую таблицу с ABC-категориями
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.Товар,
    |    ПродажиОбороты.Товар.Наименование КАК НаименованиеТовара,
    |    ПродажиОбороты.СуммаОборот КАК СуммаПродаж
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, Авто, Товар) КАК ПродажиОбороты
    |ГДЕ
    |    ПродажиОбороты.СуммаОборот > 0
    |УПОРЯДОЧИТЬ ПО
    |    ПродажиОбороты.СуммаОборот УБЫВ";

    Выборка = Запрос.Выполнить().Выбрать();

    НакопительныйПроцент = 0;

    Пока Выборка.Следующий() Цикл

        Если ОбщаяСумма > 0 Тогда
            ДоляПроцентов = Выборка.СуммаПродаж / ОбщаяСумма * 100;
        Иначе
            ДоляПроцентов = 0;
        КонецЕсли;

        НакопительныйПроцент = НакопительныйПроцент + ДоляПроцентов;

        Если НакопительныйПроцент <= 80 Тогда
            КатегорияABC = "A";
        ИначеЕсли НакопительныйПроцент <= 95 Тогда
            КатегорияABC = "B";
        Иначе
            КатегорияABC = "C";
        КонецЕсли;

        НоваяСтрока = ТаблицаРезультат.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.НаименованиеТовара = Выборка.НаименованиеТовара;
        НоваяСтрока.СуммаПродаж = Выборка.СуммаПродаж;
        НоваяСтрока.ДоляПроцентов = Окр(ДоляПроцентов, 2);
        НоваяСтрока.НакопительныйПроцент = Окр(НакопительныйПроцент, 2);
        НоваяСтрока.КатегорияABC = КатегорияABC;

    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

Функция ВыгрузитьЗадолженностьВФайлJSON() Экспорт

    ИмяВременногоФайла = ПолучитьИмяВременногоФайла("json");

    ЗаписьJSON = Новый ЗаписьJSON;
    ЗаписьJSON.ОткрытьФайл(ИмяВременногоФайла, "UTF-8");
    ЗаписьJSON.ЗаписатьНачалоМассива();

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Контрагент.Наименование КАК Контрагент,
    |    ВзаиморасчетыОстатки.Контрагент.Код КАК КодКонтрагента,
    |    ВзаиморасчетыОстатки.СуммаОстаток КАК СуммаОстаток
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(
    |            ,
    |            Контрагент <> ЗНАЧЕНИЕ(Справочник.Контрагенты.ПустаяСсылка)
    |        ) КАК ВзаиморасчетыОстатки
    |ГДЕ
    |    ВзаиморасчетыОстатки.СуммаОстаток <> 0
    |УПОРЯДОЧИТЬ ПО
    |    Контрагент.Наименование";

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    ПервыйЭлемент = Истина;
    Пока Выборка.Следующий() Цикл

        Если Не ПервыйЭлемент Тогда
            ЗаписьJSON.ЗаписатьЗначение(",");
        КонецЕсли;
        ПервыйЭлемент = Ложь;

        ЗаписьJSON.ЗаписатьНачалоОбъекта();

        ЗаписьJSON.ЗаписатьИмяСвойства("Контрагент");
        ЗаписьJSON.ЗаписатьЗначение(Выборка.Контрагент);

        ЗаписьJSON.ЗаписатьИмяСвойства("КодКонтрагента");
        ЗаписьJSON.ЗаписатьЗначение(Выборка.КодКонтрагента);

        ЗаписьJSON.ЗаписатьИмяСвойства("СуммаОстаток");
        ЗаписьJSON.ЗаписатьЧисло(Выборка.СуммаОстаток);

        Если Выборка.СуммаОстаток > 0 Тогда
            ВидЗадолженности = "Дебиторская";
        Иначе
            ВидЗадолженности = "Кредиторская";
        КонецЕсли;

        ЗаписьJSON.ЗаписатьИмяСвойства("ВидЗадолженности");
        ЗаписьJSON.ЗаписатьЗначение(ВидЗадолженности);

        ЗаписьJSON.ЗаписатьКонецОбъекта();

    КонецЦикла;

    ЗаписьJSON.ЗаписатьКонецМассива();
    ЗаписьJSON.Закрыть();

    Возврат ИмяВременногоФайла;

КонецФункции

// Функция формирует отчет об остатках номенклатуры на заданную дату
//
// Параметры:
//  ДатаОтчета   - Дата - дата формирования отчета
//  МассивТоваров - Массив - массив товаров для отбора (может быть пустым или Неопределено)
//  Склад        - СправочникСсылка.Склады - склад для отбора (может быть Неопределено)
//
// Возвращаемое значение:
//  ТабличныйДокумент - сформированный отчет
//
Функция СформироватьОтчетОстаткиПоНоменклатуре(ДатаОтчета, МассивТоваров, Склад) Экспорт

    // Создаем табличный документ для вывода отчета
    ТабДокумент = Новый ТабличныйДокумент;
    ТабДокумент.ОриентацияСтраницы = ОриентацияСтраницы.Портрет;
    ТабДокумент.АвтоМасштаб = Истина;

    // Получаем макет отчета
    Макет = ПолучитьОбщийМакет("МакетОтчетаОстаткиПоНоменклатуре");

    // Создаем запрос для получения остатков
    Запрос = Новый Запрос;

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("Период",      ДатаОтчета);
    Запрос.УстановитьПараметр("МассивТоваров", МассивТоваров);
    Запрос.УстановитьПараметр("Склад",       Склад);

    // Определяем условие отбора по номенклатуре
    УсловиеПоТоварам = "";
    Если МассивТоваров <> Неопределено И МассивТоваров.Количество() > 0 Тогда
        УсловиеПоТоварам = "И ТоварныеЗапасыОстатки.Товар В (&МассивТоваров)";
    КонецЕсли;

    // Определяем условие отбора по складу
    УсловиеПоСкладу = "";
    Если Склад <> Неопределено Тогда
        УсловиеПоСкладу = "И ТоварныеЗапасыОстатки.Склад = &Склад";
    КонецЕсли;

    // Формируем текст запроса
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Номенклатура,
    |    ТоварныеЗапасыОстатки.Товар.Наименование КАК НоменклатураНаименование,
    |    ТоварныеЗапасыОстатки.Товар.Артикул КАК Артикул,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток КАК Остаток
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(
    |        &Период,
    |        Товар <> ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка)
    |        %УсловиеПоТоварам%
    |        %УсловиеПоСкладу%
    |    ) КАК ТоварныеЗапасыОстатки
    |УПОРЯДОЧИТЬ ПО
    |    НоменклатураНаименование
    |ИТОГИ
    |    СУММА(Остаток) КАК ОбщийОстаток
    |ПО
    |    ОБЩИЕ";

    // Заменяем параметры условий в тексте запроса
    Запрос.Текст = СтрЗаменить(Запрос.Текст, "%УсловиеПоТоварам%", УсловиеПоТоварам);
    Запрос.Текст = СтрЗаменить(Запрос.Текст, "%УсловиеПоСкладу%", УсловиеПоСкладу);

    // Выводим заголовок отчета
    ОбластьЗаголовок = Макет.ПолучитьОбласть("Заголовок");
    ОбластьЗаголовок.Параметры.Заголовок = НСтр("ru = 'Остатки номенклатуры'");
    ОбластьЗаголовок.Параметры.Период    = Формат(ДатаОтчета, "ДЛФ=DD");

    // Выводим информацию о складе, если указан
    Если Склад <> Неопределено Тогда
        ОбластьЗаголовок.Параметры.Склад = Склад.Наименование;
    Иначе
        ОбластьЗаголовок.Параметры.Склад = НСтр("ru = 'Все склады'");
    КонецЕсли;

    ТабДокумент.Вывести(ОбластьЗаголовок);

    // Выводим шапку таблицы
    ОбластьШапка = Макет.ПолучитьОбласть("Шапка");
    ТабДокумент.Вывести(ОбластьШапка);

    // Выполняем запрос
    РезультатЗапроса = Запрос.Выполнить();

    // Проверяем наличие данных
    Если РезультатЗапроса.Пустой() Тогда
        ОбластьНетДанных = Макет.ПолучитьОбласть("НетДанных");
        ОбластьНетДанных.Параметры.Сообщение = НСтр("ru = 'Нет данных для отображения'");
        ТабДокумент.Вывести(ОбластьНетДанных);
        Возврат ТабДокумент;
    КонецЕсли;

    // Получаем выборку с иерархией (итоги по общему)
    ВыборкаИтоги = РезультатЗапроса.Выбрать(ОбходРезультатаЗапроса.ПоГруппировкам);

    Если ВыборкаИтоги.Следующий() Тогда
        ОбщийОстаток = ВыборкаИтоги.ОбщийОстаток;
    Иначе
        ОбщийОстаток = 0;
    КонецЕсли;

    // Получаем детальные записи
    Выборка = РезультатЗапроса.Выбрать(ОбходРезультатаЗапроса.ПоГруппировкам, "ДетальныеЗаписи");

    // Выводим строки данных
    Пока Выборка.Следующий() Цикл
        ОбластьСтрока = Макет.ПолучитьОбласть("Строка");
        ОбластьСтрока.Параметры.Заполнить(Выборка);
        ОбластьСтрока.Параметры.Номенклатура = Выборка.Номенклатура;
        ТабДокумент.Вывести(ОбластьСтрока);
    КонецЦикла;

    // Выводим итоги
    ОбластьИтоги = Макет.ПолучитьОбласть("Итоги");
    ОбластьИтоги.Параметры.ОбщийОстаток = ОбщийОстаток;
    ТабДокумент.Вывести(ОбластьИтоги);

    // Устанавливаем окончательный вид отчета
    ТабДокумент.ФиксацияСверху = ТабДокумент.ВысотаТаблицы;

    Возврат ТабДокумент;

КонецФункции

// Функция рассчитывает оборачиваемость товара на складе за период
//
// Параметры:
//  Товар - СправочникСсылка.Товары - товар для расчёта
//  Склад - СправочникСсылка.Склады - склад для расчёта
//  ДатаНачала - Дата - начало периода расчёта
//  ДатаОкончания - Дата - конец периода расчёта
//
// Возвращаемое значение:
//  Число - коэффициент оборачиваемости
//
Функция РассчитатьОборачиваемость(Товар, Склад, ДатаНачала, ДатаОкончания) Экспорт

    Запрос = Новый Запрос;

    Запрос.Текст =
    "ВЫБРАТЬ
    |    ОстаткиНаНачало.КоличествоОстаток КАК КоличествоНачало,
    |    ОстаткиНаКонец.КоличествоОстаток КАК КоличествоКонец,
    |    ЕСТЬNULL(Обороты.КоличествоОборот, 0) КАК КоличествоОборот
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаНачала, Товар = &Товар И Склад = &Склад) КАК ОстаткиНаНачало
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаОкончания, Товар = &Товар И Склад = &Склад) КАК ОстаткиНаКонец
    |        ПО ИСТИНА
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварныеЗапасы.Обороты(&ДатаНачала, &ДатаОкончания, , Товар = &Товар И Склад = &Склад) КАК Обороты
    |        ПО ИСТИНА
    |ГДЕ
    |    ОстаткиНаНачало.Товар = &Товар
    |    И ОстаткиНаНачало.Склад = &Склад";

    Запрос.УстановитьПараметр("Товар", Товар);
    Запрос.УстановитьПараметр("Склад", Склад);
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

    Результат = Запрос.Выполнить();

    Если Результат.Пустой() Тогда
        Возврат 0;
    КонецЕсли;

    Выборка = Результат.Выбрать();
    Выборка.Следующий();

    // Обработка NULL значений
    КоличествоНачало = ?(Выборка.КоличествоНачало = NULL, 0, Выборка.КоличествоНачало);
    КоличествоКонец = ?(Выборка.КоличествоКонец = NULL, 0, Выборка.КоличествоКонец);
    КоличествоОборот = Выборка.КоличествоОборот;

    // Расчёт среднего остатка
    СреднийОстаток = (КоличествоНачало + КоличествоКонец) / 2;

    // Проверка деления на ноль
    Если СреднийОстаток = 0 Тогда
        Возврат 0;
    КонецЕсли;

    // Расчёт оборачиваемости
    Оборачиваемость = КоличествоОборот / СреднийОстаток;

    Возврат Оборачиваемость;

КонецФункции

task:
Написать функцию СформироватьПрайсТоваровНаСкладе(Дата = Неопределено),
которая формирует прайс товаров, имеющихся в наличии на складе, на указанную дату.
Формирование прайса должно выполняться на основании данных регистра накопления «ТоварныеЗапасы» и регистра сведений «ЦеныТоваров».
Если параметр Дата не передан, в качестве даты формирования прайса используется конец текущего дня (КонецДня(ТекущаяДата())).
Алгоритм формирования данных выполняется следующим образом:
Сначала выполняется запрос к регистру накопления РегистрНакопления.ТоварныеЗапасы.Остатки, где:
отбираются только товары с положительным остатком (КоличествоОстаток > 0);
данные агрегируются по товару;
результат помещается во временную таблицу (ВременнаяТаблица), содержащую:
Товар;
КоличествоОстаток (суммарный остаток по товару).
Далее выполняется основной запрос, в котором:
используются актуальные цены из регистра сведений РегистрСведений.ЦеныТоваров (СрезПоследних);
выполняется внутреннее соединение с временной таблицей остатков по полю Товар;
рассчитываются итоговые показатели:
Цена — актуальная цена товара;
Остаток — количество товара на складе;
СуммаОстатков — произведение остатка на цену (стоимость складского запаса).
Результат запроса выгружается в таблицу значений.
На основании полученных данных формируется итоговая таблица (ТаблицаЗначений) со следующей структурой колонок:
Товар (СправочникСсылка.Товары);
Наименование (строковое представление товара);
Остаток (число);
Цена (число);
СуммаОстатков (число).
Для каждой строки выборки:
создаётся новая строка в таблице значений;
заполняются поля Товар, Остаток, Цена и СуммаОстатков.
После заполнения таблица сортируется по наименованию товара по возрастанию, что обеспечивает удобный вид прайса для анализа и печати.
Функция возвращает таблицу значений, содержащую прайс товаров на складе с актуальными остатками и ценами на указанную дату.
Функция ЗадачаРешена(ТабДок) предназначена для проверки корректности сформированного прайса и выполняет следующие проверки:
результат является типом ТаблицаЗначений;
таблица содержит обязательные колонки: Товар, Цена, Остаток;
таблица не пустая;
у каждой строки заполнен товар;
остаток товара не является отрицательным.
Если все проверки выполняются успешно, функция возвращает Истина, что подтверждает корректное формирование прайса товаров на складе.

output:
// Функция формирует прайс товаров, имеющихся в наличии на складе
Функция СформироватьПрайсТоваровНаСкладе(Дата = Неопределено) Экспорт

    // Определение даты формирования прайса
    Если Дата = Неопределено Тогда
        ДатаПрайса = КонецДня(ТекущаяДата());
    Иначе
        ДатаПрайса = Дата;
    КонецЕсли;

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар,
    |    СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) КАК КоличествоОстаток
    |ПОМЕСТИТЬ ВременнаяТаблица
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата, ) КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |    ТоварныеЗапасыОстатки.КоличествоОстаток > 0
    |
    |СГРУППИРОВАТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ВременнаяТаблица.Товар,
    |    ВременнаяТаблица.Товар.Наименование КАК Наименование,
    |    ВременнаяТаблица.КоличествоОстаток КАК Остаток,
    |    ЕСТЬNULL(ЦеныТоваровСрезПоследних.Цена, 0) КАК Цена,
    |    ВременнаяТаблица.КоличествоОстаток * ЕСТЬNULL(ЦеныТоваровСрезПоследних.Цена, 0) КАК СуммаОстатков
    |ИЗ
    |    ВременнаяТаблица КАК ВременнаяТаблица
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних(&Дата, ) КАК ЦеныТоваровСрезПоследних
    |        ПО ВременнаяТаблица.Товар = ЦеныТоваровСрезПоследних.Товар
    |
    |УПОРЯДОЧИТЬ ПО
    |    Наименование
    |";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("Дата", ДатаПрайса);

    // Выполнение запроса и получение результата
    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений и загрузка результата
    ТаблицаПрайса = Новый ТаблицаЗначений;
    ТаблицаПрайса.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаПрайса.Колонки.Добавить("Наименование", Новый ОписаниеТипов("Строка"));
    ТаблицаПрайса.Колонки.Добавить("Остаток", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаПрайса.Колонки.Добавить("Цена", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаПрайса.Колонки.Добавить("СуммаОстатков", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Заполнение таблицы значений из результата запроса
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаПрайса.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.Наименование = Выборка.Наименование;
        НоваяСтрока.Остаток = Выборка.Остаток;
        НоваяСтрока.Цена = Выборка.Цена;
        НоваяСтрока.СуммаОстатков = Выборка.СуммаОстатков;
    КонецЦикла;

    Возврат ТаблицаПрайса;

КонецФункции

// Функция проверки корректности сформированного прайса
Функция ЗадачаРешена(ТабДок) Экспорт

    // Проверка типа результата
    Если ТипЗнч(ТабДок) <> Тип("ТаблицаЗначений") Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверка наличия обязательных колонок
    ОбязательныеКолонки = Новый Массив;
    ОбязательныеКолонки.Добавить("Товар");
    ОбязательныеКолонки.Добавить("Цена");
    ОбязательныеКолонки.Добавить("Остаток");

    Для Каждого ИмяКолонки Из ОбязательныеКолонки Цикл
        Если ТабДок.Колонки.Найти(ИмяКолонки) = Неопределено Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    // Проверка, что таблица не пустая
    Если ТабДок.Количество() = 0 Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверка заполненности товара и отсутствия отрицательных остатков
    Для Каждого СтрокаТаблицы Из ТабДок Цикл
        Если НЕ ЗначениеЗаполнено(СтрокаТаблицы.Товар) Тогда
            Возврат Ложь;
        КонецЕсли;
        Если СтрокаТаблицы.Остаток < 0 Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    Возврат Истина;

КонецФункции

// Функция формирует отчет "ДинамикаПродаж" с программной настройкой параметров
//
// Параметры:
//  ДатаНачала    - Дата - начало периода отчета
//  ДатаОкончания - Дата - конец периода отчета
//  Товар         - СправочникСсылка.Товары - товар для отбора
//
// Возвращаемое значение:
//  ТабличныйДокумент - сформированный отчет
//
Функция СформироватьОтчетДинамикаПродажТовара(ДатаНачала, ДатаОкончания, Товар) Экспорт

    // Получаем ссылку на вариант отчета
    ВариантОтчета = Справочники.ВариантыОтчетов.НайтиПоНаименованию("СуммаИКоличество");
    Если НЕ ЗначениеЗаполнено(ВариантОтчета) Тогда
        ВызватьИсключение "Не найден вариант отчета ""СуммаИКоличество""!";
    КонецЕсли;

    // Получаем отчет по варианту
    ОтчетСсылка = ВариантОтчета.Отчет;
    ОтчетОбъект = Отчеты[ОтчетСсылка.Метаданные().Имя].СоздатьОбъект();

    // Получаем компоновщик настроек и загружаем настройки варианта отчета
    КомпоновщикНастроек = ОтчетОбъект.КомпоновщикНастроек;
    Настройки = ВариантОтчета.Настройки.Получить();
    КомпоновщикНастроек.ЗагрузитьНастройки(Настройки);

    // Работаем с основными настройками
    НастройкиКД = КомпоновщикНастроек.Настройки;

    // Устанавливаем отбор по товару
    // Получаем элемент отбора или создаем новый
    ЭлементОтбора = НастройкиКД.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение  = Новый ПолеКомпоновкиДанных("Товар");
    ЭлементОтбора.ВидСравнения   = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбора.ПравоеЗначение = Товар;
    ЭлементОтбора.Использование  = Истина;

    // Формируем структуру отчета: группировка "Период"
    // Получаем структуру (для диаграммы - это ГруппировкаДиаграммы)
    СтруктураНастроек = НастройкиКД.Структура;

    // Если структура пустая, добавляем новую группировку
    Если СтруктураНастроек.Количество() = 0 Тогда
        СтрокаГруппировки = СтруктураНастроек.Добавить();
    Иначе
        // Используем первую группировку
        СтрокаГруппировки = СтруктураНастроек[0];
    КонецЕсли;

    // Устанавливаем тип группировки и тип дополнения
    СтрокаГруппировки.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    СтрокаГруппировки.ТипДополненияПериода = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Добавляем поле группировки "Период"
    ПолеГруппировки = СтрокаГруппировки.ПоляГруппировки.Элементы.Добавить(Тип("ПолеГруппировкиКомпоновкиДанных"));
    ПолеГруппировки.Поле = Новый ПолеКомпоновкиДанных("Период");

    // Добавляем поле "Период" в выбор
    ВыборПериод = СтрокаГруппировки.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыборПериод.Поле = Новый ПолеКомпоновкиДанных("Период");
    ВыборПериод.Заголовок = "Период";

    // Параметры вывода: не выводить параметры данных и отбор
    ЗаполнитьЭлементы(НастройкиКД.ПараметрыВывода, Ложь, "ВыводитьПараметрыДанных");
    ЗаполнитьЭлементы(НастройкиКД.ПараметрыВывода, Ложь, "ВыводитьОтбор");

    // Заполняем параметры отчета - Период
    ПараметрПериод = КомпоновщикНастроек.Настройки.ПараметрыДанных.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("Период"));
    Если ПараметрПериод <> Неопределено Тогда

        // Проверяем доступность стандартных атрибутов параметра "Период"
        Если ПараметрПериод.Использование 
            И ПараметрПериод.Значение <> Неопределено 
            И НЕ ПараметрПериод.Значение.Пустая() 
            И СтруктураТипаПериод(ПараметрПериод.Значение) = "СтандартныйПериод" Тогда

            // Для стандартного периода используем атрибуты СтандартнаяДатаНачала и СтандартнаяДатаОкончания
            ПараметрПериод.Значение.ДатаНачала    = ДатаНачала;
            ПараметрПериод.Значение.ДатаОкончания = ДатаОкончания;

        Иначе
            // Прямая установка параметра "Период"
            НастройкиКД.ПараметрыДанных.УстановитьПараметр("Период", 
                Новый СтандартныйПериод(ДатаНачала, ДатаОкончания));
        КонецЕсли;

    КонецЕсли;

    // Инициализируем компоновщик и получаем схему
    ОтчетОбъект.ИнициализироватьОтчет();
    СхемаКД = ОтчетОбъект.СхемаКомпоновкиДанных;

    // Инициализируем параметры на основе схемы
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКД));

    // Выполняем компоновку
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКД = КомпоновщикМакета.Выполнить(СхемаКД, НастройкиКД, , , Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииТаблицЗначений"));

    // Создаем процессоры данных
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКД);

    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Новый ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ПроцессорВывода.Документ;

КонецФункции

// Вспомогательная процедура для рекурсивного заполнения параметров вывода
//
// Параметры:
//  КоллекцияЭлементов - Коллекция элементов структуры настроек
//  Значение          - Устанавливаемое значение
//  ИмяПараметра      - Имя параметра для установки
//
Процедура ЗаполнитьЭлементы(КоллекцияЭлементов, Значение, ИмяПараметра)

    Для Каждого Элемент Из КоллекцияЭлементов Цикл

        // Проверяем, доступен ли параметр "ВыводитьПараметрыДанных"
        Попытка
            Доступно = Элемент.ВыводитьПараметрыДанных;
        Исключение
            Доступно = Ложь;
        КонецПопытки;

        Если Доступно Тогда
            Если ВРег(Элемент.Имя) = ВРег("ВыводитьПараметрыДанных") Тогда
                Элемент.ВыводитьПараметрыДанных = Значение;
            КонецЕсли;
            Если ВРег(Элемент.Имя) = ВРег("ВыводитьОтбор") Тогда
                Элемент.ВыводитьОтбор = Значение;
            КонецЕсли;
        КонецЕсли;

        // Рекурсивно обрабатываем вложенные структуры
        Попытка
            Для Каждого ВложенныйЭлемент Из Элемент.Структура Цикл
                ЗаполнитьЭлементы(ВложенныйЭлемент, Значение, ИмяПараметра);
            КонецЦикла;
        Исключение
            // Структура не доступна, пропускаем
        КонецПопытки;

    КонецЦикла;

КонецПроцедуры

// Вспомогательная функция для определения типа параметра "Период"
//
// Параметры:
//  ЗначениеПараметра - Значение параметра
//
// Возвращаемое значение:
//  Строка - имя типа значения
//
Функция СтруктураТипаПериод(ЗначениеПараметра)

    ТипЗначения = ТипЗнч(ЗначениеПараметра);

    Если ТипЗначения = Тип("СтандартныйПериод") Тогда
        Возврат "СтандартныйПериод";
    КонецЕсли;

    Возврат "";

КонецФункции

task:
Написать функцию СформироватьПереоценкуТоваровНаСкладе(Дата, ПроцентПереоценки),
которая формирует расчет переоценки товаров на складе и выводит прайс с учетом увеличения цены на заданный процент (по умолчанию 10%).
Расчет должен выполняться на основании остатков товаров на складе и актуальных цен номенклатуры.
В обработку должны попадать только те товары, по которым есть положительные остатки на складе.
Если параметр Дата не задан, используется текущая дата (конец дня).
Если процент переоценки не задан, используется значение 10%.
Источник данных:
Регистр накопления ТоварныеЗапасы (остатки товаров на складе);
Регистр сведений ЦеныТоваров (актуальные цены товаров, срез последних на дату).
Логика формирования данных:
Из регистра накопления ТоварныеЗапасы.Остатки выбираются товары с положительным количеством остатка на указанную дату.
Данные агрегируются по измерению Товар с расчетом:
Остаток — суммарное количество товара на складе.
К полученным остаткам выполняется присоединение регистра сведений ЦеныТоваров.СрезПоследних на ту же дату для получения актуальной цены.
Рассчитываются показатели переоценки:
СтараяЦена — текущая цена из регистра цен;
НоваяЦена — цена с учетом переоценки (СтараяЦена * (1 + ПроцентПереоценки / 100));
СуммаПереоценки — общий эффект переоценки по складу (разница цены * остаток товара).
Результат формирования должен представлять таблицу значений (ТаблицаЗначений), содержащую следующие колонки:
Товар (СправочникСсылка.Товары);
Наименование (представление товара);
Остаток (число);
СтараяЦена (число);
НоваяЦена (число);
СуммаПереоценки (число).
В итоговую таблицу включаются только товары, имеющие цену и положительные остатки.
Наименование товара заполняется через представление ссылочного поля номенклатуры для удобства анализа.
После заполнения данных выполняется сортировка таблицы по убыванию суммы переоценки, что позволяет в первую очередь анализировать товары с наибольшим финансовым эффектом от изменения цены.
Функция должна возвращать сформированную таблицу значений, пригодную для:
анализа розничной переоценки;
формирования прайса после изменения цен;
оценки влияния переоценки на стоимость складских остатков;
использования в управленческих отчетах по складу и рознице.

output:
// Функция формирует таблицу значений с данными переоценки товаров на складе
//
// Параметры:
//   Дата - Дата - Дата расчета остатков и цен (необязательно)
//           Если не задана, используется текущая дата (конец дня)
//   ПроцентПереоценки - Число - Процент увеличения цены (необязательно)
//           Если не задан, используется значение 10
//
// Возвращаемое значение:
//   ТаблицаЗначений - с колонками:
//     Товар - СправочникСсылка.Товары
//     Наименование - Строка
//     Остаток - Число
//     СтараяЦена - Число
//     НоваяЦена - Число
//     СуммаПереоценки - Число
//
Функция СформироватьПереоценкуТоваровНаСкладе(Дата = '00010101', ПроцентПереоценки = 0) Экспорт

    // Установка значений по умолчанию
    Если НЕ ЗначениеЗаполнено(Дата) Тогда
        ДатаПереоценки = КонецДня(ТекущаяДата());
    Иначе
        ДатаПереоценки = КонецДня(Дата);
    КонецЕсли;

    Если ПроцентПереоценки = 0 Тогда
        Процент = 10;
    Иначе
        Процент = ПроцентПереоценки;
    КонецЕсли;

    // Создание запроса
    Запрос = Новый Запрос;

    // Формирование текста запроса
    Запрос.Текст =
    "ВЫБРАТЬ
    |    Остатки.Товар,
    |    Остатки.Товар.Представление КАК Наименование,
    |    Остатки.Остаток,
    |    Цены.Цена КАК СтараяЦена,
    |    Цены.Цена * (1 + &Процент / 100) КАК НоваяЦена,
    |    (Цены.Цена * (1 + &Процент / 100) - Цены.Цена) * Остатки.Остаток КАК СуммаПереоценки
    |ИЗ
    |    (ВЫБРАТЬ
    |        ТоварныеЗапасыОстатки.Товар,
    |        СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) КАК Остаток
    |    ИЗ
    |        РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата, ) КАК ТоварныеЗапасыОстатки
    |    СГРУППИРОВАТЬ ПО
    |        ТоварныеЗапасыОстатки.Товар
    |    ИМЕЮЩИЕ
    |        СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) > 0
    |    ) КАК Остатки
    |ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних(&Дата, ) КАК Цены
    |ПО Остатки.Товар = Цены.Товар
    |УПОРЯДОЧИТЬ ПО
    |    СуммаПереоценки УБЫВ";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("Дата", ДатаПереоценки);
    Запрос.УстановитьПараметр("Процент", Процент);

    // Выполнение запроса и получение результата
    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений и загрузка результата
    ТаблицаРезультата = РезультатЗапроса.Выгрузить();

    // Возврат таблицы результата
    Возврат ТаблицаРезультата;

КонецФункции

// Функция формирует отчет "ДинамикаПродаж" с программной заменой структуры
// на группировку по полю "Период" и настраивает отбор по СуммаОборот
//
// Параметры:
//   ДатаНачала - Дата - начало периода отчета
//   ДатаОкончания - Дата - окончание периода отчета
//   СуммаКонтроль - Число - значение для отбора по СуммаОборот
//   ТипКонтроля - ВидСравненияКомпоновкиДанных - вид сравнения для отбора
//
// Возвращаемое значение:
//   ТабличныйДокумент - результат формирования отчета
//
// Исключения:
//   Если ТипКонтроля не поддерживается - выбрасывается исключение
//
Функция СформироватьОтчетДинамикаПродажКонтрольВТаблице(
    ДатаНачала,
    ДатаОкончания,
    СуммаКонтроль,
    ТипКонтроля
) Экспорт

    // Проверка поддерживаемых видов сравнения
    ПоддерживаемыеВидыСравнения = Новый Массив;
    ПоддерживаемыеВидыСравнения.Добавить(ВидСравненияКомпоновкиДанных.Равно);
    ПоддерживаемыеВидыСравнения.Добавить(ВидСравненияКомпоновкиДанных.БольшеИлиРавно);
    ПоддерживаемыеВидыСравнения.Добавить(ВидСравненияКомпоновкиДанных.МеньшеИлиРавно);
    ПоддерживаемыеВидыСравнения.Добавить(ВидСравненияКомпоновкиДанных.Больше);
    ПоддерживаемыеВидыСравнения.Добавить(ВидСравненияКомпоновкиДанных.Меньше);

    Если ПоддерживаемыеВидыСравнения.Найти(ТипКонтроля) = Неопределено Тогда
        ВызватьИсключение СтроковыеФункцииКлиентСервер.ПодставитьПараметрыВСтроку(
            НСтр("ru = 'Тип контроля %1 не поддерживается. 
                  |Доступные значения: Равно, БольшеИлиРавно, МеньшеИлиРавно, Больше, Меньше.'"),
            ТипКонтроля
        );
    КонецЕсли;

    // Получение объекта отчета и его схемы компоновки данных
    ОтчетОбъект = Отчеты.ДинамикаПродаж.Создать();
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создание компоновщика настроек на основе схемы
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(
        Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных)
    );

    // Загрузка настроек по умолчанию из схемы
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.НастройкиПоУмолчанию);

    // Получение настроек для редактирования
    Настройки = КомпоновщикНастроек.Настройки;

    // Установка параметров периода отчета
    ПараметрПериод = Настройки.ПараметрыДанных.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("Период")
    );

    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Значение.ДатаНачала = ДатаНачала;
        ПараметрПериод.Значение.ДатаОкончания = ДатаОкончания;
        ПараметрПериод.Использование = Истина;
    КонецЕсли;

    // Установка параметра СуммаОборот для отбора
    ПараметрСумма = Настройки.ПараметрыДанных.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("СуммаОборот")
    );

    Если ПараметрСумма <> Неопределено Тогда
        ПараметрСумма.Значение = СуммаКонтроль;
        ПараметрСумма.Использование = Истина;
    КонецЕсли;

    // Формирование отбора по СуммаОборот в зависимости от типа контроля
    // Очищаем существующий отбор и добавляем новый элемент
    Отбор = Настройки.Отбор;
    Отбор.Элементы.Очистить();

    НовыйЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    НовыйЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СуммаОборот");
    НовыйЭлементОтбора.ВидСравнения = ТипКонтроля;
    НовыйЭлементОтбора.ПравоеЗначение = СуммаКонтроль;
    НовыйЭлементОтбора.Использование = Истина;

    // Программная замена структуры отчета на группировку по "Период"
    // Очищаем текущую структуру (диаграмму) и создаем новую группировку
    СтруктураОтчета = Настройки.Структура;
    СтруктураОтчета.Очистить();

    // Создание группировки по полю "Период"
    ГруппировкаПериод = СтруктураОтчета.Добавить(Тип("ГруппировкаКомпоновкиДанных"));

    // Добавление поля группировки "Период"
    ПолеГруппировки = ГруппировкаПериод.ПоляГруппировки.Элементы.Добавить(
        Тип("ПолеГруппировкиКомпоновкиДанных")
    );
    ПолеГруппировки.Поле = Новый ПолеКомпоновкиДанных("Период");
    ПолеГруппировки.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Установка типа группировки - только элементы (без иерархии и итогов)
    ПолеГруппировки.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;

    // Настройка вывода группировки
    ГруппировкаПериод.Вывод.УстановитьВывод(ВыводНастроекКомпоновкиДанных.НеВыводить);

    // Автосистемное поле для вывода детальных записей
    АвтоПоле = ГруппировкаПериод.Выбор.Элементы.Добавить(Тип("АвтоВыбранноеПолеКомпоновкиДанных"));

    // Настройка параметров вывода отчета
    ПараметрыВывода = Настройки.ПараметрыВывода;

    // Отключение вывода параметров данных
    ПараметрВыводаПараметрыДанных = Настройки.ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрМакетаКомпоновкиДанных("ВыводитьПараметрыДанных")
    );

    Если ПараметрВыводаПараметрыДанных <> Неопределено Тогда
        ПараметрВыводаПараметрыДанных.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаПараметрыДанных.Использование = Истина;
    КонецЕсли;

    // Отключение вывода отбора
    ПараметрВыводаОтбор = Настройки.ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрМакетаКомпоновкиДанных("ВыводитьОтбор")
    );

    Если ПараметрВыводаОтбор <> Неопределено Тогда
        ПараметрВыводаОтбор.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаОтбор.Использование = Истина;
    КонецЕсли;

    // Фиксированные настройки (не будут сброшены пользователем)
    Настройки.ФиксированныеНастройки.ПараметрыДанных.Элементы.Очистить();
    Настройки.ФиксированныеНастройки.Отбор.Элементы.Очистить();

    // Компоновка макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        Настройки,
        ,
        ,
        ТипМакетаКомпоновкиДанных.ТабличныйДокумент
    );

    // Процессор компоновки данных
    ПроцессорКомпоновкиДанных = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновкиДанных.Инициализировать(МакетКомпоновки);

    // Создание табличного документа для вывода результата
    ТабличныйДокумент = Новый ТабличныйДокумент;

    // Процессор вывода результата
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновкиДанных);

    // Возврат сформированного табличного документа
    Возврат ТабличныйДокумент;

КонецФункции

task:
Написать функцию СформироватьРезервированиеТоваровПодЗаказы(Дата = Неопределено),
которая формирует отчет по резервированию товаров на складе под заказы клиентов в виде таблицы значений.
Отчет должен показывать, какое количество товара уже заказано клиентами, какой остаток есть на складе и хватает ли его для обеспечения заказов.
Если дата не передана в параметрах, расчет должен выполняться на конец текущего дня (КонецДня(ТекущаяДата())).
Данные для формирования отчета выбираются из следующих источников метаданных:
Документ.Заказ (табличная часть Товары);
РегистрНакопления.ТоварныеЗапасы.Остатки.
Отбор заказов выполняется по следующим условиям:
документ Заказ проведен (Проведен = Истина);
состояние заказа равно значению перечисления СостоянияЗаказов.ВРаботе.
Алгоритм формирования отчета выполняется следующим образом:
Выполняется запрос к табличной части Документ.Заказ.Товары, где:
данные агрегируются по номенклатуре (Товар);
рассчитывается суммарное количество товара в активных заказах клиентов (КоличествоВЗаказах).
Полученные данные помещаются во временную таблицу.
Далее выполняется запрос к регистру накопления ТоварныеЗапасы.Остатки на указанную дату:
определяется остаток товара на складе (КоличествоОстаток);
выполняется левое соединение с временной таблицей заказов.
Рассчитываются итоговые показатели:
ОстатокНаСкладе — текущий складской остаток товара;
КоличествоВЗаказах — общее количество товара в заказах клиентов;
ДоступныйОстаток — разница между остатком и количеством в заказах;
РезервКОбеспечению — дефицит товара (если заказов больше, чем остатка).
Результат работы функции должен представлять ТаблицаЗначений, где каждая строка соответствует одному товару.
Таблица должна содержать следующие колонки:
Товар — ссылка на элемент справочника Товары;
Наименование — наименование номенклатуры;
ОстатокНаСкладе — текущий остаток товара на складе;
КоличествоВЗаказах — суммарное количество товара в активных заказах клиентов;
ДоступныйОстаток — доступный остаток с учетом резервирования;
РезервКОбеспечению — количество товара, которого не хватает для обеспечения заказов.
В итоговую таблицу включаются только товары, по которым есть остатки или заказы клиентов.
После формирования данных таблица сортируется по полю РезервКОбеспечению в порядке убывания, что позволяет в первую очередь видеть наиболее дефицитные позиции.
Функция ЗадачаРешена(ТабДок) должна выполнять проверку корректности результата:
результат должен быть типа ТаблицаЗначений;
таблица должна содержать обязательные колонки (Товар, ОстатокНаСкладе, КоличествоВЗаказах, РезервКОбеспечению);
у всех строк должен быть заполнен товар;
значение резерва не должно быть отрицательным.
Если структура данных корректна, функция возвращает Истина, в противном случае — Ложь.

output:
// Функция формирует отчет по резервированию товаров на складе под заказы клиентов
Функция СформироватьРезервированиеТоваровПодЗаказы(Дата = Неопределено) Экспорт

    // Создаем таблицу значений для результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    Результат.Колонки.Добавить("Наименование", Новый ОписаниеТипов("Строка"));
    Результат.Колонки.Добавить("ОстатокНаСкладе", Новый ОписаниеТипов("Число", , , Новый КвалификаторыЧисла(10, 2)));
    Результат.Колонки.Добавить("КоличествоВЗаказах", Новый ОписаниеТипов("Число", , , Новый КвалификаторыЧисла(10, 2)));
    Результат.Колонки.Добавить("ДоступныйОстаток", Новый ОписаниеТипов("Число", , , Новый КвалификаторыЧисла(10, 2)));
    Результат.Колонки.Добавить("РезервКОбеспечению", Новый ОписаниеТипов("Число", , , Новый КвалификаторыЧисла(10, 2)));

    // Определяем дату расчета
    Если Дата = Неопределено Тогда
        РасчетнаяДата = КонецДня(ТекущаяДата());
    Иначе
        РасчетнаяДата = Дата;
    КонецЕсли;

    // Создаем запрос для получения данных о заказах клиентов
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ЗаказТовары.Товар,
    |    СУММА(ЗаказТовары.Количество) КАК КоличествоВЗаказах
    |ПОМЕСТИТЬ ВременнаяТаблицаЗаказов
    |ИЗ
    |    Документ.Заказ.Товары КАК ЗаказТовары
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.Заказ КАК Заказ
    |        ПО ЗаказТовары.Ссылка = Заказ.Ссылка
    |ГДЕ
    |    Заказ.Проведен = ИСТИНА
    |    И Заказ.СостояниеЗаказа = ЗНАЧЕНИЕ(Перечисление.СостоянияЗаказов.ВРаботе)
    |СГРУППИРОВАТЬ ПО
    |    ЗаказТовары.Товар
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    ТоварныеЗапасыОстатки.Товар.Наименование КАК Наименование,
    |    ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК ОстатокНаСкладе,
    |    ЕСТЬNULL(ВременнаяТаблицаЗаказов.КоличествоВЗаказах, 0) КАК КоличествоВЗаказах,
    |    ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) - ЕСТЬNULL(ВременнаяТаблицаЗаказов.КоличествоВЗаказах, 0) КАК ДоступныйОстаток,
    |    ВЫБОР
    |        КОГДА ЕСТЬNULL(ВременнаяТаблицаЗаказов.КоличествоВЗаказах, 0) > ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0)
    |            ТОГДА ЕСТЬNULL(ВременнаяТаблицаЗаказов.КоличествоВЗаказах, 0) - ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0)
    |        ИНАЧЕ 0
    |    КОНЕЦ КАК РезервКОбеспечению
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата, ) КАК ТоварныеЗапасыОстатки
    |        ЛЕВОЕ СОЕДИНЕНИЕ ВременнаяТаблицаЗаказов КАК ВременнаяТаблицаЗаказов
    |        ПО ТоварныеЗапасыОстатки.Товар = ВременнаяТаблицаЗаказов.Товар
    |ГДЕ
    |    ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) <> 0
    |    ИЛИ ЕСТЬNULL(ВременнаяТаблицаЗаказов.КоличествоВЗаказах, 0) <> 0
    |УПОРЯДОЧИТЬ ПО
    |    РезервКОбеспечению УБЫВ";

    Запрос.УстановитьПараметр("Дата", РасчетнаяДата);

    Попытка
        РезультатЗапроса = Запрос.Выполнить();
        Результат = РезультатЗапроса.Выгрузить();
    Исключение
        Сообщить("Ошибка выполнения запроса: " + ОписаниеОшибки());
        Возврат Результат;
    КонецПопытки;

    Возврат Результат;

КонецФункции

// Функция проверяет корректность сформированного отчета
Функция ЗадачаРешена(ТабДок) Экспорт

    // Проверяем тип результата
    Если ТипЗнч(ТабДок) <> Тип("ТаблицаЗначений") Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверяем наличие обязательных колонок
    ОбязательныеКолонки = Новый Массив;
    ОбязательныеКолонки.Добавить("Товар");
    ОбязательныеКолонки.Добавить("ОстатокНаСкладе");
    ОбязательныеКолонки.Добавить("КоличествоВЗаказах");
    ОбязательныеКолонки.Добавить("РезервКОбеспечению");

    Для Каждого ИмяКолонки Из ОбязательныеКолонки Цикл
        Если ТабДок.Колонки.Найти(ИмяКолонки) = Неопределено Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    // Проверяем заполненность товара и неотрицательность резерва
    Для Каждого СтрокаТаблицы Из ТабДок Цикл

        // Проверяем заполненность товара
        Если НЕ ЗначениеЗаполнено(СтрокаТаблицы.Товар) Тогда
            Возврат Ложь;
        КонецЕсли;

        // Проверяем, что резерв не отрицательный
        Если СтрокаТаблицы.РезервКОбеспечению < 0 Тогда
            Возврат Ложь;
        КонецЕсли;

    КонецЦикла;

    Возврат Истина;

КонецФункции

Функция СформироватьОтчетДниПродажВышеНормы(ДатаНачала, ДатаОкончания, КоличествоНорма) Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ДинамикаПродаж.Создать();

    // Получаем компоновщик настроек
    КомпоновщикНастроек = ОтчетОбъект.КомпоновщикНастроек;

    // Загружаем вариант отчета "СуммаИКоличество"
    ВариантОтчета = КомпоновщикНастроек.ВариантыНастроек.Найти("СуммаИКоличество");
    Если ВариантОтчета <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ВариантОтчета.Настройки);
    КонецЕсли;

    // Получаем настройки компоновки
    НастройкиКомпоновки = КомпоновщикНастроек.Настройки;

    // Устанавливаем параметры периода отчета
    ПараметрПериод = НастройкиКомпоновки.ПараметрыДанных.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("Период"));
    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Значение.ДатаНачала = ДатаНачала;
        ПараметрПериод.Значение.ДатаОкончания = ДатаОкончания;
        ПараметрПериод.Использование = Истина;
    КонецЕсли;

    // Формируем структуру отчета - группировка по полю "Период"
    НастройкиКомпоновки.Структура.Очистить();

    ГруппировкаПериод = НастройкиКомпоновки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаПериод.ПолеГруппировки = Новый ПолеКомпоновкиДанных("Период");
    ГруппировкаПериод.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаПериод.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Добавляем отбор КоличествоОборот >= КоличествоНорма
    ЭлементОтбора = НастройкиКомпоновки.Отбор.Элементы.Добавить(
        Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("КоличествоОборот");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.БольшеИлиРавно;
    ЭлементОтбора.ПравоеЗначение = КоличествоНорма;
    ЭлементОтбора.Использование = Истина;

    // Настраиваем параметры вывода
    ПараметрыВывода = НастройкиКомпоновки.ПараметрыВывода;

    ДополнительныеСвойства = ПараметрыВывода.Элементы.Найти(
        "ВыводитьПараметрыДанных");
    Если ДополнительныеСвойства <> Неопределено Тогда
        ДополнительныеСвойства.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
        ДополнительныеСвойства.Использование = Истина;
    КонецЕсли;

    ДополнительныеСвойства = ПараметрыВывода.Элементы.Найти("ВыводитьОтбор");
    Если ДополнительныеСвойства <> Неопределено Тогда
        ДополнительныеСвойства.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
        ДополнительныеСвойства.Использование = Истина;
    КонецЕсли;

    // Инициализируем процессор компоновки
    МакетКомпоновки = Новый МакетКомпоновкиДанных;

    КомпоновочныйПроцессор = Новый ПроцессорКомпоновкиДанных;
    КомпоновочныйПроцессор.Инициализировать(
        МакетКомпоновки,
        ,
        ,
        ОтчетОбъект.ДанныеРасшифровки);

    // Формируем табличный документ
    Результат = Новый ТабличныйДокумент;

    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанных;
    ПроцессорВывода.УстановитьДокумент(Результат);
    ПроцессорВывода.Вывести(КомпоновочныйПроцессор);

    Возврат Результат;

КонецФункции

task:
Написать функцию СформироватьАнализТоваровВПутиНаличие(Дата),
которая формирует анализ наличия товаров с учетом заказов клиентов в работе в виде таблицы значений.
Анализ должен выполняться на основании данных:
регистра накопления «ТоварныеЗапасы» (остатки товаров на складе);
документа «Заказ» (табличная часть «Товары»), находящегося в состоянии ВРаботе.
Если параметр Дата не задан, в качестве даты анализа используется текущая дата (КонецДня(ТекущаяДата())).
Формирование анализа выполняется в два этапа:
На первом этапе формируется временная таблица, содержащая суммарное количество товаров по заказам клиентов, находящимся в работе.
Данные выбираются из табличной части Документ.Заказ.Товары с отбором по условию:
состояние заказа равно значению перечисления СостоянияЗаказов.ВРаботе.
Данные группируются по полю Товар, рассчитывается суммарное количество заказанного товара (Количество).
На втором этапе выполняется объединение остатков товаров на складе с временной таблицей заказов:
остатки берутся из регистра накопления РегистрНакопления.ТоварныеЗапасы.Остатки на указанную дату;
соединение выполняется по полю Товар;
рассчитываются итоговые показатели:
ОстатокНаСкладе — суммарный остаток товара на складе;
КоличествоВПути — суммарное количество товара в заказах (резерв под заказы клиентов);
НаличиеДляЗаказа — доступное количество товара с учетом заказов, вычисляемое как:
ОстатокНаСкладе − КоличествоВПути.
Результат должен представлять таблицу значений (ТаблицаЗначений), где каждая строка соответствует одному товару, участвующему в заказах клиентов.
Таблица должна содержать следующие поля:
Товар — ссылка на элемент справочника Товары;
ОстатокНаСкладе — текущий остаток товара на складе на дату анализа;
КоличествоВПути — суммарное количество товара в активных заказах клиентов (в работе);
НаличиеДляЗаказа — доступное количество товара после учета заказов;
НедостачаТовара — булево значение, принимающее Истина, если доступное наличие меньше нуля (дефицит товара), и Ложь в противном случае.
В процессе формирования результата:
для каждой строки выборки создается новая строка таблицы значений;
заполняются поля Товар, ОстатокНаСкладе, КоличествоВПути и НаличиеДляЗаказа;
признак НедостачаТовара устанавливается в Истина, если НаличиеДляЗаказа < 0, что позволяет выявить товары с недостатком запасов под текущие заказы клиентов.
После формирования всех строк функция возвращает заполненную таблицу значений, предназначенную для анализа обеспеченности заказов и выявления дефицита товаров на складе

output:
// Функция формирует анализ наличия товаров с учетом заказов клиентов в работе
// Параметры:
//   Дата - Дата - Дата анализа. Если не задана, используется текущая дата
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками:
//     * Товар - СправочникСсылка.Товары
//     * ОстатокНаСкладе - Число
//     * КоличествоВПути - Число
//     * НаличиеДляЗаказа - Число
//     * НедостачаТовара - Булево
//
Функция СформироватьАнализТоваровВПутиНаличие(Дата = Неопределено) Экспорт

    // Определяем дату анализа
    Если Дата = Неопределено Тогда
        АнализДата = КонецДня(ТекущаяДата());
    Иначе
        АнализДата = КонецДня(Дата);
    КонецЕсли;

    // Формируем текст запроса
    Запрос = Новый Запрос;

    // Этап 1: Формирование временной таблицы с товарами по заказам в работе
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЗаказТовары.Товар КАК Товар,
    |    СУММА(ЗаказТовары.Количество) КАК КоличествоЗаказано
    |ПОМЕСТИТЬ ЗаказыВРаботе
    |ИЗ
    |    Документ.Заказ.Товары КАК ЗаказТовары
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.Заказ КАК Заказ
    |        ПО ЗаказТовары.Ссылка = Заказ.Ссылка
    |ГДЕ
    |    Заказ.СостояниеЗаказа = ЗНАЧЕНИЕ(Перечисление.СостоянияЗаказов.ВРаботе)
    |СГРУППИРОВАТЬ ПО
    |    ЗаказТовары.Товар
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |// Этап 2: Объединение остатков товаров с данными заказов
    |ВЫБРАТЬ
    |    ЗаказыВРаботе.Товар КАК Товар,
    |    ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК ОстатокНаСкладе,
    |    ЗаказыВРаботе.КоличествоЗаказано КАК КоличествоВПути,
    |    ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) - ЗаказыВРаботе.КоличествоЗаказано КАК НаличиеДляЗаказа,
    |    ВЫБОР
    |        КОГДА ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) - ЗаказыВРаботе.КоличествоЗаказано < 0
    |            ТОГДА ИСТИНА
    |        ИНАЧЕ ЛОЖЬ
    |    КОНЕЦ КАК НедостачаТовара
    |ИЗ
    |    ЗаказыВРаботе КАК ЗаказыВРаботе
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаАнализа, ) КАК ТоварныеЗапасыОстатки
    |        ПО ЗаказыВРаботе.Товар = ТоварныеЗапасыОстатки.Товар
    |УПОРЯДОЧИТЬ ПО
    |    Товар.Наименование
    |АВТОУПОРЯДОЧИВАНИЕ";

    // Устанавливаем параметр даты
    Запрос.УстановитьПараметр("ДатаАнализа", АнализДата);

    // Выполняем запрос
    РезультатЗапроса = Запрос.Выполнить();

    // Создаем таблицу значений и загружаем результат
    ТаблицаРезультата = РезультатЗапроса.Выгрузить();

    // Возвращаем таблицу значений
    Возврат ТаблицаРезультата;

КонецФункции

// Функция формирует отчет "ДинамикаПродаж" с заданными параметрами и группировками.
//
// Параметры:
//   ДатаНачала    - Дата - Начало периода отчета.
//   ДатаОкончания - Дата - Окончание периода отчета.
//
// Возвращаемое значение:
//   ТабличныйДокумент - Результат формирования отчета.
//
Функция СформироватьОтчетПродажиПоПокупателям(ДатаНачала, ДатаОкончания) Экспорт

    // Получаем объект отчета на сервере
    ОтчетОбъект = Отчеты.ДинамикаПродаж.СоздатьОтчет();

    // Получаем схему компоновки данных из отчета
    СхемаКомпоновкиДанных = ОтчетОбъект.СхемаКомпоновкиДанных;

    // Инициализируем компоновщик настроек на основании схемы
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));

    // Устанавливаем вариант отчета "ПродажиТоваровПоПокупателям"
    ВариантОтчета = СхемаКомпоновкиДанных.ВариантыНастроек.Найти("ПродажиТоваровПоПокупателям");
    Если ВариантОтчета <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ВариантОтчета.Настройки);
    Иначе
        // Если вариант не найден, загружаем настройки по умолчанию
        КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.НастройкиПоУмолчанию);
    КонецЕсли;

    // Получаем настройки для редактирования
    Настройки = КомпоновщикНастроек.Настройки;

    // ----- Подмена структуры группировок -----
    // Очищаем стандартную структуру (Товар, Покупатель)
    Настройки.Структура.Очистить();

    // Добавляем новую структуру: Покупатель -> Товар
    НоваяСтруктура = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    НоваяСтруктура.Имя = "Покупатель";
    НоваяСтруктура.Поле = "Покупатель";

    // Задаём параметры группировки "Покупатель"
    НоваяСтруктура.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    НоваяСтруктура.ТипДополненияПериода = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Добавляем вложенную группировку "Товар"
    ВложеннаяГруппировка = НоваяСтруктура.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ВложеннаяГруппировка.Имя = "Товар";
    ВложеннаяГруппировка.Поле = "Товар";

    // Задаём параметры группировки "Товар"
    ВложеннаяГруппировка.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ВложеннаяГруппировка.ТипДополненияПериода = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // ----- Установка параметров отчета (Период) -----
    // Ищем параметры "НачалоПериода" и "КонецПериода" в коллекции параметров данных
    ПараметрыДанных = Настройки.ПараметрыДанных;

    НачалоПериодаПараметр = ПараметрыДанных.Элементы.Найти("НачалоПериода");
    Если НачалоПериодаПараметр <> Неопределено Тогда
        НачалоПериодаПараметр.Значение = ДатаНачала;
        НачалоПериодаПараметр.Использование = Истина;
    КонецЕсли;

    КонецПериодаПараметр = ПараметрыДанных.Элементы.Найти("КонецПериода");
    Если КонецПериодаПараметр <> Неопределено Тогда
        КонецПериодаПараметр.Значение = ДатаОкончания;
        КонецПериодаПараметр.Использование = Истина;
    КонецЕсли;

    // Альтернативный поиск по имени параметра "Период"
    ПериодПараметр = ПараметрыДанных.Элементы.Найти("Период");
    Если ПериодПараметр <> Неопределено Тогда
        ПериодПараметр.Значение.ДатаНачала = ДатаНачала;
        ПериодПараметр.Значение.ДатаОкончания = ДатаОкончания;
        ПериодПараметр.Использование = Истина;
    КонецЕсли;

    // ----- Параметры вывода -----
    ПараметрыВывода = Настройки.ПараметрыВывода;

    // Не выводить параметры данных
    ВыводитьПараметры = ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьПараметрыДанных"));
    Если ВыводитьПараметры <> Неопределено Тогда
        ВыводитьПараметры.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
        ВыводитьПараметры.Использование = Истина;
    КонецЕсли;

    // Не выводить отбор
    ВыводитьОтбор = ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьОтбор"));
    Если ВыводитьОтбор <> Неопределено Тогда
        ВыводитьОтбор.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
        ВыводитьОтбор.Использование = Истина;
    КонецЕсли;

    // Применяем все изменённые настройки
    КомпоновщикНастроек.ЗагрузитьНастройки(Настройки);

    // ----- Формирование отчета -----
    // Компилируем макет компоновки с установленными настройками
    МакетКомпоновки = КомпоновщикМакетаКомпоновкиДанных.Выполнить(
        СхемаКомпоновкиДанных,
        КомпоновщикНастроек.Настройки,
        ,
        ,
        Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    // Передаём параметры периода в макет
    Для Каждого ПараметрМакета Из МакетКомпоновки.ЗначенияПараметров Цикл
        Если Строка(ПараметрМакета.Параметр) = "НачалоПериода" Тогда
            ПараметрМакета.Значение = ДатаНачала;
        ИначеЕсли Строка(ПараметрМакета.Параметр) = "КонецПериода" Тогда
            ПараметрМакета.Значение = ДатаОкончания;
        КонецЕсли;
    КонецЦикла;

    // Создаём процессор компоновки и выводим результат в табличный документ
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    Результат = Новый ТабличныйДокумент;

    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Результат);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат Результат;

КонецФункции

// Функция формирует отчет "ДокументыОплата" с отбором по поставщику.
// 
// Параметры:
//  ПоставщикФильтр - СправочникСсылка.Контрагенты, Массив, СписокЗначений - фильтр по поставщику.
//  ВидСравненияКД  - ВидСравненияКомпоновкиДанных - вид сравнения для отбора.
//
// Возвращаемое значение:
//  ТабличныйДокумент - сформированный отчет.
//
Функция СформироватьОтчетПоОплатамПоставщика(ПоставщикФильтр, ВидСравненияКД) Экспорт

    // Получаем основную схему компоновки данных отчета.
    // ОтчетОбъект = Отчеты.ДокументыОплата.Создать();
    // Для управляемых форм используется общий модуль или менеджер отчета.
    // Ниже — типовой подход, когда схема компоновки получается из макета отчета.
    ОтчетОбъект = Отчеты.ДокументыОплата.Создать();
    МакетОтчета = ОтчетОбъект.ПолучитьМакет("Основной");

    // Получаем схему компоновки из макета.
    СхемаКомпоновки = ОтчетОбъект.ПолучитьСхемуКомпоновкиДанныхИзМакета(МакетОтчета);

    // Создаём компоновщик настроек на основании схемы.
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновки));
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновки.ВариантыНастроек.Основной.Настройки);

    // -----------------------------------------------------------------
    // Параметры вывода: не выводить параметры данных и отбор.
    ПараметрыВывода = КомпоновщикНастроек.Настройки.ПараметрыВывода;
    Отчеты.СформироватьОтчет.УстановитьПараметрВывода(
        ПараметрыВывода,
        "ВыводитьПараметрыДанных",
        ТипВыводаКД.НеВыводить);
    Отчеты.СформироватьОтчет.УстановитьПараметрВывода(
        ПараметрыВывода,
        "ВыводитьОтбор",
        ТипВыводаКД.НеВыводить);

    // -----------------------------------------------------------------
    // Добавляем отбор по полю "Поставщик".
    // Используем программное формирование элемента отбора,
    // чтобы корректно обработать все допустимые виды сравнения,
    // включая Заполнено / НеЗаполнено.
    Отбор = КомпоновщикНастроек.Настройки.Отбор;

    // Определяем поле "Поставщик".
    ПолеПоставщик = Новый ПолеКомпоновкиДанных("Поставщик");

    // Создаём элемент отбора.
    ЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение  = ПолеПоставщик;
    ЭлементОтбора.ВидСравнения   = ВидСравненияКД;
    ЭлементОтбора.Использование  = Истина;

    // Для видов сравнения Равно, ВГруппе, ВСписке и т.п.
    // правое значение — сам фильтр.
    // Для Заполнено / НеЗаполнено правое значение не требуется.
    Если ВидСравненияКД <> ВидСравненияКомпоновкиДанных.Заполнено
        И ВидСравненияКД <> ВидСравненияКомпоновкиДанных.НеЗаполнено Тогда
        ЭлементОтбора.ПравоеЗначение = ПоставщикФильтр;
    КонецЕсли;

    // -----------------------------------------------------------------
    // Формируем табличный документ.
    ДокументРезультат = Новый ТабличныйДокумент;
    ДокументРезультат.Очистить();

    // Получаем расшифровку (при необходимости можно передать ДетализацияРасшифровки).
    ДанныеРасшифровки = Новый ДанныеРасшифровкиКомпоновкиДанных;

    // Параметры процессора вывода.
    ПараметрыПроцессора = Новый Структура;
    ПараметрыПроцессора.Вставить("ВыводитьЗаголовок",   Истина);
    ПараметрыПроцессора.Вставить("ВыводитьПодвал",      Истина);
    ПараметрыПроцессора.Вставить("Колонки",             Неопределено);
    ПараметрыПроцессора.Вставить("ГоризонтальноеПоложениеВсем", ГоризонтальноеПоложение.Право);

    // Готовим параметры для процессора компоновки.
    ПараметрыКД = КомпоновщикНастроек.Настройки.ПараметрыДанных;

    // Инициализируем процессор вывода.
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ДокументРезультат);
    ПроцессорВывода.НачатьВывод();

    // Инициализируем процессор компоновки.
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(
        КомпоновщикНастроек.ПолучитьНастройки(),
        ПараметрыКД,
        ДанныеРасшифровки,
        Истина);

    // Выводим результат.
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ДокументРезультат;

КонецФункции

task:
Написать функцию СформироватьАнализНеликвидныхТоваров(ДатаНач, ДатаКон),
которая формирует аналитический отчет по неликвидным товарам на складе за указанный период.
Отчет предназначен для выявления товаров, имеющих остатки на складе, но не имеющих продаж в выбранном периоде, на основании данных регистров накопления «Продажи» и «ТоварныеЗапасы».
Если параметры периода не заданы, функция должна автоматически:
устанавливать ДатаНач = текущая дата минус 30 дней (с начала дня);
устанавливать ДатаКон = текущая дата (конец дня).
Перед выполнением расчета должна выполняться проверка корректности периода:
если ДатаКон меньше ДатаНач — вызывается исключение.
Формирование отчета выполняется следующим образом:
Выполняется запрос к регистру накопления РегистрНакопления.Продажи:
данные отбираются по периоду между ДатаНач и ДатаКон (по дате регистратора);
выполняется группировка по полю Товар;
рассчитывается агрегированный показатель:
КоличествоПродаж — суммарное количество продаж товара за период;
результат помещается во временную таблицу ВТ_Продажи.
Далее выполняется основной запрос к регистру накопления
РегистрНакопления.ТоварныеЗапасы.Остатки на дату ДатаКон:
выбираются товары с положительными остатками на складе;
выполняется левое соединение с временной таблицей продаж;
дополнительно выполняется соединение со справочником Товары для получения наименования;
рассчитываются итоговые показатели:
ОстатокНаСкладе — суммарный остаток товара;
КоличествоПродаж — количество продаж за период (с использованием ЕСТЬNULL = 0 при отсутствии продаж).
На основании полученных данных формируется итоговая таблица значений (ТаблицаЗначений) со следующей структурой:
Товар (СправочникСсылка.Товары);
Наименование (Строка);
ОстатокНаСкладе (Число);
КоличествоПродаж (Число);
Неликвид (Булево).
Заполнение итоговой таблицы выполняется построчно:
в таблицу включаются только товары, у которых:
ОстатокНаСкладе > 0;
КоличествоПродаж = 0;
такие товары помечаются признаком Неликвид = Истина.
После формирования данных выполняется сортировка результата:
по полю ОстатокНаСкладе по убыванию,
что позволяет вывести наиболее критичные неликвидные остатки в верхней части отчета.
Функция должна возвращать объект типа ТаблицаЗначений, содержащий список неликвидных товаров с остатками на складе.
Дополнительно реализуется функция ЗадачаРешена(ТабДок), которая проверяет корректность результата:
тип возвращаемого значения — ТаблицаЗначений;
наличие обязательных колонок (Товар, ОстатокНаСкладе, КоличествоПродаж, Неликвид);
отсутствие отрицательных остатков и продаж;
заполненность ссылки на товар в каждой строке.
В случае отсутствия неликвидных товаров таблица может быть пустой, что считается корректным результатом выполнения задачи анализа.

output:
////////////////////////////////////////////////////////////////////////////////
// Функция СформироватьАнализНеликвидныхТоваров
//
// Описание:
//   Формирует аналитический отчет по неликвидным товарам на складе за 
//   указанный период. Неликвидными считаются товары, имеющие остатки на 
//   складе, но не имеющие продаж в выбранном периоде.
//
// Параметры:
//   ДатаНач - Дата - Начальная дата периода анализа (необязательный)
//   ДатаКон - Дата - Конечная дата периода анализа (необязательный)
//
// Возвращаемое значение:
//   ТаблицаЗначений - Таблица с колонками:
//     * Товар             - СправочникСсылка.Товары
//     * Наименование      - Строка
//     * ОстатокНаСкладе   - Число
//     * КоличествоПродаж  - Число
//     * Неликвид          - Булево
//
Функция СформироватьАнализНеликвидныхТоваров(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка параметров периода по умолчанию
    ТекущаяДата = ТекущаяДатаСеанса();

    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата - 86400 * 30); // 30 дней назад
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата);
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    // Создание запроса для получения данных о продажах
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Продажи.Товар,
    |    СУММА(Продажи.Количество) КАК КоличествоПродаж
    |ПОМЕСТИТЬ ВТ_Продажи
    |ИЗ
    |    РегистрНакопления.Продажи КАК Продажи
    |ГДЕ
    |    Продажи.Период МЕЖДУ &ДатаНач И &ДатаКон
    |
    |СГРУППИРОВАТЬ ПО
    |    Продажи.Товар
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    ТоварныеЗапасыОстатки.Товар.Наименование КАК Наименование,
    |    СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) КАК ОстатокНаСкладе,
    |    ЕСТЬNULL(ВТ_Продажи.КоличествоПродаж, 0) КАК КоличествоПродаж
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаКон, ) КАК ТоварныеЗапасыОстатки
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.Товары КАК Товары
    |        ПО ТоварныеЗапасыОстатки.Товар = Товары.Ссылка
    |        ЛЕВОЕ СОЕДИНЕНИЕ ВТ_Продажи КАК ВТ_Продажи
    |        ПО ТоварныеЗапасыОстатки.Товар = ВТ_Продажи.Товар
    |ГДЕ
    |    ТоварныеЗапасыОстатки.КоличествоОстаток > 0
    |
    |СГРУППИРОВАТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар,
    |    ТоварныеЗапасыОстатки.Товар.Наименование,
    |    ЕСТЬNULL(ВТ_Продажи.КоличествоПродаж, 0)
    |
    |УПОРЯДОЧИТЬ ПО
    |    ОстатокНаСкладе УБЫВ
    |ИТОГИ ПО
    |    Товар";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений для результата
    ТаблицаРезультата = Новый ТаблицаЗначений;
    ТаблицаРезультата.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультата.Колонки.Добавить("Наименование", Новый ОписаниеТипов("Строка"));
    ТаблицаРезультата.Колонки.Добавить("ОстатокНаСкладе", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультата.Колонки.Добавить("КоличествоПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультата.Колонки.Добавить("Неликвид", Новый ОписаниеТипов("Булево"));

    // Обход результата запроса и формирование таблицы неликвидов
    Выборка = РезультатЗапроса.Выбрать(ОбходРезультатаЗапроса.ПоГруппировкам);

    Пока Выборка.Следующий() Цикл

        // Фильтрация: только товары с остатком > 0 и без продаж
        Если Выборка.ОстатокНаСкладе > 0 И Выборка.КоличествоПродаж = 0 Тогда

            НоваяСтрока = ТаблицаРезультата.Добавить();
            НоваяСтрока.Товар = Выборка.Товар;
            НоваяСтрока.Наименование = Выборка.Наименование;
            НоваяСтрока.ОстатокНаСкладе = Выборка.ОстатокНаСкладе;
            НоваяСтрока.КоличествоПродаж = 0;
            НоваяСтрока.Неликвид = Истина;

        КонецЕсли;

    КонецЦикла;

    Возврат ТаблицаРезультата;

КонецФункции

////////////////////////////////////////////////////////////////////////////////
// Функция ЗадачаРешена
//
// Описание:
//   Проверяет корректность результата выполнения функции
//   СформироватьАнализНеликвидныхТоваров.
//
// Параметры:
//   ТабДок - ТаблицаЗначений - Результат выполнения функции анализа
//
// Возвращаемое значение:
//   Булево - Истина, если результат корректен, Ложь - в противном случае
//
Функция ЗадачаРешена(ТабДок) Экспорт

    // Проверка типа возвращаемого значения
    Если ТипЗнч(ТабДок) <> Тип("ТаблицаЗначений") Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверка наличия обязательных колонок
    ОбязательныеКолонки = Новый Массив;
    ОбязательныеКолонки.Добавить("Товар");
    ОбязательныеКолонки.Добавить("ОстатокНаСкладе");
    ОбязательныеКолонки.Добавить("КоличествоПродаж");
    ОбязательныеКолонки.Добавить("Неликвид");

    Для Каждого ИмяКолонки Из ОбязательныеКолонки Цикл
        Если ТабДок.Колонки.Найти(ИмяКолонки) = Неопределено Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    // Проверка каждой строки таблицы
    Для Каждого СтрокаТаблицы Из ТабДок Цикл

        // Проверка заполненности ссылки на товар
        Если НЕ ЗначениеЗаполнено(СтрокаТаблицы.Товар) Тогда
            Возврат Ложь;
        КонецЕсли;

        // Проверка отсутствия отрицательных остатков
        Если СтрокаТаблицы.ОстатокНаСкладе < 0 Тогда
            Возврат Ложь;
        КонецЕсли;

        // Проверка отсутствия отрицательных продаж
        Если СтрокаТаблицы.КоличествоПродаж < 0 Тогда
            Возврат Ложь;
        КонецЕсли;

    КонецЦикла;

    Возврат Истина;

КонецФункции

// Функция формирует отчет "ДокументыОплата" с группировкой по поставщику
//
// Параметры:
//  Нет
//
// Возвращаемое значение:
//  ТабличныйДокумент - сформированный отчет
//
Функция СформироватьОтчетПоОплатамСГруппировкойПоПоставщикам() Экспорт

    // Результат выполнения функции
    Результат = Новый ТабличныйДокумент;

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ДокументыОплата.Создать();

    // Получаем основную форму отчета для доступа к настройкам
    ФормаОтчета = ОтчетОбъект.ПолучитьОсновнуюФорму();
    Если ФормаОтчета = Неопределено Тогда
        ВызватьИсключение "Не удалось получить основную форму отчета ""ДокументыОплата""";
    КонецЕсли;

    // Получаем вариант настроек "Основной"
    ПользовательскиеНастройки = ОтчетОбъект.КомпоновщикНастроек.ПолучитьНастройки();

    // Сбрасываем настройки к варианту "Основной"
    ОтчетОбъект.КомпоновщикНастроек.ЗагрузитьНастройки(
        ОтчетОбъект.СхемаКомпоновкиДанных.ВариантыНастроек.Основной.Настройки
    );

    // Получаем настройки компоновки
    Настройки = ОтчетОбъект.КомпоновщикНастроек.Настройки;

    // === Настраиваем структуру отчета ===

    // Получаем доступные группировки
    ДоступныеПоляГруппировок = ОтчетОбъект.КомпоновщикНастроек.ДоступныеПоляГруппировок;

    // Создаем новую группировку по полю "Поставщик"
    ГруппировкаПоставщик = ОтчетОбъект.КомпоновщикНастроек.Настройки.Структура.Добавить(
        Тип("ГруппировкаКомпоновкиДанных")
    );

    // Устанавливаем имя группировки
    ГруппировкаПоставщик.Имя = "Поставщик";

    // Поле группировки - Поставщик
    ПолеПоставщик = ГруппировкаПоставщик.ПоляГруппировки.Элементы.Добавить(
        Тип("ПолеГруппировкиКомпоновкиДанных")
    );
    ПолеПоставщик.Поле = Новый ПолеКомпоновкиДанных("Поставщик");
    ПолеПоставщик.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ПолеПоставщик.ТипДополнения = ТипДополненияКомпоновкиДанных.БезДополнения;

    // Добавляем детальные записи внутрь группировки
    ДетальныеЗаписи = ГруппировкаПоставщик.Структура.Добавить(
        Тип("ГруппировкаКомпоновкиДанных")
    );
    ДетальныеЗаписи.Имя = "ДетальныеЗаписи";

    // Для детальных записей добавляем автополе
    АвтоПоле = ДетальныеЗаписи.ПоляГруппировки.Элементы.Добавить(
        Тип("АвтоПолеГруппировкиКомпоновкиДанных")
    );

    // === Настраиваем параметры вывода ===

    ПараметрыВывода = Настройки.ПараметрыВывода;

    // Выводить параметры данных - Не выводить
    УстановитьПараметр(ПараметрыВывода, "ВыводитьПараметрыДанных", 
        ТипВыводаТекстаКомпоновкиДанных.НеВыводить);

    // Выводить отбор - Не выводить
    УстановитьПараметр(ПараметрыВывода, "ВыводитьОтбор", 
        ТипВыводаТекстаКомпоновкиДанных.НеВыводить);

    // === Формируем отчет ===

    // Компилируем макет компоновки
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;

    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        ОтчетОбъект.СхемаКомпоновкиДанных,
        ОтчетОбъект.КомпоновщикНастроек.ПолучитьНастройки(),
        ,
        ,
        Тип("ОбработкаРасшифровкиКомпоновкиДанных"))
    ;

    // Создаем процессор компоновки данных
    ПроцессорКомпоновкиДанных = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновкиДанных.Инициализировать(МакетКомпоновки);

    // Создаем процессор вывода результата
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Результат);

    // Выводим результат
    ПроцессорВывода.Вывести(ПроцессорКомпоновкиДанных);

    Возврат Результат;

КонецФункции

// Вспомогательная процедура для установки параметра вывода
//
// Параметры:
//  ПараметрыВывода - КоллекцияПараметровВыводаКомпоновкиДанных - коллекция параметров
//  ИмяПараметра - Строка - имя параметра
//  Значение - Произвольный - значение параметра
//
Процедура УстановитьПараметр(ПараметрыВывода, ИмяПараметра, Значение) Экспорт

    Параметр = ПараметрыВывода.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных(ИмяПараметра));
    Если Параметр <> Неопределено Тогда
        Параметр.Значение = Значение;
        Параметр.Использование = Истина;
    КонецЕсли;

КонецПроцедуры

// Функция формирует аналитический отчет по эффективности продаж склада за указанный период
//
// Параметры:
//   ДатаНачала - Дата - Дата начала периода анализа (по умолчанию - начало текущего месяца)
//   ДатаОкончания - Дата - Дата окончания периода анализа (по умолчанию - текущая дата)
//
// Возвращает:
//   ТаблицаЗначений - Содержит колонки: РегистраторСклад, Товар, Количество, Сумма, СредняяЦена
//
// Исключения:
//   - Если ДатаОкончания < ДатаНачала выбрасывается исключение
//
Функция ПолучитьПродажиСклада(ДатаНачала = Неопределено, ДатаОкончания = Неопределено) Экспорт

    // Установка значений по умолчанию
    Если ДатаНачала = Неопределено Тогда
        ДатаНачала = НачалоДня(ТекущаяДатаСеанса());
        // Если текущая дата - первое число, берем начало предыдущего месяца
        Если День(ДатаНачала) = 1 Тогда
            ДатаНачала = НачалоМесяца(ДатаНачала - 1);
        Иначе
            ДатаНачала = НачалоМесяца(ДатаНачала);
        КонецЕсли;
    КонецЕсли;

    Если ДатаОкончания = Неопределено Тогда
        ДатаОкончания = КонецДня(ТекущаяДатаСеанса());
    КонецЕсли;

    // Приведение дат к началу и концу дня
    ДатаНачала = НачалоДня(ДатаНачала);
    ДатаОкончания = КонецДня(ДатаОкончания);

    // Проверка корректности периода
    Если ДатаОкончания < ДатаНачала Тогда
        ВызватьИсключение СтрШаблон(
            "Дата окончания периода (%1) меньше даты начала периода (%2)",
            Формат(ДатаОкончания, "ДЛФ=Д"),
            Формат(ДатаНачала, "ДЛФ=Д")
        );
    КонецЕсли;

    // Создание таблицы значений для результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("РегистраторСклад", Новый ОписаниеТипов("СправочникСсылка.Склады"));
    Результат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    Результат.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    Результат.Колонки.Добавить("Сумма", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    Результат.Колонки.Добавить("СредняяЦена", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

    Запрос.Текст =
    "ВЫБРАТЬ
    |    Продажи.Регистратор.Склад КАК РегистраторСклад,
    |    Продажи.Товар,
    |    СУММА(Продажи.Количество) КАК Количество,
    |    СУММА(Продажи.Сумма) КАК Сумма,
    |    ВЫБОР
    |        КОГДА СУММА(Продажи.Количество) = 0
    |            ТОГДА 0
    |        ИНАЧЕ СУММА(Продажи.Сумма) / СУММА(Продажи.Количество)
    |    КОНЕЦ КАК СредняяЦена
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(
    |            &ДатаНачала,
    |            &ДатаОкончания,
    |            Регистратор,
    |            )
    |    КАК Продажи
    |
    |СГРУППИРОВАТЬ ПО
    |    Продажи.Регистратор.Склад,
    |    Продажи.Товар
    |
    |УПОРЯДОЧИТЬ ПО
    |    РегистраторСklad.Наименование,
    |    Товар.Наименование
    |ИТОГИ
    |    СУММА(Количество),
    |    СУММА(Сумма)
    |ПО
    |    РегистраторСклад";

    // Выполнение запроса и загрузка результата
    РезультатЗапроса = Запрос.Выполнить();

    Если Не РезультатЗапроса.Пустой() Тогда
        Результат = РезультатЗапроса.Выгрузить(ОбходРезультатаЗапроса.Прямой);
    КонецЕсли;

    Возврат Результат;

КонецФункции // ПолучитьПродажиСклада()

// Функция формирует отчет "ДокументыОплата" с отбором по непроведенным документам.
//
// Возвращаемое значение:
//   ТабличныйДокумент - результат формирования отчета.
//
Функция СформироватьОтчетПоНеПроведеннымОплатамПоставщиков() Экспорт

    // 1. Найти вариант отчета "Основной" для отчета "ДокументыОплата"
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ХранилищеВариантовОтчетов.Ссылка КАК Ссылка
    |ИЗ
    |    Справочник.ХранилищеВариантовОтчетов КАК ХранилищеВариантовОтчетов
    |ГДЕ
    |    ХранилищеВариантовОтчетов.ВариантОтчета = ЗНАЧЕНИЕ(Перечисление.ВариантыОтчетов.Основной)
    |    И ХранилищеВариантовОтчетов.КлючОбъекта = ""ДокументыОплата""";

    РезультатЗапроса = Запрос.Выполнить();
    Если РезультатЗапроса.Пустой() Тогда
        ВызватьИсключение "Не найден вариант отчета ""Основной"" для отчета ""ДокументыОплата""";
    КонецЕсли;

    Выборка = РезультатЗапроса.Выбрать();
    Выборка.Следующий();
    ВариантОтчетаСсылка = Выборка.Ссылка;

    // 2. Получить схему компоновки данных из варианта отчета
    СхемаКомпоновкиДанных = ВариантОтчетаСсылка.ХранилищеСхемыКомпоновкиДанных.Получить();

    // 3. Получить пользовательские настройки из варианта отчета
    ПользовательскиеНастройки = ВариантОтчетаСсылка.ХранилищеПользовательскихНастроекДанных.Получить();

    // 4. Создать компоновщик макета и инициализировать его
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;

    // Подготовка настроек компоновки
    НастройкиКомпоновки = Новый НастройкиКомпоновкиДанных;
    Если ПользовательскиеНастройки <> Неопределено Тогда
        НастройкиКомпоновки.Загрузить(ПользовательскиеНастройки);
    КонецЕсли;

    // 5. Добавить отбор по непроведенным документам
    // Найдем поле "Проведен" в доступных полях
    КомпоновщикМакета.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));
    ДоступныеПоля = КомпоновщикМакета.Настройки.ДоступныеПоляОтбора;

    ПолеПроведен = ДоступныеПоля.НайтиПоле(Новый ПолеКомпоновкиДанных("Проведен"));
    Если ПолеПроведен = Неопределено Тогда
        ВызватьИсключение "Не найдено поле ""Проведен"" в отчете ""ДокументыОплата""";
    КонецЕсли;

    // Добавить элемент отбора: Проведен = Ложь
    ЭлементОтбора = НастройкиКомпоновки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение  = Новый ПолеКомпоновкиДанных("Проведен");
    ЭлементОтбора.ВидСравнения   = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбора.ПравоеЗначение = Ложь;
    ЭлементОтбора.Использование  = Истина;

    // 6. Установить параметры вывода: не выводить параметры данных и отбор
    ПараметрыВывода = НастройкиКомпоновки.ПараметрыВывода;

    // ВыводитьПараметрыДанных = Не выводить
    ПараметрВыводаПараметры = ПараметрыВывода.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("ВыводитьПараметрыДанных"));
    Если ПараметрВыводаПараметры <> Неопределено Тогда
        ПараметрВыводаПараметры.Значение      = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаПараметры.Использование = Истина;
    КонецЕсли;

    // ВыводитьОтбор = Не выводить
    ПараметрВыводаОтбор = ПараметрыВывода.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("ВыводитьОтбор"));
    Если ПараметрВыводаОтбор <> Неопределено Тогда
        ПараметрВыводаОтбор.Значение      = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаОтбор.Использование = Истина;
    КонецЕсли;

    // 7. Сформировать макет компоновки
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        НастройкиКомпоновки,
        ,
        Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииТабличныйДокумент"));

    // 8. Создать процессор компоновки и выполнить формирование
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    // Создать табличный документ для результата
    РезультатОтчета = Новый ТабличныйДокумент;

    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(РезультатОтчета);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат РезультатОтчета;

КонецФункции

// Функция формирует отчет "ПрайсЛист" с раскраской строк без цены
//
// Параметры:
//   ВидЦен - СправочникСсылка.ВидыЦен - Вид цен для формирования отчета
//
// Возвращаемое значение:
//   ТабличныйДокумент - Сформированный отчет
//
Функция СформироватьОтчетТоварыБезЦены(ВидЦен) Экспорт

    // Создаем схему компоновки данных программно
    СхемаКомпоновкиДанных = Новый СхемаКомпоновкиДанных;

    // Источник данных - запрос к регистру сведений "Цены товаров"
    ИсточникДанных = СхемаКомпоновкиДанных.ИсточникиДанных.Добавить();
    ИсточникДанных.Имя = "ИсточникДанных1";
    ИсточникДанных.ТипИсточникаДанных = "Local";

    // Набор данных - запрос
    НаборДанных = СхемаКомпоновкиДанных.НаборыДанных.Добавить(
        Тип("НаборДанныхЗапросСхемыКомпоновкиДанных"));
    НаборДанных.Имя = "ОсновнойНабор";
    НаборДанных.ИсточникДанных = "ИсточникДанных1";

    // Текст запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЦеныТоваров.Товар КАК Товар,
    |    ЦеныТоваров.Цена КАК Цена,
    |    ЦеныТоваров.ВидЦен КАК ВидЦен
    |ИЗ
    |    РегистрСведений.ЦеныТоваров КАК ЦеныТоваров
    |ГДЕ
    |    ЦеныТоваров.ВидЦен = &ВидЦен
    |УПОРЯДОЧИТЬ ПО
    |    Товар.Наименование";

    НаборДанных.Запрос = Запрос.Текст;

    // Добавляем поля в схему
    ПолеТовар = СхемаКомпоновкиДанных.Поля.Добавить(Тип("ПолеНабораДанныхСхемыКомпоновкиДанных"));
    ПолеТовар.Заголовок = "Товар";
    ПолеТовар.Поле = "Товар";
    ПолеТовар.ПутьКДанным = "Товар";

    ПолеЦена = СхемаКомпоновкиДанных.Поля.Добавить(Тип("ПолеНабораДанныхСхемыКомпоновкиДанных"));
    ПолеЦена.Заголовок = "Цена";
    ПолеЦена.Поле = "Цена";
    ПолеЦена.ПутьКДанным = "Цена";

    // Добавляем параметры
    ПараметрВидЦен = СхемаКомпоновкиДанных.Параметры.Добавить();
    ПараметрВидЦен.Имя = "ВидЦен";
    ПараметрВидЦен.Заголовок = "Вид цен";
    ПараметрВидЦен.ТипЗначения = Новый ОписаниеТипов("СправочникСсылка.ВидыЦен");
    ПараметрВидЦен.Значение = ВидЦен;
    ПараметрВидЦен.Использование = ИспользованиеПараметраКомпоновкиДанных.Обязательный;

    // Создаем компоновщик настроек
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));

    // Загружаем основные настройки
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.НастройкиПоУмолчанию);

    // Устанавливаем параметры
    КомпоновщикНастроек.Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("ВидЦен", ВидЦен);

    // Получаем настройки компоновки
    Настройки = КомпоновщикНастроек.ПолучитьНастройки();

    // Настраиваем условное оформление для строк без цены
    ЭлементУсловногоОформления = Настройки.УсловноеОформление.Элементы.Добавить();

    // Условие: Цена Не Заполнена
    Отбор = ЭлементУсловногоОформления.Отбор;
    ЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Цена");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбора.ПравоеЗначение = 0;
    ЭлементОтбора.Использование = Истина;

    // Проверка на NULL (цена не установлена)
    ЭлементОтбораNULL = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбораNULL.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Цена");
    ЭлементОтбораNULL.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбораNULL.ПравоеЗначение = Неопределено;
    ЭлементОтбораNULL.Использование = Истина;

    // Группировка условий (ИЛИ)
    ГруппаОтбора = Отбор.Элементы.Добавить(Тип("ГруппаЭлементовОтбораКомпоновкиДанных"));
    ГруппаОтбора.ТипГруппы = ТипГруппыЭлементовОтбораКомпоновкиДанных.ГруппаИли;
    ГруппаОтбора.Использование = Истина;

    // Добавляем условие: Цена = 0
    НовыйЭлемент1 = ГруппаОтбора.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    НовыйЭлемент1.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Цена");
    НовыйЭлемент1.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    НовыйЭлемент1.ПравоеЗначение = 0;
    НовыйЭлемент1.Использование = Истина;

    // Добавляем условие: Цена = NULL
    НовыйЭлемент2 = ГруппаОтбора.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    НовыйЭлемент2.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Цена");
    НовыйЭлемент2.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    НовыйЭлемент2.ПравоеЗначение = Неопределено;
    НовыйЭлемент2.Использование = Истина;

    // Оформление: Цвет фона = Красный (255, 236, 239)
    Оформление = ЭлементУсловногоОформления.Оформление;

    ПараметрЦветФона = Оформление.Элементы.Найти("BackColor");
    Если ПараметрЦветФона = Неопределено Тогда
        ПараметрЦветФона = Оформление.Элементы.Добавить(Тип("ПараметрМакетаКомпоновкиДанных"));
        ПараметрЦветФона.Параметр = Новый ПараметрКомпоновкиДанных("BackColor");
    КонецЕсли;
    ПараметрЦветФона.Использование = Истина;
    ПараметрЦветФона.Значение = Новый Цвет(255, 236, 239); // Светло-красный цвет

    // Настраиваем параметры вывода (не выводить параметры и отбор)
    Настройки.ПараметрыВывода.УстановитьЗначениеПараметра("ВыводитьПараметрыДанных", 
        Новый Идентификатор("НеВыводить"));
    Настройки.ПараметрыВывода.УстановитьЗначениеПараметра("ВыводитьОтбор", 
        Новый Идентификатор("НеВыводить"));

    // Создаем табличный документ для результата
    ТабличныйДокумент = Новый ТабличныйДокумент;

    // Компонуем отчет
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        Настройки,
        ,
        ,
        Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    // Выполняем компоновку данных
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    // Создаем процессор вывода в табличный документ
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

Функция СформироватьРеестрПродажПоПокупателям(ДатаНач, ДатаКон) Экспорт

    // Создаем таблицу значений для результата
    РеестрПродаж = Новый ТаблицаЗначений;

    // Добавляем колонки в таблицу
    РеестрПродаж.Колонки.Добавить("Покупатель", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    РеестрПродаж.Колонки.Добавить("Товар",      Новый ОписаниеТипов("СправочникСсылка.Товары"));
    РеестрПродаж.Колонки.Добавить("Количество",  Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 3)));
    РеестрПродаж.Колонки.Добавить("Сумма",      Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Создаем запрос
    Запрос = Новый Запрос;

    // Формируем текст запроса с двумя этапами
    // Этап 1: Временная таблица с документами РасходТовара за период
    // Этап 2: Соединение с табличной частью для получения агрегированных данных
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    РасходТовара.Ссылка КАК Ссылка,
    |    РасходТовара.Покупатель КАК Покупатель
    |ПОМЕСТИТЬ ВременнаяТаблицаДокументов
    |ИЗ
    |    Документ.РасходТовара КАК РасходТовара
    |ГДЕ
    |    РасходТовара.Проведен = ИСТИНА
    |    И РасходТовара.Дата >= &ДатаНач
    |    И РасходТовара.Дата <= &ДатаКон
    |
    |ИНДЕКСИРОВАТЬ ПО
    |    Ссылка,
    |    Покупатель
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ВременнаяТаблицаДокументов.Покупатель КАК Покупатель,
    |    РасходТовараТовары.Товар КАК Товар,
    |    СУММА(РасходТовараТовары.Количество) КАК Количество,
    |    СУММА(РасходТовараТовары.Сумма) КАК Сумма
    |ИЗ
    |    ВременнаяТаблицаДокументов КАК ВременнаяТаблицаДокументов
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасходТовара.Товары КАК РасходТовараТовары
    |        ПО ВременнаяТаблицаДокументов.Ссылка = РасходТовараТовары.Ссылка
    |
    |СГРУППИРОВАТЬ ПО
    |    ВременнаяТаблицаДокументов.Покупатель,
    |    РасходТовараТовары.Товар
    |
    |УПОРЯДОЧИТЬ ПО
    |    Покупатель,
    |    Товар";

    // Устанавливаем параметры запроса
    // Если дата не указана (пустая), используем минимально возможную дату
    Запрос.УстановитьПараметр("ДатаНач", ?(ЗначениеЗаполнено(ДатаНач), НачалоДня(ДатаНач), Дата(1, 1, 1)));
    Запрос.УстановитьПараметр("ДатаКон", ?(ЗначениеЗаполнено(ДатаКон), КонецДня(ДатаКон), Дата(3999, 12, 31, 23, 59, 59)));

    // Выполняем запрос
    РезультатЗапроса = Запрос.Выполнить();

    // Если есть данные, выгружаем их в таблицу значений
    Если НЕ РезультатЗапроса.Пустой() Тогда
        РеестрПродаж = РезультатЗапроса.Выгрузить();
    КонецЕсли;

    Возврат РеестрПродаж;

КонецФункции

// Функция формирует анализ курсовой разницы по оплатам поставщикам
//
// Параметры:
//   ДатаНач - Дата - Начало периода анализа (необязательно)
//   ДатаКон - Дата - Конец периода анализа (необязательно)
//
// Возвращает:
//   ТаблицаЗначений - Результат анализа курсовых разниц
//
Функция СформироватьАнализКурсовойРазницыПоОплатам(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // =====================================================================
    // ЭТАП 1: Обработка параметров и установка значений по умолчанию
    // =====================================================================

    ТекущаяДата = ТекущаяДатаСеанса();

    // Если дата начала не задана, устанавливаем начало дня 30 дней назад
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата - 30 * 86400);
    КонецЕсли;

    // Если дата окончания не задана, устанавливаем конец текущего дня
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата);
    КонецЕсли;

    // =====================================================================
    // ЭТАП 2: Проверка корректности параметров
    // =====================================================================

    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала!";
    КонецЕсли;

    // =====================================================================
    // ЭТАП 3: Формирование запроса к документам "Оплата"
    // =====================================================================

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Оплата.Ссылка КАК Документ,
    |    Оплата.Дата КАК Дата,
    |    Оплата.Поставщик КАК Поставщик,
    |    Оплата.Валюта КАК Валюта,
    |    Оплата.Сумма КАК СуммаВВалюте,
    |    Оплата.Сумма * ЕстьNULL(КурсыВалют.Курс, 0) КАК СуммаВБазовойВалюте,
    |    Оплата.Сумма * ЕстьNULL(КурсыВалют.Курс, 0) - Оплата.Сумма КАК КурсоваяРазница,
    |    КурсыВалют.Курс КАК Курс
    |ИЗ
    |    Документ.Оплата КАК Оплата
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.КурсыВалют.СрезПоследних(&ДатаСреза, ) КАК КурсыВалют
    |        ПО Оплата.Валюта = КурсыВалют.Валюта
    |ГДЕ
    |    Оплата.Проведен
    |    И Оплата.Дата >= &ДатаНач
    |    И Оплата.Дата <= &ДатаКон
    |УПОРЯДОЧИТЬ ПО
    |    Дата";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Запрос.УстановитьПараметр("ДатаСреза", ДатаКон);

    // =====================================================================
    // ЭТАП 4: Выполнение запроса и получение результата
    // =====================================================================

    РезультатЗапроса = Запрос.Выполнить();

    // Создаём таблицу значений на основе результата запроса
    ТаблицаРезультата = РезультатЗапроса.Выгрузить();

    // =====================================================================
    // ЭТАП 5: Сортировка по убыванию абсолютного значения курсовой разницы
    // =====================================================================

    ТаблицаРезультата.Сортировать("КурсоваяРазница УБЫВ");

    // Удаляем колонку "Курс" из итоговой таблицы (она использовалась для сортировки)
    // Если она не нужна в результате, раскомментируйте следующую строку:
    // ТаблицаРезультата.Колонки.Удалить("Курс");

    Возврат ТаблицаРезультата;

КонецФункции

// Функция расчета среднего чека продаж за период
//
// Параметры:
//   ДатаНач - Дата - Начальная дата периода (необязательно)
//   ДатаКон - Дата - Конечная дата периода (необязательно)
//
// Возвращаемое значение:
//   ТаблицаЗначений - с колонками:
//     * КоличествоЧеков    - Число - Количество документов продаж
//     * ОбщаяСуммаПродаж   - Число - Общая сумма продаж за период
//     * СреднийЧек         - Число - Средняя сумма одного чека
//
Функция СформироватьСреднийЧекПродаж(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка значений по умолчанию, если параметры не заданы
    Если НЕ ЗначениеЗаполнено(ДатаНач) Тогда
        ДатаНач = НачалоДня(ТекущаяДата()) - 30 * 86400; // 30 дней назад
    КонецЕсли;

    Если НЕ ЗначениеЗаполнено(ДатаКон) Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода";
    КонецЕсли;

    // Создание запроса для получения данных о продажах
    Запрос = Новый Запрос;
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    Запрос.Текст = 
    "ВЫБРАТЬ
    |	РасходТовара.Ссылка КАК ДокументПродажи,
    |	СУММА(РасходТовараТовары.Сумма) КАК СуммаЧека
    |ИЗ
    |	Документ.РасходТовара КАК РасходТовара
    |		ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасходТовара.Товары КАК РасходТовараТовары
    |		ПО РасходТовара.Ссылка = РасходТовараТовары.Ссылка
    |ГДЕ
    |	РасходТовара.Проведен = ИСТИНА
    |	И РасходТовара.Дата >= &ДатаНач
    |	И РасходТовара.Дата <= &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |	РасходТовара.Ссылка";

    // Выполнение запроса и выгрузка результата в таблицу значений
    РезультатЗапроса = Запрос.Выполнить();
    ТаблицаЧеков = РезультатЗапроса.Выгрузить();

    // Расчет итоговых показателей
    КоличествоЧеков = ТаблицаЧеков.Количество();

    Если КоличествоЧеков > 0 Тогда
        ОбщаяСуммаПродаж = ТаблицаЧеков.Итог("СуммаЧека");
        СреднийЧек = ОбщаяСуммаПродаж / КоличествоЧеков;
    Иначе
        ОбщаяСуммаПродаж = 0;
        СреднийЧек = 0;
    КонецЕсли;

    // Формирование результирующей таблицы
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("КоличествоЧеков",    Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 0)));
    Результат.Колонки.Добавить("ОбщаяСуммаПродаж",  Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    Результат.Колонки.Добавить("СреднийЧек",        Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    СтрокаРезультата = Результат.Добавить();
    СтрокаРезультата.КоличествоЧеков   = КоличествоЧеков;
    СтрокаРезультата.ОбщаяСуммаПродаж = ОбщаяСуммаПродаж;
    СтрокаРезультата.СреднийЧек       = СреднийЧек;

    Возврат Результат;

КонецФункции

// Функция формирует отчет о продажах предприятия по дням за выбранный период
//
// Параметры:
//   ДатаНач - Дата - Начало периода отчета (необязательно)
//   ДатаКон - Дата - Конец периода отчета (необязательно)
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками:
//     * Дата - Дата - Дата продаж
//     * КоличествоПродаж - Число - Общее количество проданных товаров за день
//     * СуммаПродаж - Число - Общая сумма продаж за день
//
// Пример использования:
//   ТаблицаПродаж = СформироватьПродажиПоДням();
//   ТаблицаПродаж = СформироватьПродажиПоДням('20240101', '20240131');
//
Функция СформироватьПродажиПоДням(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка значений по умолчанию для параметров периода
    Если НЕ ЗначениеЗаполнено(ДатаНач) Тогда
        // ДатаНач = начало дня 30 дней назад
        ДатаНач = НачалоДня(ТекущаяДатаСеанса()) - 30 * 24 * 60 * 60;
    КонецЕсли;

    Если НЕ ЗначениеЗаполнено(ДатаКон) Тогда
        // ДатаКон = конец текущего дня
        ДатаКон = КонецДня(ТекущаяДатаСеанса());
    КонецЕсли;

    // Проверка корректности задания периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода!";
    КонецЕсли;

    // Формирование запроса для получения данных о продажах
    Запрос = Новый Запрос;

    // Текст запроса с группировкой по дням и расчетом показателей продаж
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ВЫРАЗИТЬ(РасходТовара.Дата КАК ДАТА) КАК Дата,
    |    СУММА(РасходТовараТовары.Количество) КАК КоличествоПродаж,
    |    СУММА(РасходТовараТовары.Сумма) КАК СуммаПродаж
    |ИЗ
    |    Документ.РасходТовара КАК РасходТовара
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасходТовара.Товары КАК РасходТовараТовары
    |        ПО РасходТовара.Ссылка = РасходТовараТовары.Ссылка
    |ГДЕ
    |    РасходТовара.Проведен = ИСТИНА
    |    И РасходТовара.Дата >= &ДатаНач
    |    И РасходТовара.Дата <= &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    ВЫРАЗИТЬ(РасходТовара.Дата КАК ДАТА)
    |УПОРЯДОЧИТЬ ПО
    |    Дата ВОЗР";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполнение запроса
    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений для результата
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата", , , Новый КвалификаторыДаты(ЧастиДаты.Дата)));
    ТаблицаРезультат.Колонки.Добавить("КоличествоПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультат.Колонки.Добавить("СуммаПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Выгрузка результата запроса в таблицу значений
    ТаблицаРезультат = РезультатЗапроса.Выгрузить();

    // Удаление строк с пустой датой (на случай, если такие появятся)
    Если ТаблицаРезультат.Количество() > 0 Тогда
        ПустаяДата = '00010101';
        СтрокиБезДаты = ТаблицаРезультат.НайтиСтроки(Новый Структура("Дата", ПустаяДата));
        Для Каждого СтрокаБезДаты Из СтрокиБезДаты Цикл
            ТаблицаРезультат.Удалить(СтрокаБезДаты);
        КонецЦикла;
    КонецЕсли;

    // Сортировка по дате в порядке возрастания
    // (выполняется на случай, если запрос вернул данные не в нужном порядке)
    ТаблицаРезультат.Сортировать("Дата ВОЗР");

    Возврат ТаблицаРезультат;

КонецФункции // СформироватьПродажиПоДням()

// Функция формирует отчет о товарах с отрицательными остатками
//
// Параметры:
//   ДатаОстатков - Дата - Дата, на которую формируется отчет.
//                        Если не указана, используется конец текущего дня
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками:
//     * Товар              - СправочникСсылка.Товары - ссылка на товар
//     * КоличествоОстаток  - Число - остаток товара (отрицательный)
//
Функция СформироватьТоварыСОтрицательнымиОстатками(ДатаОстатков = '00010101') Экспорт

    // Проверка параметра даты и установка значения по умолчанию
    Если НЕ ЗначениеЗаполнено(ДатаОстатков) Тогда
        ДатаОстатков = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Формируем момент времени для корректного получения остатков
    МоментВремени = Новый МоментВремени(ДатаОстатков);

    // Создание запроса к регистру накопления ТоварныеЗапасы
    Запрос = Новый Запрос;

    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток КАК КоличествоОстаток
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&МоментВремени, ) КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |    ТоварныеЗапасыОстатки.КоличествоОстаток < 0
    |    И ТоварныеЗапасыОстатки.Товар <> ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка)
    |УПОРЯДОЧИТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар.Наименование
    |АВТОУПОРЯДОЧИВАНИЕ";

    Запрос.УстановитьПараметр("МоментВремени", МоментВремени);

    // Выполнение запроса и выгрузка результата в таблицу значений
    ТаблицаРезультат = Запрос.Выполнить().Выгрузить();

    // Возврат таблицы результата
    Возврат ТаблицаРезультат;

КонецФункции

// Функция формирует отчет о товарах предприятия, для которых не установлена цена
//
// Параметры:
//   ДатаЦен - Дата - Дата, на которую необходимо проверить наличие цен
//                   Если не указана, используется конец текущего дня
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонкой "Товар", содержащая товары без цены
//
Функция СформироватьТоварыБезЦены(ДатаЦен = '00010101') Экспорт

    // Установка даты по умолчанию (конец текущего дня)
    Если НЕ ЗначениеЗаполнено(ДатаЦен) Тогда
        ДатаЦен = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    СпрТовары.Ссылка КАК Товар
    |ИЗ
    |    Справочник.Товары КАК СпрТовары
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних(&ДатаЦен, ) КАК ЦеныТоваровСрезПоследних
    |        ПО СпрТовары.Ссылка = ЦеныТоваровСрезПоследних.Товар
    |ГДЕ
    |    ЦеныТоваровСрезПоследних.Цена ЕСТЬ NULL
    |УПОРЯДОЧИТЬ ПО
    |    СпрТовары.Наименование";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаЦен", ДатаЦен);

    // Выполнение запроса и выгрузка результата в таблицу значений
    ТаблицаРезультата = Запрос.Выполнить().Выгрузить();

    // Фильтрация: исключаем строки с неопределенным товаром
    ТаблицаРезультата = ТаблицаРезультата.НайтиСтроки(
        Новый Структура("Товар", Неопределено)
    );

    Если ТаблицаРезультата.Количество() > 0 Тогда
        Для Каждого СтрокаТаблицы Из ТаблицаРезультата Цикл
            ТаблицаРезультата.Удалить(СтрокаТаблицы);
        КонецЦикла;
    КонецЕсли;

    // Альтернативный вариант фильтрации (более эффективный)
    ЗапросФильтрация = Новый Запрос;
    ЗапросФильтрация.Текст = 
    "ВЫБРАТЬ
    |    СпрТовары.Ссылка КАК Товар
    |ИЗ
    |    Справочник.Товары КАК СпрТовары
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних(&ДатаЦен, ) КАК ЦеныТоваровСрезПоследних
    |        ПО СпрТовары.Ссылка = ЦеныТоваровСрезПоследних.Товар
    |ГДЕ
    |    ЦеныТоваровСрезПоследних.Цена ЕСТЬ NULL
    |    И СпрТовары.Ссылка <> ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка)
    |УПОРЯДОЧИТЬ ПО
    |    СпрТовары.Наименование";

    ЗапросФильтрация.УстановитьПараметр("ДатаЦен", ДатаЦен);
    ТаблицаРезультата = ЗапросФильтрация.Выполнить().Выгрузить();

    // Сортировка по товару в порядке возрастания
    ТаблицаРезультата.Сортировать("Товар ВОЗР");

    Возврат ТаблицаРезультата;

КонецФункции

// Функция формирует таблицу себестоимости остатков товаров на текущую дату
//
// Параметры:
//  нет
//
// Возвращаемое значение:
//  ТаблицаЗначений - таблица с полями:
//   * Товар               - ссылка на номенклатуру
//   * КоличествоОстаток    - текущий остаток товара
//   * СебестоимостьЕд     - средневзвешенная себестоимость единицы
//   * СебестоимостьОстатка - общая стоимость остатка
//
Функция СформироватьСебестоимостьТоваровСредневзвеш() Экспорт

    Запрос = Новый Запрос;

    Запрос.Текст =
    |ВЫБРАТЬ
    |    Остатки.Товар,
    |    Остатки.КоличествоОстаток,
    |    ВЫБОР
    |        КОГДА Приходы.СебестоимостьЕд ЕСТЬ NULL
    |            ТОГДА 0
    |        ИНАЧЕ Приходы.СебестоимостьЕд
    |    КОНЕЦ КАК СебестоимостьЕд,
    |    Остатки.КоличествоОстаток * ВЫБОР
    |        КОГДА Приходы.СебестоимостьЕд ЕСТЬ NULL
    |            ТОГДА 0
    |        ИНАЧЕ Приходы.СебестоимостьЕд
    |    КОНЕЦ КАК СебестоимостьОстатка
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата, ) КАК Остатки
    |        ЛЕВОЕ СОЕДИНЕНИЕ (
    |            ВЫБРАТЬ
    |                ПриходТовараТовары.Товар,
    |                СУММА(ПриходТовараТовары.Сумма) / ВЫБОР
    |                    КОГДА СУММА(ПриходТовараТовары.Количество) = 0
    |                        ТОГДА 1
    |                    ИНАЧЕ СУММА(ПриходТовараТовары.Количество)
    |                КОНЕЦ КАК СебестоимостьЕд
    |            ИЗ
    |                Документ.ПриходТовара.Товары КАК ПриходТовараТовары
    |                ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.ПриходТовара КАК ПриходТовара
    |                    ПО ПриходТовараТовары.Ссылка = ПриходТовара.Ссылка
    |            ГДЕ
    |                ПриходТовара.Проведен = ИСТИНА
    |                И ПриходТовара.Дата <= &Дата
    |                И ПриходТовараТовары.Товар <> ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка)
    |            СГРУППИРОВАТЬ ПО
    |                ПриходТовараТовары.Товар
    |        ) КАК Приходы
    |        ПО Остатки.Товар = Приходы.Товар
    |ГДЕ
    |    Остатки.КоличествоОстаток > 0
    |УПОРЯДОЧИТЬ ПО
    |    Остатки.Товар.Наименование
    |АВТОУПОРЯДОЧИВАНИЕ";

    // Устанавливаем параметр даты - текущая дата
    Запрос.УстановитьПараметр("Дата", КонецДня(ТекущаяДата()));

    // Выполняем запрос и возвращаем результат как таблицу значений
    РезультатЗапроса = Запрос.Выполнить().Выгрузить();

    Возврат РезультатЗапроса;

КонецФункции

// Функция формирует выгрузку данных о продажах по покупателям и товарам
// за указанный период в XML-файл
//
// Параметры:
//   ДатаНач - Дата - Начальная дата периода
//   ДатаКон - Дата - Конечная дата периода
//
// Возвращаемое значение:
//   Строка - Путь к сформированному XML-файлу
//
Функция ВыгрузитьПродажиВXMLФайл(ДатаНач, ДатаКон) Экспорт

    // Формируем запрос к регистру накопления Продажи
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.Покупатель КАК Покупатель,
    |    ПродажиОбороты.Товар КАК Товар,
    |    ПродажиОбороты.КоличествоОборот КАК Количество,
    |    ПродажиОбороты.СуммаОборот КАК Сумма
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, Авто, Покупатель, Товар) КАК ПродажиОбороты
    |УПОРЯДОЧИТЬ ПО
    |    Покупатель.Наименование,
    |    Товар.Наименование";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполняем запрос и получаем выборку
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // Формируем путь к временному файлу
    ИмяВременногоФайла = ПолучитьИмяВременногоФайла("xml");

    // Создаём объект записи XML
    ЗаписьXML = Новый ЗаписьXML;
    ЗаписьXML.ОткрытьФайл(ИмяВременногоФайла, "UTF-8");

    // Записываем объявление XML
    ЗаписьXML.ЗаписатьОбъявлениеXML();

    // Формируем корневой элемент с атрибутами
    ЗаписьXML.ЗаписатьНачалоЭлемента("Продажи");

    ЗаписьXML.ЗаписатьАтрибут("Имя", "ПродажиПоПокупателямИТоварам");
    ЗаписьXML.ЗаписатьАтрибут("ДатаНач", Формат(ДатаНач, "ДФ=yyyy-MM-dd"));
    ЗаписьXML.ЗаписатьАтрибут("ДатаКон", Формат(ДатаКон, "ДФ=yyyy-MM-dd"));

    // Обходим выборку и формируем элементы "Запись"
    Пока Выборка.Следующий() Цикл

        ЗаписьXML.ЗаписатьНачалоЭлемента("Запись");

        // Записываем данные покупателя
        ЗаписьXML.ЗаписатьНачалоЭлемента("Покупатель");
        ЗаписьXML.ЗаписатьТекст(Строка(Выборка.Покупатель));
        ЗаписьXML.ЗаписатьКонецЭлемента();

        // Записываем данные товара
        ЗаписьXML.ЗаписатьНачалоЭлемента("Товар");
        ЗаписьXML.ЗаписатьТекст(Строка(Выборка.Товар));
        ЗаписьXML.ЗаписатьКонецЭлемента();

        // Записываем количество
        ЗаписьXML.ЗаписатьНачалоЭлемента("Количество");
        ЗаписьXML.ЗаписатьТекст(Формат(Выборка.Количество, "ЧДЦ=2; ЧГ=0"));
        ЗаписьXML.ЗаписатьКонецЭлемента();

        // Записываем сумму
        ЗаписьXML.ЗаписатьНачалоЭлемента("Сумма");
        ЗаписьXML.ЗаписатьТекст(Формат(Выборка.Сумма, "ЧДЦ=2; ЧГ=0"));
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьКонецЭлемента();

    КонецЦикла;

    // Закрываем корневой элемент
    ЗаписьXML.ЗаписатьКонецЭлемента();

    // Закрываем файл и возвращаем путь
    ЗаписьXML.Закрыть();

    Возврат ИмяВременногоФайла;

КонецФункции

task:
Написать функцию ПолучитьДанныеФайла(ФайлСсылка), которая получает структуру с сведениями о переданном файле.
Параметры функции:
ФайлСсылка (тип: СправочникСсылка.ХранимыеФайлы) - ссылка на файл.

Возвращаемое значение:
Структура - данные о файле:
    * Ссылка (тип СправочникСсылка.ХранимыеФайлы) - ссылка на файл;
    * СсылкаНаДвоичныеДанныеФайла (тип Строка) - адрес во временном хранилище, по которому помещены данные файла.
    * Владелец (тип СправочникСсылка.Товары, СправочникСсылка.Контрагенты) - ссылка на объект-владелец файла;
    * ИмяФайла (тип Строка) - имя файла;
    * Наименование (тип Строка) наименование файла (в справочнике ХранимыеФайлы);   
    * Расширение (тип Строка) - расширение файла без точки;  
    * Подписан (тип Булево) - признак того, что файл подписан;
    * Зашифрован (тип Булево) - признак того, что файл зашифрован; 
    * Ширина (тип Число) - ширина файла, только для .png;
    * Высота (тип Число) - высота файла, только для .png;
    * Размер (тип Число) - размер файла в кб.

output:
Функция ПолучитьДанныеФайла(ФайлСсылка) Экспорт

    // Проверка на пустую ссылку
    Если НЕ ЗначениеЗаполнено(ФайлСсылка) Тогда
        Возврат Неопределено;
    КонецЕсли;

    СтруктураФайла = Новый Структура;
    СтруктураФайла.Вставить("Ссылка", ФайлСсылка);
    СтруктураФайла.Вставить("СсылкаНаДвоичныеДанныеФайла", "");
    СтруктураФайла.Вставить("Владелец", Справочники.Товары.ПустаяСсылка());
    СтруктураФайла.Вставить("ИмяФайла", "");
    СтруктураФайла.Вставить("Наименование", "");
    СтруктураФайла.Вставить("Расширение", "");
    СтруктураФайла.Вставить("Подписан", Ложь);
    СтруктураФайла.Вставить("Зашифрован", Ложь);
    СтруктураФайла.Вставить("Ширина", 0);
    СтруктураФайла.Вставить("Высота", 0);
    СтруктураФайла.Вставить("Размер", 0);

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   ХранимыеФайлы.ВладелецФайла КАК Владелец,
    |   ХранимыеФайлы.ИмяФайла КАК ИмяФайла,
    |   ХранимыеФайлы.Наименование КАК Наименование,
    |   ХранимыеФайлы.Подписан КАК Подписан,
    |   ХранимыеФайлы.Зашифрован КАК Зашифрован,
    |   ХранимыеФайлы.ДанныеФайла КАК ДанныеФайла
    |ИЗ
    |   Справочник.ХранимыеФайлы КАК ХранимыеФайлы
    |ГДЕ
    |   ХранимыеФайлы.Ссылка = &ФайлСсылка";

    Запрос.УстановитьПараметр("ФайлСсылка", ФайлСсылка);

    Выборка = Запрос.Выполнить().Выбрать();

    Если Выборка.Следующий() Тогда

        СтруктураФайла.Владелец         = Выборка.Владелец;
        СтруктураФайла.ИмяФайла         = Выборка.ИмяФайла;
        СтруктураФайла.Наименование     = Выборка.Наименование;
        СтруктураФайла.Подписан         = Выборка.Подписан;
        СтруктураФайла.Зашифрован       = Выборка.Зашифрован;

        ДвоичныеДанные = Выборка.ДанныеФайла.Получить();

        // Извлекаем расширение из имени файла
        ИмяФайла = Выборка.ИмяФайла;
        Если ИмяФайла <> "" Тогда
            ПозицияТочки = СтрНайти(ИмяФайла, ".", НаправлениеПоиска.СКонца);
            Если ПозицияТочки > 0 Тогда
                СтруктураФайла.Расширение = Сред(ИмяФайла, ПозицияТочки + 1);
            КонецЕсли;
        КонецЕсли;

        // Получаем размеры PNG
        Если ВРег(СтруктураФайла.Расширение) = "PNG" 
            И ДвоичныеДанные <> Неопределено 
            И НЕ Выборка.Зашифрован Тогда

            Попытка
                Картинка = Новый Картинка(ДвоичныеДанные);
                СтруктураФайла.Ширина  = Картинка.Ширина;
                СтруктураФайла.Высота = Картинка.Высота;
            Исключение
                // Игнорируем ошибки чтения PNG
            КонецПопытки;

        КонецЕсли;

        // Вычисляем размер в КБ
        Если ДвоичныеДанные <> Неопределено Тогда
            РазмерВБайтах = ДвоичныеДанные.Размер();
            СтруктураФайла.Размер = Окр(РазмерВБайтах / 1024, 2);

            // Помещаем данные во временное хранилище, если файл не зашифрован
            Если НЕ Выборка.Зашифрован Тогда
                Адрес = ПоместитьВоВременноеХранилище(
                    ДвоичныеДанные, 
                    Новый УникальныйИдентификатор
                );
                СтруктураФайла.СсылкаНаДвоичныеДанныеФайла = Адрес;
            КонецЕсли;
        КонецЕсли;

    КонецЕсли;

    Возврат СтруктураФайла;

КонецФункции

// Функция загружает данные товаров из строки JSON в справочник "Товары"
//
// Параметры:
//    СтрокаJSON - Строка - Строка в формате JSON, содержащая данные товаров
//
// Возвращаемое значение:
//    ТаблицаЗначений - Таблица с колонками: 
//        Успешно (Булево) - признак успешной обработки
//        Артикул (Строка) - артикул обработанного товара
//        Сообщение (Строка) - информация о результате
//
Функция ЗагрузитьДанныеТоваровИзJSON(СтрокаJSON) Экспорт

    РезультатОбработки = Новый ТаблицаЗначений;
    РезультатОбработки.Колонки.Добавить("Успешно", Новый ОписаниеТипов("Булево"));
    РезультатОбработки.Колонки.Добавить("Артикул", Новый ОписаниеТипов("Строка"));
    РезультатОбработки.Колонки.Добавить("Сообщение", Новый ОписаниеТипов("Строка"));

    Если Не ЗначениеЗаполнено(СтрокаJSON) Тогда
        СтрокаРезультата = РезультатОбработки.Добавить();
        СтрокаРезультата.Успешно = Ложь;
        СтрокаРезультата.Сообщение = "Получена пустая строка JSON";
        Возврат РезультатОбработки;
    КонецЕсли;

    // Преобразуем строку JSON в массив структур
    ЧтениеJSON = Новый ЧтениеJSON;
    ЧтениеJSON.УстановитьСтроку(СтрокаJSON);

    Попытка
        ДанныеТоваров = ПрочитатьJSON(ЧтениеJSON);
    Исключение
        СтрокаРезультата = РезультатОбработки.Добавить();
        СтрокаРезультата.Успешно = Ложь;
        СтрокаРезультата.Сообщение = "Ошибка чтения JSON: " + ОписаниеОшибки();
        Возврат РезультатОбработки;
    КонецПопытки;

    // Определяем, является ли результат массивом или одиночной структурой
    Если ТипЗнч(ДанныеТоваров) = Тип("Массив") Тогда
        МассивТоваров = ДанныеТоваров;
    Иначе
        МассивТоваров = Новый Массив;
        МассивТоваров.Добавить(ДанныеТоваров);
    КонецЕсли;

    // Получаем менеджер справочника Товары
    СправочникТовары = Справочники.Товары;
    СправочникКонтрагенты = Справочники.Контрагенты;

    // Получаем менеджер перечисления ВидыТоваров
    ПеречислениеВидыТоваров = Перечисления.ВидыТоваров;

    Для Каждого СтруктураТовара Из МассивТоваров Цикл

        СтрокаРезультата = РезультатОбработки.Добавить();

        // Проверяем обязательные свойства
        Если Не СтруктураТовара.Свойство("article") 
            Или Не СтруктураТовара.Свойство("description") Тогда
            СтрокаРезультата.Успешно = Ложь;
            СтрокаРезультата.Сообщение = "Отсутствуют обязательные свойства (article или description)";
            Продолжить;
        КонецЕсли;

        Артикул = СокрЛП(СтруктураТовара.article);
        Наименование = СокрЛП(СтруктураТовара.description);

        // Проверяем заполненность обязательных полей
        Если Не ЗначениеЗаполнено(Артикул) Тогда
            СтрокаРезультата.Успешно = Ложь;
            СтрокаРезультата.Сообщение = "Не заполнен артикул товара";
            Продолжить;
        КонецЕсли;

        Если Не ЗначениеЗаполнено(Наименование) Тогда
            СтрокаРезультата.Успешно = Ложь;
            СтрокаРезультата.Сообщение = "Не заполнено наименование товара";
            Продолжить;
        КонецЕсли;

        // Ищем существующий товар по артикулу
        НайденныйТовар = СправочникТовары.НайтиПоРеквизиту("Артикул", Артикул);

        Если НайденныйТовар.Пустая() Тогда
            // Создаём новый элемент справочника
            ТоварОбъект = СправочникТовары.СоздатьЭлемент();
            ТоварОбъект.Артикул = Артикул;
        Иначе
            // Получаем объект существующего элемента для редактирования
            ТоварОбъект = НайденныйТовар.ПолучитьОбъект();
        КонецЕсли;

        // Заполняем основные реквизиты
        ТоварОбъект.Наименование = Наименование;

        // Заполняем необязательные свойства

        // Штрихкод
        Если СтруктураТовара.Свойство("barcode") 
            И ЗначениеЗаполнено(СтруктураТовара.barcode) Тогда
            ТоварОбъект.Штрихкод = СокрЛП(Лев(СтруктураТовара.barcode, 20));
        КонецЕсли;

        // Код поставщика (необходимо найти контрагента)
        Если СтруктураТовара.Свойство("counterparty_code") 
            И ЗначениеЗаполнено(СтруктураТовара.counterparty_code) Тогда
            КодПоставщика = СокрЛП(СтруктураТовара.counterparty_code);

            // Найдём контрагента по коду
            Запрос = Новый Запрос;
            Запрос.Текст = 
            "ВЫБРАТЬ ПЕРВЫЕ 1
            |    Контрагенты.Ссылка
            |ИЗ
            |    Справочник.Контрагенты КАК Контрагенты
            |ГДЕ
            |    Контрагенты.Код = &Код
            |    И Не Контрагенты.ПометкаУдаления";

            Запрос.УстановитьПараметр("Код", КодПоставщика);

            РезультатЗапроса = Запрос.Выполнить();

            Если Не РезультатЗапроса.Пустой() Тогда
                Выборка = РезультатЗапроса.Выбрать();
                Выборка.Следующий();
                ТоварОбъект.Поставщик = Выборка.Ссылка;
            КонецЕсли;
        КонецЕсли;

        // Вид товара (перечисление)
        Если СтруктураТовара.Свойство("type") 
            И ЗначениеЗаполнено(СтруктураТовара.type) Тогда
            ИмяВидаТовара = СокрЛП(СтруктураТовара.type);

            // Пытаемся найти значение перечисления по имени
            Попытка
                ЗначениеПеречисления = ПеречислениеВидыТоваров[ИмяВидаТовара];
                Если ЗначениеЗаполнено(ЗначениеПеречисления) Тогда
                    ТоварОбъект.Вид = ЗначениеПеречисления;
                КонецЕсли;
            Исключение
                // Игнорируем ошибку, если перечисление не найдено
            КонецПопытки;
        КонецЕсли;

        // Сохраняем элемент справочника
        Попытка
            ТоварОбъект.Записать();

            СтрокаРезультата.Успешно = Истина;
            СтрокаРезультата.Артикул = Артикул;

            Если НайденныйТовар.Пустая() Тогда
                СтрокаРезультата.Сообщение = "Создан новый товар: " + Наименование;
            Иначе
                СтрокаРезультата.Сообщение = "Обновлён товар: " + Наименование;
            КонецЕсли;

        Исключение
            СтрокаРезультата.Успешно = Ложь;
            СтрокаРезультата.Артикул = Артикул;
            СтрокаРезультата.Сообщение = "Ошибка записи товара: " + ОписаниеОшибки();
        КонецПопытки;

    КонецЦикла;

    Возврат РезультатОбработки;

КонецФункции

Функция СформироватьРасчетЗаказа(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка параметров периода по умолчанию
    Если ДатаКон = Неопределено Тогда
        ДатаКон = ТекущаяДата();
    КонецЕсли;

    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ДатаКон) - 30 * 24 * 60 * 60; // 30 дней назад
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода";
    КонецЕсли;

    // Формирование временной таблицы продаж
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    Продажи.Товар,
    |    СУММА(Продажи.Количество) КАК КоличествоПродаж
    |ПОМЕСТИТЬ ВТ_Продажи
    |ИЗ
    |    РегистрНакопления.Продажи КАК Продажи
    |ГДЕ
    |    Продажи.Период >= &ДатаНач
    |    И Продажи.Период <= &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    Продажи.Товар
    |";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Запрос.Выполнить();

    // Формирование итогового расчета с использованием левого соединения
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ВТ_Продажи.Товар,
    |    ВТ_Продажи.КоличествоПродаж,
    |    ЕстьNull(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК ОстаткиТовара,
    |    Максимум(ВТ_Продажи.КоличествоПродаж - ЕстьNull(ТоварныеЗапасыОстатки.КоличествоОстаток, 0), 0) КАК РекомендуемыйЗаказ
    |ИЗ
    |    ВТ_Продажи КАК ВТ_Продажи
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаКон, ) КАК ТоварныеЗапасыОстатки
    |        ПО ВТ_Продажи.Товар = ТоварныеЗапасыОстатки.Товар
    |СГРУППИРОВАТЬ ПО
    |    ВТ_Продажи.Товар,
    |    ВТ_Продажи.КоличествоПродаж,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток
    |ИМЕЮЩИЕ
    |    Максимум(ВТ_Продажи.КоличествоПродаж - ЕстьNull(ТоварныеЗапасыОстатки.КоличествоОстаток, 0), 0) > 0
    |УПОРЯДОЧИТЬ ПО
    |    ВТ_Продажи.Товар.Наименование
    |";

    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    Возврат Запрос.Выполнить().Выгрузить();

КонецФункции

// Функция формирует таблицу остатков товаров за заданный период,
// скорректированных по результатам инвентаризации.
//
// Параметры:
//   ДатаНачала - Дата - начало периода
//   ДатаОкончания - Дата - окончание периода
//
// Возвращаемое значение:
//   ТаблицаЗначений - с колонками:
//     * Товар - СправочникСсылка.Товар
//     * Склад - СправочникСсылка.Склады
//     * Корректировка - ДокументСсылка.ОперацияПоУчетуТоваров
//     * ЗначениеКорректировки - Число
//     * ОстатокНаКонецПериода - Число
//
Функция УчетТоваровПоИнвентаризации(ДатаНачала, ДатаОкончания) Экспорт

    Запрос = Новый Запрос;
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);

    // Список вариаций подстрок для поиска инвентаризации
    ТекстУсловияИнвентаризации = "
        |СодержаниеОперации ПОДОБНО ""%инвентаризация%""
        |ИЛИ СодержаниеОперации ПОДОБНО ""%в результате инвентаризации%""
        |ИЛИ СодержаниеОперации ПОДОБНО ""%по инвентаризации%""
        |ИЛИ СодержаниеОперации ПОДОБНО ""%инвентар.%""
        |";

    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар,
    |    ТоварныеЗапасыОстатки.Склад,
    |    ИнвентаризацияТЧ.Ссылка КАК Корректировка,
    |    ИнвентаризацияТЧ.КоличествоФактическое - ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК ЗначениеКорректировки,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток КАК ОстатокНаКонецПериода
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаОкончания, ) КАК ТоварныеЗапасыОстатки
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.ОперацияПоУчетуТоваров.Товары КАК ИнвентаризацияТЧ
    |        ПО ТоварныеЗапасыОстатки.Товар = ИнвентаризацияТЧ.Товар
    |            И ТоварныеЗапасыОстатки.Склад = ИнвентаризацияТЧ.Склад
    |            И ИнвентаризацияТЧ.Ссылка.Дата <= &ДатаОкончания
    |ГДЕ
    |    ИнвентаризацияТЧ.Ссылка.Проведен
    |    И ИнвентаризацияТЧ.Ссылка.Дата >= &ДатаНачала
    |    И ИнвентаризацияТЧ.Ссылка.Дата <= &ДатаОкончания
    |    И (&ТекстУсловияИнвентаризации)
    |УПОРЯДОЧИТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар.Наименование,
    |    ТоварныеЗапасыОстатки.Склад.Наименование,
    |    ИнвентаризацияТЧ.Ссылка.Дата УБЫВ
    |";

    // Подставляем условие поиска инвентаризации в текст запроса
    Запрос.Текст = СтрЗаменить(
        Запрос.Текст,
        "&ТекстУсловияИнвентаризации",
        ТекстУсловияИнвентаризации
    );

    РезультатЗапроса = Запрос.Выполнить();
    ТаблицаРезультата = РезультатЗапроса.Выгрузить();

    Возврат ТаблицаРезультата;

КонецФункции

// Функция загружает цены товаров в регистр сведений "ЦеныТоваров" из строки JSON
//
// Параметры:
//   СтрокаJSON - Строка - строка в формате JSON с данными о ценах товаров
//
// Возвращаемое значение:
//   Число - количество успешно загруженных записей
//
Функция ЗагрузитьЦеныТоваровJSON(СтрокаJSON) Экспорт

    // Преобразование строки JSON в структуру или массив структур
    ЧтениеJSON = Новый ЧтениеJSON;
    ЧтениеJSON.УстановитьСтроку(СтрокаJSON);
    ДанныеJSON = ПрочитатьJSON(ЧтениеJSON);
    ЧтениеJSON.Закрыть();

    // Подготовка данных для обработки (поддержка массива и одиночного объекта)
    Если ТипЗнч(ДанныеJSON) = Тип("Массив") Тогда
        МассивДанных = ДанныеJSON;
    Иначе
        МассивДанных = Новый Массив;
        МассивДанных.Добавить(ДанныеJSON);
    КонецЕсли;

    ЗагруженоКоличество = 0;

    // Обработка каждого элемента JSON
    Для Каждого ТекущаяСтрока Из МассивДанных Цикл

        // Поиск товара в справочнике "Товары" по артикулу и наименованию
        Запрос = Новый Запрос;
        Запрос.Текст = 
        "ВЫБРАТЬ
        |    Ссылка
        |ИЗ
        |    Справочник.Товары
        |ГДЕ
        |    Артикул = &Артикул
        |    И Наименование = &Наименование";

        Запрос.УстановитьПараметр("Артикул", ТекущаяСтрока.article);
        Запрос.УстановитьПараметр("Наименование", ТекущаяСтрока.description);

        РезультатЗапроса = Запрос.Выполнить();
        Если НЕ РезультатЗапроса.Пустой() Тогда
            Выборка = РезультатЗапроса.Выбрать();
            Выборка.Следующий();
            Товар = Выборка.Ссылка;
        Иначе
            // Товар не найден - пропускаем загрузку цены
            Продолжить;
        КонецЕсли;

        // Поиск вида цен в справочнике "ВидыЦен" по наименованию
        Запрос = Новый Запрос;
        Запрос.Текст = 
        "ВЫБРАТЬ
        |    Ссылка
        |ИЗ
        |    Справочник.ВидыЦен
        |ГДЕ
        |    Наименование = &Наименование";

        Запрос.УстановитьПараметр("Наименование", ТекущаяСтрока.type_of_price);

        РезультатЗапроса = Запрос.Выполнить();
        Если НЕ РезультатЗапроса.Пустой() Тогда
            Выборка = РезультатЗапроса.Выбрать();
            Выборка.Следующий();
            ВидЦен = Выборка.Ссылка;
        Иначе
            // Вид цен не найден - пропускаем загрузку цены
            Продолжить;
        КонецЕсли;

        // Проверка цены на отрицательное значение
        Если ТекущаяСтрока.price < 0 Тогда
            // Отрицательная цена - пропускаем загрузку
            Продолжить;
        КонецЕсли;

        // Создание записи в регистре сведений "ЦеныТоваров"
        Запись = РегистрыСведений.ЦеныТоваров.СоздатьМенеджерЗаписи();
        Запись.Период = ТекущаяСтрока.date;
        Запись.Товар = Товар;
        Запись.ВидЦен = ВидЦен;
        Запись.Цена = ТекущаяСтрока.price;
        Запись.Записать(Истина);

        ЗагруженоКоличество = ЗагруженоКоличество + 1;

    КонецЦикла;

    Возврат ЗагруженоКоличество;

КонецФункции

task:
Написать функцию СформироватьИнвентаризациюТоваров(Склад = Неопределено, ДатаИнв = Неопределено),
которая формирует инвентаризацию товаров на складе в виде таблицы значений на указанную дату.
Инвентаризация должна формироваться на основании данных регистра накопления «ТоварныеЗапасы».
Данные выбираются из регистра РегистрНакопления.ТоварныеЗапасы.Остатки с учетом следующих условий:
остатки рассчитываются на дату, переданную в параметре ДатаИнв (на конец дня);
если склад не указан, формируется инвентаризация по всем складам;
если склад указан, выполняется отбор по конкретному складу.
Перед выполнением запроса выполняется проверка входных параметров:
если дата инвентаризации не задана, используется текущая дата;
если тип даты некорректен, формируется исключение.
Формирование инвентаризации выполняется следующим образом:
выполняется запрос к регистру накопления «ТоварныеЗапасы.Остатки» на дату инвентаризации;
данные группируются по складу и товару;
рассчитывается фактическое количество остатка товара на складе;
из результирующей выборки отбираются только позиции с ненулевыми остатками.
Результат должен представлять таблицу значений (ТаблицаЗначений), где каждая строка соответствует сочетанию:
Склад + Товар.
Таблица должна содержать следующие поля:
Склад — ссылка на склад хранения товаров (измерение регистра ТоварныеЗапасы);
Товар — номенклатура (измерение регистра ТоварныеЗапасы);
КоличествоФактическое — фактический остаток товара на складе на дату инвентаризации (ресурс регистра).
После формирования таблицы выполняется сортировка данных по складу и товару для удобства анализа инвентаризационных остатков.

output:
// Функция формирует инвентаризацию товаров на складе на указанную дату
//
// Параметры:
//  Склад - СправочникСсылка.Склады - Склад для отбора (необязательно).
//           Если не указан, формируется по всем складам.
//  ДатаИнв - Дата - Дата инвентаризации (необязательно).
//           Если не указана, используется текущая дата.
//
// Возвращает:
//  ТаблицаЗначений - Результат инвентаризации с колонками:
//   - Склад - СправочникСсылка.Склады - Склад хранения товара
//   - Товар - СправочникСсылка.Товары - Номенклатура
//   - КоличествоФактическое - Число - Фактический остаток товара
//
Функция СформироватьИнвентаризациюТоваров(Склад = Неопределено, ДатаИнв = Неопределено) Экспорт

    // Проверка параметра ДатаИнв
    Если ДатаИнв = Неопределено Тогда
        // Если дата не указана, используем текущую дату
        ТекущаяДата = ТекущаяДата();
    Иначе
        // Проверка корректности типа даты
        Если ТипЗнч(ДатаИнв) <> Тип("Дата") Тогда
            ВызватьИсключение "Параметр ""ДатаИнв"" должен иметь тип Дата. " +
                "Передано значение типа: " + ТипЗнч(ДатаИнв);
        КонецЕсли;
        ТекущаяДата = ДатаИнв;
    КонецЕсли;

    // Формируем запрос к регистру накопления
    Запрос = Новый Запрос;

    // Устанавливаем параметры запроса
    // Для остатков на конец дня используем КонецДня(Дата)
    Запрос.УстановитьПараметр("Период", КонецДня(ТекущаяДата));

    // Если склад указан - устанавливаем параметр для отбора
    // Если нет - передаем Неопределено (отбор не требуется)
    Если Склад <> Неопределено Тогда
        Запрос.УстановитьПараметр("Склад", Склад);
    Иначе
        Запрос.УстановитьПараметр("Склад", Неопределено);
    КонецЕсли;

    // Формируем текст запроса к виртуальной таблице остатков
    // Используем параметр виртуальной таблицы для эффективной фильтрации
    |ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Склад,
    |    ТоварныеЗапасыОстатки.Товар,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток КАК КоличествоФактическое
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Период,
    |        Склад = &Склад) КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |    ТоварныеЗапасыОстатки.КоличествоОстаток <> 0
    |УПОРЯДОЧИТЬ ПО
    |    ТоварныеЗапасыОстатки.Склад.Наименование,
    |    ТоварныеЗапасыОстатки.Товар.Наименование
    |ИТОГИ ПО
    |    Склад,
    |    Товар";

    // Выполняем запрос и выгружаем результат в таблицу значений
    РезультатЗапроса = Запрос.Выполнить();
    ТаблицаИнвентаризации = РезультатЗапроса.Выгрузить(ОбходРезультатаЗапроса.Прямой);

    // Сортируем данные по складу и товару
    ТаблицаИнвентаризации.Сортировать("Склад Возр, Товар Возр");

    Возврат ТаблицаИнвентаризации;

КонецФункции

// Проверяет строку на соответствие заданным условиям
//
// Параметры:
//   ИсходнаяСтрока - Строка - строка для проверки
//   Фильтр - Структура - структура условий отбора
//
// Возвращаемое значение:
//   Булево - Истина, если строка соответствует условиям, Ложь - в противном случае
//
Функция ПроверитьСтрокуНаСоответствие(ИсходнаяСтрока, Фильтр) Экспорт

    // Проверка на пустую строку
    Если ПустаяСтрока(ИсходнаяСтрока) Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверка на использование только кириллицы
    Если Фильтр.Свойство("ИспользоватьТолькоКириллицу") 
        И Фильтр.ИспользоватьТолькоКириллицу = Истина Тогда

        Если НЕ СодержитТолькоКириллицу(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;

    КонецЕсли;

    // Проверка на использование только цифр
    Если Фильтр.Свойство("ИспользоватьТолькоЦифры") 
        И Фильтр.ИспользоватьТолькоЦифры = Истина Тогда

        Если НЕ СодержитТолькоЦифры(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;

    КонецЕсли;

    // Проверка начала строки
    Если Фильтр.Свойство("НачинаетсяС") 
        И ЗначениеЗаполнено(Фильтр.НачинаетсяС) Тогда

        Если НЕ СтрНачинаетсяС(ИсходнаяСтрока, Фильтр.НачинаетсяС) Тогда
            Возврат Ложь;
        КонецЕсли;

    КонецЕсли;

    // Проверка наличия подстроки
    Если Фильтр.Свойство("Подстрока") 
        И ЗначениеЗаполнено(Фильтр.Подстрока) Тогда

        Если СтрНайти(ИсходнаяСтрока, Фильтр.Подстрока) = 0 Тогда
            Возврат Ложь;
        КонецЕсли;

    КонецЕсли;

    // Проверка формата даты
    Если Фильтр.Свойство("ЭтоФорматДата") 
        И Фильтр.ЭтоФорматДата = Истина Тогда

        Если НЕ ПроверитьФорматДаты(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;

    КонецЕсли;

    // Проверка формата телефона
    Если Фильтр.Свойство("ЭтоФорматТелефон") 
        И Фильтр.ЭтоФорматТелефон = Истина Тогда

        Если НЕ ПроверитьФорматТелефона(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;

    КонецЕсли;

    // Проверка формата email
    Если Фильтр.Свойство("ЭтоФорматEmail") 
        И Фильтр.ЭтоФорматEmail = Истина Тогда

        Если НЕ ПроверитьФорматEmail(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;

    КонецЕсли;

    // Все проверки пройдены
    Возврат Истина;

КонецФункции

// Проверяет, содержит ли строка только кириллические символы и пробелы
//
// Параметры:
//   Строка - Строка - проверяемая строка
//
// Возвращаемое значение:
//   Булево - Истина, если строка содержит только кириллицу, Ложь - в противном случае
//
Функция СодержитТолькоКириллицу(Строка)

    Кириллица = "абвгдежзийклмнопрстуфхцчшщъыьэюяёАБВГДЕЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯЁ";

    Для Индекс = 1 По СтрДлина(Строка) Цикл
        Символ = Сред(Строка, Индекс, 1);

        Если Символ <> " " И СтрНайти(Кириллица, Символ) = 0 Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    Возврат Истина;

КонецФункции

// Проверяет, содержит ли строка только цифры
//
// Параметры:
//   Строка - Строка - проверяемая строка
//
// Возвращаемое значение:
//   Булево - Истина, если строка содержит только цифры, Ложь - в противном случае
//
Функция СодержитТолькоЦифры(Строка)

    Цифры = "0123456789";

    Для Индекс = 1 По СтрДлина(Строка) Цикл
        Символ = Сред(Строка, Индекс, 1);

        Если СтрНайти(Цифры, Символ) = 0 Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    Возврат Истина;

КонецФункции

// Проверяет формат даты дд.мм.гггг
//
// Параметры:
//   Строка - Строка - проверяемая строка
//
// Возвращаемое значение:
//   Булево - Истина, если строка соответствует формату даты, Ложь - в противном случае
//
Функция ПроверитьФорматДаты(Строка)

    // Проверяем общую структуру (dd.mm.yyyy)
    Если СтрДлина(Строка) <> 10 Тогда
        Возврат Ложь;
    КонецЕсли;

    Если Сред(Строка, 3, 1) <> "." 
        Или Сред(Строка, 6, 1) <> "." Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверяем, что день, месяц и год состоят из цифр
    День = Лев(Строка, 2);
    Месяц = Сред(Строка, 4, 2);
    Год = Прав(Строка, 4);

    Если НЕ СодержитТолькоЦифры(День) 
        ИЛИ НЕ СодержитТолькоЦифры(Месяц) 
        ИЛИ НЕ СодержитТолькоЦифры(Год) Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверяем корректность значений
    ЧислоДень = Число(День);
    ЧислоМесяц = Число(Месяц);
    ЧислоГод = Число(Год);

    Если ЧислоДень < 1 ИЛИ ЧислоДень > 31 Тогда
        Возврат Ложь;
    КонецЕсли;

    Если ЧислоМесяц < 1 ИЛИ ЧислоМесяц > 12 Тогда
        Возврат Ложь;
    КонецЕсли;

    Если ЧислоГод < 1 Тогда
        Возврат Ложь;
    КонецЕсли;

    Возврат Истина;

КонецФункции

// Проверяет формат телефона
// Допустимые форматы:
//   +7(8) XXX-XXX-XX-XX
//   +7(8)(XXX)XXXXXXX
//   +7(8)XXXXXXXXXX
//
// Параметры:
//   Строка - Строка - проверяемая строка
//
// Возвращаемое значение:
//   Булево - Истина, если строка соответствует одному из форматов телефона, Ложь - в противном случае
//
Функция ПроверитьФорматТелефона(Строка)

    // Удаляем все пробелы и дефисы для анализа
    НормализованнаяСтрока = СтрЗаменить(СтрЗаменить(Строка, " ", ""), "-", "");

    // Проверяем, что строка начинается с +7 или +8
    Если НЕ СтрНачинаетсяС(НормализованнаяСтрока, "+7") 
        И НЕ СтрНачинаетсяС(НормализованнаяСтрока, "+8") Тогда
        Возврат Ложь;
    КонецЕсли;

    // Удаляем префикс +7 или +8
    НомерБезПрефикса = Сред(НормализованнаяСтрока, 3);

    // Проверяем длину номера (должно быть 10 цифр)
    Если СтрДлина(НомерБезПрефикса) <> 10 Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверяем, что все оставшиеся символы - цифры
    Если НЕ СодержитТолькоЦифры(НомерБезПрефикса) Тогда
        Возврат Ложь;
    КонецЕсли;

    // Дополнительная проверка исходной строки на допустимые форматы
    // Формат 1: +7(8)XXXXXXXXXX
    Шаблон1 = "^\+[78]\d{10}$";

    // Формат 2: +7(8) XXX-XXX-XX-XX
    Шаблон2 = "^\+[78]\s?\d{3}\s?\d{3}\s?\d{2}\s?\d{2}$";

    // Формат 3: +7(8)(XXX)XXXXXXX
    Шаблон3 = "^\+[78]\s?\(\d{3}\)\d{7}$";

    // Проверяем, соответствует ли строка хотя бы одному из шаблонов
    Если СоответствуетШаблону(Строка, Шаблон1) 
        ИЛИ СоответствуетШаблону(Строка, Шаблон2) 
        ИЛИ СоответствуетШаблону(Строка, Шаблон3) Тогда
        Возврат Истина;
    КонецЕсли;

    Возврат Ложь;

КонецФункции

// Проверяет соответствие строки простому регулярному выражению
//
// Параметры:
//   Строка - Строка - проверяемая строка
//   Шаблон - Строка - шаблон регулярного выражения
//
// Возвращаемое значение:
//   Булево - Истина, если строка соответствует шаблону, Ложь - в противном случае
//
Функция СоответствуетШаблону(Строка, Шаблон)

    // Разбор простого шаблона
    // x - любой символ
    // \d - цифра
    // \s - пробел
    // {n} - повторение n раз
    // ^ - начало строки
    // $ - конец строки

    ШаблонБезЯкоря = СтрЗаменить(Шаблон, "^", "");
    ШаблонБезЯкоря = СтрЗаменить(ШаблонБезЯкоря, "$", "");

    ИндексСтроки = 1;
    ИндексШаблона = 1;

    Пока ИндексШаблона <= СтрДлина(ШаблонБезЯкоря) Цикл

        Если ИндексСтроки > СтрДлина(Строка) Тогда
            Возврат Ложь;
        КонецЕсли;

        СимволШаблона = Сред(ШаблонБезЯкоря, ИндексШаблона, 1);

        Если СимволШаблона = "\" Тогда
            // Экранированный символ
            ИндексШаблона = ИндексШаблона + 1;
            СпецСимвол = Сред(ШаблонБезЯкоря, ИндексШаблона, 1);

            Если СпецСимвол = "d" Тогда
                СимволСтроки = Сред(Строка, ИндексСтроки, 1);
                Если НЕ СодержитТолькоЦифры(СимволСтроки) Тогда
                    Возврат Ложь;
                КонецЕсли;
            ИначеЕсли СпецСимвол = "s" Тогда
                СимволСтроки = Сред(Строка, ИндексСтроки, 1);
                Если СимволСтроки <> " " Тогда
                    Возврат Ложь;
                КонецЕсли;
            КонецЕсли;

            ИндексСтроки = ИндексСтроки + 1;
            ИндексШаблона = ИндексШаблона + 1;

        ИначеЕсли СимволШаблона = "?" Тогда
            // ? - любой символ
            ИндексСтроки = ИндексСтроки + 1;
            ИндексШаблона = ИндексШаблона + 1;

        Иначе
            // Обычный символ
            Если Сред(Строка, ИндексСтроки, 1) <> СимволШаблона Тогда
                Возврат Ложь;
            КонецЕсли;

            ИндексСтроки = ИндексСтроки + 1;
            ИндексШаблона = ИндексШаблона + 1;

        КонецЕсли;

    КонецЦикла;

    Возврат ИндексСтроки > СтрДлина(Строка);

КонецФункции

// Проверяет формат email
//
// Параметры:
//   Строка - Строка - проверяемая строка
//
// Возвращаемое значение:
//   Булево - Истина, если строка соответствует формату email, Ложь - в противном случае
//
Функция ПроверитьФорматEmail(Строка)

    // Проверяем наличие символа @
    ПозицияСобаки = СтрНайти(Строка, "@");

    Если ПозицияСобаки = 0 Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверяем, что до и после @ есть символы
    Если ПозицияСобаки = 1 Тогда
        Возврат Ложь;
    КонецЕсли;

    Если ПозицияСобаки = СтрДлина(Строка) Тогда
        Возврат Ложь;
    КонецЕсли;

    // Получаем локальную часть и домен
    ЛокальнаяЧасть = Лев(Строка, ПозицияСобаки - 1);
    Домен = Сред(Строка, ПозицияСобаки + 1);

    // Проверяем локальную часть
    // Допустимые символы: буквы (латиница и кириллица), цифры, точка, дефис, подчёркивание
    ДопустимыеСимволыЛокальнойЧасти = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZабвгдежзийклмнопрстуфхцчшщъыьэюяёАБВГДЕЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯЁ0123456789.-_";

    Для Индекс = 1 По СтрДлина(ЛокальнаяЧасть) Цикл
        Символ = Сред(ЛокальнаяЧасть, Индекс, 1);

        Если СтрНайти(ДопустимыеСимволыЛокальнойЧасти, Символ) = 0 Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    // Проверяем, что локальная часть не начинается и не заканчивается точкой
    Если Лев(ЛокальнаяЧасть, 1) = "." Или Прав(ЛокальнаяЧасть, 1) = "." Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверяем домен
    // Допустимые символы: буквы (латиница и кириллица), цифры, точка, дефис
    ДопустимыеСимволыДомена = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZабвгдежзийклмнопрстуфхцчшщъыьэюяёАБВГДЕЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯЁ0123456789.-";

    Для Индекс = 1 По СтрДлина(Домен) Цикл
        Символ = Сред(Домен, Индекс, 1);

        Если СтрНайти(ДопустимыеСимволыДомена, Символ) = 0 Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    // Проверяем наличие точки в домене
    Если СтрНайти(Домен, ".") = 0 Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверяем, что домен не начинается и не заканчивается точкой или дефисом
    Если Лев(Домен, 1) = "." Или Прав(Домен, 1) = "." Тогда
        Возврат Ложь;
    КонецЕсли;

    Если Лев(Домен, 1) = "-" Или Прав(Домен, 1) = "-" Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверяем, что в домене есть только одна точка (упрощённо)
    ЧастиДомена = СтрРазделить(Домен, ".", Истина);

    Если ЧастиДомена.Количество() < 2 Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверяем, что каждая часть домена не пустая
    Для Каждого ЧастьДомена Из ЧастиДомена Цикл
        Если ПустаяСтрока(ЧастьДомена) Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    Возврат Истина;

КонецФункции

// Функция загружает расчетные счета из JSON
//
// Параметры:
//   СтрокаJSON - Строка - JSON строка с данными расчетных счетов
//
// Возвращаемое значение:
//   Число - Количество обработанных счетов
//
Функция ЗагрузитьРасчетныеСчетаКонтрагентовJSON(СтрокаJSON) Экспорт

    // 1) Преобразование JSON в массив структур
    Данные = ПрочитатьJSON(СтрокаJSON);

    // Если передан одиночный объект, преобразуем в массив
    Если ТипЗнч(Данные) = Тип("Структура") Тогда
        МассивДанных = Новый Массив;
        МассивДанных.Добавить(Данные);
    Иначе
        МассивДанных = Данные;
    КонецЕсли;

    КоличествоОбработанных = 0;

    // 2-4) Обработка каждого элемента
    Для Каждого Элемент Из МассивДанных Цикл

        // Получаем обязательные свойства
        БанкОписание = Элемент["bank_description"];
        КонтрагентКод = Элемент["counterparty_code"];
        НомерСчета = Элемент["number"];

        // Проверка обязательных полей
        Если Не ЗначениеЗаполнено(БанкОписание) 
            Или Не ЗначениеЗаполнено(КонтрагентКод) 
            Или Не ЗначениеЗаполнено(НомерСчета) Тогда
            Продолжить;
        КонецЕсли;

        // Поиск банка по наименованию
        БанкСсылка = НайтиБанкПоНаименованию(БанкОписание);

        // Поиск контрагента по коду
        КонтрагентСсылка = НайтиКонтрагентаПоКоду(КонтрагентКод);

        // Проверка уникальности: поиск существующего элемента
        Запрос = Новый Запрос;
        Запрос.Текст =
        "ВЫБРАТЬ
        |    РасчетныеСчетаКонтрагентов.Ссылка
        |ИЗ
        |    Справочник.РасчетныеСчетаКонтрагентов КАК РасчетныеСчетаКонтрагентов
        |ГДЕ
        |    РасчетныеСчетаКонтрагентов.Владелец = &Контрагент
        |    И РасчетныеСчетаКонтрагентов.Номер = &НомерСчета
        |    И РасчетныеСчетаКонтрагентов.ПометкаУдаления = ЛОЖЬ";
        |<вторая строка запроса>
        Запрос.УстановитьПараметр("Контрагент", КонтрагентСсылка);
        Запрос.УстановитьПараметр("НомерСчета", НомерСчета);

        Результат = Запрос.Выполнить();

        Если Не Результат.Пустой() Тогда
            // Элемент не уникален - пропускаем
            Продолжить;
        КонецЕсли;

        // Создание нового элемента справочника
        НовыйСчет = Справочники.РасчетныеСчетаКонтрагентов.СоздатьЭлемент();
        НовыйСчет.Номер = НомерСчета;
        НовыйСчет.Банк = БанкСсылка;
        НовыйСчет.Владелец = КонтрагентСсылка;

        // Запись элемента
        НовыйСчет.Записать();

        КоличествоОбработанных = КоличествоОбработанных + 1;

    КонецЦикла;

    Возврат КоличествоОбработанных;

КонецФункции

// Вспомогательная функция поиска банка
//
// Параметры:
//   НаименованиеБанка - Строка - Наименование банка
//
// Возвращаемое значение:
//   СправочникСсылка.Банки - Ссылка на банк
//
Функция НайтиБанкПоНаименованию(НаименованиеБанка)

    БанкСсылка = Справочники.Банки.НайтиПоНаименованию(НаименованиеБанка);

    Если Не ЗначениеЗаполнено(БанкСсылка) Тогда
        ВызватьИсключение "Банк с наименованием """ + НаименованиеБанка + """ не найден";
    КонецЕсли;

    // Проверка пометки удаления
    БанкОбъект = БанкСсылка.ПолучитьОбъект();
    Если БанкОбъект <> Неопределено И БанкОбъект.ПометкаУдаления Тогда
        ВызватьИсключение "Банк с наименованием """ + НаименованиеБанка + """ помечен на удаление";
    КонецЕсли;

    Возврат БанкСсылка;

КонецФункции

// Вспомогательная функция поиска контрагента
//
// Параметры:
//   КодКонтрагента - Строка - Код контрагента
//
// Возвращаемое значение:
//   СправочникСсылка.Контрагенты - Ссылка на контрагента
//
Функция НайтиКонтрагентаПоКоду(КодКонтрагента)

    КонтрагентСсылка = Справочники.Контрагенты.НайтиПоКоду(КодКонтрагента);

    Если Не ЗначениеЗаполнено(КонтрагентСсылка) Тогда
        ВызватьИсключение "Контрагент с кодом """ + КодКонтрагента + """ не найден";
    КонецЕсли;

    // Проверка пометки удаления
    КонтрагентОбъект = КонтрагентСсылка.ПолучитьОбъект();
    Если КонтрагентОбъект <> Неопределено И КонтрагентОбъект.ПометкаУдаления Тогда
        ВызватьИсключение "Контрагент с кодом """ + КодКонтрагента + """ помечен на удаление";
    КонецЕсли;

    Возврат КонтрагентСсылка;

КонецФункции

// ПроверкаКорректностиЗаполненияНоменклатуры
//
// Функция выполняет проверку корректности заполнения карточек номенклатуры
// в справочнике "Товары" и формирует таблицу с перечнем некорректно заполненных позиций.
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с некорректно заполненными позициями номенклатуры.
//                     Пустая таблица означает, что все карточки заполнены корректно.
//
Функция ПроверкаКорректностиЗаполненияНоменклатуры() Экспорт

    // Создаём запрос к справочнику Товары
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    Товары.Ссылка,
    |    Товары.Наименование,
    |    Товары.Штрихкод,
    |    Товары.Описание
    |ИЗ
    |    Справочник.Товары КАК Товары";

    // Выполняем запрос и выгружаем результат в таблицу значений
    РезультатЗапроса = Запрос.Выполнить().Выгрузить();

    // Создаём результирующую таблицу значений
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    Результат.Колонки.Добавить("Наименование", Новый ОписаниеТипов("Строка"));
    Результат.Колонки.Добавить("Штрихкод", Новый ОписаниеТипов("Строка"));
    Результат.Колонки.Добавить("Описание", Новый ОписаниеТипов("Строка"));
    Результат.Колонки.Добавить("КорректноЗаполнено", Новый ОписаниеТипов("Булево"));

    // Обрабатываем каждую строку выборки
    Для Каждого СтрокаТовара Из РезультатЗапроса Цикл

        // Проверяем заполненность обязательных реквизитов
        НаименованиеЗаполнено = НЕ ПустаяСтрока(СтрокаТовара.Наименование);
        ШтрихкодЗаполнен = ЗначениеЗаполнено(СтрокаТовара.Штрихкод);
        ОписаниеЗаполнено = НЕ ПустаяСтрока(СтрокаТовара.Описание);

        // Определяем корректность заполнения
        Если НЕ НаименованиеЗаполнено
            ИЛИ НЕ ШтрихкодЗаполнен
            ИЛИ НЕ ОписаниеЗаполнено Тогда

            // Добавляем строку с некорректными данными
            НоваяСтрока = Результат.Добавить();
            НоваяСтрока.Товар = СтрокаТовара.Ссылка;
            НоваяСтрока.Наименование = СтрокаТовара.Наименование;
            НоваяСтрока.Штрихкод = СтрокаТовара.Штрихкод;
            НоваяСтрока.Описание = СтрокаТовара.Описание;
            НоваяСтрока.КорректноЗаполнено = Ложь;

        КонецЕсли;

    КонецЦикла;

    // Сортируем результат по наименованию в порядке возрастания
    Результат.Сортировать("Наименование ВОЗР");

    Возврат Результат;

КонецФункции

Функция СформироватьОтчетВзаимосвязьПродажТоваровВариантТаблица(ДатаНачала, ДатаОкончания, СравниваемыйТовар) Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ВзаимосвязьПродажТоваров.Создать();

    // Получаем компоновщик настроек
    КомпоновщикНастроек = ОтчетОбъект.КомпоновщикНастроек;

    // Загружаем вариант "Основной" если он существует
    ОсновнойВариант = Неопределено;
    Для Каждого Вариант Из ОтчетОбъект.СхемаКомпоновкиДанных.ВариантыНастроек Цикл
        Если Вариант.Имя = "Основной" Тогда
            ОсновнойВариант = Вариант;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Если ОсновнойВариант <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ОсновнойВариант.Настройки);
    КонецЕсли;

    // Устанавливаем параметры отчета
    ПараметрыОтчета = КомпоновщикНастроек.Настройки.ПараметрыДанных;
    ПараметрыОтчета.УстановитьЗначениеПараметра("НачалоПериода", ДатаНачала);
    ПараметрыОтчета.УстановитьЗначениеПараметра("КонецПериода", ДатаОкончания);
    ПараметрыОтчета.УстановитьЗначениеПараметра("СравниваемыйТовар", СравниваемыйТовар);

    // Очищаем текущую структуру отчета
    КомпоновщикНастроек.Настройки.Структура.Очистить();

    // Создаем таблицу
    ТаблицаОтчета = КомпоновщикНастроек.Настройки.Структура.Добавить(Тип("ТаблицаКомпоновкиДанных"));

    // Настраиваем строки: Товар
    // Тип группировки = Элементы, Тип дополнения = БезДополнения
    СтрокаТовар = ТаблицаОтчета.Строки.Добавить();
    ГруппировкаСтроки = СтрокаТовар.ПараметрыГруппировки.Элементы.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаСтроки.Поле = Новый ПолеКомпоновкиДанных("Товар");
    ГруппировкаСтроки.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    СтрокаТовар.ПараметрыВывода.ТипДополненияПериода = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Настраиваем столбцы: Период
    // Тип группировки = Элементы, Тип дополнения = БезДополнения
    СтолбецПериод = ТаблицаОтчета.Столбцы.Добавить();
    ГруппировкаСтолбца = СтолбецПериод.ПараметрыГруппировки.Элементы.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаСтолбца.Поле = Новый ПолеКомпоновкиДанных("Период");
    ГруппировкаСтолбца.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    СтолбецПериод.ПараметрыВывода.ТипДополненияПериода = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Устанавливаем параметры вывода
    ПараметрыВывода = КомпоновщикНастроек.Настройки.ПараметрыВывода;
    ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    ПараметрыВывода.ВыводитьОтбор = Ложь;
    ПараметрыВывода.ВертикальноеРасположениеОбщихИтогов = Ложь;

    // Формируем отчет
    Результат = Новый ТабличныйДокумент;

    Расширение = Новый РасширениеКомпоновкиДанныхДляОтображенияОтчета(ОтчетОбъект);

    // Получаем макет компоновки
    МакетКомпоновки = ОтчетОбъект.ПолучитьМакетКомпоновки(
        КомпоновщикНастроек.Настройки,
        ОтчетОбъект.СхемаКомпоновкиДанных
    );

    // Инициализируем расширение
    Расширение.Инициализировать(МакетКомпоновки);

    // Устанавливаем параметры
    Расширение.УстановитьПараметр("НачалоПериода", ДатаНачала);
    Расширение.УстановитьПараметр("КонецПериода", ДатаОкончания);
    Расширение.УстановитьПараметр("СравниваемыйТовар", СравниваемыйТовар);

    // Выполняем компоновку
    Расширение.Выполнить(Результат);

    Возврат Результат;

КонецФункции

Функция ВыгрузитьЗадолженностьКонтрагентовВJSON() Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   ВзаиморасчетыОстатки.Валюта.Наименование КАК Валюта,
    |   ВзаиморасчетыОстатки.Контрагент.Наименование КАК Контрагент,
    |   ВЫРАЗИТЬ(ВзаиморасчетыОстатки.СуммаОстаток КАК ЧИСЛО(10, 2)) КАК Сумма
    |ИЗ
    |   РегистрНакопления.Взаиморасчеты.Остатки(&МоментВремени, СуммаОстаток < 0) КАК ВзаиморасчетыОстатки
    |
    |УПОРЯДОЧИТЬ ПО
    |   Валюта,
    |   Контрагент";

    Запрос.УстановитьПараметр("МоментВремени", КонецДня(ТекущаяДата()));

    РезультатЗапроса = Запрос.Выполнить();

    Если РезультатЗапроса.Пустой() Тогда
        МассивЗадолженностей = Новый Массив;
    Иначе
        МассивЗадолженностей = Новый Массив;

        ВыборкаПоВалютам = РезультатЗапроса.Выбрать(ОбходРезультатаЗапроса.ПоГруппировкам);

        Пока ВыборкаПоВалютам.Следующий() Цикл
            СтруктураВалюты = Новый Структура("Валюта, Контрагенты");
            СтруктураВалюты.Валюта = ВыборкаПоВалютам.Валюта;

            МассивКонтрагентов = Новый Массив;

            ВыборкаПоКонтрагентам = ВыборкаПоВалютам.Выбрать();
            Пока ВыборкаПоКонтрагентам.Следующий() Цикл
                СтруктураКонтрагента = Новый Структура("Контрагент, Сумма");
                СтруктураКонтрагента.Контрагент = ВыборкаПоКонтрагентам.Контрагент;
                СтруктураКонтрагента.Сумма = ВыборкаПоКонтрагентам.Сумма;

                МассивКонтрагентов.Добавить(СтруктураКонтрагента);
            КонецЦикла;

            СтруктураВалюты.Контрагенты = МассивКонтрагентов;
            МассивЗадолженностей.Добавить(СтруктураВалюты);
        КонецЦикла;
    КонецЕсли;

    ЗаписьJSON = Новый ЗаписьJSON;
    ПараметрыЗаписиJSON = Новый ПараметрыЗаписиJSON(ПереносСтрокJSON.Авто, Символы.Таб);

    ИмяФайла = ПолучитьИмяВременногоФайла("json");
    ЗаписьJSON.ОткрытьФайл(ИмяФайла, , Ложь);

    СериализаторXDTO.ЗаписатьJSON(ЗаписьJSON, МассивЗадолженностей, НазначениеТипаXML.Неявное);

    ЗаписьJSON.Закрыть();

    Возврат ИмяФайла;

КонецФункции

// Функция формирует отчет по оборачиваемости товаров
//
// Параметры:
//   ДатаНач - Дата - Начало периода анализа
//   ДатаКон - Дата - Конец периода анализа
//
// Возвращаемое значение:
//   ТаблицаЗначений - Таблица с показателями оборачиваемости товаров
//
Функция СформироватьОтчетОборачиваемости(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка периода по умолчанию (последние 30 дней)
    ТекущаяДата = ТекущаяДата();

    Если ДатаКон = Неопределено Или ДатаКон = '00010101' Тогда
        ДатаКон = ТекущаяДата;
    КонецЕсли;

    Если ДатаНач = Неопределено Или ДатаНач = '00010101' Тогда
        ДатаНач = ТекущаяДата - 30 * 24 * 60 * 60; // 30 дней назад
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода";
    КонецЕсли;

    // Расчет количества дней в периоде
    КоличествоДнейВПериоде = (ДатаКон - ДатаНач) / (24 * 60 * 60) + 1;

    // Создание запроса
    Запрос = Новый Запрос;

    // Формирование текста запроса
    Запрос.Текст =
    "ВЫБРАТЬ
    |   ПродажиОбороты.Товар,
    |   СУММА(ПродажиОбороты.КоличествоОборот) КАК КоличествоПродаж
    |ПОМЕСТИТЬ ВременнаяТаблицаПродаж
    |ИЗ
    |   РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, Авто, ) КАК ПродажиОбороты
    |
    |СГРУППИРОВАТЬ ПО
    |   ПродажиОбороты.Товар
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |   ТоварныеЗапасыОстатки.Товар,
    |   СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) КАК Остаток
    |ПОМЕСТИТЬ ВременнаяТаблицаОстатков
    |ИЗ
    |   РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаКон, , ) КАК ТоварныеЗапасыОстатки
    |
    |СГРУППИРОВАТЬ ПО
    |   ТоварныеЗапасыОстатки.Товар
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |   ВременнаяТаблицаОстатков.Товар,
    |   ВременнаяТаблицаОстатков.Остаток,
    |   ЕСТЬNULL(ВременнаяТаблицаПродаж.КоличествоПродаж, 0) КАК КоличествоПродаж,
    |   ВЫБОР
    |       КОГДА &КоличествоДнейВПериоде > 0
    |           ТОГДА ЕСТЬNULL(ВременнаяТаблицаПродаж.КоличествоПродаж, 0) / &КоличествоДнейВПериоде
    |       ИНАЧЕ 0
    |   КОНЕЦ КАК СреднедневныеПродажи,
    |   ВЫБОР
    |       КОГДА ЕСТЬNULL(ВременнаяТаблицаПродаж.КоличествоПродаж, 0) = 0
    |           ТОГДА 9999 // Условно высокая величина для товаров без продаж
    |       КОГДА ВременнаяТаблицаОстатков.Остаток = 0
    |           ТОГДА 0
    |       КОГДА (ЕСТЬNULL(ВременнаяТаблицаПродаж.КоличествоПродаж, 0) / &КоличествоДнейВПериоде) = 0
    |           ТОГДА 9999 // Условно высокая величина при отсутствии среднедневных продаж
    |       ИНАЧЕ
    |           ВременнаяТаблицаОстатков.Остаток / (ЕСТЬNULL(ВременнаяТаблицаПродаж.КоличествоПродаж, 0) / &КоличествоДнейВПериоде)
    |   КОНЕЦ КАК ОборачиваемостьВДнях
    |ИЗ
    |   ВременнаяТаблицаОстатков КАК ВременнаяТаблицаОстатков
    |       ЛЕВОЕ СОЕДИНЕНИЕ ВременнаяТаблицаПродаж КАК ВременнаяТаблицаПродаж
    |       ПО ВременнаяТаблицаОстатков.Товар = ВременнаяТаблицаПродаж.Товар
    |
    |УПОРЯДОЧИТЬ ПО
    |   ОборачиваемостьВДнях УБЫВ
    |";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Запрос.УстановитьПараметр("КоличествоДнейВПериоде", КоличествоДнейВПериоде);

    // Выполнение запроса
    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений результата
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Товар");
    ТаблицаРезультат.Колонки.Добавить("Остаток", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    ТаблицаРезультат.Колонки.Добавить("КоличествоПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    ТаблицаРезультат.Колонки.Добавить("СреднедневныеПродажи", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 4)));
    ТаблицаРезультат.Колонки.Добавить("ОборачиваемостьВДнях", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Обход результата запроса и заполнение таблицы
    Если НЕ РезультатЗапроса.Пустой() Тогда
        Выборка = РезультатЗапроса.Выбрать();

        Пока Выборка.Следующий() Цикл
            НоваяСтрока = ТаблицаРезультат.Добавить();
            НоваяСтрока.Товар = Выборка.Товар;
            НоваяСтрока.Остаток = Выборка.Остаток;
            НоваяСтрока.КоличествоПродаж = Выборка.КоличествоПродаж;
            НоваяСтрока.СреднедневныеПродажи = Выборка.СреднедневныеПродажи;
            НоваяСтрока.ОборачиваемостьВДнях = Выборка.ОборачиваемостьВДнях;
        КонецЦикла;
    КонецЕсли;

    // Возврат результата
    Возврат ТаблицаРезультат;

КонецФункции

// Функция формирует отчет "ДинамикаПродаж" с отбором по товару
//
// Параметры:
//   ДатаНачала - Дата - Начало периода отчета
//   ДатаОкончания - Дата - Окончание периода отчета
//   Товар - СправочникСсылка.Товары - Товар для отбора
//
// Возвращаемое значение:
//   ТабличныйДокумент - Результат формирования отчета
//
Функция СформироватьОтчетДинамикаПродажТовара(ДатаНачала, ДатаОкончания, Товар) Экспорт

    // Создаем табличный документ для результата
    Результат = Новый ТабличныйДокумент;

    // Получаем объект отчета из менеджера
    ОтчетОбъект = Отчеты.ДинамикаПродаж.Создать();

    // Получаем схему компоновки данных из макета отчета
    СхемаКомпоновкиДанных = Отчеты.ДинамикаПродаж.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Получаем настройки по умолчанию из варианта отчета
    ВариантНастроек = СхемаКомпоновкиДанных.ВариантыНастроек.Найти("ПродажиТоваровПоПокупателям");

    // Создаем компоновщик настроек с预先 загруженной схемой
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));

    // Если вариант найден, загружаем его настройки
    Если ВариантНастроек <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ВариантНастроек.Настройки);
    Иначе
        КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.НастройкиПоУмолчанию);
    КонецЕсли;

    // Получаем пользовательские настройки для редактирования
    ПользовательскиеНастройки = КомпоновщикНастроек.ПользовательскиеНастройки;

    // === Устанавливаем параметры периода ===

    // Ищем параметр "Период" в пользовательских настройках
    ПараметрПериод = КомпоновщикНастроек.Настройки.ПараметрыДанных.Элементы.Найти("Период");

    Если ПараметрПериод <> Неопределено Тогда

        // Устанавливаем значение параметра "Период"
        ТекущийПараметр = ПользовательскиеНастройки.Элементы.Найти(ПараметрПериод.ИдентификаторПользовательскойНастройки);

        Если ТекущийПараметр <> Неопределено Тогда

            // Создаем стандартный период
            СтандартныйПериод = Новый СтандартныйПериод;
            СтандартныйПериод.ДатаНачала = ДатаНачала;
            СтандартныйПериод.ДатаОкончания = ДатаОкончания;

            ТекущийПараметр.Значение = СтандартныйПериод;
            ТекущийПараметр.Использование = Истина;

        КонецЕсли;

    КонецЕсли;

    // Альтернативно: устанавливаем параметры ДатаНачала и ДатаОкончания напрямую
    ПараметрДатаНачала = КомпоновщикНастроек.Настройки.ПараметрыДанных.Элементы.Найти("ДатаНачала");
    ПараметрДатаОкончания = КомпоновщикНастроек.Настройки.ПараметрыДанных.Элементы.Найти("ДатаОкончания");

    Если ПараметрДатаНачала <> Неопределено Тогда
        ТекущийПараметр = ПользовательскиеНастройки.Элементы.Найти(ПараметрДатаНачала.ИдентификаторПользовательскойНастройки);
        Если ТекущийПараметр <> Неопределено Тогда
            ТекущийПараметр.Значение = ДатаНачала;
            ТекущийПараметр.Использование = Истина;
        КонецЕсли;
    КонецЕсли;

    Если ПараметрДатаОкончания <> Неопределено Тогда
        ТекущийПараметр = ПользовательскиеНастройки.Элементы.Найти(ПараметрДатаОкончания.ИдентификаторПользовательскойНастройки);
        Если ТекущийПараметр <> Неопределено Тогда
            ТекущийПараметр.Значение = КонецДня(ДатаОкончания);
            ТекущийПараметр.Использование = Истина;
        КонецЕсли;
    КонецЕсли;

    // === Устанавливаем отбор по товару ===

    // Получаем коллекцию отборов
    Отбор = КомпоновщикНастроек.Настройки.Отбор;

    // Ищем существующий элемент отбора или создаем новый
    ЭлементОтбораТовар = Неопределено;

    Для Каждого ЭлементОтбора Из Отбор.Элементы Цикл
        Если ТипЗнч(ЭлементОтбора) = Тип("ЭлементОтбораКомпоновкиДанных") Тогда
            Если Строка(ЭлементОтбора.ЛевоеЗначение) = "Товар" 
                ИЛИ Строка(ЭлементОтбора.ЛевоеЗначение) = "Номенклатура" 
                ИЛИ Строка(ЭлементОтбора.ЛевоеЗначение) = "Товары" Тогда
                ЭлементОтбораТовар = ЭлементОтбора;
                Прервать;
            КонецЕсли;
        КонецЕсли;
    КонецЦикла;

    // Если элемент отбора не найден, создаем новый
    Если ЭлементОтбораТовар = Неопределено Тогда
        ЭлементОтбораТовар = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    КонецЕсли;

    // Устанавливаем параметры отбора
    ЭлементОтбораТовар.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Товар");
    ЭлементОтбораТовар.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбораТовар.ПравоеЗначение = Товар;
    ЭлементОтбораТовар.Использование = Истина;

    // === Настраиваем параметры вывода ===

    // Получаем настройки вывода
    ПараметрыВывода = КомпоновщикНастроек.Настройки.ПараметрыВывода;

    // Устанавливаем параметр "Выводить параметры данных"
    ЭлементВыводПараметров = ПараметрыВывода.Элементы.Найти("ВыводитьПараметрыДанных");
    Если ЭлементВыводПараметров <> Неопределено Тогда
        ЭлементВыводПараметров.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    // Устанавливаем параметр "Выводить отбор"
    ЭлементВыводОтбора = ПараметрыВывода.Элементы.Найти("ВыводитьОтбор");
    Если ЭлементВыводОтбора <> Неопределено Тогда
        ЭлементВыводОтбора.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    // === Формируем отчет ===

    // Создаем процессор компоновки
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;

    // Подготавливаем макет с учетом настроек
    Попытка
        МакетКомпоновки = КомпоновщикМакета.Выполнить(
            СхемаКомпоновкиДанных,
            КомпоновщикНастроек.ПолучитьНастройки(),
            ,
            ,
            Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));
    Исключение
        // Если не удалось сформировать с типом коллекции, пробуем стандартный вариант
        МакетКомпоновки = КомпоновщикМакета.Выполнить(
            СхемаКомпоновкиДанных,
            КомпоновщикНастроек.ПолучитьНастройки());
    КонецПопытки;

    // Создаем процессор результата
    ПроцессорКомпоновкиДанных = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновкиДанных.Инициализировать(МакетКомпоновки);

    // Создаем процессор вывода
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Результат);

    // Выводим результат
    ПроцессорВывода.Вывести(ПроцессорКомпоновкиДанных, Истина);

    // Возвращаем результат
    Возврат Результат;

КонецФункции

// Функция ПолучитьОстаткиПоНоменклатуреПоВсемСкладам
// Возвращает таблицу остатков, сгруппированную по номенклатуре
//
// Параметры:
//  ТаблицаТовары - ТаблицаЗначений - исходная таблица с колонками:
//               Номенклатура (Строка), Склад (Строка), Количество (Число), Сумма (Число)
//
// Возвращаемое значение:
//  ТаблицаЗначений - сгруппированная таблица с колонками:
//               Номенклатура, Количество, Сумма
//
Функция ПолучитьОстаткиПоНоменклатуреПоВсемСкладам(ТаблицаТовары) Экспорт

    // Создаём запрос для выборки данных
    Запрос = Новый Запрос;

    // Устанавливаем параметр запроса - передаём входную таблицу значений
    // Это не изменяет оригинальную таблицу
    Запрос.УстановитьПараметр("ТаблицаТовары", ТаблицаТовары);

    // Формируем текст запроса с группировкой по номенклатуре
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ИсходныеДанные.Номенклатура,
    |    СУММА(ИсходныеДанные.Количество) КАК Количество,
    |    СУММА(ИсходныеДанные.Сумма) КАК Сумма
    |ИЗ
    |    &ТаблицаТовары КАК ИсходныеДанные
    |СГРУППИРОВАТЬ ПО
    |    ИсходныеДанные.Номенклатура
    |УПОРЯДОЧИТЬ ПО
    |    Номенклатура ВОЗР";

    // Выполняем запрос и возвращаем результат
    // Метод Выгрузить() создаёт новую таблицу значений
    Возврат Запрос.Выполнить().Выгрузить();

КонецФункции

// Функция находит максимальное значение в указанной колонке таблицы.
// Не изменяет входную таблицу.
//
// Параметры:
//   Таблица - ТаблицаЗначений - Таблица, в которой производится поиск
//   Колонка - Строка - Имя колонки для поиска максимального значения
//
// Возвращаемое значение:
//   Произвольный - Максимальное значение в колонке или Неопределено
//                   если таблица пустая
//
Функция НайтиМаксимальноеЗначениеВКолонке(Таблица, Колонка) Экспорт

    // Проверка входных параметров
    Если Таблица = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    Если Таблица.Количество() = 0 Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Проверка существования колонки
    НайденнаяКолонка = Таблица.Колонки.Найти(Колонка);
    Если НайденнаяКолонка = Неопределено Тогда
        ВызватьИсключение "Колонка """ + Колонка + """ не найдена в таблице";
    КонецЕсли;

    // Используем запрос для работы с коллекцией
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    МАКСИМУМ(Таблица." + Колонка + ") КАК Максимум
    |ИЗ
    |    &Таблица КАК Таблица";

    Запрос.УстановитьПараметр("Таблица", Таблица);

    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    Если Выборка.Следующий() Тогда
        Возврат Выборка.Максимум;
    Иначе
        Возврат Неопределено;
    КонецЕсли;

КонецФункции

// Функция НайтиДублиТоваров
// Возвращает таблицу значений с найденными дублями товаров по артикулу
//
// Параметры:
//   Товар - СправочникСсылка.Товары - элемент, для которого необходимо найти дубли
//
// Возвращаемое значение:
//   ТаблицаЗначений с колонками:
//     * Товар    - СправочникСсылка.Товары - ссылка на дублирующий товар
//     * Артикул - Строка - артикул товара
//
Функция НайтиДублиТоваров(Товар) Экспорт

    // Создаем запрос для поиска дублей
    Запрос = Новый Запрос;

    // Формируем текст запроса
    // Ищем все товары с таким же артикулом, кроме текущего
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товары.Ссылка КАК Товар,
    |    Товары.Артикул КАК Артикул
    |ИЗ
    |    Справочник.Товары КАК Товары
    |ГДЕ
    |    Товары.Артикул = &Артикул
    |    И Товары.Ссылка <> &ТекущийТовар
    |    И Товары.Ссылка <> ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка)
    |УПОРЯДОЧИТЬ ПО
    |    Товары.Наименование";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("Артикул", Товар.Артикул);
    Запрос.УстановитьПараметр("ТекущийТовар", Товар);

    // Выполняем запрос и получаем результат
    РезультатЗапроса = Запрос.Выполнить();

    // Если дубли не найдены, возвращаем пустую таблицу
    Если РезультатЗапроса.Пустой() Тогда
        Возврат Новый ТаблицаЗначений;
    КонецЕсли;

    // Выгружаем результат в таблицу значений
    ТаблицаДублей = РезультатЗапроса.Выгрузить();

    // Возвращаем таблицу с дублями
    Возврат ТаблицаДублей;

КонецФункции

// Функция суммирует значения указанной колонки таблицы
// 
// Параметры:
//   ТаблицаДанных - ТаблицаЗначений, ТабличнаяЧасть - источник данных
//   ИмяКолонки    - Строка - имя колонки для суммирования
// 
// Возвращаемое значение:
//   Число - итоговая сумма значений колонки
//
Функция РассчитатьИтогПоКолонке(ТаблицаДанных, ИмяКолонки) Экспорт

    // Проверка обязательных параметров
    Если ТаблицаДанных = Неопределено Тогда
        Возврат 0;
    КонецЕсли;

    Если Не ЗначениеЗаполнено(ИмяКолонки) Тогда
        Возврат 0;
    КонецЕсли;

    // Проверка наличия колонки в таблице
    Если ТаблицаДанных.Колонки.Найти(ИмяКолонки) = Неопределено Тогда
        ВызватьИсключение "Колонка """ + ИмяКолонки + """ не найдена в таблице данных";
    КонецЕсли;

    Итог = 0;

    // Перебор коллекции строк таблицы
    Для каждого СтрокаТаблицы Из ТаблицаДанных Цикл

        Значение = СтрокаТаблицы[ИмяКолонки];

        // Суммируем только числовые значения
        Если ТипЗнч(Значение) = Тип("Число") Тогда
            Итог = Итог + Значение;
        КонецЕсли;

    КонецЦикла;

    Возврат Итог;

КонецФункции

// Функция выполняет поиск контрагентов по части наименования
// Параметры:
//   СтрокаПоиска - Строка - Часть наименования для поиска
// Возвращаемое значение:
//   ТаблицаЗначений - колонки: Ссылка, Наименование
//
Функция ПолучитьКонтрагентовПоЧастиНаименования(СтрокаПоиска) Экспорт

    // Если строка поиска пустая, возвращаем пустую таблицу значений
    Если ПустаяСтрока(СтрокаПоиска) Тогда
        Возврат Новый ТаблицаЗначений;
    КонецЕсли;

    Запрос = Новый Запрос;

    // Формируем текст запроса с использованием ПОДОБНО
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Контрагенты.Ссылка,
    |    Контрагенты.Наименование
    |ИЗ
    |    Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |    Контрагенты.Наименование ПОДОБНО &СтрокаПоиска
    |    И НЕ Контрагенты.ПометкаУдаления
    |УПОРЯДОЧИТЬ ПО
    |    Контрагенты.Наименование";

    // Формируем параметр для поиска:
    // 1. Экранируем служебные символы шаблона (% и _), чтобы они искались как литералы
    // 2. Добавляем % в начале и конце для поиска подстроки в любом месте наименования
    СтрокаПоискаПараметр = "%"
        + СтрЗаменить(СтрЗаменить(СтрокаПоиска, "%", "\%"), "_", "\_")
        + "%";

    Запрос.УстановитьПараметр("СтрокаПоиска", СтрокаПоискаПараметр);

    РезультатЗапроса = Запрос.Выполнить();

    // Возвращаем таблицу значений из результата запроса
    Возврат РезультатЗапроса.Выгрузить();

КонецФункции

// Функция получает обороты по регистру Продажи для указанного покупателя
//
// Параметры:
//  Покупатель      - СправочникСсылка.Контрагенты - контрагент-покупатель
//  ДатаНачала      - Дата - начало периода выборки
//  ДатаОкончания   - Дата - конец периода выборки
//
// Возвращаемое значение:
//  Структура - содержит ключи:
//              КоличествоОборот - число (оборот количества)
//              СуммаОборот      - число (оборот суммы)
//
Функция ПолучитьОборотыПоПокупателю(Покупатель, ДатаНачала, ДатаОкончания) Экспорт

    // Создаём запрос для получения данных из регистра накопления
    Запрос = Новый Запрос;

    // Формируем текст запроса к виртуальной таблице оборотов регистра "Продажи"
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.КоличествоОборот,
    |    ПродажиОбороты.СуммаОборот
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНачала, &ДатаОкончания, , Покупатель = &Покупатель) КАК ПродажиОбороты";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("Покупатель", Покупатель);
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

    // Выполняем запрос и получаем результат
    РезультатЗапроса = Запрос.Выполнить();

    // Инициализируем структуру с результатами (по умолчанию - нулевые значения)
    СтруктураОборотов = Новый Структура("КоличествоОборот, СуммаОборот", 0, 0);

    // Если данные найдены, заполняем структуру
    Если НЕ РезультатЗапроса.Пустой() Тогда
        Выборка = РезультатЗапроса.Выбрать();
        Выборка.Следующий();

        СтруктураОборотов.КоличествоОборот = Выборка.КоличествоОборот;
        СтруктураОборотов.СуммаОборот = Выборка.СуммаОборот;
    КонецЕсли;

    // Возвращаем структуру с оборотами
    Возврат СтруктураОборотов;

КонецФункции

// Функция находит минимальное значение в указанной колонке таблицы значений
//
// Параметры:
//   Таблица - ТаблицаЗначений - Таблица, в которой необходимо найти минимум
//   Колонка - Строка - Имя колонки, в которой производится поиск
//
// Возвращаемое значение:
//   Число - Минимальное значение в колонке, или 0 если таблица пустая
//
// Исключения:
//   Выбрасывает исключение, если колонка не найдена в таблице
//
Функция НайтиМинимальноеЗначениеВКолонке(Таблица, Колонка) Экспорт

    // 1) Проверка наличия колонки в таблице
    НайденнаяКолонка = Таблица.Колонки.Найти(Колонка);
    Если НайденнаяКолонка = Неопределено Тогда
        ВызватьИсключение "Колонка """ + Колонка + """ не найдена в таблице.";
    КонецЕсли;

    // 4) Если таблица пустая — вернуть 0
    Если Таблица.Количество() = 0 Тогда
        Возврат 0;
    КонецЕсли;

    // 2) Определение минимального значения перебором коллекции строк
    МинимальноеЗначение = Неопределено;

    Для Каждого СтрокаТаблицы Из Таблица Цикл

        ТекущееЗначение = СтрокаТаблицы[Колонка];

        // Пропускаем NULL значения
        Если ТекущееЗначение = Неопределено Тогда
            Продолжить;
        КонецЕсли;

        Если МинимальноеЗначение = Неопределено
            ИЛИ ТекущееЗначение < МинимальноеЗначение Тогда
            МинимальноеЗначение = ТекущееЗначение;
        КонецЕсли;

    КонецЦикла;

    // 3) Вернуть найденное значение (или 0, если все значения были NULL)
    Возврат ?(МинимальноеЗначение = Неопределено, 0, МинимальноеЗначение);

КонецФункции

// Функция выполняет поиск элемента указанного справочника по значению реквизита
//
// Параметры:
//   ИмяСправочника      - Строка - Имя справочника (например, "Номенклатура")
//   ИмяРеквизита        - Строка - Имя реквизита для поиска (например, "Артикул")
//   ЗначениеРеквизита  - Произвольный - Значение для поиска
//
// Возвращаемое значение:
//   Неопределено - элемент не найден
//   СправочникСсылка.* - найден один элемент
//   Массив - найдено несколько элементов (массив ссылок)
//
Функция НайтиЭлементПоРеквизиту(ИмяСправочника, ИмяРеквизита, ЗначениеРеквизита) Экспорт

    // Формируем текст запроса динамически
    // Используем параметризованный запрос для безопасности
    ТекстЗапроса = 
    "ВЫБРАТЬ
    |    Справочник.Ссылка
    |ИЗ
    |    Справочник." + ИмяСправочника + " КАК Справочник
    |ГДЕ
    |    Справочник." + ИмяРеквизита + " = &ЗначениеРеквизита";

    Запрос = Новый Запрос;
    Запрос.Текст = ТекстЗапроса;
    Запрос.УстановитьПараметр("ЗначениеРеквизита", ЗначениеРеквизита);

    РезультатЗапроса = Запрос.Выполнить();

    // Проверяем, есть ли записи в результате
    Если РезультатЗапроса.Пустой() Тогда
        Возврат Неопределено;
    КонецЕсли;

    Выборка = РезультатЗапроса.Выбрать();

    // Если найден только один элемент - возвращаем ссылку
    Если Выборка.Количество() = 1 Тогда
        Выборка.Следующий();
        Возврат Выборка.Ссылка;
    КонецЕсли;

    // Если найдено несколько элементов - формируем массив ссылок
    МассивСсылок = Новый Массив;

    Пока Выборка.Следующий() Цикл
        МассивСсылок.Добавить(Выборка.Ссылка);
    КонецЦикла;

    Возврат МассивСсылок;

КонецФункции

Функция ПодготовитьМассивСтруктурДляИнтеграции(Таблица) Экспорт

    МассивСтруктур = Новый Массив;

    Для Каждого СтрокаТаблицы Из Таблица Цикл
        СтруктураСтроки = Новый Структура;
        СтруктураСтроки.Вставить("Товар",     СтрокаТаблицы.Товар);
        СтруктураСтроки.Вставить("Количество", СтрокаТаблицы.Количество);
        СтруктураСтроки.Вставить("Цена",       СтрокаТаблицы.Цена);
        СтруктураСтроки.Вставить("Сумма",      СтрокаТаблицы.Сумма);

        МассивСтруктур.Добавить(СтруктураСтроки);
    КонецЦикла;

    Возврат МассивСтруктур;

КонецФункции

// Функция добавляет строку в табличную часть документа и заполняет её данными из структуры
// Параметры:
//   ДокументОбъект - ДокументОбъект - объект документа (тип ДокументОбъект.Заказ)
//   СтруктураСтроки - Структура - структура с данными для заполнения строки ТЧ
// Возвращаемое значение:
//   Число - номер добавленной строки в табличной части
//
Функция ДобавитьСтрокуВТабличнуюЧастьДокумента(ДокументОбъект, СтруктураСтроки) Экспорт

    // Добавляем новую строку в табличную часть "Товары"
    НоваяСтрока = ДокументОбъект.Товары.Добавить();

    // Получаем номер добавленной строки
    НомерСтроки = ДокументОбъект.Товары.Индекс(НоваяСтрока) + 1;

    // Заполняем колонки строки из структуры
    // Перебираем все ключи структуры
    Для Каждого КлючИЗначение Из СтруктураСтроки Цикл

        ИмяКолонки = КлючИЗначение.Ключ;
        Значение = КлючИЗначение.Значение;

        // Проверяем, существует ли колонка с таким именем в табличной части
        // Если колонка существует - заполняем её значением
        // Если колонки нет - пропускаем (как указано в требованиях)

        Попытка
            // Проверяем наличие колонки в коллекции колонок табличной части
            Если НоваяСтрока.Владелец().Колонки.Найти(ИмяКолонки) <> Неопределено Тогда
                НоваяСтрока[ИмяКолонки] = Значение;
            КонецЕсли;
        Исключение
            // Игнорируем ошибки - просто не заполняем колонку
        КонецПопытки;

    КонецЦикла;

    Возврат НомерСтроки;

КонецФункции

// Функция получает все цены товаров на указанную дату
//
// Параметры:
//   Номенклатура - СправочникСсылка.Товары - ссылка на товар
//   Дата - Дата - дата, на которую получаем цены
//
// Возвращаемое значение:
//   ТаблицаЗначений с колонками:
//     - ВидЦен (СправочникСсылка.ВидыЦен)
//     - Цена (Число)
//
Функция ПолучитьВсеЦеныТоваровНаДату(Номенклатура, Дата) Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ЦеныТоваровСрезПоследних.ВидЦен КАК ВидЦен,
    |    ЦеныТоваровСрезПоследних.Цена КАК Цена
    |ИЗ
    |    РегистрСведений.ЦеныТоваров.СрезПоследних(
    |            &Дата,
    |            Товар = &Товар) КАК ЦеныТоваровСрезПоследних";

    Запрос.УстановитьПараметр("Товар", Номенклатура);
    Запрос.УстановитьПараметр("Дата", Дата);

    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаЦен = РезультатЗапроса.Выгрузить();

    Возврат ТаблицаЦен;

КонецФункции

// Функция копирует параметр схемы компоновки данных
//
// Параметры:
//  СхемаКомпоновкиДанных - СхемаКомпоновкиДанных - Схема отчета
//  Приемник - Строка - Имя параметра, в который необходимо скопировать настройки
//  Источник - Строка - Имя параметра, из которого настройки копируются
//  ЗначениеПриемника - Произвольный - Значение параметра приемника
//
// Возвращаемое значение:
//  ПараметрКомпоновкиДанных, Неопределено - Созданный или измененный параметр
//
Функция СкопироватьПараметрСхемыКомпоновкиДанных(
    СхемаКомпоновкиДанных, 
    Приемник, 
    Источник, 
    ЗначениеПриемника) Экспорт

    Параметры = СхемаКомпоновкиДанных.Параметры;

    // Ищем параметр источник
    ПараметрИсточник = Неопределено;
    Для Каждого Параметр Из Параметры Цикл
        Если Параметр.Имя = Источник Тогда
            ПараметрИсточник = Параметр;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Если ПараметрИсточник = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Ищем параметр приемник
    ПараметрПриемник = Неопределено;
    Для Каждого Параметр Из Параметры Цикл
        Если Параметр.Имя = Приемник Тогда
            ПараметрПриемник = Параметр;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    // Если приемник не найден - создаем новый параметр
    Если ПараметрПриемник = Неопределено Тогда
        ПараметрПриемник = Параметры.Добавить();
    КонецЕсли;

    // Копируем свойства с источника на приемник
    ЗаполнитьЗначенияСвойств(ПараметрПриемник, ПараметрИсточник, 
        "ТипЗначения,
        |ВключатьВДоступныеПоля,
        |ОграничиватьДоступным,
        |ЗначениеДоступно,
        |Использование,
        |РазрешеноВыбиратьТип,
        |ЗначениеТипа");

    // Копируем доступные значения
    ПараметрПриемник.ДоступныеЗначения.Очистить();
    Для Каждого ДоступноеЗначение Из ПараметрИсточник.ДоступныеЗначения Цикл
        ПараметрПриемник.ДоступныеЗначения.Добавить(ДоступноеЗначение);
    КонецЦикла;

    // Устанавливаем имя приемника
    ПараметрПриемник.Имя = Приемник;

    // Устанавливаем значение приемника (если не Неопределено)
    Если ЗначениеПриемника <> Неопределено Тогда
        ПараметрПриемник.Значение = ЗначениеПриемника;
    КонецЕсли;

    Возврат ПараметрПриемник;

КонецФункции

// Функция разбирает строку параметров вида "Имя=Значение;Имя2=Значение2"
// Возвращает структуру, где ключ - имя параметра, значение - значение параметра
//
// Параметры:
//   СтрокаПараметров - Строка - строка с параметрами
//   Разделитель - Строка - символ-разделитель фрагментов
//
// Возвращаемое значение:
//   Структура - значения параметров
//
Функция ПараметрыИзСтроки(СтрокаПараметров, Разделитель) Экспорт

    Результат = Новый Структура;

    // Обработка пустой строки
    Если ПустаяСтрока(СтрокаПараметров) Тогда
        Возврат Результат;
    КонецЕсли;

    // Шаг 1: Разбиваем строку по разделителю с учётом кавычек
    // (разделитель внутри кавычек не считается разделителем фрагментов)
    Фрагменты = Новый Массив;
    ТекущийФрагмент = "";
    ВКавычках = Ложь;

    Для й = 1 По СтрДлина(СтрокаПараметров) Цикл
        Символ = Сред(СтрокаПараметров, й, 1);

        Если Символ = """" Тогда
            // Переключаем состояние "мы в кавычках"
            ТекущийФрагмент = ТекущийФрагмент + Символ;
            ВКавычках = НЕ ВКавычках;
        ИначеЕсли Символ = Разделитель И НЕ ВКавычках Тогда
            // Конец текущего фрагмента (разделитель встречен вне кавычек)
            Если НЕ ПустаяСтрока(ТекущийФрагмент) Тогда
                Фрагменты.Добавить(ТекущийФрагмент);
                ТекущийФрагмент = "";
            КонецЕсли;
        Иначе
            ТекущийФрагмент = ТекущийФрагмент + Символ;
        КонецЕсли;
    КонецЦикла;

    // Добавляем последний фрагмент
    Если НЕ ПустаяСтрока(ТекущийФрагмент) Тогда
        Фрагменты.Добавить(ТекущийФрагмент);
    КонецЕсли;

    // Шаг 2: Обрабатываем каждый фрагмент
    Для Каждого Фрагмент Из Фрагменты Цикл

        // Находим первую "=" для разделения имени и значения
        Позиция = Найти(Фрагмент, "=");

        Если Позиция = 0 Тогда
            Продолжить; // Пропускаем фрагменты без "="
        КонецЕсли;

        // Извлекаем имя параметра
        ИмяПараметра = СокрЛП(Лев(Фрагмент, Позиция - 1));

        // Извлекаем значение параметра
        ЗначениеПараметра = Сред(Фрагмент, Позиция + 1);

        // Обрабатываем значение: проверяем наличие внешних кавычек
        Если СтрДлина(ЗначениеПараметра) >= 2
            И Лев(ЗначениеПараметра, 1) = """"
            И Прав(ЗначениеПараметра, 1) = """" Тогда

            // Убираем внешние кавычки
            ЗначениеПараметра = Сред(ЗначениеПараметра, 2, СтрДлина(ЗначениеПараметра) - 2);

            // Заменяем экранированные кавычки "" на "
            ЗначениеПараметра = СтрЗаменить(ЗначениеПараметра, """""", """");

        КонецЕсли;

        // Добавляем параметр в структуру
        Результат.Вставить(ИмяПараметра, ЗначениеПараметра);

    КонецЦикла;

    Возврат Результат;

КонецФункции

// === Пример использования ===
Процедура ПримерИспользования()

    СтрокаПараметров = "Фамилия=""Иванов"";Имя=""Иван"";Возраст=30";
    Разделитель = ";";

    Параметры = ПараметрыИзСтроки(СтрокаПараметров, Разделитель);

    // Вывод результата
    Для Каждого КлючИЗначение Из Параметры Цикл
        Сообщить(КлючИЗначение.Ключ + " = " + КлючИЗначение.Значение);
    КонецЦикла;

    // Результат:
    // Фамилия = Иванов
    // Имя = Иван
    // Возраст = 30

КонецПроцедуры

// Проверяет проведенность переданных документов и возвращает непроведенные.
//
// Параметры:
//   мДокументы - Массив из ДокументСсылка - документы для проверки.
//
// Возвращаемое значение:
//   Массив из ДокументСсылка - непроведенные документы.
//
Функция ПроверитьПроведенностьДокументов(мДокументы) Экспорт

    результат = Новый Массив;

    Если мДокументы = Неопределено Или мДокументы.Количество() = 0 Тогда
        Возврат результат;
    КонецЕсли;

    Для Каждого ДокументСсылка Из мДокументы Цикл

        // Пропускаем пустые ссылки
        Если НЕ ЗначениеЗаполнено(ДокументСсылка) Тогда
            Продолжить;
        КонецЕсли;

        // Проверяем проведенность документа
        Если НЕ ДокументСсылка.Проведен Тогда
            результат.Добавить(ДокументСсылка);
        КонецЕсли;

    КонецЦикла;

    Возврат результат;

КонецФункции

// Функция выполняет попытку проведения документов и возвращает информацию
// о документах, которые не удалось провести
//
// Параметры:
//   мДокументы - Массив из ДокументСсылка - документы для проведения
//
// Возвращаемое значение:
//   Массив из Структура:
//     * Ссылка - ДокументСсылка - документ, который не удалось провести
//     * ОписаниеОшибки - Строка - текст ошибки при проведении
//
Функция ПровестиДокументы(мДокументы) Экспорт

	мРезультат = Новый Массив;

	Если мДокументы = Неопределено Или мДокументы.Количество() = 0 Тогда
		Возврат мРезультат;
	КонецЕсли;

	Для Каждого ДокументСсылка Из мДокументы Цикл

		// Пропускаем пустые ссылки
		Если НЕ ЗначениеЗаполнено(ДокументСсылка) Тогда
			Продолжить;
		КонецЕсли;

		Попытка

			ДокументОбъект = ДокументСсылка.ПолучитьОбъект();

			Если ДокументОбъект = Неопределено Тогда
				ВызватьИсключение "Не удалось получить объект документа";
			КонецЕсли;

			// Определяем режим записи в зависимости от текущего состояния
			РежимЗаписи = ?(ДокументОбъект.Проведен,
				РежимЗаписиДокумента.Проведение,
				РежимЗаписиДокумента.Запись);

			// Выполняем проведение документа
			ДокументОбъект.Записать(РежимЗаписи);

		Исключение

			ОписаниеОшибки = ?(
				ПодробноеОписаниеОшибки(ИнформацияОбОшибке()) = "",
				КраткоеОписаниеОшибки(ИнформацияОбОшибке()),
				ПодробноеОписаниеОшибки(ИнформацияОбОшибке())
			);

			СтруктураОшибки = Новый Структура;
			СтруктураОшибки.Вставить("Ссылка", ДокументСсылка);
			СтруктураОшибки.Вставить("ОписаниеОшибки", ОписаниеОшибки);

			мРезультат.Добавить(СтруктураОшибки);

		КонецПопытки;

	КонецЦикла;

	Возврат мРезультат;

КонецФункции

// Функция находит параметры в настройках компоновки данных по их именам.
// Поиск осуществляется в пользовательских настройках, затем в настройках варианта.
//
// Параметры:
//   ПользовательскиеНастройкиКД - ПользовательскиеНастройкиКомпоновкиДанных, Неопределено
//   НастройкиКД - НастройкиКомпоновкиДанных, Неопределено
//   ИменаПараметров - Строка - имена параметров через запятую
//
// Возвращаемое значение:
//   Структура, Неопределено - ключ = имя параметра, значение = найденный параметр
//
Функция НайтиПараметрыВНайстройкахКД(ПользовательскиеНастройкиКД, НастройкиКД, ИменаПараметров) Экспорт

    // Разбор строки имен параметров
    ИменаПараметровМассив = СтрРазделить(ИменаПараметров, ",");

    Результат = Новый Структура;

    // Итерация 1: Поиск в пользовательских настройках
    Если ПользовательскиеНастройкиКД <> Неопределено Тогда

        Для Каждого ЭлементНастройки Из ПользовательскиеНастройкиКД Цикл

            // Проверяем, является ли элемент параметром данных
            // Параметр данных имеет свойства: Value, Use, Property
            Попытка
                ЗначениеПараметра = ЭлементНастройки.Value;
                ЭтоПараметрДанных = (НЕ ЗначениеПараметра = Неопределено);
            Исключение
                ЭтоПараметрДанных = Ложь;
            КонецПопытки;

            Если НЕ ЭтоПараметрДанных Тогда
                Продолжить;
            КонецЕсли;

            // Получаем ссылку на параметр данных в настройках варианта
            ПараметрДанныхСсылка = Неопределено;
            Попытка
                ПараметрДанныхСсылка = ЭлементНастройки.Property;
            Исключение
                // Свойство Property недоступно
            КонецПопытки;

            Если ПараметрДанныхСсылка = Неопределено Тогда
                Продолжить;
            КонецЕсли;

            // Проверяем, включен ли параметр в пользовательских настройках
            Использование = Ложь;
            Попытка
                Использование = ЭлементНастройки.Use;
            Исключение
                Использование = Истина;
            КонецПопытки;

            // Если параметр выключен, пропускаем его
            Если НЕ Использование Тогда
                Продолжить;
            КонецЕсли;

            // Ищем соответствующий параметр в настройках варианта
            Если НастройкиКД <> Неопределено 
                И НастройкиКД.ПараметрыДанных <> Неопределено Тогда

                Для Каждого ПараметрКД Из НастройкиКД.ПараметрыДанных Цикл

                    // Сравниваем по идентификатору
                    Если ПараметрКД.Идентификатор = ПараметрДанныхСсылка.Идентификатор Тогда

                        // Проверяем, есть ли имя параметра в списке искомых
                        Для Каждого ИмяПараметра Из ИменаПараметровМассив Цикл

                            ТекущееИмя = СокрЛП(ИмяПараметра);

                            // Сравниваем имя (с учётом того, что параметр данных может не иметь имени)
                            Если СтрСравнить(ТекущееИмя, ПараметрКД.Имя) = 0 
                                ИЛИ СтрСравнить(ТекущееИмя, Строка(ПараметрКД.Идентификатор)) = 0 Тогда

                                Результат.Вставить(ТекущееИмя, ПараметрКД);
                            КонецЕсли;

                        КонецЦикла;

                        Прервать;

                    КонецЕсли;

                КонецЦикла;

            КонецЕсли;

        КонецЦикла;

    КонецЕсли;

    // Итерация 2: Поиск в настройках варианта отчета
    Если НастройкиКД <> Неопределено 
        И НастройкиКД.ПараметрыДанных <> Неопределено Тогда

        Для Каждого ИмяПараметра Из ИменаПараметровМассив Цикл

            ТекущееИмя = СокрЛП(ИмяПараметра);

            // Если параметр уже найден в пользовательских настройках, пропускаем
            Если Результат.Свойство(ТекущееИмя) Тогда
                Продолжить;
            КонецЕсли;

            // Поиск параметра по имени в коллекции параметров данных
            Для Каждого ПараметрКД Из НастройкиКД.ПараметрыДанных Цикл

                // Проверяем имя параметра
                Если СтрСравнить(ТекущееИмя, ПараметрКД.Имя) = 0 Тогда

                    Результат.Вставить(ТекущееИмя, ПараметрКД);
                    Прервать;

                КонецЕсли;

            КонецЦикла;

        КонецЦикла;

    КонецЕсли;

    // Возвращаем результат
    Если Результат.Количество() = 0 Тогда
        Возврат Неопределено;
    КонецЕсли;

    Возврат Результат;

КонецФункции

// Функция добавляет группировку в корневой уровень структуры настроек компоновщика
//
// Параметры:
//   КомпоновщикНастроек - КомпоновщикНастроекКомпоновкиДанных, НастройкиКомпоновкиДанных - 
//       Компоновщик настроек или объект настроек
//   Поле - Строка, ПолеКомпоновкиДанных - Необязательно. Имя поля или объект поля компоновки.
//       Если не указано, создаётся группировка для детальных записей.
//   ПараметрыГруппировки - Структура - Необязательно. Параметры группировки:
//       * НачалоПериода - Дата - Начало периода для полей типа Период
//       * КонецПериода - Дата - Конец периода для полей типа Период
//       * ТипГруппировки - ТипГруппировкиКомпоновкиДанных - Тип группировки
//       * ТипДополнения - ТипДополненияПериодаКомпоновкиДанных - Тип дополнения периода
//
// Возвращаемое значение:
//   ГруппировкаКомпоновкиДанных - Добавленная группировка
//
// Пример использования:
//   ДобавитьГруппировкуВКореньСтруктуры(КомпоновщикМакета, "Номенклатура");
//   ДобавитьГруппировкуВКореньСтруктуры(КомпоновщикМакета, "Период", 
//       Новый Структура("НачалоПериода, КонецПериода, ТипГруппировки, ТипДополнения",
//           '20240101', '20241231', ТипГруппировкиКомпоновкиДанных.Период, 
//           ТипДополненияПериодаКомпоновкиДанных.День));
//
Функция ДобавитьГруппировкуВКореньСтруктуры(КомпоновщикНастроек, Знач Поле = Неопределено, 
	ПараметрыГруппировки = Неопределено) Экспорт

	// Определяем настройки компоновки
	Если ТипЗнч(КомпоновщикНастроек) = Тип("КомпоновщикНастроекКомпоновкиДанных") Тогда
		Настройки = КомпоновщикНастроек.Настройки;
	Иначе
		Настройки = КомпоновщикНастроек;
	КонецЕсли;

	// Получаем корневую структуру
	СтруктураНастроек = Настройки.Структура;

	// Создаём новую группировку в корне структуры
	Группировка = СтруктураНастроек.Добавить(Тип("ГруппировкаКомпоновкиДанных"));

	// Если поле не указано - это детальные записи
	// Иначе настраиваем поле группировки
	Если Поле <> Неопределено Тогда

		// Преобразуем строку в поле компоновки данных, если требуется
		Если ТипЗнч(Поле) = Тип("Строка") Тогда
			ПолеКомпоновки = Новый ПолеКомпоновкиДанных(Поле);
		Иначе
			ПолеКомпоновки = Поле;
		КонецЕсли;

		// Добавляем поле группировки и устанавливаем его тип
		ЭлементПоляГруппировки = Группировка.ПоляГруппировки.Элементы.Добавить(
			Тип("ПолеГруппировкиКомпоновкиДанных"));
		ЭлементПоляГруппировки.Поле = ПолеКомпоновки;
		ЭлементПоляГруппировки.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;

	КонецЕсли;

	// Обрабатываем параметры группировки (период, дополнение)
	Если ПараметрыГруппировки <> Неопределено Тогда

		// Для установки параметров периода необходимо иметь поле группировки
		Если ЭлементПоляГруппировки <> Неопределено Тогда

			// Устанавливаем границы периода для полей типа Период
			Если ПараметрыГруппировки.Свойство("НачалоПериода") 
				И ПараметрыГруппировки.НачалоПериода <> Неопределено Тогда
				ЭлементПоляГруппировки.НачалоПериода = ПараметрыГруппировки.НачалоПериода;
			КонецЕсли;

			Если ПараметрыГруппировки.Свойство("КонецПериода") 
				И ПараметрыГруппировки.КонецПериода <> Неопределено Тогда
				ЭлементПоляГруппировки.КонецПериода = ПараметрыГруппировки.КонецПериода;
			КонецЕсли;

			// Устанавливаем тип группировки (по полю, по периоду и т.д.)
			Если ПараметрыГруппировки.Свойство("ТипГруппировки") 
				И ПараметрыГруппировки.ТипГруппировки <> Неопределено Тогда
				ЭлементПоляГруппировки.ТипГруппировки = ПараметрыГруппировки.ТипГруппировки;
			КонецЕсли;

			// Устанавливаем тип дополнения (день, неделя, месяц и т.д.)
			Если ПараметрыГруппировки.Свойство("ТипДополнения") 
				И ПараметрыГруппировки.ТипДополнения <> Неопределено Тогда
				ЭлементПоляГруппировки.ТипДополнения = ПараметрыГруппировки.ТипДополнения;
			КонецЕсли;

		КонецЕсли;

	КонецЕсли;

	Возврат Группировка;

КонецФункции

// Устанавливает ограничения использования поля в схеме компоновки данных.
//
// Параметры:
//   СхемаКД      - СхемаКомпоновкиДанных - Схема компоновки данных отчета.
//   Поле         - Строка, ПолеКомпоновкиДанных - Поле, для которого требуется установить ограничения.
//   Ограничения  - Структура - Структура с ключами ограничений:
//                  * Поле          - Булево - Ограничение доступа поле для выбора.
//                  * Условие       - Булево - Ограничение использования поля в условии.
//                  * Группа        - Булево - Ограничение использования поля в группировке.
//                  * Упорядочивание - Булево - Ограничение использования поля для упорядочивания.
//
// Возвращаемое значение:
//   ПолеНабораДанных - Найденное поле, для которого установлены ограничения.
//   Неопределено     - Если поле не найдено ни в одном наборе данных.
//
Функция УстановитьОграниченияИспользованияПоля(СхемаКД, Поле, Ограничения) Экспорт

    СтрокаПоле = Строка(Поле);

    НайденноеПоле = Неопределено;

    // Обход всех наборов данных в схеме
    Для Каждого НаборДанных Из СхемаКД.НаборыДанных Цикл

        НайденноеПоле = НайтиПолеВНаборе(НаборДанных, СтрокаПоле);

        Если НайденноеПоле <> Неопределено Тогда
            Прервать;
        КонецЕсли;

    КонецЦикла;

    Возврат НайденноеПоле;

КонецФункции

// Выполняет поиск поля в наборе данных по строке пути.
//
// Параметры:
//   НаборДанных   - НаборДанныхСхемыКомпоновкиДанных - Набор данных для поиска.
//   СтрокаПоле    - Строка - Путь к полю (например, "Товары.Номенклатура.Наименование").
//
// Возвращаемое значение:
//   ПолеНабораДанных, Неопределено - Найденное поле или Неопределено.
//
Функция НайтиПолеВНаборе(НаборДанных, СтрокаПоле)

    Перем НайденноеПоле;

    // Обработка набора данных типа Запрос
    Если ТипЗнч(НаборДанных) = Тип("НаборДанныхЗапросСхемыКомпоновкиДанных") Тогда

        НайденноеПоле = НайтиПолеВКоллекцииПолей(НаборДанных.Поля, СтрокаПоле);

    // Обработка набора данных типа Объект
    ИначеЕсли ТипЗнч(НаборДанных) = Тип("НаборДанныхОбъектСхемыКомпоновкиДанных") Тогда

        ПоляНабора = НаборДанных.ПолучитьПоля();

        Если ПоляНабора <> Неопределено Тогда

            НайденноеПоле = НайтиПолеВКоллекцииПолей(ПоляНабора, СтрокаПоле);

        КонецЕсли;

    КонецЕсли;

    Возврат НайденноеПоле;

КонецФункции

// Выполняет поиск поля в коллекции полей по строке пути.
//
// Параметры:
//   Поля          - КоллекцияПолейНабораДанныхСхемыКомпоновкиДанных - Коллекция полей для поиска.
//   СтрокаПоле    - Строка - Путь к полю.
//   ЧастиПути     - Массив - Части пути (разбитый путь по разделителю ".").
//   Индекс        - Число  - Текущий индекс обрабатываемой части пути.
//
// Возвращаемое значение:
//   ПолеНабораДанных, Неопределено - Найденное поле.
//
Функция НайтиПолеВКоллекцииПолей(Поля, СтрокаПоле)

    Перем ПолеНабора, НайденноеВложенноеПоле;

    ЧастиПути = СтрРазделить(СтрокаПоле, ".");
    Индекс    = 0;

    НайденноеПоле = Неопределено;

    Для Каждого ПолеНабора Из Поля Цикл

        Если СтрНайти(ЧастиПути[Индекс], ".") = 0
            И ПолеНабора.ПутьКДанным = ЧастиПути[Индекс] Тогда

            Если Индекс = ЧастиПути.Количество() - 1 Тогда

                НайденноеПоле = ПолеНабора;
                Прервать;

            Иначе

                ВложенныеПоля = ПолеНабора.ПолучитьПоля();

                Если ВложенныеПоля <> Неопределено Тогда

                    Для Сч = Индекс + 1 По ЧастиПути.Количество() - 1 Цикл

                        НайденноеВложенноеПоле = НайтиПолеРекурсивно(
                            ВложенныеПоля,
                            ЧастиПути,
                            Сч
                        );

                        Если НайденноеВложенноеПоле <> Неопределено Тогда

                            НайденноеПоле = НайденноеВложенноеПоле;

                        КонецЕсли;

                    КонецЦикла;

                    Если НайденноеПоле <> Неопределено Тогда
                        Прервать;
                    КонецЕсли;

                КонецЕсли;

            КонецЕсли;

        КонецЕсли;

    КонецЦикла;

    Возврат НайденноеПоле;

КонецФункции

// Рекурсивно ищет поле по частям пути.
//
// Параметры:
//   Поля        - КоллекцияПолейНабораДанныхСхемыКомпоновкиДанных - Коллекция полей.
//   ЧастиПути   - Массив - Части пути.
//   Индекс      - Число  - Индекс текущей части.
//
// Возвращаемое значение:
//   ПолеНабораДанных, Неопределено.
//
Функция НайтиПолеРекурсивно(Поля, ЧастиПути, Индекс)

    Перем ПолеНабора, ВложенныеПоля, НайденноеПоле, Сч;

    НайденноеПоле = Неопределено;

    Для Каждого ПолеНабора Из Поля Цикл

        Если ПолеНабора.ПутьКДанным = ЧастиПути[Индекс] Тогда

            Если Индекс = ЧастиПути.Количество() - 1 Тогда

                НайденноеПоле = ПолеНабора;

            Иначе

                ВложенныеПоля = ПолеНабора.ПолучитьПоля();

                Если ВложенныеПоля <> Неопределено Тогда

                    НайденноеПоле = НайтиПолеРекурсивно(
                        ВложенныеПоля,
                        ЧастиПути,
                        Индекс + 1
                    );

                КонецЕсли;

            КонецЕсли;

            Прервать;

        КонецЕсли;

    КонецЦикла;

    Возврат НайденноеПоле;

КонецФункции

// Устанавливает ограничения использования для найденного поля.
//
// Параметры:
//   ПолеНабора  - ПолеНабораДанныхСхемыКомпоновкиДанных - Поле, для которого устанавливаются ограничения.
//   Ограничения - Структура - Структура с ограничениями.
//
Процедура УстановитьОграниченияДляПоля(ПолеНабора, Ограничения)

    ОграничениеИспользования = ПолеНабора.ОграничениеИспользования;

    // Ограничение доступа для выбора (ключ "Поле" в структуре)
    Если Ограничения.Свойство("Поле") Тогда

        Если ОграничениеИспользования.Свойство("Доступность") Тогда
            ОграничениеИспользования.Доступность = Ограничения.Поле;
        КонецЕсли;

    КонецЕсли;

    // Ограничение использования в условии
    Если Ограничения.Свойство("Условие") Тогда

        Если ОграничениеИспользования.Свойство("Условие") Тогда
            ОграничениеИспользования.Условие = Ограничения.Условие;
        КонецЕсли;

    КонецЕсли;

    // Ограничение использования в группировке
    Если Ограничения.Свойство("Группа") Тогда

        Если ОграничениеИспользования.Свойство("Группировка") Тогда
            ОграничениеИспользования.Группировка = Ограничения.Группа;
        КонецЕсли;

    КонецЕсли;

    // Ограничение использования для упорядочивания
    Если Ограничения.Свойство("Упорядочивание") Тогда

        Если ОграничениеИспользования.Свойство("Упорядочивание") Тогда
            ОграничениеИспользования.Упорядочивание = Ограничения.Упорядочивание;
        КонецЕсли;

    КонецЕсли;

КонецПроцедуры

// Устанавливает роль для поля набора данных в схеме компоновки данных.
// Параметры:
//   СхемаКД      - СхемаКомпоновкиДанных - схема КД.
//   Поле         - Строка, ПолеКомпоновкиДанных - полный путь к полю.
//   СвойстваРоль - Структура - структура с описанием роли.
//
// Возвращаемое значение:
//   Булево - Истина, если поле найдено и роль установлена.
//
Функция УстановитьРольПоляНабораДанныхСКД(СхемаКД, Поле, СвойстваРоль) Экспорт

    ИмяПоля = Строка(Поле);

    Если СхемаКД.НаборыДанных = Неопределено Тогда
        Возврат Ложь;
    КонецЕсли;

    Для Каждого НаборДанных Из СхемаКД.НаборыДанных Цикл
        Найдено = НайтиИУстановитьРольПоляНабораДанных(НаборДанных, ИмяПоля, СвойстваРоль);
        Если Найдено Тогда
            Возврат Истина;
        КонецЕсли;
    КонецЦикла;

    Возврат Ложь;

КонецФункции

// Рекурсивно обходит набор данных и его вложенные элементы, 
// находит поле и устанавливает роль.
// Параметры:
//   НаборДанных    - НаборДанныхСКД - обходимый набор.
//   ИмяПоля        - Строка - полный путь к полю.
//   СвойстваРоль   - Структура - свойства роли.
//
// Возвращаемое значение:
//   Булево - Истина, если поле найдено.
//
Функция НайтиИУстановитьРольПоляНабораДанных(НаборДанных, ИмяПоля, СвойстваРоль)

    // Обход собственных полей набора
    ПолеНайдено = ОбойтиПоляНабораИУстановитьРоль(НаборДанных, ИмяПоля, СвойстваРоль);
    Если ПолеНайдено Тогда
        Возврат Истина;
    КонецЕсли;

    // Обход собственного набора данных для объединения
    СобственныйНабор = НаборДанных.Элементы.Найти("НаборДанных");
    Если СобственныйНабор <> Неопределено Тогда
        ПолеНайдено = НайтиИУстановитьРольПоляНабораДанных(СобственныйНабор, ИмяПоля, СвойстваРоль);
        Если ПолеНайдено Тогда
            Возврат Истина;
        КонецЕсли;
    КонецЕсли;

    // Обход связи наборов данных (НаборДанныхСвязьНабораДанных)
    Для Каждого Связь Из НаборДанных.Связи Цикл
        Если ТипЗнч(Связь) = Тип("НаборДанныхСвязьНабораДанных") Тогда
            Приемник = Связь.Приемник;
            Если Приемник <> Неопределено Тогда
                ПолеНайдено = НайтиИУстановитьРольПоляНабораДанных(Приемник, ИмяПоля, СвойстваРоль);
                Если ПолеНайдено Тогда
                    Возврат Истина;
                КонецЕсли;
            КонецЕсли;
        КонецЕсли;
    КонецЦикла;

    Возврат Ложь;

КонецФункции

// Обходит коллекцию полей набора данных, ищет поле по пути и устанавливает роль.
// Параметры:
//   НаборДанных  - НаборДанныхСКД - набор данных.
//   ИмяПоля      - Строка - полный путь к полю.
//   СвойстваРоль - Структура - свойства роли.
//
// Возвращаемое значение:
//   Булево - Истина, если поле найдено.
//
Функция ОбойтиПоляНабораИУстановитьРоль(НаборДанных, ИмяПоля, СвойстваРоль)

    ПолеНайдено = Ложь;

    // Обход полей набора (рекурсивно для сложных структур)
    Поле = НайтиПолеПоПолномуПути(НаборДанных, ИмяПоля);
    Если Поле <> Неопределено Тогда
        УстановитьСвойстваРолиПоля(Поле, СвойстваРоль);
        Возврат Истина;
    КонецЕсли;

    // Обход вычисляемых полей набора (для НаборДанныхЗапроса)
    ВычисляемоеПоле = НайтиВычисляемоеПоле(НаборДанных, ИмяПоля);
    Если ВычисляемоеПоле <> Неопределено Тогда
        УстановитьСвойстваРолиПоля(ВычисляемоеПоле, СвойстваРоль);
        Возврат Истина;
    КонецЕсли;

    // Обход ресурсов набора данных (для НаборДанныхЗапроса)
    Ресурс = НайтиРесурс(НаборДанных, ИмяПоля);
    Если Ресурс <> Неопределено Тогда
        УстановитьСвойстваРолиПоля(Ресурс, СвойстваРоль);
        Возврат Истина;
    КонецЕсли;

    // Обход вложенных наборов объединения
    Для Каждого ЭлементНабора Из НаборДанных.Элементы Цикл
        Если ЭлементНабора <> НаборДанных.Элементы.Найти("НаборДанных") Тогда
            // Пропускаем вложенный НаборДанных — он обрабатывается в рекурсии выше
            ПолеНайдено = ОбойтиПоляНабораИУстановитьРоль(ЭлементНабора, ИмяПоля, СвойстваРоль);
            Если ПолеНайдено Тогда
                Возврат Истина;
            КонецЕсли;
        КонецЕсли;
    КонецЦикла;

    Возврат Ложь;

КонецФункции

// Ищет поле в наборе данных по полному пути (рекурсивно).
// Параметры:
//   НаборДанных - НаборДанныхСКД - набор данных.
//   ИмяПоля     - Строка - полный путь к полю.
//
// Возвращаемое значение:
//   ПолеНабораДанныхСКД, Неопределено.
//
Функция НайтиПолеПоПолномуПути(НаборДанных, ИмяПоля)

    ПутьОдногоУровня = "";
    ОставшийсяПуть   = "";

    ПозицияТочки = СтрНайти(ИмяПоля, ".");
    Если ПозицияТочки > 0 Тогда
        ПутьОдногоУровня = Лев(ИмяПоля, ПозицияТочки - 1);
        ОставшийсяПуть   = Сред(ИмяПоля, ПозицияТочки + 1);
    Иначе
        ПутьОдногоУровня = ИмяПоля;
    КонецЕсли;

    // Поиск на текущем уровне
    Поле = НаборДанных.Поля.Найти(ПутьОдногоУровня);

    Если Поле = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Если есть вложенный путь — рекурсивно ищем дальше
    Если Не ПустаяСтрока(ОставшийсяПуть) Тогда
        Возврат НайтиПолеПоПолномуПути(Поле, ОставшийсяПуть);
    КонецЕсли;

    Возврат Поле;

КонецФункции

// Ищет вычисляемое поле по полному пути.
// Параметры:
//   НаборДанных - НаборДанныхСКД - набор данных.
//   ИмяПоля     - Строка - полный путь.
//
// Возвращаемое значение:
//   ВычисляемоеПолеНабораДанныхСКД, Неопределено.
//
Функция НайтиВычисляемоеПоле(НаборДанных, ИмяПоля)

    Если НЕ НаборДанных.Свойства().Свойство("ВычисляемыеПоля") Тогда
        Возврат Неопределено;
    КонецЕсли;

    ПутьОдногоУровня = "";
    ОставшийсяПуть   = "";

    ПозицияТочки = СтрНайти(ИмяПоля, ".");
    Если ПозицияТочки > 0 Тогда
        ПутьОдногоУровня = Лев(ИмяПоля, ПозицияТочки - 1);
        ОставшийсяПуть   = Сред(ИмяПоля, ПозицияТочки + 1);
    Иначе
        ПутьОдногоУровня = ИмяПоля;
    КонецЕсли;

    ВычисляемоеПоле = НаборДанных.ВычисляемыеПоля.Найти(ПутьОдногоУровня);
    Если ВычисляемоеПоле <> Неопределено И Не ПустаяСтрока(ОставшийсяПуть) Тогда
        Возврат Неопределено; // У вычисляемого поля нет вложенных полей
    КонецЕсли;

    Возврат ВычисляемоеПоле;

КонецФункции

// Ищет ресурс по полному пути.
// Параметры:
//   НаборДанных - НаборДанныхСКД - набор данных.
//   ИмяПоля     - Строка - полный путь.
//
// Возвращаемое значение:
//   РесурсНабораДанныхСКД, Неопределено.
//
Функция НайтиРесурс(НаборДанных, ИмяПоля)

    Если НЕ СхемаКД.Свойства().Свойство("ВычисляемыеПоля") Тогда
        // Ресурсы могут быть и в наборе, и на уровне схемы — ищем в наборе
        Возврат Неопределено;
    КонецЕсли;

    Возврат НаборДанных.Ресурсы.Найти(ИмяПоля);

КонецФункции

// Устанавливает свойства роли поля по структуре.
// Параметры:
//   Поле         - ПолеНабораДанныхСКД - поле.
//   СвойстваРоль - Структура - свойства роли.
//
Процедура УстановитьСвойстваРолиПоля(Поле, СвойстваРоль)

    Роль = Поле.Роль;

    // Если указано очистить роль
    Если СвойстваРоль.Свойство("БезРоли") И СвойстваРоль.БезРоли Тогда
        Роль = Новый РольПоляКомпоновкиДанных();
        Поле.Роль = Роль;
        Возврат;
    КонецЕсли;

    // Установка строковых свойств
    Если СвойстваРоль.Свойство("ВыражениеВидаСчета") Тогда
        Роль.ВыражениеВидаСчета = СвойстваРоль.ВыражениеВидаСчета;
    КонецЕсли;

    Если СвойстваРоль.Свойство("ГруппаОстатка") Тогда
        Роль.ГруппаОстатка = СвойстваРоль.ГруппаОстатка;
    КонецЕсли;

    Если СвойстваРоль.Свойство("НомерПериода") Тогда
        Роль.НомерПериода = СвойстваРоль.НомерПериода;
    КонецЕсли;

    Если СвойстваРоль.Свойство("РодительскоеИзмерение") Тогда
        Роль.РодительскоеИзмерение = СвойстваРоль.РодительскоеИзмерение;
    КонецЕсли;

    // Установка булевых свойств
    Если СвойстваРоль.Свойство("ИгнорироватьЗначенияNULL") Тогда
        Роль.ИгнорироватьЗначенияNULL = СвойстваРоль.ИгнорироватьЗначенияNULL;
    КонецЕсли;

    Если СвойстваРоль.Свойство("Измерение") Тогда
        Роль.Измерение = СвойстваРоль.Измерение;
    КонецЕсли;

    Если СвойстваРоль.Свойство("Обязательное") Тогда
        Роль.Обязательное = СвойстваРоль.Обязательное;
    КонецЕсли;

    Если СвойстваРоль.Свойство("Остаток") Тогда
        Роль.Остаток = СвойстваРоль.Остаток;
    КонецЕсли;

    Если СвойстваРоль.Свойство("ПолеСчета") Тогда
        Роль.ПолеСчета = СвойстваРоль.ПолеСчета;
    КонецЕсли;

    Если СвойстваРоль.Свойство("РеквизитИзмерения") Тогда
        Роль.РеквизитИзмерения = СвойстваРоль.РеквизитИзмерения;
    КонецЕсли;

    Если СвойстваРоль.Свойство("Счет") Тогда
        Роль.Счет = СвойстваРоль.Счет;
    КонецЕсли;

    // Установка значений перечислений
    Если СвойстваРоль.Свойство("ТипБухгалтерскогоОстатка") Тогда
        Роль.ТипБухгалтерскогоОстатка = СвойстваРоль.ТипБухгалтерскогоОстатка;
    КонецЕсли;

    Если СвойстваРоль.Свойство("ТипОстатка") Тогда
        Роль.ТипОстатка = СвойстваРоль.ТипОстатка;
    КонецЕсли;

    Если СвойстваРоль.Свойство("ТипПериода") Тогда
        Роль.ТипПериода = СвойстваРоль.ТипПериода;
    КонецЕсли;

КонецПроцедуры

// Функция формирует отчет "ПрайсЛист" с группировкой по детальным записям
// Параметры:
//   ВидЦен - СправочникСсылка.ВидыЦен - Вид цен для формирования отчета
// Возвращаемое значение:
//   ТабличныйДокумент - Результат формирования отчета
Функция СформироватьОтчетПрайсЛистТолькоЦены(ВидЦен) Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ПрайсЛист.Создать();

    // Получаем основную схему компоновки данных из макета отчета
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Инициализируем компоновщик настроек
    КомпоновщикНастроек = ОтчетОбъект.КомпоновщикНастроек;
    КомпоновщикНастроек.Инициализировать(
        Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных)
    );

    // Загружаем вариант "Основной" (настройки по умолчанию)
    Если ОтчетОбъект.ВариантыОтчетов.Получить("Основной") <> Неопределено Тогда
        ОсновнойВариант = ОтчетОбъект.СхемаКомпоновкиДанных.ВариантыНастроек.Основной;
        КомпоновщикНастроек.ЗагрузитьНастройки(ОсновнойВариант.Настройки);
    Иначе
        КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.НастройкиПоУмолчанию);
    КонецЕсли;

    // Получаем настройки компоновки
    Настройки = КомпоновщикНастроек.Настройки;

    // Подменяем структуру отчета - оставляем только ДетальныеЗаписи
    Настройки.Структура.Очистить();

    // Создаем группировку "Детальные записи"
    ДетальныеЗаписи = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ДетальныеЗаписи.Имя = "ДетальныеЗаписи";
    ДетальныеЗаписи.Состояние = СостояниеГруппировкиКомпоновкиДанных.Включено;

    // Настраиваем выбранные поля для детальных записей
    ДетальныеЗаписи.Выбор.Элементы.Очистить();

    // Поле: Товар
    ПолеТовар = ДетальныеЗаписи.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");
    ПолеТовар.Заголовок = "Товар";

    // Поле: Артикул
    ПолеАртикул = ДетальныеЗаписи.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеАртикул.Поле = Новый ПолеКомпоновкиДанных("Артикул");
    ПолеАртикул.Заголовок = "Артикул";

    // Поле: Цена
    ПолеЦена = ДетальныеЗаписи.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеЦена.Поле = Новый ПолеКомпоновкиДанных("Цена");
    ПолеЦена.Заголовок = "Цена";

    // Устанавливаем параметры отчета
    ПараметрВидЦен = Настройки.ПараметрыДанных.Элементы.Найти("ВидЦен");
    Если ПараметрВидЦен <> Неопределено Тогда
        ПараметрВидЦен.Значение = ВидЦен;
        ПараметрВидЦен.Использование = Истина;
    КонецЕсли;

    // Настраиваем параметры вывода
    ПараметрыВывода = Настройки.ПараметрыВывода;

    // Не выводить параметры данных
    ПараметрВыводаПараметрыДанных = ПараметрыВывода.Элементы.Найти("ВыводитьПараметрыДанных");
    Если ПараметрВыводаПараметрыДанных <> Неопределено Тогда
        ПараметрВыводаПараметрыДанных.Значение = РежимВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаПараметрыДанных.Использование = Истина;
    КонецЕсли;

    // Не выводить отбор
    ПараметрВыводаОтбор = ПараметрыВывода.Элементы.Найти("ВыводитьОтбор");
    Если ПараметрВыводаОтбор <> Неопределено Тогда
        ПараметрВыводаОтбор.Значение = РежимВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаОтбор.Использование = Истина;
    КонецЕсли;

    // Формируем табличный документ
    ДокументРезультат = Новый ТабличныйДокумент;

    // Генерируем макет компоновки
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        Настройки,
        ДанныеРасшифровки
    );

    // Создаем процессор компоновки
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(
        МакетКомпоновки,
        ,
        ДанныеРасшифровки
    );

    // Создаем процессор вывода
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ДокументРезультат);

    // Выводим результат
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ДокументРезультат;

КонецФункции

// Устанавливает оформление для поля остатка в схеме компоновки данных
//
// Параметры:
//   СхемаКД - СхемаКомпоновкиДанных - схема компоновки данных отчета
//   ТипОстатка - Строка - тип остатка: "Количество" или "Сумма"
//   ДопПараметры - Массив из Структура, Неопределено - дополнительные параметры оформления
//
// Возвращаемое значение:
//   Булево - Истина, если оформление успешно установлено
//
Функция УстановитьОформлениеОстатка(СхемаКД, ТипОстатка, ДопПараметры = Неопределено) Экспорт

    // Определяем имя поля на основе типа остатка
    Если ТипОстатка = "Количество" Тогда
        ИмяПоля = "КоличествоОстаток";
    ИначеЕсли ТипОстатка = "Сумма" Тогда
        ИмяПоля = "СуммаОстаток";
    Иначе
        Возврат Ложь;
    КонецЕсли;

    // Ищем набор данных с искомым полем
    Поле = НайтиПолеВНабореДанных(СхемаКД.НаборыДанных, ИмяПоля);

    // Если поле не найдено, возвращаем Ложь
    Если Поле = Неопределено Тогда
        Возврат Ложь;
    КонецЕсли;

    // Устанавливаем обязательные параметры оформления

    // Формат: числовой формат с двумя знаками после запятой
    ПараметрФормат = Новый ПараметрКомпоновкиДанных("Формат");
    Поле.Оформление.УстановитьЗначениеПараметра(
        ПараметрФормат, 
        "ЧЦ=10; ЧДЦ=2; ЧН=0; ЧО=1"
    );

    // Выделять отрицательные - выделяем красным цветом
    ПараметрВыделятьОтрицательные = Новый ПараметрКомпоновкиДанных("ВыделятьОтрицательные");
    Поле.Оформление.УстановитьЗначениеПараметра(
        ПараметрВыделятьОтрицательные, 
        Истина
    );

    // Горизонтальное положение - прижать вправо
    ПараметрГоризонтальноеПоложение = Новый ПараметрКомпоновкиДанных("ГоризонтальноеПоложение");
    Поле.Оформление.УстановитьЗначениеПараметра(
        ПараметрГоризонтальноеПоложение, 
        ГоризонтальноеПоложение.ПрижатьВправо
    );

    // Применяем дополнительные параметры, если они переданы
    Если ДопПараметры <> Неопределено И ДопПараметры.Количество() > 0 Тогда

        Для Каждого Параметр Из ДопПараметры Цикл

            // Проверяем, что структура содержит необходимые ключи
            Если НЕ (Параметр.Свойство("Ключ") И Параметр.Свойство("Значение")) Тогда
                Продолжить;
            КонецЕсли;

            // Получаем значение параметра
            ЗначениеПараметра = Параметр.Значение;

            // Проверяем тип значения - должен быть ЗначениеПараметраНастроекКомпоновкиДанных
            Если ТипЗнч(ЗначениеПараметра) <> Тип("ЗначениеПараметраНастроекКомпоновкиДанных") Тогда
                Продолжить;
            КонецЕсли;

            // Устанавливаем дополнительный параметр оформления
            Поле.Оформление.УстановитьЗначениеПараметра(
                Параметр.Ключ, 
                ЗначениеПараметра
            );

        КонецЦикла;

    КонецЕсли;

    Возврат Истина;

КонецФункции

// Выполняет поиск поля по имени в коллекции наборов данных схемы КД
//
// Параметры:
//   НаборыДанных - КоллекцияНаборовДанныхСхемыКомпоновкиДанных - коллекция наборов данных
//   ИмяПоля - Строка - имя искомого поля
//
// Возвращаемое значение:
//   ПолеНабораДанныхСхемыКомпоновкиДанных, Неопределено - найденное поле или Неопределено
//
Функция НайтиПолеВНабореДанных(НаборыДанных, ИмяПоля)

    Для Каждого НаборДанных Из НаборыДанных Цикл

        // Обрабатываем вложенные наборы данных (для объединений)
        Если НРег(ТипЗнч(НаборДанных)) = "наборданныхобъединение" Тогда
            ВложенноеПоле = НайтиПолеВНабореДанных(НаборДанных.Элементы, ИмяПоля);
            Если ВложенноеПоле <> Неопределено Тогда
                Возврат ВложенноеПоле;
            КонецЕсли;
        Иначе
            // Ищем поле в текущем наборе данных
            НайденноеПоле = НаборДанных.Поля.Найти(ИмяПоля);
            Если НайденноеПоле <> Неопределено Тогда
                Возврат НайденноеПоле;
            КонецЕсли;
        КонецЕсли;

    КонецЦикла;

    Возврат Неопределено;

КонецФункции

// Функция добавляет в схему компоновки данных набор данных, заполненный из таблицы значений
//
// Параметры:
//   СхемаКД - СхемаКомпоновкиДанных - Схема компоновки данных, в которую добавляется набор
//   ИмяИсточникДанных - Строка - Имя источника данных
//   Таблица - ТаблицаЗначений - Таблица, по колонкам которой заполняется набор
//   ИмяНабора - Строка - Имя нового набора данных
//
// Возвращаемое значение:
//   НаборДанныхОбъектСхемыКомпоновкиДанных - Созданный набор данных
//
Функция ДобавитьНаборДанныхИзТаблицыЗначений(СхемаКД, ИмяИсточникДанных, Таблица, ИмяНабора) Экспорт

    // Проверяем, указано ли имя набора данных
    Если ПустаяСтрока(ИмяНабора) Тогда
        ИмяНабора = "НаборДанныхИзТаблицы";
    КонецЕсли;

    // Поиск существующего источника данных по имени
    ИсточникДанных = Неопределено;
    Для Каждого ТекИсточник Из СхемаКД.ИсточникиДанных Цикл
        Если ТекИсточник.Имя = ИмяИсточникДанных Тогда
            ИсточникДанных = ТекИсточник;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    // Если источник данных не найден, создаем новый
    Если ИсточникДанных = Неопределено Тогда
        ИсточникДанных = СхемаКД.ИсточникиДанных.Добавить();
        ИсточникДанных.Имя = ИмяИсточникДанных;
        ИсточникДанных.СтрокаСоединения = "";
        ИсточникДанных.ТипИсточникаДанных = "Local";
    КонецЕсли;

    // Создаем набор данных типа "НаборДанныхОбъектСхемыКомпоновкиДанных"
    НаборДанных = СхемаКД.НаборыДанных.Добавить(Тип("НаборДанныхОбъектСхемыКомпоновкиДанных"));
    НаборДанных.Имя = ИмяНабора;
    НаборДанных.ИсточникДанных = ИмяИсточникДанных;

    // Добавляем поля в набор данных на основе колонок таблицы значений
    Для Каждого Колонка Из Таблица.Колонки Цикл
        ДобавленноеПоле = НаборДанных.Поля.Добавить();
        ДобавленноеПоле.Поле = Колонка.Имя;
        ДобавленноеПоле.Заголовок = Колонка.Имя;
        ДобавленноеПоле.ТипЗначения = Новый ОписаниеТипов(Колонка.ТипЗначения);
        ДобавленноеПоле.ПутьКДанным = Колонка.Имя;
    КонецЦикла;

    Возврат НаборДанных;

КонецФункции

// Функция формирует отчет по проведенным документам оплаты с выводом валюты
//
// Возвращаемое значение:
//   ТабличныйДокумент - сформированный отчет
//
Функция СформироватьОтчетПоПроведеннымОплатамСВалютой() Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ДокументыОплата.Создать();

    // Получаем доступные варианты отчета
    ДоступныеВарианты = ОтчетОбъект.ПолучитьДоступныеВарианты();

    // Находим вариант "Основной"
    ВариантОсновной = Неопределено;
    Для Каждого ДоступныйВариант Из ДоступныеВарианты Цикл
        Если ДоступныйВариант.Представление = "Основной" Тогда
            ВариантОсновной = ДоступныйВариант;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    // Если вариант не найден, выбрасываем исключение
    Если ВариантОсновной = Неопределено Тогда
        ВызватьИсключение "Вариант отчета ""Основной"" не найден";
    КонецЕсли;

    // Загружаем настройки варианта
    ОтчетОбъект.КомпоновщикНастроек.ЗагрузитьНастройки(ВариантОсновной.Настройки);

    // Получаем настройки компоновки
    Настройки = ОтчетОбъект.КомпоновщикНастроек.Настройки;

    // Настраиваем параметры вывода
    ПараметрыВывода = Настройки.ПараметрыВывода;
    ПараметрыВывода.ВыводитьПараметрыДанных = РежимВывода.НеВыводить;
    ПараметрыВывода.ВыводитьОтбор           = РежимВывода.НеВыводить;

    // Устанавливаем отбор: Проведен = Истина
    Отбор = Настройки.Отбор;

    // Очищаем существующий отбор
    Отбор.Элементы.Очистить();

    // Добавляем элемент отбора Проведен = Истина
    ЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение  = Новый ПолеКомпоновкиДанных("Проведен");
    ЭлементОтбора.ВидСравнения   = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбора.ПравоеЗначение = Истина;
    ЭлементОтбора.Использование  = Истина;

    // Добавляем элемент отбора ПометкаУдаления = Ложь
    ЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение  = Новый ПолеКомпоновкиДанных("ПометкаУдаления");
    ЭлементОтбора.ВидСравнения   = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбора.ПравоеЗначение = Ложь;
    ЭлементОтбора.Использование  = Истина;

    // Очищаем выбранные поля
    ВыбранныеПоля = Настройки.Выбор;
    ВыбранныеПоля.Элементы.Очистить();

    // Добавляем поля в требуемом порядке: Валюта перед Сумма
    ДобавитьПолеВыбора(ВыбранныеПоля, "Дата");
    ДобавитьПолеВыбора(ВыбранныеПоля, "Номер");
    ДобавитьПолеВыбора(ВыбранныеПоля, "Поставщик");
    ДобавитьПолеВыбора(ВыбранныеПоля, "РасчетныйСчетПоставщика");
    ДобавитьПолеВыбора(ВыбранныеПоля, "Валюта");
    ДобавитьПолеВыбора(ВыбранныеПоля, "Сумма");

    // Формируем табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;

    // Создаем макет компоновки
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        ОтчетОбъект.СхемаКомпоновкиДанных,
        Настройки,
        ОтчетОбъект.ДанныеРасшифровки,
        ,
        Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    // Выполняем компоновку
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанных;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

// Процедура добавляет поле в выбор компоновки данных
//
// Параметры:
//   ВыбранныеПоля - КоллекцияЭлементовВыбораКомпоновкиДанных - коллекция выбранных полей
//   ИмяПоля - Строка - имя поля компоновки данных
//
Процедура ДобавитьПолеВыбора(ВыбранныеПоля, ИмяПоля)

    Поле = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    Поле.Поле       = Новый ПолеКомпоновкиДанных(ИмяПоля);
    Поле.Использование = Истина;

КонецПроцедуры

// Функция сохраняет настройки компоновщика данных (СКД) в XML файл
//
// Параметры:
//   КомпоновщикНастроек - КомпоновщикНастроекКомпоновкиДанных - компоновщик настроек
//   Путь - Строка - путь к файлу или каталогу (необязательный)
//
// Возвращаемое значение:
//   Строка - полный путь к сохраненному файлу
//
// Пример использования:
//   Путь = СохранитьНастройкиСКДВФайлXML(КомпоновщикНастроек);
//   Путь = СохранитьНастройкиСКДВФайлXML(КомпоновщикНастроек, "C:\Reports");
//
Функция СохранитьНастройкиСКДВФайлXML(КомпоновщикНастроек, Путь = "") Экспорт

    // Определение итогового пути к файлу
    Если НЕ ЗначениеЗаполнено(Путь) Тогда
        // Создаем временный файл с расширением xml
        Путь = ПолучитьИмяВременногоФайла("xml");
    Иначе
        // Проверяем, заканчивается ли путь разделителем
        Если НЕ СтрЗаканчиваетсяНа(Путь, "\") 
            И НЕ СтрЗаканчиваетсяНа(Путь, "/") Тогда
            // Добавляем разделитель пути ОС
            Путь = Путь + ПолучитьРазделительПути();
        КонецЕсли;
        // Добавляем имя файла
        Путь = Путь + "config.xml";
    КонецЕсли;

    // Получаем настройки компоновщика
    Настройки = КомпоновщикНастроек.ПолучитьНастройки();

    // Создаем объект записи XML
    ЗаписьXML = Новый ЗаписьXML;
    ЗаписьXML.ОткрытьФайл(Путь, "UTF-8");
    ЗаписьXML.ЗаписатьОбъявлениеXML();

    // Сериализуем настройки в XML формат
    СериализаторXDTO.ЗаписатьXML(ЗаписьXML, Настройки);

    // Закрываем файл
    ЗаписьXML.Закрыть();

    Возврат Путь;

КонецФункции

// Функция выгружает просроченные заказы клиентов в JSON файл
//
// Параметры:
//  ДатаКонтроля - Дата - дата, на которую выполняется анализ просроченных заказов
//                  Если не задана, устанавливается текущая дата (конец дня)
//
// Возвращаемое значение:
//  Строка - полный путь к сформированному JSON файлу
//
Функция ВыгрузитьПросроченныеЗаказыВФайлJSON(ДатаКонтроля = Неопределено) Экспорт

    // Установка даты контроля
    Если ДатаКонтроля = Неопределено Тогда
        ДатаКонтроля = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Формирование запроса к документам Заказ
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |	Заказ.Номер КАК НомерЗаказа,
    |	Заказ.Дата КАК ДатаЗаказа,
    |	Заказ.Покупатель КАК Покупатель,
    |	Заказ.Сумма КАК Сумма,
    |	Заказ.СостояниеЗаказа КАК СостояниеЗаказа,
    |	Заказ.Покупатель.ЭлектроннаяПочта КАК ЭлектроннаяПочта
    |ИЗ
    |	Документ.Заказ КАК Заказ
    |ГДЕ
    |	Заказ.Проведен = ИСТИНА
    |	И Заказ.СостояниеЗаказа = ЗНАЧЕНИЕ(Перечисление.СостоянияЗаказов.Открыт)
    |	И Заказ.Дата < &ДатаКонтроля
    |УПОРЯДОЧИТЬ ПО
    |	Заказ.Дата УБЫВ";

    Запрос.УстановитьПараметр("ДатаКонтроля", ДатаКонтроля);

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // Создание массива для хранения данных
    МассивЗаказов = Новый Массив;

    // Обработка результатов запроса
    Пока Выборка.Следующий() Цикл

        // Расчет количества просроченных дней
        ПросроченоДней = Цел((ДатаКонтроля - Выборка.ДатаЗаказа) / 86400);

        // Включаем в JSON только записи с просрочкой
        Если ПросроченоДней > 0 Тогда

            СтруктураЗаказа = Новый Структура;
            СтруктураЗаказа.Вставить("НомерЗаказа", Строка(Выборка.НомерЗаказа));
            СтруктураЗаказа.Вставить("ДатаЗаказа", Формат(Выборка.ДатаЗаказа, "ДФ=yyyy-MM-dd"));
            СтруктураЗаказа.Вставить("Покупатель", Строка(Выборка.Покупатель));
            СтруктураЗаказа.Вставить("Сумма", Выборка.Сумма);
            СтруктураЗаказа.Вставить("ПросроченоДней", ПросроченоДней);

            // Формирование состояния заказа
            Если НЕ ЗначениеЗаполнено(Выборка.СостояниеЗаказа) Тогда
                СтруктураЗаказа.Вставить("СостояниеЗаказа", "");
            Иначе
                СтруктураЗаказа.Вставить("СостояниеЗаказа", Строка(Выборка.СостояниеЗаказа));
            КонецЕсли;

            // Формирование электронной почты
            Если ЗначениеЗаполнено(Выборка.ЭлектроннаяПочта) Тогда
                СтруктураЗаказа.Вставить("ЭлектроннаяПочта", Строка(Выборка.ЭлектроннаяПочта));
            Иначе
                СтруктураЗаказа.Вставить("ЭлектроннаяПочта", "");
            КонецЕсли;

            МассивЗаказов.Добавить(СтруктураЗаказа);

        КонецЕсли;

    КонецЦикла;

    // Формирование JSON строки
    ЗаписьJSON = Новый ЗаписьJSON;
    ЗаписьJSON.УстановитьСтроку();
    ЗаписатьJSON(ЗаписьJSON, МассивЗаказов);
    JSONСтрока = ЗаписьJSON.Закрыть();

    // Формирование пути к файлу
    ИмяФайла = "ПросроченныеЗаказы_" + Формат(ДатаКонтроля, "ДФ=yyyyMMdd") + ".json";
    ПутьКФайлу = КаталогВременныхФайлов() + ИмяФайла;

    // Запись в файл
    ЗаписьФайла = Новый ЗаписьТекста(ПутьКФайлу, КодировкаТекста.UTF8);
    ЗаписьФайла.ЗаписатьСтроку(JSONСтрока);
    ЗаписьФайла.Закрыть();

    Возврат ПутьКФайлу;

КонецФункции

Функция СформироватьОтчетПоОплатамПоОрганизациям() Экспорт

    // Создаем табличный документ для результата отчета
    Результат = Новый ТабличныйДокумент;

    // Получаем объект отчета
    ОтчетОбъект = Отчеты.ДокументыОплата.Создать();

    // Инициализируем отчет
    ОтчетОбъект.ИнициализироватьОтчет();

    // Получаем компоновщик настроек
    КомпоновщикНастроек = ОтчетОбъект.КомпоновщикНастроек;

    // Получаем схему компоновки данных
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Загружаем вариант отчета "Основной"
    КомпоновщикНастроек.ЗагрузитьНастройки(
        СхемаКомпоновкиДанных.ВариантыНастроек.Основной.Настройки
    );

    // Получаем текущие настройки
    Настройки = КомпоновщикНастроек.ПолучитьНастройки();

    // =====================================
    // Настраиваем структуру отчета
    // =====================================

    // Очищаем существующую структуру
    Настройки.Структура.Очистить();

    // Создаем группировку по организации
    ГруппировкаПоОрганизации = Настройки.Структура.Добавить(
        Тип("ГруппировкаКомпоновкиДанных")
    );

    // Устанавливаем поле группировки
    ГруппировкаПоОрганизации.Поле = Новый ПолеКомпоновкиДанных(
        "Ссылка.Организация"
    );

    // Тип группировки - Иерархия
    ГруппировкаПоОрганизации.ТипГруппировки = 
        ТипГруппировкиКомпоновкиДанных.Иерархия;

    // Тип дополнения - Без дополнения
    ГруппировкаПоОрганизации.ТипДополненияПериода = 
        ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Создаем группировку для детальных записей
    ДетальныеЗаписи = ГруппировкаПоОрганизации.Структура.Добавить(
        Тип("ГруппировкаКомпоновкиДанных")
    );

    // Устанавливаем поле - детальные записи (без группировки)
    ДетальныеЗаписи.Поле = Новый ПолеКомпоновкиДанных(
        "Ссылка"
    );

    // Тип группировки для детальных записей - только группы
    ДетальныеЗаписи.ТипГруппировки = 
        ТипГруппировкиКомпоновкиДанных.ТолькоИерархия;

    // =====================================
    // Настраиваем выбранные поля
    // =====================================

    // Очищаем выбранные поля
    Настройки.Выбор.Элементы.Очистить();

    // Добавляем поле "Организация" с измененным заголовком
    ПолеОрганизация = Настройки.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных")
    );
    ПолеОрганизация.Поле = Новый ПолеКомпоновкиДанных(
        "Ссылка.Организация"
    );
    ПолеОрганизация.Заголовок = "Организация";
    ПолеОрганизация.Использование = Истина;

    // Добавляем поле "Поставщик"
    ПолеПоставщик = Настройки.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных")
    );
    ПолеПоставщик.Поле = Новый ПолеКомпоновкиДанных("Поставщик");
    ПолеПоставщик.Использование = Истина;

    // Добавляем поле "Дата"
    ПолеДата = Настройки.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных")
    );
    ПолеДата.Поле = Новый ПолеКомпоновкиДанных("Дата");
    ПолеДата.Использование = Истина;

    // Добавляем поле "Сумма"
    ПолеСумма = Настройки.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных")
    );
    ПолеСумма.Поле = Новый ПолеКомпоновкиДанных("Сумма");
    ПолеСумма.Использование = Истина;

    // =====================================
    // Настраиваем параметры вывода
    // =====================================

    // Выводить параметры данных - Не выводить
    ПараметрВывода = Настройки.ПараметрыВывода.Элементы.Найти(
        "ВыводитьПараметрыДанных"
    );
    Если ПараметрВывода <> Неопределено Тогда
        ПараметрВывода.Использование = Истина;
        ПараметрВывода.Значение = РежимВыводаТекстаКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    // Выводить отбор - Не выводить
    ПараметрВывода = Настройки.ПараметрыВывода.Элементы.Найти(
        "ВыводитьОтбор"
    );
    Если ПараметрВывода <> Неопределено Тогда
        ПараметрВывода.Использование = Истина;
        ПараметрВывода.Значение = РежимВыводаТекстаКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    // Применяем настроенные настройки
    КомпоновщикНастроек.ЗагрузитьНастройки(Настройки);

    // =====================================
    // Формируем отчет
    // =====================================

    // Создаем компоновщик макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;

    // Создаем объект для расшифровки
    ДанныеРасшифровки = Новый ДанныеРасшифровкиКомпоновкиДанных;

    // Получаем макет компоновки
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        КомпоновщикНастроек.ПолучитьНастройки(),
        ДанныеРасшифровки
    );

    // Создаем процессор компоновки данных
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(
        МакетКомпоновки,
        ,
        ДанныеРасшифровки
    );

    // Создаем процессор вывода
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Результат);

    // Выводим результат
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    // Возвращаем сформированный табличный документ
    Возврат Результат;

КонецФункции

// Функция формирует аналитический отчет по задолженности предприятия перед поставщиками
//
// Параметры:
//   ДатаНач - Дата - Дата начала периода анализа (необязательно)
//   ДатаКон - Дата - Дата окончания периода анализа (необязательно)
//
// Возвращаемое значение:
//   ТаблицаЗначений - Таблица с колонками:
//     Поставщик, Наименование, СуммаПоставок, Оплачено, Долг
//
Функция СформироватьАнализЗадолженностиПоставщикам(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Создаем таблицу результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Поставщик",       Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    Результат.Колонки.Добавить("Наименование",    Новый ОписаниеТипов("Строка", , Новый КвалификаторыСтроки(150)));
    Результат.Колонки.Добавить("СуммаПоставок",  Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    Результат.Колонки.Добавить("Оплачено",        Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    Результат.Колонки.Добавить("Долг",           Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Проверка и установка параметров периода

    // Если ДатаНач не задана - значение по умолчанию (30 дней назад)
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДатаСеанса() - 30 * 86400); // 86400 - секунд в сутках
    КонецЕсли;

    // Проверка: ДатаКон не может быть меньше ДатаНач
    Если ДатаКон <> Неопределено И ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала!";
    КонецЕсли;

    // Если ДатаКон не задана - текущий день
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДатаСеанса());
    Иначе
        ДатаКон = КонецДня(ДатаКон);
    КонецЕсли;

    // Получаем ссылку на валюту Рубль
    ВалютаРубль = Справочники.Валюты.НайтиПоКоду("643"); // ОКВ (Общероссийский классификатор валют)

    Если ВалютаРубль.Пустая() Тогда
        // Альтернативный поиск по наименованию
        ЗапросВалюты = Новый Запрос;
        ЗапросВалюты.Текст = 
        "ВЫБРАТЬ ПЕРВЫЕ 1
        |    Валюты.Ссылка КАК Ссылка
        |ИЗ
        |    Справочник.Валюты КАК Валюты
        |ГДЕ
        |    Валюты.Наименование ПОДОБНО ""%Руб%""
        |    ИЛИ Валюты.Наименование ПОДОБНО ""%RUB%""";

        РезультатВалюты = ЗапросВалюты.Выполнить();
        Если НЕ РезультатВалюты.Пустой() Тогда
            ВалютаРубль = РезультатВалюты.Выбрать().Ссылка;
        КонецЕсли;
    КонецЕсли;

    // Запрос для получения сумм поставок по контрагентам с учетом курса валют
    ЗапросПоставки = Новый Запрос;
    ЗапросПоставки.Текст = 
    "ВЫБРАТЬ
    |    ПриходТовара.Поставщик КАК Поставщик,
    |    ПриходТовара.Поставщик.Наименование КАК Наименование,
    |    ЕСТЬNULL(Товары.СуммаОборот, 0) КАК СуммаВВалютеДокумента,
    |    ПриходТовара.Валюта КАК ВалютаДокумента,
    |    ПриходТовара.Дата КАК ДатаДокумента
    |ПОМЕСТИТЬ втПоставки
    |ИЗ
    |    Документ.ПриходТовара.Товары КАК Товары
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.ПриходТовара КАК ПриходТовара
    |        ПО Товары.Ссылка = ПриходТовара.Ссылка
    |ГДЕ
    |    ПриходТовара.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |    И ПриходТовара.Проведен
    |
    |ОБЪЕДИНИТЬ ВСЕ
    |
    |ВЫБРАТЬ
    |    ПриходТовара.Поставщик,
    |    ПриходТовара.Поставщик.Наименование,
    |    0,
    |    ЗНАЧЕНИЕ(Справочник.Валюты.ПустаяСсылка),
    |    ПриходТовара.Дата
    |ИЗ
    |    Документ.ПриходТовара КАК ПриходТовара
    |ГДЕ
    |    ПриходТовара.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |    И ПриходТовара.Проведен
    |    И ПриходТовара.Товары.Количество() = 0
    |
    |ИНДЕКСИРОВАТЬ ПО
    |    Поставщик,
    |    ВалютаДокумента,
    |    ДатаДокумента
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    втПоставки.Поставщик,
    |    втПоставки.Наименование,
    |    СУММА(втПоставки.СуммаВВалютеДокумента) КАК СуммаВВалютеДокумента,
    |    втПоставки.ВалютаДокумента,
    |    втПоставки.ДатаДокумента
    |ПОМЕСТИТЬ втСгруппированныеПоставки
    |ИЗ
    |    втПоставки
    |
    |СГРУППИРОВАТЬ ПО
    |    втПоставки.Поставщик,
    |    втПоставки.Наименование,
    |    втПоставки.ВалютаДокумента,
    |    втПоставки.ДатаДокумента
    |
    |ИНДЕКСИРОВАТЬ ПО
    |    Поставщик
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    втСгруппированныеПоставки.Поставщик,
    |    втСгруппированныеПоставки.Наименование,
    |    СУММА(втСгруппированныеПоставки.СуммаВВалютеДокумента) КАК СуммаВВалютеДокумента,
    |    МАКСИМУМ(КурсыВалют.Курс) КАК КурсВалюты
    |ПОМЕСТИТЬ втПоставкиСКурсами
    |ИЗ
    |    втСгруппированныеПоставки
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.КурсыВалют.СрезПоследних(
    |                &ДатаКон,
    |                Валюта В
    |                (ВЫБРАТЬ РАЗЛИЧНЫЕ ВалютаДокумента
    |                 ИЗ втСгруппированныеПоставки
    |                 ГДЕ ВалютаДокумента <> ЗНАЧЕНИЕ(Справочник.Валюты.ПустаяСсылка))) КАК КурсыВалют
    |        ПО (КурсыВалют.Валюта = втСгруппированныеПоставки.ВалютаДокумента)
    |           И (КурсыВалют.Период <= втСгруппированныеПоставки.ДатаДокумента)
    |
    |СГРУППИРОВАТЬ ПО
    |    втСгруппированныеПоставки.Поставщик,
    |    втСгруппированныеПоставки.Наименование
    |
    |ИНДЕКСИРОВАТЬ ПО
    |    Поставщик
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    втПоставкиСКурсами.Поставщик,
    |    втПоставкиСКурсами.Наименование,
    |    ВЫРАЗИТЬ(ВЫБОР
    |        КОГДА втПоставкиСКурсами.ВалютаДокумента = &ВалютаРубль
    |                ИЛИ втПоставкиСКурсами.ВалютаДокумента = ЗНАЧЕНИЕ(Справочник.Валюты.ПустаяСсылка)
    |            ТОГДА втПоставкиСКурсами.СуммаВВалютеДокумента
    |        КОГДА втПоставкиСКурсами.КурсВалюты = 0
    |            ТОГДА втПоставкиСКурсами.СуммаВВалютеДокумента
    |        ИНАЧЕ втПоставкиСКурсами.СуммаВВалютеДокумента / втПоставкиСКурсами.КурсВалюты
    |    КОНЕЦ КАК ЧИСЛО(15, 2)) КАК СуммаПоставок
    |ИЗ
    |    втПоставкиСКурсами
    |
    |УПОРЯДОЧИТЬ ПО
    |    СуммаПоставок УБЫВ
    |АВТОУПОРЯДОЧИВАНИЕ";

    // Устанавливаем параметры запроса поставок
    ЗапросПоставки.УстановитьПараметр("ДатаНач",     ДатаНач);
    ЗапросПоставки.УстановитьПараметр("ДатаКон",     ДатаКон);
    ЗапросПоставки.УстановитьПараметр("ВалютаРубль", ВалютаРубль);

    // Выполняем запрос поставок
    РезультатПоставки = ЗапросПоставки.Выполнить();

    Если РезультатПоставки.Пустой() Тогда
        Результат.Сортировать("Долг УБЫВ");
        Возврат Результат;
    КонецЕсли;

    // Запрос для получения сумм оплат из регистра Взаиморасчеты
    ЗапросОплаты = Новый Запрос;
    ЗапросОплаты.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОбороты.Контрагент КАК Контрагент,
    |    ВЫРАЗИТЬ(ВзаиморасчетыОбороты.СуммаОборот КАК ЧИСЛО(15, 2)) КАК Оплачено
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Обороты(
    |            &ДатаНач,
    |            &ДатаКон,
    |            ,
    |            Валюта = &ВалютаРубль
    |            И Контрагент В (&СписокКонтрагентов)) КАК ВзаиморасчетыОбороты
    |
    |УПОРЯДОЧИТЬ ПО
    |    Контрагент
    |АВТОУПОРЯДОЧИВАНИЕ";

    // Получаем список контрагентов из результата поставок
    СписокКонтрагентов = РезультатПоставки.Выгрузить().ВыгрузитьКолонку("Поставщик");

    // Устанавливаем параметры запроса оплат
    ЗапросОплаты.УстановитьПараметр("ДатаНач",           НачалоДня(ДатаНач));
    ЗапросОплаты.УстановитьПараметр("ДатаКон",           ДатаКон);
    ЗапросОплаты.УстановитьПараметр("ВалютаРубль",       ВалютаРубль);
    ЗапросОплаты.УстановитьПараметр("СписокКонтрагентов", СписокКонтрагентов);

    // Выполняем запрос оплат
    РезультатОплаты = ЗапросОплаты.Выполнить();

    // Создаем соответствие для быстрого поиска сумм оплат
    СоответствиеОплат = Новый Соответствие;

    Если НЕ РезультатОплаты.Пустой() Тогда
        ВыборкаОплат = РезультатОплаты.Выбрать();
        Пока ВыборкаОплат.Следующий() Цикл
            СоответствиеОплат.Вставить(ВыборкаОплат.Контрагент, ВыборкаОплат.Оплачено);
        КонецЦикла;
    КонецЕсли;

    // Формируем итоговую таблицу
    ВыборкаПоставки = РезультатПоставки.Выбрать();

    Пока ВыборкаПоставки.Следующий() Цикл

        Оплачено = СоответствиеОплат.Получить(ВыборкаПоставки.Поставщик);
        Если Оплачено = Неопределено Тогда
            Оплачено = 0;
        КонецЕсли;

        Долг = ВыборкаПоставки.СуммаПоставок - Оплачено;

        // Включаем в результат только контрагентов с положительной задолженностью
        Если Долг > 0 Тогда

            НоваяСтрока = Результат.Добавить();
            НоваяСтрока.Поставщик      = ВыборкаПоставки.Поставщик;
            НоваяСтрока.Наименование   = ВыборкаПоставки.Наименование;
            НоваяСтрока.СуммаПоставок  = ВыборкаПоставки.СуммаПоставок;
            НоваяСтрока.Оплачено       = Оплачено;
            НоваяСтрока.Долг           = Долг;

        КонецЕсли;

    КонецЦикла;

    // Сортируем по убыванию суммы долга
    Результат.Сортировать("Долг УБЫВ");

    Возврат Результат;

КонецФункции

Функция СформироватьОтчетПоОплатамНаОсновныеСчета() Экспорт

    // Получаем схему компоновки данных из макета отчета
    ОтчетОбъект = Отчеты.ДокументыОплата.СоздатьОтчетОбъект();

    // Получаем схему из макета компоновки данных
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("Основной");

    // Создаем компоновщик настроек на основании схемы
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));

    // Загружаем вариант "Основной"
    ВариантНастроек = СхемаКомпоновкиДанных.ВариантыНастроек.Найти("Основной");
    Если ВариантНастроек <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ВариантНастроек.Настройки);
    Иначе
        КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.ВариантыНастроек[0].Настройки);
    КонецЕсли;

    // Получаем настройки компоновки
    НастройкиКомпоновки = КомпоновщикНастроек.Настройки;

    // --- НАСТРОЙКА ВЫБРАННЫХ ПОЛЕЙ ---
    ВыбранныеПоля = НастройкиКомпоновки.Выбор;
    ВыбранныеПоля.Очистить();

    // Формируем выбранные поля
    ПолеОрганизация = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеОрганизация.Поле = Новый ПолеКомпоновкиДанных("Ссылка.Организация");
    ПолеОрганизация.Заголовок = "Организация";

    ПолеНомерСчета = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеНомерСчета.Поле = Новый ПолеКомпоновкиДанных("РасчетныйСчет.Номер");
    ПолеНомерСчета.Заголовок = "Номер счета";

    ПолеБанк = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеБанк.Поле = Новый ПолеКомпоновкиДанных("РасчетныйСчет.Банк");
    ПолеБанк.Заголовок = "Банк";

    ПолеПоставщик = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеПоставщик.Поле = Новый ПолеКомпоновкиДанных("Поставщик");

    ПолеДата = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеДата.Поле = Новый ПолеКомпоновкиДанных("Дата");

    ПолеСумма = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеСумма.Поле = Новый ПолеКомпоновкиДанных("Сумма");

    // --- НАСТРОЙКА ПАРАМЕТРОВ ВЫВОДА ---
    ПараметрыВывода = НастройкиКомпоновки.ПараметрыВывода;

    // Выводить параметры данных = Не выводить
    Буфер = ПараметрыВывода.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("ВыводитьПараметрыДанных"));
    Если Буфер <> Неопределено Тогда
        Буфер.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    // Выводить отбор = Не выводить
    Буфер = ПараметрыВывода.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("ВыводитьОтбор"));
    Если Буфер <> Неопределено Тогда
        Буфер.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    // --- НАСТРОЙКА ОТБОРА ---
    // Отбор: РасчетныйСчет.Наименование Подобно "Основной"
    Отбор = НастройкиКомпоновки.Отбор;

    ЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("РасчетныйСчет.Наименование");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.Подобно;
    ЭлементОтбора.ПравоеЗначение = "Основной";
    ЭлементОтбора.Использование = Истина;

    // --- КОМПОНОВКА И ВЫВОД ОТЧЕТА ---
    // Создаем процессор компоновки
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;

    // Получаем макет компоновки
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        НастройкиКомпоновки,
        ,
        ,
        Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииТабличныйДокумент")
    );

    // Создаем процессор результата
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    // Создаем процессор вывода в табличный документ
    Результат = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Результат);

    // Выводим результат
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    // Возвращаем табличный документ
    Возврат Результат;

КонецФункции

// Функция формирует отчет "ДокументыОплата" с заданными параметрами
//
// Параметры:
//  ДатаНачала     - Дата - Начало периода отчета
//  ДатаОкончания  - Дата - Конец периода отчета
//
// Возвращаемое значение:
//  ТабличныйДокумент - Сформированный отчет
//
Функция СформироватьОтчетПоОплатамЗаПериод(ДатаНачала, ДатаОкончания) Экспорт

	// Получаем объект отчета
	ОтчетОбъект = Отчеты.ДокументыОплата.СоздатьОтчет();

	// Инициализируем отчет
	ОтчетОбъект.ИнициализироватьОтчет();

	// Получаем схему компоновки данных из макета отчета
	СхемаКомпоновки = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

	// Получаем компоновщик настроек
	КомпоновщикНастроек = ОтчетОбъект.КомпоновщикНастроек;

	// Загружаем схему в компоновщик
	АдресСхемы = ПоместитьВоВременноеХранилище(СхемаКомпоновки, Новый УникальныйИдентификатор);
	КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(АдресСхемы));

	// Получаем настройки и очищаем их
	Настройки = КомпоновщикНастроек.Настройки;
	Настройки.ПараметрыДанных.Элементы.Очистить();

	// Устанавливаем параметры вывода
	ПараметрыВывода = Настройки.ПараметрыВывода;

	// Устанавливаем параметр "Выводить параметры данных" = Не выводить
	ПараметрВыводаПараметры = ПараметрыВывода.Элементы.Найти("ВыводитьПараметрыДанных");
	Если ПараметрВыводаПараметры <> Неопределено Тогда
		ПараметрВыводаПараметры.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
		ПараметрВыводаПараметры.Использование = Истина;
	КонецЕсли;

	// Устанавливаем параметр "Выводить отбор" = Не выводить
	ПараметрВыводаОтбор = ПараметрыВывода.Элементы.Найти("ВыводитьОтбор");
	Если ПараметрВыводаОтбор <> Неопределено Тогда
		ПараметрВыводаОтбор.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
		ПараметрВыводаОтбор.Использование = Истина;
	КонецЕсли;

	// Устанавливаем параметр "ДатаНачала"
	ПараметрДатаНачала = Настройки.ПараметрыДанных.Элементы.Добавить();
	ПараметрДатаНачала.Параметр = Новый ПараметрКомпоновкиДанных("ДатаНачала");
	ПараметрДатаНачала.Значение = ДатаНачала;
	ПараметрДатаНачала.Использование = Истина;

	// Устанавливаем параметр "ДатаОкончания"
	ПараметрДатаОкончания = Настройки.ПараметрыДанных.Элементы.Добавить();
	ПараметрДатаОкончания.Параметр = Новый ПараметрКомпоновкиДанных("ДатаОкончания");
	ПараметрДатаОкончания.Значение = ДатаОкончания;
	ПараметрДатаОкончания.Использование = Истина;

	// Получаем отборы
	Отборы = Настройки.Отбор.Элементы;

	// Очищаем все существующие отборы
	Отборы.Очистить();

	// Добавляем отбор: Дата >= ДатаНачала
	ЭлементОтбораДатаНачала = Отборы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
	ЭлементОтбораДатаНачала.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Дата");
	ЭлементОтбораДатаНачала.ВидСравнения = ВидСравненияКомпоновкиДанных.БольшеИлиРавно;
	ЭлементОтбораДатаНачала.ПравоеЗначение = ДатаНачала;
	ЭлементОтбораДатаНачала.Использование = Истина;

	// Добавляем отбор: Дата <= ДатаОкончания
	ЭлементОтбораДатаОкончания = Отборы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
	ЭлементОтбораДатаОкончания.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Дата");
	ЭлементОтбораДатаОкончания.ВидСравнения = ВидСравненияКомпоновкиДанных.МеньшеИлиРавно;
	ЭлементОтбораДатаОкончания.ПравоеЗначение = ДатаОкончания;
	ЭлементОтбораДатаОкончания.Использование = Истина;

	// Устанавливаем выбранные поля
	ВыбранныеПоля = Настройки.Выбор.Элементы;
	ВыбранныеПоля.Очистить();

	// Добавляем поле "Поставщик"
	ПолеПоставщик = ВыбранныеПоля.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
	ПолеПоставщик.Поле = Новый ПолеКомпоновкиДанных("Поставщик");
	ПолеПоставщик.Использование = Истина;

	// Добавляем поле "Дата"
	ПолеДата = ВыбранныеПоля.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
	ПолеДата.Поле = Новый ПолеКомпоновкиДанных("Дата");
	ПолеДата.Использование = Истина;

	// Добавляем поле "Сумма"
	ПолеСумма = ВыбранныеПоля.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
	ПолеСумма.Поле = Новый ПолеКомпоновкиДанных("Сумма");
	ПолеСумма.Использование = Истина;

	// Формируем отчет
	Результат = Новый ТабличныйДокумент;

	// Компилируем макеты
	КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
	МакетКомпоновки = КомпоновщикМакета.Выполнить(
		СхемаКомпоновки,
		Настройки,
		,
		,
		ТипГенератораКомпоновкиДанных.ФорматированныйДокумент
	);

	// Создаем процессор компоновки
	ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
	ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

	// Создаем процессор вывода
	ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
	ПроцессорВывода.УстановитьДокумент(Результат);

	// Выводим результат
	ПроцессорВывода.НачатьВывод();
	ПроцессорВывода.ЗакончитьВывод();

	Возврат Результат;

КонецФункции

// Функция формирует ТОП-10 самых продаваемых товаров за указанный период
//
// Параметры:
//   ДатаНач - Дата - дата начала периода анализа (по умолчанию: 30 дней назад)
//   ДатаКон - Дата - дата окончания периода анализа (по умолчанию: конец текущего дня)
//
// Возвращает:
//   ТаблицаЗначений с колонками:
//     * Товар           - ссылка на товар
//     * КоличествоПродаж - общее количество проданных единиц
//     * СуммаПродаж      - общая сумма продаж
//
// Исключения:
//   - если ДатаКон < ДатаНач выбрасывается исключение
//
Функция СформироватьТоп10ПродаваемыхТоваров(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка значений по умолчанию для дат
    ТекущаяДата = ТекущаяДата();

    Если ДатаНач = Неопределено Тогда
        ДатаНач = ТекущаяДата - 30 * 24 * 60 * 60; // 30 дней назад
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата); // Конец текущего дня
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода!";
    КонецЕсли;

    // Формирование запроса к оборотному регистру "Продажи"
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ ПЕРВЫЕ 10
    |    ПродажиОбороты.Товар,
    |    ПродажиОбороты.КоличествоОборот КАК КоличествоПродаж,
    |    ПродажиОбороты.СуммаОборот КАК СуммаПродаж
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, , Товар <> ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка)) КАК ПродажиОбороты
    |УПОРЯДОЧИТЬ ПО
    |    КоличествоПродаж УБЫВ
    |";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполнение запроса
    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений для результата
    ТабРезультат = Новый ТаблицаЗначений;
    ТабРезультат.Колонки.Добавить("Товар");
    ТабРезультат.Колонки.Добавить("КоличествоПродаж");
    ТабРезультат.Колонки.Добавить("СуммаПродаж");

    // Обход результатов запроса и заполнение таблицы значений
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТабРезультат.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.КоличествоПродаж = Выборка.КоличествоПродаж;
        НоваяСтрока.СуммаПродаж = Выборка.СуммаПродаж;
    КонецЦикла;

    Возврат ТабРезультат;

КонецФункции

// Функция формирует отчет "ДинамикаПродаж" с условным оформлением
// строк, для которых сумма продаж соответствует заданному уровню.
//
// Параметры:
//  ДатаНачала     - Дата - начало периода отчета
//  ДатаОкончания  - Дата - окончание периода отчета
//  УровеньПродаж  - Число - желаемый уровень продаж для условного оформления
//
// Возвращаемое значение:
//  ТабличныйДокумент - результат формирования отчета
//
// Пример текста запроса, используемого в СКД отчета:
// Запрос.Текст = 
// "ВЫБРАТЬ
// |    ПродажиОбороты.Период КАК Период,
// |    ПродажиОбороты.СуммаОборот КАК СуммаОборот
// |{ВЫБРАТЬ
// |    Период,
// |    СуммаОборот}
// |ИЗ
// |    РегистрНакопления.Продажи.Обороты(&ДатаНачала, &ДатаОкончания, Авто, ) 
// |        КАК ПродажиОбороты
// |{УПОРЯДОЧИТЬ ПО
// |    Период}
// |ИТОГИ
// |    СУММА(СуммаОборот)
// |ПО
// |    Период
// |";

&НаСервере
Функция СформироватьОтчетЖелаемыйУровеньПродаж(ДатаНачала, ДатаОкончания, УровеньПродаж) Экспорт

    // Получаем схему компоновки данных из отчета "ДинамикаПродаж"
    СхемаКомпоновкиДанных = Отчеты.ДинамикаПродаж.ПолучитьМакет("СуммаИКоличество");

    // Создаем и инициализируем компоновщик настроек
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    ИсточникДоступныхНастроек = Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных);
    КомпоновщикНастроек.Инициализировать(ИсточникДоступныхНастроек);

    // Загружаем настройки варианта "СуммаИКоличество"
    КомпоновщикНастроек.ЗагрузитьНастройки(
        СхемаКомпоновкиДанных.ВариантыНастроек.СуммаИКоличество.Настройки
    );

    // Получаем текущие настройки
    Настройки = КомпоновщикНастроек.ПолучитьНастройки();

    // Подменяем стандартную структуру (диаграмму) на группировку по полю "Период"
    СтруктураОтчета = Настройки.Структура;
    СтруктураОтчета.Очистить();

    // Создаем новую группировку
    Группировка = СтруктураОтчета.Добавить(Тип("ГруппировкаКомпоновкиДанных"));

    // Настраиваем поле группировки "Период"
    ПолеГруппировки = Группировка.ПоляГруппировки

Функция СформироватьОтчетПродажиСуммированиеТолькоТоваров(ДатаНачала, ДатаОкончания) Экспорт

    // Получаем отчет и его схему компоновки данных
    ОтчетОбъект = Отчеты.ДинамикаПродаж.Создать();
    Схема = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создаем компоновщик настроек на основании схемы
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(Схема));

    // Загружаем вариант отчета
    ВариантОтчета = Схема.ВариантыНастроек.Найти("ПродажиТоваровПоПокупателям");
    Если ВариантОтчета <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ВариантОтчета.Настройки);
    Иначе
        КомпоновщикНастроек.ЗагрузитьНастройки(Схема.НастройкиПоУмолчанию);
    КонецЕсли;

    // Получаем настройки для редактирования
    Настройки = КомпоновщикНастроек.Настройки;

    // Очищаем стандартную структуру
    Настройки.Структура.Очистить();

    // Создаем корневую группировку для общего итога
    КорневаяГруппировка = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));

    // Добавляем группировку Покупатель
    ГруппировкаПокупатель = КорневаяГруппировка.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаПокупатель.Имя = "Покупатель";

    ПараметрыГруппировки = ГруппировкаПокупатель.ПараметрыВывода;
    УстановитьПараметрВывода(ПараметрыГруппировки, "ТипГруппировки", 
        ТипГруппировкиКомпоновкиДанных.Элементы);
    УстановитьПараметрВывода(ПараметрыГруппировки, "ТипДополнения", 
        ТипДополненияПериодаКомпоновкиДанных.БезДополнения);

    // Добавляем поле СуммаОборот для группировки Покупатель
    ПолеСуммаОборот = ГруппировкаПокупатель.Выбор.Элементы.Добавить(Тип("ПолеКомпоновкиДанных"));
    ПолеСуммаОборот.Поле = Новый ПолеКомпоновкиДанных("СуммаОборот");

    // Добавляем группировку Товар
    ГруппировкаТовар = ГруппировкаПокупатель.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаТовар.Имя = "Товар";

    ПараметрыГруппировкиТовар = ГруппировкаТовар.ПараметрыВывода;
    УстановитьПараметрВывода(ПараметрыГруппировкиТовар, "ТипГруппировки", 
        ТипГруппировкиКомпоновкиДанных.Элементы);
    УстановитьПараметрВывода(ПараметрыГруппировкиТовар, "ТипДополнения", 
        ТипДополненияПериодаКомпоновкиДанных.БезДополнения);

    // Добавляем поле СуммаОборот для группировки Товар
    ПолеСуммаОборотТовар = ГруппировкаТовар.Выбор.Элементы.Добавить(Тип("ПолеКомпоновкиДанных"));
    ПолеСуммаОборотТовар.Поле = Новый ПолеКомпоновкиДанных("СуммаОборот");

    // Очищаем стандартные поля итога
    Настройки.ПоляИтога.Очистить();

    // Добавляем поле итога для группировки Покупатель и ОбщийИтог
    // Суммирование только товаров (исключаем услуги)
    ПолеИтогаПокупатель = Настройки.ПоляИтога.Добавить();
    ПолеИтогаПокупатель.ПутьКДанным = "СуммаОборот";
    ПолеИтогаПокупатель.Выражение = "СУММА(ВычислитьВыражениеСГруппировкойМассив(""СУММА(СуммаОборот)"", ""Товар"", ""Не Товар.Вид = ЗНАЧЕНИЕ(Перечисление.ВидыТоваров.Услуга)"")";
	ПолеИтогаПокупатель.Группировки.Добавить(Новый ПолеКомпоновкиДанных("Покупатель"));
    ПолеИтогаПокупатель.Группировки.Добавить(Новый ПолеКомпоновкиДанных("ОбщийИтог"));

    // Добавляем поле итога для группировки Товар
    ПолеИтогаТовар = Настройки.ПоляИтога.Добавить();
    ПолеИтогаТовар.ПутьКДанным = "СуммаОборот";
    ПолеИтогаТовар.Выражение = "СУММА(СуммаОборот)";
    ПолеИтогаТовар.Группировки.Добавить(Новый ПолеКомпоновкиДанных("Товар"));

    // Устанавливаем параметры отчета - Период
    ПараметрПериод = КомпоновщикНастроек.Настройки.ПараметрыДанных.Элементы.Найти("Период");
    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Использование = Истина;
        ПараметрПериод.Значение.ДатаНачала = ДатаНачала;
        ПараметрПериод.Значение.ДатаОкончания = ДатаОкончания;
    КонецЕсли;

    // Устанавливаем параметры вывода
    ПараметрыВывода = Настройки.ПараметрыВывода;

    ПараметрВыводаПараметрыДанных = ПараметрыВывода.Элементы.Найти("ВыводитьПараметрыДанных");
    Если ПараметрВыводаПараметрыДанных <> Неопределено Тогда
        ПараметрВыводаПараметрыДанных.Использование = Истина;
        ПараметрВыводаПараметрыДанных.Значение = Ложь;
    КонецЕсли;

    ПараметрВыводаОтбор = ПараметрыВывода.Элементы.Найти("ВыводитьОтбор");
    Если ПараметрВыводаОтбор <> Неопределено Тогда
        ПараметрВыводаОтбор.Использование = Истина;
        ПараметрВыводаОтбор.Значение = Ложь;
    КонецЕсли;

    // Формируем отчет
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    ДанныеРасшифровки = Новый ДанныеРасшифровкиКомпоновкиДанных;

    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        Схема,
        Настройки,
        ДанныеРасшифровки,
        ,
        Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений")
    );

    // Создаем процессор компоновки и выводим результат
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки, , ДанныеРасшифровки);

    ТабДок = Новый ТабличныйДокумент;

    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабДок);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабДок;

КонецФункции

// Вспомогательная процедура для установки параметров вывода группировки
Процедура УстановитьПараметрВывода(ПараметрыВывода, ИмяПараметра, Значение)

    НайденныйПараметр = ПараметрыВывода.Элементы.Найти(ИмяПараметра);
    Если НайденныйПараметр <> Неопределено Тогда
        НайденныйПараметр.Использование = Истина;
        НайденныйПараметр.Значение = Значение;
    КонецЕсли;

КонецПроцедуры

// Функция формирует отчет "ДинамикаПродаж" с вариантом "СуммаИКоличество"
// Параметры:
//   ДатаНачала - Дата - начало периода отчета
//   ДатаОкончания - Дата - окончание периода отчета
// Возвращаемое значение:
//   ТабличныйДокумент - сформированный отчет
//
Функция СформироватьОтчетПродажиТовараНаДень(ДатаНачала, ДатаОкончания) Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ДинамикаПродаж.СоздатьОтчет();

    // Получаем настройки компоновщика
    Настройки = ОтчетОбъект.КомпоновщикНастроек.Настройки;

    // Загружаем вариант отчета "СуммаИКоличество"
    ВариантНастроек = ОтчетОбъект.СхемаКомпоновкиДанных.ВариантыНастроек.Найти("СуммаИКоличество");
    Если ВариантНастроек <> Неопределено Тогда
        ОтчетОбъект.КомпоновщикНастроек.ЗагрузитьНастройки(ВариантНастроек.Настройки);
    КонецЕсли;

    // Получаем обновленные настройки после загрузки варианта
    Настройки = ОтчетОбъект.КомпоновщикНастроек.Настройки;

    // Настраиваем структуру отчета
    Структура = Настройки.Структура;
    Структура.Очистить();

    // Группировка "Период"
    ГруппировкаПериод = Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаПериод.Поле = Новый ПолеКомпоновкиДанных("Период");
    ГруппировкаПериод.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаПериод.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Вложенная группировка "Товар"
    ВложеннаяСтруктура = ГруппировкаПериод.Структура;
    ГруппировкаТовар = ВложеннаяСтруктура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");
    ГруппировкаТовар.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаТовар.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Устанавливаем параметры отчета "Период"
    ПараметрыДанных = ОтчетОбъект.КомпоновщикНастроек.ПараметрыДанных;

    // Находим параметр "Период" и устанавливаем значения
    ПараметрПериод = ПараметрыДанных.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("Период"));
    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Значение = Новый СтандартныйПериод(ДатаНачала, ДатаОкончания);
        ПараметрПериод.Использование = Истина;
    КонецЕсли;

    // Настраиваем параметры вывода
    ПараметрыВывода = ОтчетОбъект.КомпоновщикНастроек.ПараметрыВывода;

    // ВыводитьПараметрыДанных = Не выводить
    ПараметрВыводитьПараметрыДанных = ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьПараметрыДанных"));
    Если ПараметрВыводитьПараметрыДанных <> Неопределено Тогда
        ПараметрВыводитьПараметрыДанных.Значение = РежимВыводаГруппировкиКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    // ВыводитьОтбор = Не выводить
    ПараметрВыводитьОтбор = ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьОтбор"));
    Если ПараметрВыводитьОтбор <> Неопределено Тогда
        ПараметрВыводитьОтбор.Значение = РежимВыводаГруппировкиКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    // Формируем отчет
    Результат = Новый ТабличныйДокумент;

    ОтчетОбъект.СформироватьОтчет(
        Результат,
        ОтчетОбъект.КомпоновщикНастроек.Настройки,
        ,
        Истина
    );

    Возврат Результат;

КонецФункции

// Функция формирует отчет по взаиморасчетам с подсветкой строк,
// где сумма расходов превышает сумму приходов
//
// Параметры:
//   ДатаНачала - Дата - начало периода отчета
//   ДатаОкончания - Дата - окончание периода отчета
//
// Возвращаемое значение:
//   ТабличныйДокумент - сформированный отчет
//
Функция СформироватьОтчетВзаиморасчетыПодсветитьРасход(ДатаНачала, ДатаОкончания) Экспорт

    // Создаем объект отчета
    Отчет = Отчеты.ОтчетПоВзаиморасчетам.Создать();

    // Получаем компоновщик настроек отчета
    КомпоновщикНастроек = Отчет.КомпоновщикНастроек;

    // Загружаем вариант отчета "Основной"
    ОсновнойВариант = Неопределено;
    Для Каждого Вариант Из Отчет.СхемаКомпоновкиДанных.ВариантыНастроек Цикл
        Если Вариант.Имя = "Основной" Тогда
            ОсновнойВариант = Вариант;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Если ОсновнойВариант <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ОсновнойВариант.Настройки);
    КонецЕсли;

    // Устанавливаем параметры периода отчета
    ПараметрПериод = КомпоновщикНастроек.Настройки.ПараметрыДанных.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("Период"));

    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Использование = Истина;
        ПараметрПериод.Значение.ДатаНачала = ДатаНачала;
        ПараметрПериод.Значение.ДатаОкончания = ДатаОкончания;
    КонецЕсли;

    // Настраиваем выбранные поля: СуммаПриход, СуммаРасход
    КомпоновщикНастроек.Настройки.Выбор.Элементы.Очистить();

    ВыбранноеПолеПриход = КомпоновщикНастроек.Настройки.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбранноеПолеПриход.Поле = Новый ПолеКомпоновкиДанных("СуммаПриход");
    ВыбранноеПолеПриход.Использование = Истина;

    ВыбранноеПолеРасход = КомпоновщикНастроек.Настройки.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбранноеПолеРасход.Поле = Новый ПолеКомпоновкиДанных("СуммаРасход");
    ВыбранноеПолеРасход.Использование = Истина;

    // Настраиваем параметры вывода
    ПараметрВыводаПараметрыДанных = КомпоновщикНастроек.Настройки.ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьПараметрыДанных"));

    Если ПараметрВыводаПараметрыДанных <> Неопределено Тогда
        ПараметрВыводаПараметрыДанных.Использование = Истина;
        ПараметрВыводаПараметрыДанных.Значение = Ложь;
    КонецЕсли;

    ПараметрВыводаОтбор = КомпоновщикНастроек.Настройки.ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьОтбор"));

    Если ПараметрВыводаОтбор <> Неопределено Тогда
        ПараметрВыводаОтбор.Использование = Истина;
        ПараметрВыводаОтбор.Значение = Ложь;
    КонецЕсли;

    // Добавляем условное оформление для подсветки строк
    ЭлементОформления = КомпоновщикНастроек.Настройки.УсловноеОформление.Элементы.Добавить();
    ЭлементОформления.Использование = Истина;

    // Устанавливаем цвет фона - зеленый RGB(0, 150, 30)
    ЭлементОформления.Оформление.УстановитьЗначениеПараметра(
        "ЦветФона", 
        Новый Цвет(0, 150, 30));

    // Настраиваем отбор: СуммаРасход > СуммаПриход
    ЭлементОтбора = ЭлементОформления.Отбор.Элементы.Добавить(
        Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СуммаРасход");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.Больше;
    ЭлементОтбора.ПравоеЗначение = Новый ПолеКомпоновкиДанных("СуммаПриход");
    ЭлементОтбора.Использование = Истина;

    // Добавляем поля для оформления
    ОформляемоеПолеПриход = ЭлементОформления.Поля.Элементы.Добавить();
    ОформляемоеПолеПриход.Поле = Новый ПолеКомпоновкиДанных("СуммаПриход");
    ОформляемоеПолеПриход.Использование = Истина;

    ОформляемоеПолеРасход = ЭлементОформления.Поля.Элементы.Добавить();
    ОформляемоеПолеРасход.Поле = Новый ПолеКомпоновкиДанных("СуммаРасход");
    ОформляемоеПолеРасход.Использование = Истина;

    // Настраиваем использование условного оформления
    ЭлементОформления.ИспользованиеВЗаголовкеПолейРесурсов = Ложь;
    ЭлементОформления.ИспользованиеВОбщемИтоге = Ложь;

    // Получаем настройки для формирования
    Настройки = КомпоновщикНастроек.ПолучитьНастройки();

    // Создаем компоновщик макета и формируем макет компоновки
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        Отчет.СхемаКомпоновкиДанных, 
        Настройки, 
        ДанныеРасшифровки);

    // Создаем процессор компоновки данных
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки, , ДанныеРасшифровки, Истина);

    // Создаем процессор вывода результата
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Результат);

    // Формируем табличный документ
    Результат = Новый ТабличныйДокумент;
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат Результат;

КонецФункции

// Функция формирует отчет по взаиморасчетам с округлением сумм до целых
//
// Параметры:
//   ДатаНачала - Дата - Начало периода отчета
//   ДатаОкончания - Дата - Окончание периода отчета
//
// Возвращаемое значение:
//   ТабличныйДокумент - Сформированный отчет
//
Функция СформироватьОтчетВзаиморасчетыБезКопеек(ДатаНачала, ДатаОкончания) Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ОтчетПоВзаиморасчетам.Создать();

    // Получаем компоновщик настроек
    КомпоновщикНастроек = ОтчетОбъект.КомпоновщикНастроек;

    // Загружаем вариант отчета "Основной"
    ВариантОтчета = НайтиВариантОтчета(КомпоновщикНастроек, "Основной");
    Если ВариантОтчета <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ВариантОтчета.Настройки);
    КонецЕсли;

    // Получаем настройки компоновки данных
    НастройкиКомпоновки = КомпоновщикНастроек.Настройки;

    // Устанавливаем параметры отчета "Период"
    ПараметрПериод = КомпоновщикНастроек.Параметры.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("Период"));

    Если ПараметрПериод <> Неопределено Тогда

        // Формируем структуру периода
        СтруктураПериода = Новый Структура("ДатаНачала, ДатаОкончания",
            ДатаНачала, ДатаОкончания);

        ПараметрПериод.Значение = СтруктураПериода;
        ПараметрПериод.Использование = Истина;

    КонецЕсли;

    // Настраиваем выбранные поля: СуммаПриход, СуммаРасход
    НастройкиКомпоновки.Выбор.Элементы.Очистить();

    // Поле СуммаПриход
    ВыбранноеПолеПриход = НастройкиКомпоновки.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбранноеПолеПриход.Поле = Новый ПолеКомпоновкиДанных("СуммаПриход");
    ВыбранноеПолеПриход.Использование = Истина;

    // Поле СуммаРасход
    ВыбранноеПолеРасход = НастройкиКомпоновки.Выбор.Элементы.Добавить(
        Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбранноеПолеРасход.Поле = Новый ПолеКомпоновкиДанных("СуммаРасход");
    ВыбранноеПолеРасход.Использование = Истина;

    // Настраиваем параметры вывода
    ПараметрВыводаВыводПараметров = НастройкиКомпоновки.ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьПараметрыДанных"));
    Если ПараметрВыводаВыводПараметров <> Неопределено Тогда
        ПараметрВыводаВыводПараметров.Значение = РежимВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаВыводПараметров.Использование = Истина;
    КонецЕсли;

    ПараметрВыводаВыводОтбора = НастройкиКомпоновки.ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьОтбор"));
    Если ПараметрВыводаВыводОтбора <> Неопределено Тогда
        ПараметрВыводаВыводОтбора.Значение = РежимВыводаТекстаКомпоновкиДанных.НеВыводить;
        ПараметрВыводаВыводОтбора.Использование = Истина;
    КонецЕсли;

    // Настраиваем условное оформление: Формат = "ЧЦ=10" для суммовых полей
    // Оформление для СуммаПриход
    ЭлементОформленияПриход = НастройкиКомпоновки.УсловноеОформление.Элементы.Добавить();
    ЭлементОформленияПриход.Использование = Истина;

    // Отбор условного оформления
    ЭлементОтбораПриход = ЭлементОформленияПриход.Отбор.Элементы.Добавить(
        Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбораПриход.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СуммаПриход");
    ЭлементОтбораПриход.ВидСравнения = ВидСравненияКомпоновкиДанных.Заполнено;
    ЭлементОтбораПриход.Использование = Истина;

    // Устанавливаем формат
    ЭлементОформленияПриход.Оформление.УстановитьЗначениеПараметра(
        "Формат", "ЧЦ=10");

    // Применяем к полю СуммаПриход
    ОформляемоеПолеПриход = ЭлементОформленияПриход.Поля.Элементы.Добавить();
    ОформляемоеПолеПриход.Поле = Новый ПолеКомпоновкиДанных("СуммаПриход");
    ОформляемоеПолеПриход.Использование = Истина;

    // Оформление для СуммаРасход
    ЭлементОформленияРасход = НастройкиКомпоновки.УсловноеОформление.Элементы.Добавить();
    ЭлементОформленияРасход.Использование = Истина;

    // Отбор условного оформления
    ЭлементОтбораРасход = ЭлементОформленияРасход.Отбор.Элементы.Добавить(
        Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбораРасход.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СуммаРасход");
    ЭлементОтбораРасход.ВидСравнения = ВидСравненияКомпоновкиДанных.Заполнено;
    ЭлементОтбораРасход.Использование = Истина;

    // Устанавливаем формат
    ЭлементОформленияРасход.Оформление.УстановитьЗначениеПараметра(
        "Формат", "ЧЦ=10");

    // Применяем к полю СуммаРасход
    ОформляемоеПолеРасход = ЭлементОформленияРасход.Поля.Элементы.Добавить();
    ОформляемоеПолеРасход.Поле = Новый ПолеКомпоновкиДанных("СуммаРасход");
    ОформляемоеПолеРасход.Использование = Истина;

    // Создаем табличный документ для результата
    РезультатОтчета = Новый ТабличныйДокумент;

    // Инициализируем процессор компоновки
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;

    Попытка

        // Получаем схему компоновки из макета отчета
        МакетКомпоновки = КомпоновщикМакета.Выполнить(
            ОтчетОбъект.СхемаКомпоновкиДанных,
            НастройкиКомпоновки,
            ,
            ,
            Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

        // Создаем процессор компоновки
        ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
        ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

        // Создаем процессор вывода
        ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
        ПроцессорВывода.УстановитьДокумент(РезультатОтчета);

        // Выводим результат
        ПроцессорВывода.Вывести(ПроцессорКомпоновки, Истина);

    Исключение

        // Обработка ошибок формирования отчета
        ИнформацияОбОшибке = ИнформацияОбОшибке();

        СообщениеОбОшибке = Новый СообщениеПользователю;
        СообщениеОбОшибке.Текст = "Ошибка формирования отчета: " 
            + ПодробноеПредставлениеОшибки(ИнформацияОбОшибке);
        СообщениеОбОшибке.Сообщить();

        ВызватьИсключение ИнформацияОбОшибке.Описание;

    КонецПопытки;

    Возврат РезультатОтчета;

КонецФункции

// Вспомогательная функция для поиска варианта отчета по наименованию
//
// Параметры:
//   КомпоновщикНастроек - КомпоновщикНастроекКомпоновкиДанных
//   НаименованиеВарианта - Строка - Наименование искомого варианта
//
// Возвращаемое значение:
//   ВариантНастройкиКоманды - Найденный вариант или Неопределено
//
Функция НайтиВариантОтчета(КомпоновщикНастроек, НаименованиеВарианта)

    Если КомпоновщикНастроек = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    ВариантыОтчета = КомпоновщикНастроек.ВариантыНастроек;

    Для Каждого Вариант Из ВариантыОтчета Цикл
        Если ВРег(Вариант.Наименование) = ВРег(НаименованиеВарианта) Тогда
            Возврат Вариант;
        КонецЕсли;
    КонецЦикла;

    Возврат Неопределено;

КонецФункции

Функция СформироватьОтчетВзаиморасчетыДобавитьКолонкуРазница(ДатаНачала, ДатаОкончания) Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ОтчетПоВзаиморасчетам.Создать();

    // Получаем компоновщик настроек
    КомпоновщикНастроек = ОтчетОбъект.КомпоновщикНастроек;

    // Загружаем вариант отчета "Основной"
    ВариантОтчета = Неопределено;
    Для Каждого Вариант Из КомпоновщикНастроек.ВариантыНастроек Цикл
        Если Вариант.Наименование = "Основной" Тогда
            ВариантОтчета = Вариант;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Если ВариантОтчета <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ВариантОтчета.Настройки);
    КонецЕсли;

    // Получаем настройки
    Настройки = КомпоновщикНастроек.Настройки;

    // Получаем схему компоновки данных
    Схема = ОтчетОбъект.СхемаКомпоновкиДанных;

    // Добавляем вычисляемое поле "Разница"
    ВычисляемоеПоле = Настройки.ВычисляемыеПоля.Добавить();
    ВычисляемоеПоле.ПутьКДанным = "Разница";
    ВычисляемоеПоле.Заголовок = "Разница";
    ВычисляемоеПоле.Выражение = "СуммаПриход - СуммаРасход";
    ВычисляемоеПоле.ТипЗначения = Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2));

    // Добавляем поле в поля итога
    ПолеИтога = Настройки.ПоляИтога.Добавить();
    ПолеИтога.ПутьКДанным = "Разница";
    ПолеИтога.Выражение = "Сумма(Разница)";
    ПолеИтога.Использование = Истина;

    // Устанавливаем параметры периода
    ПараметрПериод = Настройки.ПараметрыДанных.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("Период"));
    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Значение = Новый СтандартныйПериод(ДатаНачала, ДатаОкончания);
        ПараметрПериод.Использование = Истина;
    КонецЕсли;

    // Альтернативный вариант - если параметры периода раздельные
    ПараметрДатаНачала = Настройки.ПараметрыДанных.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("ДатаНачала"));
    Если ПараметрДатаНачала <> Неопределено Тогда
        ПараметрДатаНачала.Значение = ДатаНачала;
        ПараметрДатаНачала.Использование = Истина;
    КонецЕсли;

    ПараметрДатаОкончания = Настройки.ПараметрыДанных.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("ДатаОкончания"));
    Если ПараметрДатаОкончания <> Неопределено Тогда
        ПараметрДатаОкончания.Значение = ДатаОкончания;
        ПараметрДатаОкончания.Использование = Истина;
    КонецЕсли;

    // Настраиваем выбранные поля
    ВыбранныеПоля = Настройки.Выбор;
    ВыбранныеПоля.Элементы.Очистить();

    // Добавляем поле СуммаПриход
    ПолеСуммаПриход = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеСуммаПриход.Поле = Новый ПолеКомпоновкиДанных("СуммаПриход");
    ПолеСуммаПриход.Заголовок = "Сумма приход";

    // Добавляем поле СуммаРасход
    ПолеСуммаРасход = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеСуммаРасход.Поле = Новый ПолеКомпоновкиДанных("СуммаРасход");
    ПолеСуммаРасход.Заголовок = "Сумма расход";

    // Добавляем вычисляемое поле Разница
    ПолеРазница = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеРазница.Поле = Новый ПолеКомпоновкиДанных("Разница");
    ПолеРазница.Заголовок = "Разница";

    // Настраиваем параметры вывода
    ПараметрВыводаПараметры = Настройки.ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьПараметрыДанных"));
    Если ПараметрВыводаПараметры <> Неопределено Тогда
        ПараметрВыводаПараметры.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    ПараметрВыводаОтбор = Настройки.ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьОтбор"));
    Если ПараметрВыводаОтбор <> Неопределено Тогда
        ПараметрВыводаОтбор.Значение = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
    КонецЕсли;

    // Формируем отчет
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных();

    // Выполняем компоновку
    Макет = КомпоновщикМакета.Выполнить(
        Схема,
        Настройки,
        ,
        ,
        Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    // Создаем процессор компоновки
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных();
    ПроцессорКомпоновки.Инициализировать(Макет);

    // Создаем табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;

    // Создаем процессор вывода
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент();
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

Функция СформироватьОтчетОстаткиВыводРеквизитовТовара() Экспорт

    // Получаем отчет
    ОтчетОбъект = Отчеты.ОстаткиТоваровНаСкладах.СоздатьОбъект();

    // Получаем схему компоновки данных из макета отчета
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Получаем вариант отчета "Основной" из хранилища вариантов отчетов
    ВариантОтчета = Справочники.ВариантыОтчетов.НайтиПоРеквизиту(
        "КлючОбъекта", 
        "Отчет.ОстаткиТоваровНаСкладах"
    );

    Если ВариантОтчета = Неопределено Тогда
        ВызватьИсключение "Не найден вариант отчета ""Основной"" для отчета ""ОстаткиТоваровНаСкладах""";
    КонецЕсли;

    // Находим именно вариант "Основной" среди найденных
    ЗапросВариантов = Новый Запрос;
    ЗапросВариантов.Текст = 
    "ВЫБРАТЬ
    |    ВариантыОтчетов.Ссылка
    |ИЗ
    |    Справочник.ВариантыОтчетов КАК ВариантыОтчетов
    |ГДЕ
    |    ВариантыОтчетов.КлючОбъекта = &КлючОбъекта
    |    И ВариантыОтчетов.Наименование = &Наименование
    |    И НЕ ВариантыОтчетов.ПометкаУдаления";
    ЗапросВариантов.УстановитьПараметр("КлючОбъекта", "Отчет.ОстаткиТоваровНаСкладах");
    ЗапросВариантов.УстановитьПараметр("Наименование", "Основной");

    РезультатЗапроса = ЗапросВариантов.Выполнить();
    Если РезультатЗапроса.Пустой() Тогда
        ВызватьИсключение "Вариант отчета ""Основной"" не найден";
    КонецЕсли;

    ВариантОтчета = РезультатЗапроса.Выбрать().ПолучитьОбъект();

    // Создаем компоновщик настроек и инициализируем его
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    ИсточникНастроек = Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных);
    КомпоновщикНастроек.Инициализировать(ИсточникНастроек);

    // Загружаем настройки из варианта отчета
    КомпоновщикНастроек.ЗагрузитьНастройки(ВариантОтчета.Настройки);

    // Получаем структуру настроек
    Настройки = КомпоновщикНастроек.Настройки;

    // Настраиваем структуру: группировка по Товару
    // Очищаем текущую структуру
    Настройки.Структура.Очистить();

    // Создаем новую группировку по Товару
    ГруппировкаТовар = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));

    // Настраиваем поле группировки
    ПолеГруппировки = ГруппировкаТовар.ПоляГруппировки.Элементы.Добавить(Тип("ПолеГруппировкиКомпоновкиДанных"));
    ПолеГруппировки.Поле = Новый ПолеКомпоновкиДанных("Товар");
    ПолеГруппировки.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ПолеГруппировки.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Настраиваем выбранные поля
    ВыбранныеПоля = Настройки.Выбор;
    ВыбранныеПоля.Элементы.Очистить();

    // Поле "Товар"
    ПолеТовар = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");

    // Группа колонок "Свойства" с расположением в отдельной колонке
    ГруппаКолонокСвойства = ВыбранныеПоля.Элементы.Добавить(Тип("ГруппаВыбранныхПолейКомпоновкиДанных"));
    ГруппаКолонокСвойства.Заголовок = "Свойства";
    ГруппаКолонокСвойства.Расположение = РасположениеРеквизитовВСтрокеТаблицы.ОтдельнаяКолонка;

    // Поле "Товар.Артикул" с заголовком "Артикул"
    ПолеАртикул = ГруппаКолонокСвойства.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеАртикул.Поле = Новый ПолеКомпоновкиДанных("Товар.Артикул");
    ПолеАртикул.Заголовок = "Артикул";

    // Поле "Товар.ФайлКартинки.ДанныеФайла" с заголовком "Изображение"
    ПолеИзображение = ГруппаКолонокСвойства.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеИзображение.Поле = Новый ПолеКомпоновкиДанных("Товар.ФайлКартинки.ДанныеФайла");
    ПолеИзображение.Заголовок = "Изображение";

    // Поле "КоличествоОстаток"
    ПолеКоличество = ВыбранныеПоля.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеКоличество.Поле = Новый ПолеКомпоновкиДанных("КоличествоОстаток");

    // Параметры вывода: не выводить параметры данных и отбор
    ПараметрыВывода = Настройки.ПараметрыВывода;
    ПараметрыВывода.УстановитьЗначениеПараметра(
        "ВыводитьПараметрыДанных", 
        РежимВыводаТекстаКнопки.НеВыводить
    );
    ПараметрыВывода.УстановитьЗначениеПараметра(
        "ВыводитьОтбор", 
        РежимВыводаТекстаКнопки.НеВыводить
    );

    // Формируем отчет
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;

    // Генерируем макет компоновки
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        КомпоновщикНастроек.ПолучитьНастройки()
    );

    // Создаем процессор компоновки и выполняем его
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    // Создаем табличный документ и выводим в него результат
    ДокументРезультат = Новый ТабличныйДокумент;

    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ДокументРезультат);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ДокументРезультат;

КонецФункции

// Функция формирует таблицу дублирующихся заказов покупателей
//
// Параметры:
//  ДатаНач - Дата - дата начала периода анализа (по умолчанию - начало текущего дня)
//  ДатаКон - Дата - дата окончания периода анализа (по умолчанию - конец текущего дня)
//
// Возвращаемое значение:
//  ТаблицаЗначений - таблица с колонками:
//   * Покупатель - СправочникСсылка.Контрагенты - покупатель с дублями
//   * ДатаЗаказа - Дата - дата заказов
//   * КоличествоЗаказов - Число - количество заказов за этот день
//
Функция СформироватьДублирующиесяЗаказы(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Устанавливаем параметры периода по умолчанию
    ТекущаяДата = ТекущаяДатаСеанса();

    Если ДатаНач = Неопределено Тогда
        ДатаНачала = НачалоДня(ТекущаяДата);
    Иначе
        ДатаНачала = НачалоДня(ДатаНач);
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаОкончания = КонецДня(ТекущаяДата);
    Иначе
        ДатаОкончания = КонецДня(ДатаКон);
    КонецЕсли;

    // Создаём запрос для выборки данных
    Запрос = Новый Запрос;

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

    // Формируем текст запроса
    Запрос.Текст =
    "ВЫБРАТЬ
    |    Заказы.Покупатель КАК Покупатель,
    |    НАЧАЛОПЕРИОДА(Заказы.Дата, ДЕНЬ) КАК ДатаЗаказа,
    |    КОЛИЧЕСТВО(Заказы.Ссылка) КАК КоличествоЗаказов
    |ИЗ
    |    Документ.Заказ КАК Заказы
    |ГДЕ
    |    Заказы.Дата >= &ДатаНачала
    |    И Заказы.Дата <= &ДатаОкончания
    |    И Заказы.Проведен = ИСТИНА
    |
    |СГРУППИРОВАТЬ ПО
    |    Заказы.Покупатель,
    |    НАЧАЛОПЕРИОДА(Заказы.Дата, ДЕНЬ)
    |
    |ИМЕЮЩИЕ
    |    КОЛИЧЕСТВО(Заказы.Ссылка) > 1
    |
    |УПОРЯДОЧИТЬ ПО
    |    Покупатель,
    |    ДатаЗаказа";

    // Выполняем запрос и получаем результат
    РезультатЗапроса = Запрос.Выполнить();

    // Создаём таблицу значений для результата
    ТаблицаДублей = Новый ТаблицаЗначений;
    ТаблицаДублей.Колонки.Добавить("Покупатель", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    ТаблицаДублей.Колонки.Добавить("ДатаЗаказа", Новый ОписаниеТипов("Дата"));
    ТаблицаДублей.Колонки.Добавить("КоличествоЗаказов", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 0)));

    // Если запрос вернул данные, выгружаем их в таблицу значений
    Если НЕ РезультатЗапроса.Пустой() Тогда
        ТаблицаДублей = РезультатЗапроса.Выгрузить();
    КонецЕсли;

    Возврат ТаблицаДублей;

КонецФункции

// Функция формирует отчет "ОстаткиТоваровНаСкладах" с измененными заголовками колонок
//
// Возвращаемое значение:
//   ТабличныйДокумент - сформированный отчет
//
Функция СформироватьОтчетОстаткиИзменитьЗаголовокКолонкиОстаток() Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ОстаткиТоваровНаСкладах.Создать();

    // Получаем основную схему компоновки данных
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создаем компоновщик настроек и инициализируем его
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    ИсточникДоступныхНастроек = Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных);
    КомпоновщикНастроек.Инициализировать(ИсточникДоступныхНастроек);

    // Загружаем настройки по умолчанию
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.НастройкиПоУмолчанию);

    // Устанавливаем вариант отчета "Основной"
    ОсновнойВариант = СхемаКомпоновкиДанных.ВариантыНастроек.Найти("Основной");
    Если ОсновнойВариант <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ОсновнойВариант.Настройки);
    КонецЕсли;

    // Получаем коллекцию условного оформления
    УсловноеОформление = КомпоновщикНастроек.Настройки.УсловноеОформление;

    // Устанавливаем условное оформление для основного заголовка поля
    ЭлементОформления = УсловноеОформление.Элементы.Добавить();
    ЭлементОформления.Использование = Истина;

    // Оформление: Текст = "Остаток на складе"
    ЭлементОформления.Оформление.УстановитьЗначениеПараметра("Текст", "Остаток на складе");

    // Оформляемое поле: КоличествоОстаток
    ОформляемоеПоле = ЭлементОформления.Поля.Элементы.Добавить();
    ОформляемоеПоле.Поле = Новый ПолеКомпоновкиДанных("КоличествоОстаток");
    ОформляемоеПоле.Использование = Истина;

    // Область использования: В заголовке полей ресурсов
    ЭлементОформления.ОбластьИспользования = ИспользованиеПараметраКомпоновкиДанных.ВЗаголовкеПолейРесурсов;

    // Устанавливаем условное оформление для заголовка поля в общем итоге
    ЭлементОформленияОбщийИтог = УсловноеОформление.Элементы.Добавить();
    ЭлементОформленияОбщийИтог.Использование = Истина;

    // Оформление: Текст = "Количество"
    ЭлементОформленияОбщийИтог.Оформление.УстановитьЗначениеПараметра("Текст", "Количество");

    // Оформляемое поле: КоличествоОстаток
    ОформляемоеПолеОбщее = ЭлементОформленияОбщийИтог.Поля.Элементы.Добавить();
    ОформляемоеПолеОбщее.Поле = Новый ПолеКомпоновкиДанных("КоличествоОстаток");
    ОформляемоеПолеОбщее.Использование = Истина;

    // Область использования: В заголовке полей ресурсов общего итога
    ЭлементОформленияОбщийИтог.ОбластьИспользования = ИспользованиеПараметраКомпоновкиДанных.ВЗаголовкеПолейРесурсовОбщегоИтога;

    // Устанавливаем параметры вывода
    ПараметрыВывода = КомпоновщикНастроек.Настройки.ПараметрыВывода;

    // ВыводитьПараметрыДанных = Не выводить
    ПараметрВывода = ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьПараметрыДанных"));
    Если ПараметрВывода <> Неопределено Тогда
        ПараметрВывода.Значение = Ложь;
        ПараметрВывода.Использование = Истина;
    КонецЕсли;

    // ВыводитьОтбор = Не выводить
    ПараметрВывода = ПараметрыВывода.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("ВыводитьОтбор"));
    Если ПараметрВывода <> Неопределено Тогда
        ПараметрВывода.Значение = Ложь;
        ПараметрВывода.Использование = Истина;
    КонецЕсли;

    // Получаем ссылку на отчет
    ОтчетСсылка = Отчеты.ОстаткиТоваровНаСкладах.ПустаяСсылка();

    // Создаем и настраиваем компоновщик макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;

    // Выполняем компоновку макета
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        СхемаКомпоновкиДанных,
        КомпоновщикНастроек.ПолучитьНастройки(),
        ,
        ,
        Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    // Создаем внешний набор данных (если требуется)
    ВнешниеНаборыДанных = Новый Структура;

    // Создаем процессор компоновки данных
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(
        МакетКомпоновки,
        ВнешниеНаборыДанных,
        ,
        Истина);

    // Создаем табличный документ для результата
    ДокументРезультат = Новый ТабличныйДокумент;

    // Создаем процессор вывода результата
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ДокументРезультат);

    // Выводим результат компоновки в табличный документ
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    // Возвращаем сформированный табличный документ
    Возврат ДокументРезультат;

КонецФункции

// Функция ищет настройку в пользовательских настройках компоновщика по заданным свойствам
//
// Параметры:
//   стрНастройки - Структура - свойства поиска:
//       * ВидНастройки - Строка - вид настройки (Выбор, ПараметрВывода, ПараметрДанных, Отбор, Порядок, Группировка)
//       * ИмяНастройки - Строка - имя поля у элемента настроек
//   КомпоновщикНастроек - КомпоновщикНастроекКомпоновкиДанных - компоновщик настроек
//
// Возвращаемое значение:
//   Элемент из КоллекцияЭлементовПользовательскихНастроекКомпоновкиДанных - найденная настройка
//   Неопределено - настройка не найдена
//
Функция НайтиНастройкуКомпоновщика(стрНастройки, КомпоновщикНастроек) Экспорт

    // Проверка обязательных параметров структуры
    Если НЕ стрНастройки.Свойство("ВидНастройки") 
        ИЛИ НЕ стрНастройки.Свойство("ИмяНастройки") Тогда
        Возврат Неопределено;
    КонецЕсли;

    ВидНастройки = стрНастройки.ВидНастройки;
    ИмяНастройки = стрНастройки.ИмяНастройки;

    // Проверка на пустые значения
    Если ПустаяСтрока(ВидНастройки) ИЛИ ПустаяСтрока(ИмяНастройки) Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Проверка компоновщика
    Если КомпоновщикНастроек = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    КоллекцияЭлементов = КомпоновщикНастроек.ПользовательскиеНастройки.Элементы;

    Для Каждого ЭлементНастройки Из КоллекцияЭлементов Цикл

        ТекущаяНастройка = ЭлементНастройки.Настройка;

        // Пропускаем элементы без настройки
        Если ТекущаяНастройка = Неопределено Тогда
            Продолжить;
        КонецЕсли;

        // Определяем соответствие типа настройки заданному виду
        Если ВидНастройки = "ПараметрДанных" Тогда

            // Параметры данных - ЗначениеПараметраКомпоновкиДанных
            Если ТипЗнч(ТекущаяНастройка) = Тип("ЗначениеПараметраКомпоновкиДанных") Тогда

                Если ТекущаяНастройка.Параметр <> Неопределено 
                    И ТекущаяНастройка.Параметр.Имя = ИмяНастройки Тогда
                    Возврат ЭлементНастройки;
                КонецЕсли;

            КонецЕсли;

        ИначеЕсли ВидНастройки = "ПараметрВывода" Тогда

            // Параметры вывода - ПараметрВыводаКомпоновкиДанных
            Если ТипЗнч(ТекущаяНастройка) = Тип("ПараметрВыводаКомпоновкиДанных") Тогда

                Если ТекущаяНастройка.Параметр <> Неопределено 
                    И ТекущаяНастройка.Параметр.Имя = ИмяНастройки Тогда
                    Возврат ЭлементНастройки;
                КонецЕсли;

            КонецЕсли;

        ИначеЕсли ВидНастройки = "Выбор" Тогда

            // Выбор полей - ЭлементВыбораКомпоновкиДанных
            Если ТипЗнч(ТекущаяНастройка) = Тип("ЭлементВыбораКомпоновкиДанных") Тогда

                Если ТекущаяНастройка.Поле <> Неопределено 
                    И Строка(ТекущаяНастройка.Поле) = ИмяНастройки Тогда
                    Возврат ЭлементНастройки;
                КонецЕсли;

            КонецЕсли;

        ИначеЕсли ВидНастройки = "Отбор" Тогда

            // Отбор - ЭлементОтбораКомпоновкиДанных
            Если ТипЗнч(ТекущаяНастройка) = Тип("ЭлементОтбораКомпоновкиДанных") Тогда

                Если ТекущаяНастройка.ЛевоеЗначение <> Неопределено 
                    И Строка(ТекущаяНастройка.ЛевоеЗначение) = ИмяНастройки Тогда
                    Возврат ЭлементНастройки;
                КонецЕсли;

            КонецЕсли;

        ИначеЕсли ВидНастройки = "Порядок" Тогда

            // Сортировка - ЭлементПорядкаКомпоновкиДанных
            Если ТипЗнч(ТекущаяНастройка) = Тип("ЭлементПорядкаКомпоновкиДанных") Тогда

                Если ТекущаяНастройка.Поле <> Неопределено 
                    И Строка(ТекущаяНастройка.Поле) = ИмяНастройки Тогда
                    Возврат ЭлементНастройки;
                КонецЕсли;

            КонецЕсли;

        ИначеЕсли ВидНастройки = "Группировка" Тогда

            // Группировка - ЭлементГруппировкиКомпоновкиДанных
            Если ТипЗнч(ТекущаяНастройка) = Тип("ЭлементГруппировкиКомпоновкиДанных") Тогда

                Если ТекущаяНастройка.Поле <> Неопределено 
                    И Строка(ТекущаяНастройка.Поле) = ИмяНастройки Тогда
                    Возврат ЭлементНастройки;
                КонецЕсли;

            КонецЕсли;

        ИначеЕсли ВидНастройки = "УсловноеОформление" Тогда

            // Условное оформление - ЭлементУсловногоОформленияКомпоновкиДанных
            Если ТипЗнч(ТекущаяНастройка) = Тип("ЭлементУсловногоОформленияКомпоновкиДанных") Тогда

                // Для условного оформления ищем по представлению или第一个 полю
                Если ТекущаяНастройка.Представление = ИмяНастройки Тогда
                    Возврат ЭлементНастройки;
                КонецЕсли;

                // Дополнительно проверяем поля условия
                Для Каждого ОформляемоеПоле Из ТекущаяНастройка.ОформляемыеПоля Цикл
                    Если Строка(ОформляемоеПоле.Поле) = ИмяНастройки Тогда
                        Возврат ЭлементНастройки;
                    КонецЕсли;
                КонецЦикла;

            КонецЕсли;

        КонецЕсли;

    КонецЦикла;

    Возврат Неопределено;

КонецФункции

Функция СформироватьИсториюИзмененияЦен(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка значений по умолчанию для дат
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата());
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Создание запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЦеныТоваров.Товар,
    |    ЦеныТоваров.ВидЦен,
    |    ЦеныТоваров.Период КАК ДатаИзменения,
    |    ЦеныТоваров.Цена
    |ИЗ
    |    РегистрСведений.ЦеныТоваров.СрезПоследних(&КонДата, ) КАК ЦеныТоваров
    |ГДЕ
    |    ЦеныТоваров.Период >= &НачДата
    |УПОРЯДОЧИТЬ ПО
    |    ЦеныТоваров.Товар,
    |    ДатаИзменения";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("НачДата", ДатаНач);
    Запрос.УстановитьПараметр("КонДата", ДатаКон);

    // Выполнение запроса и возврат результата
    РезультатЗапроса = Запрос.Выполнить();

    Возврат РезультатЗапроса.Выгрузить();

КонецФункции

// Функция получает значение свойства доступного поля компоновки данных
//
// Параметры:
//   СтруктураКД - КомпоновщикНастроекКомпоновкиДанных, ДоступныеПоляКомпоновкиДанных
//   Поле - Строка, ПолеКомпоновкиДанных - Путь к полю или объект поля
//   Свойство - Строка - Имя свойства, значение которого необходимо получить
//
// Возвращаемое значение:
//   Произвольный - Значение свойства поля или Неопределено
//
Функция ПолучитьСвойствоДоступногоПоля(СтруктураКД, Поле, Свойство) Экспорт

    // Проверка обязательных параметров
    Если СтруктураКД = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Определяем коллекцию доступных полей
    ДоступныеПоля = Неопределено;

    Если ТипЗнч(СтруктураКД) = Тип("КомпоновщикНастроекКомпоновкиДанных") Тогда
        ДоступныеПоля = СтруктураКД.Настройки.ДоступныеПоляВыбора;
    ИначеЕсли ТипЗнч(СтруктураКД) = Тип("ДоступныеПоляКомпоновкиДанных") Тогда
        ДоступныеПоля = СтруктураКД;
    Иначе
        Возврат Неопределено;
    КонецЕсли;

    Если ДоступныеПоля = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Получаем путь к полю
    ПутьКДанным = "";

    Если ТипЗнч(Поле) = Тип("Строка") Тогда
        ПутьКДанным = СокрЛП(Поле);
    ИначеЕсли ТипЗнч(Поле) = Тип("ПолеКомпоновкиДанных") Тогда
        ПутьКДанным = СокрЛП(Поле.ПутьКДанным);
    КонецЕсли;

    Если ПустаяСтрока(ПутьКДанным) Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Находим поле в коллекции доступных полей
    НайденноеПоле = ДоступныеПоля.НайтиПоле(ПутьКДанным);

    Если НайденноеПоле = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Получаем значение запрашиваемого свойства
    ВозвращаемоеЗначение = Неопределено;

    Попытка
        ВозвращаемоеЗначение = Вычислить("НайденноеПоле." + Свойство);
    Исключение
        ВозвращаемоеЗначение = Неопределено;
    КонецПопытки;

    Возврат ВозвращаемоеЗначение;

КонецФункции

// Функция формирует рекомендуемый объём заказа товаров у поставщиков
// на основе анализа продаж и текущих остатков.
//
// Параметры:
//   ДатаНач - Дата - дата начала периода анализа продаж (по умолчанию 30 дней назад)
//   ДатаКон - Дата - дата окончания периода анализа продаж (по умолчанию конец текущего дня)
//
// Возвращает:
//   ТаблицаЗначений - с колонками: Товар, Продано, Остаток, РекомендуемыйЗаказ
//
Функция СформироватьРекомендуемыйЗаказ(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Определение текущей даты один раз
    ТекущаяДата = ТекущаяДата();

    // Установка параметров дат по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата - 30 * 24 * 60 * 60); // 30 дней назад от начала текущего дня
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата); // Конец текущего дня
    КонецЕсли;

    // Создание запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ
        |    ПродажиОбороты.Товар КАК Товар,
        |    ЕСТЬNULL(ПродажиОбороты.КоличествоОборот, 0) КАК Продано,
        |    ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК Остаток
        |ПОМЕСТИТЬ втТоварыСДанными
        |ИЗ
        |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, , ) КАК ПродажиОбороты
        |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварныеЗапасы.Остатки(&МоментПолучения, , ) КАК ТоварныеЗапасыОстатки
        |        ПО ПродажиОбороты.Товар = ТоварныеЗапасыОстатки.Товар
        |;
        |////////////////////////////////////////////////////////////////////////////////
        |ВЫБРАТЬ
        |    втТоварыСДанными.Товар КАК Товар,
        |    втТоварыСДанными.Продано,
        |    втТоварыСДанными.Остаток,
        |    ВЫБОР
        |        КОГДА втТоварыСДанными.Продано - втТоварыСДанными.Остаток > 0
        |            ТОГДА втТоварыСДанными.Продано - втТоварыСДанными.Остаток
        |        ИНАЧЕ 0
        |    КАК РекомендуемыйЗаказ
        |ИЗ
        |    втТоварыСДанными
        |ГДЕ
        |    втТоварыСДанными.Продано - втТоварыСДанными.Остаток > 0
        |УПОРЯДОЧИТЬ ПО
        |    РекомендуемыйЗаказ УБЫВ
        |АВТОУПОРЯДОЧИВАНИЕ";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Запрос.УстановитьПараметр("МоментПолучения", КонецДня(ТекущаяДата));

    // Выполнение запроса и возврат результата
    РезультатЗапроса = Запрос.Выполнить();

    Если РезультатЗапроса.Пустой() Тогда
        ПустаяТаблица = Новый ТаблицаЗначений;
        ПустаяТаблица.Колонки.Добавить("Товар");
        ПустаяТаблица.Колонки.Добавить("Продано", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
        ПустаяТаблица.Колонки.Добавить("Остаток", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
        ПустаяТаблица.Колонки.Добавить("РекомендуемыйЗаказ", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
        Возврат ПустаяТаблица;
    КонецЕсли;

    Возврат РезультатЗапроса.Выгрузить();

КонецФункции

// Функция проверяет заполненность реквизитов объекта и его табличных частей
// Параметры:
//   Объект - ДокументОбъект, СправочникОбъект - проверяемый объект
//   МассивПроверяемыхРеквизитов - Массив Из Строка - массив проверяемых реквизитов
// Возвращаемое значение:
//   Булево - Ложь, если значение хотя бы одного реквизита не заполнено, иначе Истина
Функция ПроверитьЗаполнениеРеквизитовОбъекта(Объект, МассивПроверяемыхРеквизитов) Экспорт

    Для Каждого ИмяРеквизита Из МассивПроверяемыхРеквизитов Цикл

        // Определяем тип реквизита по наличию точки
        Если СтрНайти(ИмяРеквизита, ".") > 0 Тогда

            // Реквизит табличной части (формат: "ИмяТЧ.ИмяРеквизита")
            ПозицияТочки = СтрНайти(ИмяРеквизита, ".");
            ИмяТабличнойЧасти = Лев(ИмяРеквизита, ПозицияТочки - 1);
            ИмяРеквизитаТЧ = Сред(ИмяРеквизита, ПозицияТочки + 1);

            // Получаем метаданные табличной части
            МетаданныеОбъекта = Объект.Метаданные();

            // Проверяем существование табличной части
            Если НЕ МетаданныеОбъекта.ТабличныеЧасти.Найти(ИмяТабличнойЧасти) <> Неопределено Тогда
                Продолжить; // Табличная часть не найдена, пропускаем
            КонецЕсли;

            // Проверяем существование реквизита табличной части
            РеквизитТЧ = МетаданныеОбъекта.ТабличныеЧасти[ИмяТабличнойЧасти].Реквизиты.Найти(ИмяРеквизитаТЧ);
            Если РеквизитТЧ = Неопределено Тогда
                Продолжить; // Реквизит табличной части не найден, пропускаем
            КонецЕсли;

            // Получаем коллекцию строк табличной части
            ТабличнаяЧасть = Объект[ИмяТабличнойЧасти];

            // Проверяем заполненность реквизита во всех строках табличной части
            Для Каждого СтрокаТЧ Из ТабличнаяЧасть Цикл
                Значение = СтрокаТЧ[ИмяРеквизитаТЧ];
                Если НЕ ЗначениеЗаполнено(Значение) Тогда
                    Возврат Ложь;
                КонецЕсли;
            КонецЦикла;

        Иначе

            // Реквизит объекта
            // Проверяем существование реквизита в метаданных
            МетаданныеОбъекта = Объект.Метаданные();

            // Проверяем в реквизитах
            Если МетаданныеОбъекта.Реквизиты.Найти(ИмяРеквизита) <> Неопределено Тогда
                Значение = Объект[ИмяРеквизита];
                Если НЕ ЗначениеЗаполнено(Значение) Тогда
                    Возврат Ложь;
                КонецЕсли;
            ИначеЕсли МетаданныеОбъекта.СтандартныеРеквизиты.Найти(ИмяРеквизита) <> Неопределено Тогда
                // Стандартный реквизит
                Значение = Объект[ИмяРеквизита];
                Если НЕ ЗначениеЗаполнено(Значение) Тогда
                    Возврат Ложь;
                КонецЕсли;
            КонецЕсли;

        КонецЕсли;

    КонецЦикла;

    Возврат Истина;

КонецФункции

// Функция формирует таблицу пересортицы товаров
//
// Параметры:
//   ДатаНач - Дата - дата начала периода анализа (по умолчанию 30 дней назад)
//   ДатаКон - Дата - дата окончания периода анализа (по умолчанию конец текущего дня)
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками:
//     * Товар       - СправочникСсылка.Товары
//     * Продано     - Число - количество проданного товара
//     * Остаток     - Число - текущий остаток товара
//     * Пересортица - Число - разница (Продано - Остаток)
//
Функция СформироватьПересортицу(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Устанавливаем параметры периода
    ТекущаяДата = ТекущаяДата();

    Если ДатаНач = Неопределено Тогда
        ДатаНачала = НачалоДня(ТекущаяДата - 30 * 86400); // 30 дней назад
    Иначе
        ДатаНачала = НачалоДня(ДатаНач);
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаОкончания = КонецДня(ТекущаяДата); // Конец текущего дня
    Иначе
        ДатаОкончания = КонецДня(ДатаКон);
    КонецЕсли;

    // Создаём запрос для получения данных о продажах и остатках
    Запрос = Новый Запрос;

    Запрос.Текст =
    "ВЫБРАТЬ
    |   ПродажиОбороты.Товар,
    |   ПродажиОбороты.КоличествоОборот КАК Продано,
    |   ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК Остаток,
    |   ПродажиОбороты.КоличествоОборот - ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК Пересортица
    |ПОМЕСТИТЬ ВремТаблица
    |ИЗ
    |   РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, , ) КАК ПродажиОбороты
    |       ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаКон, , ) КАК ТоварныеЗапасыОстатки
    |       ПО ПродажиОбороты.Товар = ТоварныеЗапасыОстатки.Товар
    |ГДЕ
    |   ПродажиОбороты.КоличествоОборот - ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) > 0
    |УПОРЯДОЧИТЬ ПО
    |   Пересортица УБЫВ
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |   ВремТаблица.Товар,
    |   ВремТаблица.Продано,
    |   ВремТаблица.Остаток,
    |   ВремТаблица.Пересортица
    |ИЗ
    |   ВремТаблица КАК ВремТаблица
    |УПОРЯДОЧИТЬ ПО
    |   ВремТаблица.Пересортица УБЫВ";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаКон", ДатаОкончания);

    // Выполняем запрос и возвращаем результат
    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаПересортицы = Новый ТаблицаЗначений;
    ТаблицаПересортицы.Колонки.Добавить("Товар",       Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаПересортицы.Колонки.Добавить("Продано",     Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаПересортицы.Колонки.Добавить("Остаток",     Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаПересортицы.Колонки.Добавить("Пересортица", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    Если НЕ РезультатЗапроса.Пустой() Тогда
        ТаблицаПересортицы = РезультатЗапроса.Выгрузить();
    КонецЕсли;

    Возврат ТаблицаПересортицы;

КонецФункции

// Функция возвращает последний элемент структуры настроек компоновки данных.
// 
// Параметры:
//  НастройкиКД - КомпоновщикНастроекКомпоновкиДанных, НастройкиКомпоновкиДанных - 
//                элемент структуры настроек компоновки данных.
//  ПолучитьСтроки - Булево - признак для получения строк/серий или колонок/точек:
//                    Истина - для таблицы вернуть Строки, для диаграммы вернуть Серии.
//                    Ложь - для таблицы вернуть Колонки, для диаграммы вернуть Точки.
//
// Возвращаемое значение:
//  ГруппировкаКомпоновкиДанных, ГруппировкаТаблицыКомпоновкиДанных, 
//  ГруппировкаДиаграммыКомпоновкиДанных, КоллекцияЭлементовСтруктурыТаблицыКомпоновкиДанных,
//  КоллекцияЭлементовСтруктурыДиаграммыКомпоновкиДанных, Неопределено.
//
Функция ПолучитьПоследнийЭлементСтруктуры(НастройкиКД, ПолучитьСтроки) Экспорт

    // Определяем настройки
    Настройки = Неопределено;

    ТипНастроек = ТипЗнч(НастройкиКД);

    Если ТипНастроек = Тип("КомпоновщикНастроекКомпоновкиДанных") Тогда
        Настройки = НастройкиКД.Настройки;
    ИначеЕсли ТипНастроек = Тип("НастройкиКомпоновкиДанных") Тогда
        Настройки = НастройкиКД;
    КонецЕсли;

    // Если настройки не получены, возвращаем Неопределено
    Если Настройки = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Получаем коллекцию структуры
    СтруктураНастроек = Настройки.Структура;

    // Проверяем наличие элементов в структуре
    Если СтруктураНастроек.Количество() = 0 Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Получаем последний элемент структуры
    ПоследнийЭлемент = СтруктураНастроек[СтруктураНастроек.Количество() - 1];

    // Возвращаем элемент в зависимости от его типа
    ТипЭлемента = ТипЗнч(ПоследнийЭлемент);

    Если ТипЭлемента = Тип("ГруппировкаКомпоновкиДанных") Тогда
        // Для группировки возвращаем саму группировку
        Возврат ПоследнийЭлемент;

    ИначеЕсли ТипЭлемента = Тип("ТаблицаКомпоновкиДанных") Тогда
        // Для таблицы возвращаем строки или колонки
        Если ПолучитьСтроки Тогда
            Возврат ПоследнийЭлемент.Строки;
        Иначе
            Возврат ПоследнийЭлемент.Колонки;
        КонецЕсли;

    ИначеЕсли ТипЭлемента = Тип("ДиаграммаКомпоновкиДанных") Тогда
        // Для диаграммы возвращаем серии или точки
        Если ПолучитьСтроки Тогда
            Возврат ПоследнийЭлемент.Серии;
        Иначе
            Возврат ПоследнийЭлемент.Точки;
        КонецЕсли;

    Иначе
        // Для неизвестного типа возвращаем Неопределено
        Возврат Неопределено;

    КонецЕсли;

КонецФункции

// Функция анализа сезонности продаж по месяцам
//
// Параметры:
//   ДатаНач - Дата - дата начала периода анализа (по умолчанию - начало текущего года)
//   ДатаКон - Дата - дата окончания периода анализа (по умолчанию - конец текущего года)
//
// Возвращаемое значение:
//   ТаблицаЗначений - с колонками:
//     * ПериодМесяца - Дата - начало месяца (первое число месяца)
//     * КоличествоПродано - Число - общее количество проданных товаров
//     * СуммаПродаж - Число - общая сумма продаж (выручка)
//
Функция СформироватьАнализСезонностиПродаж(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Устанавливаем параметры периода по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДата());
    Иначе
        ДатаНач = НачалоДня(ДатаНач);
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецГода(ТекущаяДата());
    Иначе
        ДатаКон = КонецДня(ДатаКон);
    КонецЕсли;

    // Формируем текст запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    НАЧАЛОПЕРИОДА(Продажи.Период, МЕСЯЦ) КАК ПериодМесяца,
    |    СУММА(Продажи.Количество) КАК КоличествоПродано,
    |    СУММА(Продажи.Сумма) КАК СуммаПродаж
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, Авто, ) КАК Продажи
    |СГРУППИРОВАТЬ ПО
    |    НАЧАЛОПЕРИОДА(Продажи.Период, МЕСЯЦ)
    |УПОРЯДОЧИТЬ ПО
    |    ПериодМесяца";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполняем запрос и возвращаем результат
    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаРезультат = РезультатЗапроса.Выгрузить();

    Возврат ТаблицаРезультат;

КонецФункции

// Находит поле в структуре настроек компоновки данных.
//
// Параметры:
//  СтруктураКД - Коллекция элементов структуры настроек СКД
//  Поле - Строка или ПолеКомпоновкиДанных - имя/поле для поиска
//  ВключаяВложенныеПоля - Булево - признак поиска во вложенных структурах
//
// Возвращаемое значение:
//  Булево - Истина, если поле найдено
//
Функция НайтиПолеВСтуктуреКД(СтруктураКД, Поле, ВключаяВложенныеПоля = Ложь) Экспорт

    ИмяПоля = ПолучитьИмяПоляКомпоновки(Поле);

    Если Не ЗначениеЗаполнено(ИмяПоля) Тогда
        Возврат Ложь;
    КонецЕсли;

    Возврат НайтиПолеРекурсивноКД(СтруктураКД, ИмяПоля, ВключаяВложенныеПоля);

КонецФункции

// Получает имя поля из строки или объекта ПолеКомпоновкиДанных
Функция ПолучитьИмяПоляКомпоновки(Поле) Экспорт

    ТипЗначения = ТипЗнч(Поле);

    Если ТипЗначения = Тип("Строка") Тогда
        Возврат СокрЛП(Поле);
    ИначеЕсли ТипЗначения = Тип("ПолеКомпоновкиДанных") Тогда
        Возврат СокрЛП(Поле.ПутьКДанным);
    Иначе
        Возврат "";
    КонецЕсли;

КонецФункции

// Рекурсивно обходит структуру и ищет совпадение по имени поля
Функция НайтиПолеРекурсивноКД(СтруктураКД, ИмяПоля, ВключаяВложенныеПоля)

    Если СтруктураКД = Неопределено Тогда
        Возврат Ложь;
    КонецЕсли;

    Для Каждого ЭлементСтруктуры Из СтруктураКД Цикл

        // Проверяем поля текущего элемента структуры
        Если ПолеНайденоВЭлементеКД(ЭлементСтруктуры, ИмяПоля) Тогда
            Возврат Истина;
        КонецЕсли;

        // Рекурсивно проверяем вложенные структуры
        Если ВключаяВложенныеПоля Тогда

            // Строки и колонки таблицы
            Если ТипЗнч(ЭлементСтруктуры) = Тип("ТаблицаКомпоновкиДанных") Тогда

                Если НайтиПолеРекурсивноКД(ЭлементСтруктуры.Строки, ИмяПоля, Истина) Тогда
                    Возврат Истина;
                КонецЕсли;

                Если НайтиПолеРекурсивноКД(ЭлементСтруктуры.Колонки, ИмяПоля, Истина) Тогда
                    Возврат Истина;
                КонецЕсли;

            // Строки и колонки группировки
            ИначеЕсли ТипЗнч(ЭлементСтруктуры) = Тип("ГруппировкаКомпоновкиДанных") Тогда

                Если НайтиПолеРекурсивноКД(ЭлементСтруктуры.Строки, ИмяПоля, Истина) Тогда
                    Возврат Истина;
                КонецЕсли;

                Если НайтиПолеРекурсивноКД(ЭлементСтруктуры.Колонки, ИмяПоля, Истина) Тогда
                    Возврат Истина;
                КонецЕсли;

            // Вложенные структуры диаграммы
            ИначеЕсли ТипЗнч(ЭлементСтруктуры) = Тип("ГруппировкаДиаграммыКомпоновкиДанных") Тогда

                Если НайтиПолеРекурсивноКД(ЭлементСтруктуры.Точки, ИмяПоля, Истина) Тогда
                    Возврат Истина;
                КонецЕсли;

                Если НайтиПолеРекурсивноКД(ЭлементСтруктуры.Серии, ИмяПоля, Истина) Тогда
                    Возврат Истина;
                КонецЕсли;

            КонецЕсли;

        КонецЕсли;

    КонецЦикла;

    Возврат Ложь;

КонецФункции

// Проверяет наличие поля среди доступных полей элемента структуры
Функция ПолеНайденоВЭлементеКД(ЭлементСтруктуры, ИмяПоля)

    ДоступныеПоля = Неопределено;

    // Получаем коллекцию доступных полей в зависимости от типа элемента
    ТипЭлемента = ТипЗнч(ЭлементСтруктуры);

    Если ТипЭлемента = Тип("ГруппировкаКомпоновкиДанных")
        Или ТипЭлемента = Тип("ГруппировкаТаблицыКомпоновкиДанных")
        Или ТипЭлемента = Тип("ГруппировкаДиаграммыКомпоновкиДанных") Тогда

        ДоступныеПоля = ЭлементСтруктуры.Выбор.Элементы;

    ИначеЕсли ТипЭлемента = Тип("НаборДанныхОбъединениеКомпоновкиДанных")
        Или ТипЭлемента = Тип("НаборДанныхЗапросКомпоновкиДанных")
        Или ТипЭлемента = Тип("НаборДанныхОбъектКомпоновкиДанных") Тогда

        ДоступныеПоля = ЭлементСтруктуры.Поля.Элементы;

    КонецЕсли;

    Если ДоступныеПоля = Неопределено Тогда
        Возврат Ложь;
    КонецЕсли;

    // Обходим доступные поля и сравниваем по пути к данным
    Для Каждого ДоступноеПоле Из ДоступныеПоля Цикл

        Если ТипЗнч(ДоступноеПоле) = Тип("АвтоВыбранноеПолеКомпоновкиДанных")
            Или ТипЗнч(ДоступноеПоле) = Тип("АвтоПолеКомпоновкиДанных") Тогда
            Продолжить;
        КонецЕсли;

        ПутьПоля = СокрЛП(ДоступноеПоле.ПутьКДанным);

        Если СтрСравнить(ПутьПоля, ИмяПоля) = 0 Тогда
            Возврат Истина;
        КонецЕсли;

    КонецЦикла;

    Возврат Ложь;

КонецФункции

// Функция формирует анализ покупателей по регионам
//
// Параметры:
//   ДатаНач - Дата - дата начала периода анализа (по умолчанию начало текущего года)
//   ДатаКон - Дата - дата окончания периода анализа (по умолчанию конец текущего года)
//
// Возвращает:
//   ТаблицаЗначений - таблица с колонками:
//     * Регион - регион покупателя
//     * КоличествоПокупателей - количество уникальных покупателей
//     * КоличествоПродано - общее количество проданного товара
//     * СуммаПродаж - общая сумма выручки
//
Функция СформироватьАнализПокупателейПоРегионам(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка значений по умолчанию для дат
    ТекущаяДата = ТекущаяДата();

    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДата);
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецГода(ТекущаяДата);
    КонецЕсли;

    // Создание таблицы результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Регион");
    Результат.Колонки.Добавить("КоличествоПокупателей", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 0)));
    Результат.Колонки.Добавить("КоличествоПродано", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    Результат.Колонки.Добавить("СуммаПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    ПродажиОбороты.Покупатель.Регион КАК Регион,
    |    КОЛИЧЕСТВО(РАЗЛИЧНЫЕ ПродажиОбороты.Покупатель) КАК КоличествоПокупателей,
    |    ПродажиОбороты.КоличествоОборот КАК КоличествоПродано,
    |    ПродажиОбороты.СуммаОборот КАК СуммаПродаж
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, , ) КАК ПродажиОбороты
    |
    |СГРУППИРОВАТЬ ПО
    |    ПродажиОбороты.Покупатель.Регион,
    |    ПродажиОбороты.КоличествоОборот,
    |    ПродажиОбороты.СуммаОборот
    |
    |УПОРЯДОЧИТЬ ПО
    |    СуммаПродаж УБЫВ";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполнение запроса и загрузка результата
    РезультатЗапроса = Запрос.Выполнить();

    Если НЕ РезультатЗапроса.Пустой() Тогда
        Результат = РезультатЗапроса.Выгрузить();
    КонецЕсли;

    Возврат Результат;

КонецФункции

Функция СформироватьКонтрольЗадержкиОплаты(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка значений по умолчанию для параметров периода
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДата());
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Контрагент КАК Покупатель,
    |    ВзаиморасчетыОстатки.Валюта,
    |    СУММА(ВзаиморасчетыОстатки.СуммаОстаток) КАК СуммаДолга
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&ПериодКон, ) КАК ВзаиморасчетыОстатки
    |ГДЕ
    |    ВзаиморасчетыОстатки.СуммаОстаток > 0
    |
    |СГРУППИРОВАТЬ ПО
    |    ВзаиморасчетыОстатки.Контрагент,
    |    ВзаиморасчетыОстатки.Валюта
    |
    |УПОРЯДОЧИТЬ ПО
    |    СуммаДолга УБЫВ";

    // Устанавливаем параметры запроса
    Запрос.УстановитьПараметр("ПериодКон", ДатаКон);

    // Выполняем запрос и возвращаем результат в виде таблицы значений
    Возврат Запрос.Выполнить().Выгрузить();

КонецФункции

Функция СформироватьИсториюДвиженияТовара(Товар, ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка параметров периода по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДата());
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Приведение параметра Товар к массиву
    Если ТипЗнч(Товар) = Тип("Массив") Тогда
        МассивТоваров = Товар;
    Иначе
        МассивТоваров = Новый Массив;
        МассивТоваров.Добавить(Товар);
    КонецЕсли;

    // Создание запроса
    Запрос = Новый Запрос;
    Запрос.Текст =
    |ВЫБРАТЬ
    |    ПриходТовары.Ссылка.Дата КАК Дата,
    |    "Приход" КАК ВидДвижения,
    |    ПриходТовары.Товар КАК Товар,
    |    ПриходТовары.Количество,
    |    ПриходТовары.Сумма
    |ИЗ
    |    Документ.ПриходТовара.Товары КАК ПриходТовары
    |ГДЕ
    |    ПриходТовары.Товар В (&Товар)
    |    И ПриходТовары.Ссылка.Дата >= &ДатаНач
    |    И ПриходТовары.Ссылка.Дата <= &ДатаКон
    |    И ПриходТовары.Ссылка.Проведен
    |
    |ОБЪЕДИНИТЬ ВСЕ
    |
    |ВЫБРАТЬ
    |    РасходТовары.Ссылка.Дата КАК Дата,
    |    "Расход" КАК ВидДвижения,
    |    РасходТовары.Товар КАК Товар,
    |    РасходТовары.Количество,
    |    РасходТовары.Сумма
    |ИЗ
    |    Документ.РасходТовара.Товары КАК РасходТовары
    |ГДЕ
    |    РасходТовары.Товар В (&Товар)
    |    И РасходТовары.Ссылка.Дата >= &ДатаНач
    |    И РасходТовары.Ссылка.Дата <= &ДатаКон
    |    И РасходТовары.Ссылка.Проведен
    |
    |УПОРЯДОЧИТЬ ПО
    |    Дата ВОЗР";

    // Установка параметров запроса
    Запрос.УстановитьПараметр("Товар", МассивТоваров);
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполнение запроса и возврат результата
    РезультатЗапроса = Запрос.Выполнить();
    ТаблицаДвижений = РезультатЗапроса.Выгрузить();

    Возврат ТаблицаДвижений;

КонецФункции

// Функция выполняет XYZ-анализ продаж товаров
//
// Параметры:
//  ДатаНач - Дата - дата начала периода анализа (по умолчанию 12 месяцев назад)
//  ДатаКон - Дата - дата окончания периода анализа (по умолчанию конец текущего дня)
//
// Возвращает:
//  ТаблицаЗначений - результаты анализа с колонками:
//   Товар, СредниеПродажи, ОтклонениеПродаж, КоэффициентВариации, XYZКатегория
//
Функция СформироватьXYZАнализПродаж(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка значений по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = ДобавитьМесяц(НачалоДня(ТекущаяДата()), -12);
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    // Создание таблицы результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Товар");
    Результат.Колонки.Добавить("СредниеПродажи", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    Результат.Колонки.Добавить("ОтклонениеПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    Результат.Колонки.Добавить("КоэффициентВариации", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 4)));
    Результат.Колонки.Добавить("XYZКатегория", Новый ОписаниеТипов("Строка", Новый КвалификаторыСтроки(1)));

    // Формирование запроса для получения месячных продаж
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    РасходТовараТовары.Товар,
    |    СУММА(РасходТовараТовары.Количество) КАК СуммаКоличество,
    |    СУММА(РасходТовараТовары.Количество * РасходТовараТовары.Количество) КАК СуммаКоличествоКвадрат,
    |    КОЛИЧЕСТВО(РАЗЛИЧНЫЕ НАЧАЛОПЕРИОДА(РасходТовара.Дата, МЕСЯЦ)) КАК КоличествоМесяцев
    |ИЗ
    |    Документ.РасходТовара.Товары КАК РасходТовараТовары
    |    ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасходТовара КАК РасходТовара
    |    ПО РасходТовараТовары.Ссылка = РасходТовара.Ссылка
    |ГДЕ
    |    РасходТовара.Проведен = ИСТИНА
    |    И РасходТовара.Дата >= &ДатаНач
    |    И РасходТовара.Дата <= &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    РасходТовараТовары.Товар
    |УПОРЯДОЧИТЬ ПО
    |    РасходТовараТовары.Товар";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    Если РезультатЗапроса.Пустой() Тогда
        Возврат Результат;
    КонецЕсли;

    // Обработка результатов и расчёт показателей
    Выборка = РезультатЗапроса.Выбрать();

    Пока Выборка.Следующий() Цикл

        // Расчёт среднего значения продаж
        СредниеПродажи = Выборка.СуммаКоличество / Выборка.КоличествоМесяцев;

        // Расчёт стандартного отклонения по формуле
        // σ = sqrt((Σxi² - n * x̄²) / (n - 1))
        // где xi - количество продаж в i-м месяце
        // x̄ - среднее значение
        // n - количество месяцев

        Если Выборка.КоличествоМесяцев > 1 Тогда

            // Вычисление дисперсии через сумму квадратов
            Дисперсия = (Выборка.СуммаКоличествоКвадрат 
                - Выборка.КоличествоМесяцев * СредниеПродажи * СредниеПродажи) 
                / (Выборка.КоличествоМесяцев - 1);

            // Стандартное отклонение (квадратный корень из дисперсии)
            Если Дисперсия > 0 Тогда
                ОтклонениеПродаж = Sqrt(Дисперсия);
            Иначе
                ОтклонениеПродаж = 0;
            КонецЕсли;

        Иначе
            // При只有一个月це продаж стандартное отклонение равно нулю
            ОтклонениеПродаж = 0;
        КонецЕсли;

        // Расчёт коэффициента вариации
        Если СредниеПродажи <> 0 Тогда
            КоэффициентВариации = Окр(ОтклонениеПродаж / СредниеПродажи, 4);
        Иначе
            КоэффициентВариации = 0;
        КонецЕсли;

        // Определение категории XYZ
        Если КоэффициентВариации <= 0.10 Тогда
            XYZКатегория = "X";  // Стабильные продажи
        ИначеЕсли КоэффициентВариации <= 0.25 Тогда
            XYZКатегория = "Y";  // Средняя вариабельность
        Иначе
            XYZКатегория = "Z";  // Нестабильные продажи
        КонецЕсли;

        // Добавление строки в результат
        НоваяСтрока = Результат.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.СредниеПродажи = СредниеПродажи;
        НоваяСтрока.ОтклонениеПродаж = ОтклонениеПродаж;
        НоваяСтрока.КоэффициентВариации = КоэффициентВариации;
        НоваяСтрока.XYZКатегория = XYZКатегория;

    КонецЦикла;

    Возврат Результат;

КонецФункции

// Получает значения указанных полей документа по его ссылке
//
// Параметры:
//   ДокументСсылка - ДокументСсылка - Ссылка на документ
//   Поля - Строка или Массив - Список полей для получения
//
// Возвращает:
//   Структура - Ключ = имя поля, Значение = значение реквизита
//               Если поле не найдено или документ не существует - значение = Неопределено
//
Функция ПолучитьЗначенияПолейДокумента(ДокументСсылка, Поля) Экспорт

    Результат = Новый Структура;

    // ═══════════════════════════════════════════════════════════════════
    // 1. ВАЛИДАЦИЯ ВХОДНЫХ ПАРАМЕТРОВ
    // ═══════════════════════════════════════════════════════════════════

    // Проверка ссылки на документ
    Если НЕ ЗначениеЗаполнено(ДокументСсылка) Тогда
        Возврат Результат;
    КонецЕсли;

    // Проверка типа ссылки (должна быть ссылкой на документ)
    Если НЕ ОбщегоНазначения.ЭтоДокумент(ДокументСсылка) Тогда
        Возврат Результат;
    КонецЕсли;

    // Проверка наличия полей
    Если Поля = Неопределено 
        ИЛИ (ТипЗнч(Поля) = Тип("Строка") И ПустаяСтрока(Поля))
        ИЛИ (ТипЗнч(Поля) = Тип("Массив") И Поля.Количество() = 0) Тогда
        Возврат Результат;
    КонецЕсли;

    // ═══════════════════════════════════════════════════════════════════
    // 2. ПОДГОТОВКА СПИСКА ПОЛЕЙ
    // ═══════════════════════════════════════════════════════════════════

    // Нормализация списка полей
    Если ТипЗнч(Поля) = Тип("Строка") Тогда
        МассивПолей = СтрРазделить(Поля, ",", Ложь);
    Иначе
        МассивПолей = Поля;
    КонецЕсли;

    // Нормализация имен полей
    Для Индекс = 0 По МассивПолей.ВГраница() Цикл
        МассивПолей[Индекс] = СокрЛП(СтрЗаменить(МассивПолей[Индекс], ".", "/"));
    КонецЦикла;

    // Удаление дублей
    СоответствиеПолей = Новый Соответствие;
    Для Каждого Поле Из МассивПолей Цикл
        Поле = СокрЛП(Поле);
        Если НЕ ПустаяСтрока(Поле) Тогда
            СоответствиеПолей.Вставить(Поле, Истина);
        КонецЕсли;
    КонецЦикла;

    // Проверка на пустой список
    Если СоответствиеПолей.Количество() = 0 Тогда
        Возврат Результат;
    КонецЕсли;

    // ═══════════════════════════════════════════════════════════════════
    // 3. РАЗБОР ПОЛЕЙ НА ПРОСТЫЕ И ВЛОЖЕННЫЕ
    // ═══════════════════════════════════════════════════════════════════

    ПростыеПоля       = Новый Массив;  // Поля без точки (например: "Номер", "Дата")
    ВложенныеПоля     = Новый Массив;  // Поля с точкой (например: "Контрагент.Наименование")
    ТабличныеЧасти   = Новый Массив;  // Табличные части (например: "Товары.Номенклатура")

    Для Каждого КлючЗначение Из СоответствиеПолей Цикл

        ИмяПоля = КлючЗначение.Ключ;
        Разделители = СтрНайти(ИмяПоля, "/");

        Если Разделители = 0 Тогда
            // Простое поле
            ПростыеПоля.Добавить(ИмяПоля);
        Иначе
            // Проверяем, есть ли еще разделители (вложенное или табличная часть)
            ВтораяТочка = СтрНайти(ИмяПоля, "/", , 2);

            Если ВтораяТочка > 0 Тогда
                // Табличная часть (Товары.Номенклатура.Цена)
                ТабличныеЧасти.Добавить(ИмяПоля);
            Иначе
                // Вложенное поле (Контрагент.Наименование)
                ВложенныеПоля.Добавить(ИмяПоля);
            КонецЕсли;
        КонецЕсли;

    КонецЦикла;

    // ═══════════════════════════════════════════════════════════════════
    // 4. ПОЛУЧЕНИЕ МЕТАДАННЫХ ДОКУМЕНТА
    // ═══════════════════════════════════════════════════════════════════

    МетаДокумента = ДокументСсылка.Метаданные();
    ПолноеИмя     = МетаДокумента.ПолноеИмя();

    // Получаем реквизиты и стандартные реквизиты документа
    ВсеРеквизиты = Новый Соответствие;
    Для Каждого Реквизит Из МетаДокумента.Реквизиты Цикл
        ВсеРеквизиты.Вставить(Реквизит.Имя, Реквизит);
    КонецЦикла;
    Для Каждого СтандартныйРеквизит Из МетаДокумента.СтандартныеРеквизиты Цикл
        ВсеРеквизиты.Вставить(СтандартныйРеквизит.Имя, СтандартныйРеквизит);
    КонецЦикла;

    // Получаем табличные части
    ТабличныеЧастиМД = Новый Соответствие;
    Для Каждого ТЧ Из МетаДокумента.ТабличныеЧасти Цикл
        ТабличныеЧастиМД.Вставить(ТЧ.Имя, ТЧ);
    КонецЦикла;

    // ═══════════════════════════════════════════════════════════════════
    // 5. ПОСТРОЕНИЕ ЗАПРОСА
    // ═══════════════════════════════════════════════════════════════════

    Запрос = Новый Запрос;

    // Формируем текст запроса
    ТекстЗапроса = "ВЫБРАТЬ РАЗРЕШЕННЫЕ" + Символы.ПС;
    ТекстЗапроса = ТекстЗапроса + "|    Ссылка";

    // Добавляем простые поля в запрос
    Для Каждого ИмяПоля Из ПростыеПоля Цикл

        // Проверяем существование поля в метаданных
        Если ВсеРеквизиты.Получить(ИмяПоля) <> Неопределено Тогда
            ТекстЗапроса = ТекстЗапроса + "," + Символы.ПС + "|    " + ИмяПоля;
        КонецЕсли;

    КонецЦикла;

    // Добавляем вложенные поля (нужно получить значение ссылки)
    Для Каждого ВложенноеПоле Из ВложенныеПоля Цикл

        Части = СтрРазделить(ВложенноеПоле, "/");
        ИмяРеквизита = Части[0];

        // Проверяем существование реквизита
        РеквизитМД = ВсеРеквизиты.Получить(ИмяРеквизита);
        Если РеквизитМД <> Неопределено Тогда
            ТекстЗапроса = ТекстЗапроса + "," + Символы.ПС + "|    " + ИмяРеквизита;
        КонецЕсли;

    КонецЦикла;

    // Добавляем табличные части
    Для Каждого ПолноеИмяТЧ Из ТабличныеЧасти Цикл

        Части = СтрРазделить(ПолноеИмяТЧ, "/");
        ИмяТЧ = Части[0];

        // Проверяем существование табличной части
        Если ТабличныеЧастиМД.Получить(ИмяТЧ) <> Неопределено Тогда
            ТекстЗапроса = ТекстЗапроса + "," + Символы.ПС 
                         + "|    " + ИмяТЧ + ".(
                         |        " + СтрЗаменить(ПолноеИмяТЧ, "/", ".") + "
                         |    ) КАК " + ИмяТЧ;
        КонецЕсли;

    КонецЦикла;

    // Указываем источник данных
    ТекстЗапроса = ТекстЗапроса + Символы.ПС + "ИЗ " + ПолноеИмя;

    // Условие отбора
    ТекстЗапроса = ТекстЗапроса + Символы.ПС + "ГДЕ Ссылка = &Ссылка";

    Запрос.Текст = ТекстЗапроса;
    Запрос.УстановитьПараметр("Ссылка", ДокументСсылка);

    // ═══════════════════════════════════════════════════════════════════
    // 6. ВЫПОЛНЕНИЕ ЗАПРОСА И ОБРАБОТКА РЕЗУЛЬТАТА
    // ═══════════════════════════════════════════════════════════════════

    Попытка

        РезультатЗапроса = Запрос.Выполнить();

        Если РезультатЗапроса.Пустой() Тогда
            // Документ не найден - возвращаем структуру с Неопределено
            Возврат Результат;
        КонецЕсли;

        Выборка = РезультатЗапроса.Выбрать();
        Выборка.Следующий();

        // Заполняем простые поля
        Для Каждого ИмяПоля Из ПростыеПоля Цикл

            Если ВсеРеквизиты.Получить(ИмяПоля) <> Неопределено Тогда
                Попытка
                    Результат.Вставить(ИмяПоля, Выборка[ИмяПоля]);
                Исключение
                    Результат.Вставить(ИмяПоля, Неопределено);
                КонецПопытки;
            Иначе
                Результат.Вставить(ИмяПоля, Неопределено);
            КонецЕсли;

        КонецЦикла;

        // Заполняем вложенные поля
        Для Каждого ВложенноеПоле Из ВложенныеПоля Цикл

            Части = СтрРазделить(ВложенноеПоле, "/");
            ИмяРеквизита = Части[0];
            ИмяСвойства  = Части[1];

            РеквизитМД = ВсеРеквизиты.Получить(ИмяРеквизита);

            Если РеквизитМД = Неопределено Тогда
                Результат.Вставить(ВложенноеПоле, Неопределено);
                Продолжить;
            КонецЕсли;

            Попытка

                ЗначениеРеквизита = Выборка[ИмяРеквизита];

                Если НЕ ЗначениеЗаполнено(ЗначениеРеквизита) Тогда
                    Результат.Вставить(ВложенноеПоле, Неопределено);
                Иначе
                    // Получаем значение вложенного реквизита через запрос
                    ЗначениеВложенное = ПолучитьВложенноеЗначение(
                        ЗначениеРеквизита, 
                        ИмяСвойства
                    );
                    Результат.Вставить(ВложенноеПоле, ЗначениеВложенное);
                КонецЕсли;

            Исключение
                Результат.Вставить(ВложенноеПоле, Неопределено);
            КонецПопытки;

        КонецЦикла;

        // Заполняем табличные части
        Для Каждого ПолноеИмяТЧ Из ТабличныеЧасти Цикл

            Части = СтрРазделить(ПолноеИмяТЧ, "/");
            ИмяТЧ = Части[0];

            Если ТабличныеЧастиМД.Получить(ИмяТЧ) = Неопределено Тогда
                Результат.Вставить(ПолноеИмяТЧ, Неопределено);
                Продолжить;
            КонецЕсли;

            Попытка

                ТаблицаРезультат = Выборка[ИмяТЧ].Выгрузить();
                Результат.Вставить(ПолноеИмяТЧ, ТаблицаРезультат);

            Исключение
                Результат.Вставить(ПолноеИмяТЧ, Неопределено);
            КонецПопытки;

        КонецЦикла;

    Исключение

        // Логирование ошибки при необходимости
        ЗаписьЖурналаРегистрации(
            "ПолучитьЗначенияПолейДокумента",
            УровеньЖурналаРегистрации.Ошибка,
            МетаДокумента,
            ДокументСсылка,
            ПодробноеПредставлениеОшибки(ИнформацияОбОшибке())
        );

        // Возвращаем структуру с Неопределено для всех полей
        Для Каждого КлючЗначение Из СоответствиеПолей Цикл
            Результат.Вставить(КлючЗначение.Ключ, Неопределено);
        КонецЦикла;

    КонецПопытки;

    Возврат Результат;

КонецФункции

// ═══════════════════════════════════════════════════════════════════════════
// ВСПОМОГАТЕЛЬНАЯ ФУНКЦИЯ: Получить значение вложенного реквизита
// ═══════════════════════════════════════════════════════════════════════════

Функция ПолучитьВложенноеЗначение(Ссылка, ИмяРеквизита)

    // Для примитивных типов (Дата, Число, Строка, Булево) возвращаем Неопределено
    // или можно получить через запрос, но это будет неэффективно

    Если НЕ ОбщегоНазначения.ЭтоСсылка(ТипЗнч(Ссылка)) Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Для ссылочных типов используем запрос
    Попытка

        Запрос = Новый Запрос;
        Запрос.Текст =
        "ВЫБРАТЬ РАЗРЕШЕННЫЕ
        |    ВложенныйОбъект." + ИмяРеквизита + " КАК Значение
        |ИЗ " + Ссылка.Метаданные().ПолноеИмя() + " КАК ВложенныйОбъект
        |ГДЕ ВложенныйОбъект.Ссылка = &Ссылка";

        Запрос.УстановитьПараметр("Ссылка", Ссылка);

        Результат = Запрос.Выполнить();

        Если НЕ Результат.Пустой() Тогда
            Выборка = Результат.Выбрать();
            Выборка.Следующий();
            Возврат Выборка.Значение;
        КонецЕсли;

    Исключение
        Возврат Неопределено;
    КонецПопытки;

    Возврат Неопределено;

КонецФункции

task:
Написать функцию СформироватьПродажиПоДнямНедели(ДатаНач, ДатаКон), которая формирует отчет о продажах предприятия с разбивкой по 
дням недели за выбранный период.
Задача предназначена для анализа покупательской активности и позволяет определить, в какие дни недели наблюдаются наибольшие продажи.

Результаты анализа могут использоваться для:
оптимизации графика работы персонала;
планирования акций и маркетинговых мероприятий;
анализа нагрузки на торговые точки;
выявления пиковых и слабых дней продаж;
повышения эффективности управления продажами.

Параметры функции:
ДатаНач — дата начала периода анализа;
ДатаКон — дата окончания периода анализа.

Если параметры периода не заданы, используются значения по умолчанию:
ДатаНач = начало дня 30 дней назад;
ДатаКон = конец текущего дня.

Перед выполнением расчета выполняется проверка параметров:
если ДатаКон < ДатаНач — генерируется исключение;
анализ выполняется только в пределах указанного периода.

Расчет выполняется на основании регистра накопления Продажи.
Используются следующие поля:
Период — дата продажи;
Количество — количество проданного товара;
Сумма — сумма продаж.

В процессе выполнения:
определяется день недели по дате продажи;
выполняется группировка по дням недели;
рассчитываются итоговые показатели по количеству и сумме продаж;
формируется итоговая таблица значений.

Результат функции представляет собой таблицу, содержащую:
день недели;
общее количество продаж;
общую сумму продаж.

output:
Функция СформироватьПродажиПоДнямНедели(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка параметров по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 86400 * 30); // 30 дней назад
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода";
    КонецЕсли;

    // Формирование таблицы результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("ДеньНедели", Новый ОписаниеТипов("Строка", , Новый КвалификаторыСтроки(20)));
    Результат.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    Результат.Колонки.Добавить("Сумма", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ДЕНЬНЕДЕЛИ(Продажи.Период) КАК НомерДняНедели,
    |    СУММА(Продажи.Количество) КАК Количество,
    |    СУММА(Продажи.Сумма) КАК Сумма
    |ИЗ
    |    РегистрНакопления.Продажи КАК Продажи
    |ГДЕ
    |    Продажи.Период >= &ДатаНач
    |    И Продажи.Период <= &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    ДЕНЬНЕДЕЛИ(Продажи.Период)
    |УПОРЯДОЧИТЬ ПО
    |    НомерДняНедели";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    // Соответствие номеров дней недели их названиям
    СоответствиеДней = Новый Соответствие;
    СоответствиеДней.Вставить(1, "Понедельник");
    СоответствиеДней.Вставить(2, "Вторник");
    СоответствиеДней.Вставить(3, "Среда");
    СоответствиеДней.Вставить(4, "Четверг");
    СоответствиеДней.Вставить(5, "Пятница");
    СоответствиеДней.Вставить(6, "Суббота");
    СоответствиеДней.Вставить(7, "Воскресенье");

    // Обход результата запроса и заполнение таблицы
    ИтоговоеКоличество = 0;
    ИтоговаяСумма = 0;

    Пока РезультатЗапроса.Следующий() Цикл
        СтрокаРезультата = Результат.Добавить();
        СтрокаРезультата.ДеньНедели = СоответствиеДней.Получить(РезультатЗапроса.НомерДняНедели);
        СтрокаРезультата.Количество = РезультатЗапроса.Количество;
        СтрокаРезультата.Сумма = РезультатЗапроса.Сумма;

        ИтоговоеКоличество = ИтоговоеКоличество + РезультатЗапроса.Количество;
        ИтоговаяСумма = ИтоговаяСумма + РезультатЗапроса.Сумма;
    КонецЦикла;

    // Добавление итоговой строки
    СтрокаИтогов = Результат.Добавить();
    СтрокаИтогов.ДеньНедели = "Итого";
    СтрокаИтогов.Количество = ИтоговоеКоличество;
    СтрокаИтогов.Сумма = ИтоговаяСумма;

    Возврат Результат;

КонецФункции

task:
Написать функцию СформироватьТоварыБезДвижения(ДатаНач, ДатаКон), которая формирует список товаров, по которым отсутствовали движения (продажи) 
за выбранный период.
Задача предназначена для анализа ассортимента и позволяет выявить товары, не участвующие в продажах.

Результаты анализа могут использоваться для:
выявления неликвидных и залежалых товаров;
принятия решений о скидках или акциях;
оптимизации ассортимента;
освобождения складских запасов;
повышения оборачиваемости товаров.

Параметры функции:
ДатаНач — дата начала периода анализа;
ДатаКон — дата окончания периода анализа.

Если параметры периода не заданы, используются значения по умолчанию:
ДатаНач = начало дня 30 дней назад;
ДатаКон = конец текущего дня.

Перед выполнением расчета выполняется проверка параметров:
если ДатаКон < ДатаНач — генерируется исключение;
анализ выполняется только в пределах указанного периода.

Расчет выполняется на основании следующих объектов конфигурации:
Справочник Товары — используется для получения полного списка товаров;
Регистр накопления Продажи — используется для определения наличия движений по товарам.

В процессе выполнения:
формируется список всех товаров без пометки удаления;
определяются товары, по которым были продажи за указанный период;
выполняется сравнение списков;
отбираются товары, по которым отсутствуют движения.

Результат функции представляет собой таблицу значений, содержащую:
товар;
наименование товара.

Полученный список позволяет оперативно выявить товары без движения и принять управленческие решения.

output:
// Функция формирует список товаров без движения (продаж) за указанный период
//
// Параметры:
//   ДатаНач - Дата - Дата начала периода анализа (по умолчанию: 30 дней назад)
//   ДатаКон - Дата - Дата окончания периода анализа (по умолчанию: конец текущего дня)
//
// Возвращаемое значение:
//   ТаблицаЗначений - таблица с колонками:
//     * Товар - СправочникСсылка.Товары - ссылка на товар
//     * Наименование - Строка - наименование товара
//
Функция СформироватьТоварыБезДвижения(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка параметров по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 30 * 24 * 60 * 60); // 30 дней назад
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода!";
    КонецЕсли;

    // Формируем результат
    Запрос = Новый Запрос;

    // Получаем все товары без пометки удаления,
    // которые не участвовали в продажах за указанный период
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товары.Ссылка КАК Товар,
    |    Товары.Наименование КАК Наименование
    |ИЗ
    |    Справочник.Товары КАК Товары
    |ГДЕ
    |    НЕ Товары.ПометкаУдаления
    |    И НЕ Товары.Ссылка В
    |            (ВЫБРАТЬ
    |                Продажи.Товар
    |            ИЗ
    |                РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, АВТОЗАПОЛНЕНИЕ, ) КАК Продажи
    |            ГДЕ
    |                Продажи.КоличествоОборот > 0)
    |
    |УПОРЯДОЧИТЬ ПО
    |    Товары.Наименование";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    Результат = Запрос.Выполнить().Выгрузить();

    Возврат Результат;

КонецФункции

task:
Написать функцию НайтиПревышениеЛимитаПродаж(ДатаНач, ДатаКон, Лимит),
которая формирует список документов продаж предприятия, у которых сумма документа превышает установленный лимит за выбранный период.

Функция принимает три параметра:

ДатаНач — дата начала периода анализа;
ДатаКон — дата окончания периода анализа;
Лимит — максимальная допустимая сумма документа.

Если параметры периода не заданы, функция должна автоматически установить:

ДатаНач = начало дня 30 дней назад  
ДатаКон = конец текущего дня
Если параметр Лимит не задан — может использоваться значение по умолчанию


Перед выполнением расчета необходимо выполнить проверки:

если ДатаКон < ДатаНач — должно быть сгенерировано исключение;
если даты не заданы — используются значения по умолчанию;
анализ выполняется только в пределах указанного период 

Расчет выполняется на основании следующих объектов конфигурации:
Документ.РасходТовара

Функция должна возвращать объект типа ТаблицаЗначений, содержащий:

Ссылка — ссылка на документ;
Дата — дата документа;
Покупатель — контрагент;
Сумма — сумма документа

output:
// Функция формирует список документов продаж с превышением установленного лимита
//
// Параметры:
//   ДатаНач - Дата - дата начала периода анализа (необязательно)
//   ДатаКон - Дата - дата окончания периода анализа (необязательно)
//   Лимит   - Число - максимальная допустимая сумма документа (необязательно)
//
// Возвращаемое значение:
//   ТаблицаЗначений - с колонками: Ссылка, Дата, Покупатель, Сумма
//
// Пример использования:
//   Результат = НайтиПревышениеЛимитаПродаж('20240101000000', '20240131235959', 50000);
//
Функция НайтиПревышениеЛимитаПродаж(ДатаНач = Неопределено, ДатаКон = Неопределено, Лимит = Неопределено) Экспорт

    // Установка значений по умолчанию для дат
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 30 * 86400);
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала периода";
    КонецЕсли;

    // Установка значения по умолчанию для лимита
    Если Лимит = Неопределено Тогда
        Лимит = 0;
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    РасходТовара.Ссылка КАК Ссылка,
    |    РасходТовара.Дата КАК Дата,
    |    РасходТовара.Покупатель КАК Покупатель,
    |    ЕСТЬNULL(РасходТовараТовары.СуммаДокумента, 0) КАК Сумма
    |ИЗ
    |    Документ.РасходТовара КАК РасходТовара
    |        ЛЕВОЕ СОЕДИНЕНИЕ (
    |            ВЫБРАТЬ
    |                РасходТовараТовары.Ссылка,
    |                СУММА(РасходТовараТовары.Сумма) КАК СуммаДокумента
    |            ИЗ
    |                Документ.РасходТовара.Товары КАК РасходТовараТовары
    |            СГРУППИРОВАТЬ ПО
    |                РасходТовараТовары.Ссылка
    |        ) КАК РасходТовараТовары
    |        ПО РасходТовара.Ссылка = РасходТовараТовары.Ссылка
    |ГДЕ
    |    РасходТовара.Дата >= &ДатаНач
    |    И РасходТовара.Дата <= &ДатаКон
    |    И ЕСТЬNULL(РасходТовараТовары.СуммаДокумента, 0) > &Лимит
    |УПОРЯДОЧИТЬ ПО
    |    РасходТовара.Дата УБЫВ";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", КонецДня(ДатаКон));
    Запрос.УстановитьПараметр("Лимит", Лимит);

    РезультатЗапроса = Запрос.Выполнить().Выбрать();

    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Ссылка");
    Результат.Колонки.Добавить("Дата");
    Результат.Колонки.Добавить("Покупатель");
    Результат.Колонки.Добавить("Сумма");

    Пока РезультатЗапроса.Следующий() Цикл
        НоваяСтрока = Результат.Добавить();
        НоваяСтрока.Ссылка = РезультатЗапроса.Ссылка;
        НоваяСтрока.Дата = РезультатЗапроса.Дата;
        НоваяСтрока.Покупатель = РезультатЗапроса.Покупатель;
        НоваяСтрока.Сумма = РезультатЗапроса.Сумма;
    КонецЦикла;

    Возврат Результат;

КонецФункции

// Функция формирует отчет "ОстаткиТоваровНаСкладах" с контролем остатков
//
// Параметры:
//  Период - Дата - Период отчета
//  КоличествоКонтроль - Число - Значение контроля остатка
//
// Возвращаемое значение:
//  ТабличныйДокумент - Сформированный отчет
//
Функция СформироватьОтчетОстаткиТоваровКонтроль(Период, КоличествоКонтроль) Экспорт

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ОстаткиТоваровНаСкладах.Создать();

    // Получаем схему компоновки данных из макета
    СхемаКомпоновки = ОтчетОбъект.ПолучитьМакет("Основной");

    // Создаем компоновщик настроек
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновки));
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновки.НастройкиПоУмолчанию);

    // Получаем настройки компоновки
    Настройки = КомпоновщикНастроек.Настройки;

    // Устанавливаем параметр "Период"
    ПараметрПериод = Настройки.ПараметрыДанных.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("Период"));
    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Значение = Период;
        ПараметрПериод.Использование = Истина;
    КонецЕсли;

    // Устанавливаем параметр "КоличествоКонтроль"
    ПараметрКоличествоКонтроль = Настройки.ПараметрыДанных.НайтиЗначениеПараметра(Новый ПараметрКомпоновкиДанных("КоличествоКонтроль"));
    Если ПараметрКоличествоКонтроль <> Неопределено Тогда
        ПараметрКоличествоКонтроль.Значение = КоличествоКонтроль;
        ПараметрКоличествоКонтроль.Использование = Истина;
    КонецЕсли;

    // Устанавливаем отбор по КоличествоОстаток <= КоличествоКонтроль
    Отбор = Настройки.Отбор;
    НовыйЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    НовыйЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("КоличествоОстаток");
    НовыйЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.МеньшеИлиРавно;
    НовыйЭлементОтбора.ПравоеЗначение = Новый ПолеКомпоновкиДанных("ПараметрыДанных.КоличествоКонтроль");
    НовыйЭлементОтбора.Использование = Истина;

    // Устанавливаем параметры вывода: Не выводить параметры данных и отбор
    ПараметрыВывода = Настройки.ПараметрыВывода;
    ПараметрВыводаПараметрыДанных = ПараметрыВывода.Элементы.Найти("ВыводитьПараметрыДанных");
    Если ПараметрВыводаПараметрыДанных <> Неопределено Тогда
        ПараметрВыводаПараметрыДанных.Значение = Ложь;
        ПараметрВыводаПараметрыДанных.Использование = Истина;
    КонецЕсли;

    ПараметрВыводаОтбор = ПараметрыВывода.Элементы.Найти("ВыводитьОтбор");
    Если ПараметрВыводаОтбор <> Неопределено Тогда
        ПараметрВыводаОтбор.Значение = Ложь;
        ПараметрВыводаОтбор.Использование = Истина;
    КонецЕсли;

    // Выполняем компоновку данных
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновки, Настройки, , , 
        Тип("ГенераторМакетаКомпоновкиДанных"));

    // Создаем процессор компоновки
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    // Создаем табличный документ для вывода результата
    ТабДокумент = Новый ТабличныйДокумент;

    // Создаем процессор вывода
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабДокумент);

    // Выводим результат в табличный документ
    ПроцессорВывода.Вывести(ПроцессорКомпоновки, Истина);

    Возврат ТабДокумент;

КонецФункции

// Функция заполняет табличную часть "Покупатели" исходящих писем
// данными контрагентов из параметра Получатели
//
// Параметры:
//  Получатели - Массив - массив ссылок на справочник Контрагенты
//  Дата       - Дата - дата, greater than which letters will be selected
//
// Возвращаемое значение:
//  Число - количество обработанных писем
//
Функция ДобавитьПолучателейИсходящихПисем(Получатели, Дата) Экспорт

    // Проверка обязательных параметров
    Если НЕ ЗначениеЗаполнено(Получатели) Тогда
        Возврат 0;
    КонецЕсли;

    // Запрос для выборки неотправленных писем
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ РАЗЛИЧНЫЕ
    |    ИсходящиеПисьма.Ссылка КАК Письмо,
    |    ИсходящиеПисьма.Контрагент КАК Контрагент
    |ИЗ
    |    Справочник.ИсходящиеПисьма КАК ИсходящиеПисьма
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрСведений.СостояниеИсходящихПисем КАК СостояниеИсходящихПисем
    |        ПО ИсходящиеПисьма.Ссылка = СостояниеИсходящихПисем.Письмо
    |ГДЕ
    |    ИсходящиеПисьма.Дата > &Дата
    |    И НЕ ИсходящиеПисьма.ПометкаУдаления
    |    И СостояниеИсходящихПисем.Отправлено = ЛОЖЬ
    |    И ИсходящиеПисьма.Контрагент В (&МассивПолучателей)";

    Запрос.УстановитьПараметр("МассивПолучателей", Получатели);
    Запрос.УстановитьПараметр("Дата", Дата);

    РезультатЗапроса = Запрос.Выполнить();

    Если РезультатЗапроса.Пустой() Тогда
        Возврат 0;
    КонецЕсли;

    ВыборкаПисем = РезультатЗапроса.Выбрать();

    // Получаем массив email-адресов контрагентов
    ЗапросПочта = Новый Запрос;
    ЗапросПочта.Текст = 
    "ВЫБРАТЬ
    |    Контрагенты.Ссылка КАК Контрагент,
    |    Контрагенты.ЭлектроннаяПочта КАК ЭлектроннаяПочта
    |ИЗ
    |    Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |    Контрагенты.Ссылка В (&МассивПолучателей)
    |    И Контрагенты.ЭлектроннаяПочта <> """"
    |    И Контрагенты.ЭлектроннаяПочта <> &ПустаяСтрока";

    ЗапросПочта.УстановитьПараметр("МассивПолучателей", Получатели);
    ЗапросПочта.УстановитьПараметр("ПустаяСтрока", "");

    ТаблицаПолучателей = ЗапросПочта.Выполнить().Выгрузить();

    Если ТаблицаПолучателей.Количество() = 0 Тогда
        Возврат 0;
    КонецЕсли;

    КоличествоОбработанных = 0;

    Пока ВыборкаПисем.Следующий() Цикл

        ПисьмоСсылка = ВыборкаПисем.Письмо;

        Попытка
            // Получаем объект письма для редактирования
            ПисьмоОбъект = ПисьмоСсылка.ПолучитьОбъект();

            Если ПисьмоОбъект = Неопределено Тогда
                Продолжить;
            КонецЕсли;

            // Очищаем табличную часть Покупатели перед заполнением
            // (в конфигурации табличная часть называется "Получатели")
            ПисьмоОбъект.Получатели.Очистить();

            // Заполняем табличную часть данными контрагентов
            Для Каждого СтрокаПолучателя Из ТаблицаПолучателей Цикл

                НоваяСтрока = ПисьмоОбъект.Получатели.Добавить();
                НоваяСтрока.Контрагент = СтрокаПолучателя.Контрагент;
                НоваяСтрока.ЭлектроннаяПочта = СтрокаПолучателя.ЭлектроннаяПочта;

            КонецЦикла;

            // Записываем письмо с отключением авторегистрации изменений
            // для оптимизации производительности
            ПисьмоОбъект.Записать(РежимЗаписиДокумента.Запись);

            КоличествоОбработанных = КоличествоОбработанных + 1;

        Исключение
            // Логирование ошибки для отладки
            ТекстОшибки = СтрШаблон(
                "Ошибка при обработке письма ""%1"": %2",
                Строка(ПисьмоСсылка),
                ПодробноеПредставлениеОшибки(ИнформацияОбОшибке())
            );

            ЗаписьЖурналаРегистрации(
                "ДобавитьПолучателейИсходящихПисем",
                УровеньЖурналаРегистрации.Ошибка,
                Метаданные.Справочники.ИсходящиеПисьма,
                ПисьмоСсылка,
                ТекстОшибки
            );
        КонецПопытки;

    КонецЦикла;

    Возврат КоличествоОбработанных;

КонецФункции
